{
  "name": "SmartBet Tracker",
  "description": "A comprehensive sports betting tracker that uses Gemini AI to automatically validate bet slips against real-world match results."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum BetType {
  MATCH_WINNER = '1X2',
  BTTS = 'BTTS',
  OVER_UNDER = 'OVER_UNDER'
}

export enum LegStatus {
  PENDING = 'PENDING',
  WON = 'WON',
  LOST = 'LOST',
  VOID = 'VOID'
}

export enum SlipStatus {
  PENDING = 'PENDING',
  WON = 'WON',
  LOST = 'LOST',
  VOID = 'VOID'
}

export interface Leg {
  id: string;
  matchName: string; // e.g., "Arsenal vs Liverpool"
  date: string; // YYYY-MM-DD
  type: BetType;
  selection: string; // e.g., "Home", "Yes", "Over 2.5"
  status: LegStatus;
  resultScore?: string; // e.g., "2-1"
  notes?: string;
}

export interface Slip {
  id: string;
  createdAt: number;
  legs: Leg[];
  stake: number;
  odds: number;
  potentialReturn: number;
  status: SlipStatus;
  groundingUrls?: string[]; // URLs used for verification
}

export interface ValidationResult {
  legId: string;
  status: LegStatus;
  score: string;
}

export interface Stats {
  totalSlips: number;
  wins: number;
  losses: number;
  winRate: number;
  totalStaked: number;
  totalReturned: number;
  profit: number;
  roi: number;
}

import { GoogleGenAI } from "@google/genai";
import { Slip, Leg, LegStatus, ValidationResult } from "../types";

// Initialize Gemini Client
const apiKey = process.env.API_KEY || '';
const ai = new GoogleGenAI({ apiKey });

export interface ValidationResponse {
  results: ValidationResult[];
  sources: string[];
}

export const validateSlipWithGemini = async (slip: Slip): Promise<ValidationResponse> => {
  if (!apiKey) {
    throw new Error("API Key is missing.");
  }

  // Construct a prompt that describes the bet slip
  const legsDescription = slip.legs.map(leg => 
    `- ID: ${leg.id} | Match: ${leg.matchName} | Date: ${leg.date} | Bet Type: ${leg.type} | Selection: ${leg.selection}`
  ).join('\n');

  const prompt = `
    I have a sports betting slip with the following matches and predictions. 
    Please search for the final match results (scores) using Google Search.

    For each leg, determine if the bet is WON, LOST, or VOID based on the final score.

    Bet Types Logic:
    - 1X2: Home (1) means Home team wins, Draw (X) means draw, Away (2) means Away team wins.
    - BTTS: "Yes" means both teams scored > 0. "No" means at least one team scored 0.
    - OVER_UNDER: "Over X.5" means total goals > X.5. "Under X.5" means total goals < X.5.

    Bet Slip Details:
    ${legsDescription}

    IMPORTANT OUTPUT FORMAT:
    You must return the data in a raw JSON array format inside a code block, like this:
    \`\`\`json
    [
      { "legId": "...", "status": "WON", "score": "2-1" },
      { "legId": "...", "status": "LOST", "score": "0-0" }
    ]
    \`\`\`
    Valid statuses are: WON, LOST, VOID, PENDING (if match hasn't started/finished).
    If you cannot find a result, mark as PENDING and score as "?".
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
      },
    });

    const text = response.text || '';

    // Extract Grounding Metadata (Sources)
    const sources: string[] = [];
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
    chunks.forEach(chunk => {
      if (chunk.web?.uri) {
        sources.push(chunk.web.uri);
      }
    });

    // Extract JSON from text
    const jsonMatch = text.match(/```json\s*([\s\S]*?)\s*```/) || text.match(/\[\s*\{[\s\S]*\}\s*\]/);

    if (!jsonMatch) {
      console.error("Failed to parse JSON from Gemini response:", text);
      throw new Error("AI could not format the results correctly. Please try again.");
    }

    const jsonString = jsonMatch[1] || jsonMatch[0];
    const results = JSON.parse(jsonString) as ValidationResult[];

    return { results, sources };

  } catch (error) {
    console.error("Gemini Validation Error:", error);
    throw error;
  }
};

import React from 'react';
import { LucideIcon } from 'lucide-react';

