import React, { useState } from 'react';
import { Plus, Trash2, Save, Calendar, CheckCircle } from 'lucide-react';
import { BetType, Leg, LegStatus, Slip, SlipStatus } from '../types';

interface NewSlipFormProps {
  onSave: (slip: Slip) => void;
  onCancel: () => void;
}

export const NewSlipForm: React.FC<NewSlipFormProps> = ({ onSave, onCancel }) => {
  const [stake, setStake] = useState<string>('10');
  const [legs, setLegs] = useState<Leg[]>([
    {
      id: crypto.randomUUID(),
      matchName: '',
      date: new Date().toISOString().split('T')[0],
      type: BetType.MATCH_WINNER,
      selection: 'Home',
      status: LegStatus.PENDING,
    }
  ]);

  // Calculate odds roughly (manual input usually, but we'll mock simple combined odds if we wanted to auto-calculate)
  const [totalOdds, setTotalOdds] = useState<string>('1.00');

  const addLeg = () => {
    setLegs([
      ...legs,
      {
        id: crypto.randomUUID(),
        matchName: '',
        date: new Date().toISOString().split('T')[0],
        type: BetType.MATCH_WINNER,
        selection: 'Home',
        status: LegStatus.PENDING,
      }
    ]);
  };

  const removeLeg = (id: string) => {
    if (legs.length > 1) {
      setLegs(legs.filter(l => l.id !== id));
    }
  };

  const updateLeg = (id: string, field: keyof Leg, value: any) => {
    setLegs(legs.map(l => {
      if (l.id === id) {
        const updated = { ...l, [field]: value };
        // Reset selection if type changes to avoid invalid states
        if (field === 'type') {
           if (value === BetType.MATCH_WINNER) updated.selection = 'Home';
           if (value === BetType.BTTS) updated.selection = 'Yes';
           if (value === BetType.OVER_UNDER) updated.selection = 'Over 2.5';
        }
        return updated;
      }
      return l;
    }));
  };

  const handleSave = () => {
    if (legs.some(l => !l.matchName)) {
      alert("Please enter all match names.");
      return;
    }

    const numStake = parseFloat(stake) || 0;
    const numOdds = parseFloat(totalOdds) || 1;

    const newSlip: Slip = {
      id: crypto.randomUUID(),
      createdAt: Date.now(),
      legs,
      stake: numStake,
      odds: numOdds,
      potentialReturn: numStake * numOdds,
      status: SlipStatus.PENDING,
    };

    onSave(newSlip);
  };

  return (
    <div className="bg-surface rounded-xl shadow-xl border border-slate-700 overflow-hidden">
      <div className="p-6 border-b border-slate-700 flex justify-between items-center bg-slate-800">
        <h2 className="text-xl font-bold text-white flex items-center gap-2">
          <Plus className="text-primary" /> Create New Bet Slip
        </h2>
      </div>

      <div className="p-6 space-y-6">

        {/* Legs Section */}
        <div className="space-y-4">
          <label className="text-sm font-medium text-slate-400 uppercase tracking-wider">Selections</label>

          {legs.map((leg, index) => (
            <div key={leg.id} className="grid grid-cols-1 md:grid-cols-12 gap-4 p-4 bg-slate-900/50 rounded-lg border border-slate-700 hover:border-slate-600 transition-colors">
              <div className="md:col-span-4 space-y-1">
                <label className="text-xs text-slate-500">Match</label>
                <input
                  type="text"
                  value={leg.matchName}
                  onChange={(e) => updateLeg(leg.id, 'matchName', e.target.value)}
                  placeholder="e.g. Arsenal vs Liverpool"
                  className="w-full bg-slate-800 border border-slate-600 rounded px-3 py-2 text-white text-sm focus:outline-none focus:border-primary placeholder-slate-600"
                />
              </div>

              <div className="md:col-span-2 space-y-1">
                <label className="text-xs text-slate-500">Date</label>
                <div className="relative">
                  <input
                    type="date"
                    value={leg.date}
                    onChange={(e) => updateLeg(leg.id, 'date', e.target.value)}
                    className="w-full bg-slate-800 border border-slate-600 rounded px-3 py-2 text-white text-sm focus:outline-none focus:border-primary"
                  />
                </div>
              </div>

              <div className="md:col-span-2 space-y-1">
                <label className="text-xs text-slate-500">Market</label>
                <select
                  value={leg.type}
                  onChange={(e) => updateLeg(leg.id, 'type', e.target.value)}
                  className="w-full bg-slate-800 border border-slate-600 rounded px-3 py-2 text-white text-sm focus:outline-none focus:border-primary"
                >
                  <option value={BetType.MATCH_WINNER}>1X2 Winner</option>
                  <option value={BetType.BTTS}>Both Teams To Score</option>
                  <option value={BetType.OVER_UNDER}>Over/Under</option>
                </select>
              </div>

              <div className="md:col-span-3 space-y-1">
                <label className="text-xs text-slate-500">Selection</label>
                {leg.type === BetType.MATCH_WINNER && (
                  <select
                    value={leg.selection}
                    onChange={(e) => updateLeg(leg.id, 'selection', e.target.value)}
                    className="w-full bg-slate-800 border border-slate-600 rounded px-3 py-2 text-white text-sm focus:outline-none focus:border-primary"
                  >
                    <option value="Home">Home Win (1)</option>
                    <option value="Draw">Draw (X)</option>
                    <option value="Away">Away Win (2)</option>
                  </select>
                )}
                {leg.type === BetType.BTTS && (
                  <select
                    value={leg.selection}
                    onChange={(e) => updateLeg(leg.id, 'selection', e.target.value)}
                    className="w-full bg-slate-800 border border-slate-600 rounded px-3 py-2 text-white text-sm focus:outline-none focus:border-primary"
                  >
                    <option value="Yes">Yes</option>
                    <option value="No">No</option>
                  </select>
                )}
                {leg.type === BetType.OVER_UNDER && (
                  <div className="flex gap-2">
                     <select
                        value={leg.selection.split(' ')[0]} // Over/Under
                        onChange={(e) => updateLeg(leg.id, 'selection', `${e.target.value} ${leg.selection.split(' ')[1]}`)}
                        className="w-1/2 bg-slate-800 border border-slate-600 rounded px-2 py-2 text-white text-sm"
                      >
                        <option value="Over">Over</option>
                        <option value="Under">Under</option>
                      </select>
                       <select
                        value={leg.selection.split(' ')[1]} // Val
                        onChange={(e) => updateLeg(leg.id, 'selection', `${leg.selection.split(' ')[0]} ${e.target.value}`)}
                        className="w-1/2 bg-slate-800 border border-slate-600 rounded px-2 py-2 text-white text-sm"
                      >
                        <option value="0.5">0.5</option>
                        <option value="1.5">1.5</option>
                        <option value="2.5">2.5</option>
                        <option value="3.5">3.5</option>
                      </select>
                  </div>
                )}
              </div>

              <div className="md:col-span-1 flex items-end justify-center pb-1">
                <button 
                  onClick={() => removeLeg(leg.id)}
                  disabled={legs.length === 1}
                  className={`p-2 rounded hover:bg-red-500/20 text-red-400 hover:text-red-500 transition-colors ${legs.length === 1 ? 'opacity-50 cursor-not-allowed' : ''}`}
                >
                  <Trash2 size={18} />
                </button>
              </div>
            </div>
          ))}

          <button 
            onClick={addLeg}
            className="w-full py-3 border border-dashed border-slate-600 rounded-lg text-slate-400 hover:text-white hover:border-slate-500 hover:bg-slate-800 transition-all flex items-center justify-center gap-2"
          >
            <Plus size={18} /> Add Another Match
          </button>
        </div>

        {/* Totals Section */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 pt-6 border-t border-slate-700">
           <div>
              <label className="text-sm font-medium text-slate-400 block mb-2">Total Stake ($)</label>
              <input 
                type="number" 
                value={stake}
                onChange={(e) => setStake(e.target.value)}
                className="w-full bg-slate-800 border border-slate-600 rounded px-4 py-3 text-white font-bold focus:outline-none focus:border-primary"
              />
           </div>
           <div>
              <label className="text-sm font-medium text-slate-400 block mb-2">Total Odds</label>
              <input 
                type="number" 
                value={totalOdds}
                onChange={(e) => setTotalOdds(e.target.value)}
                className="w-full bg-slate-800 border border-slate-600 rounded px-4 py-3 text-white font-bold focus:outline-none focus:border-primary"
              />
           </div>
        </div>

        <div className="bg-primary/10 rounded-lg p-4 flex justify-between items-center border border-primary/20">
          <span className="text-primary font-medium">Potential Return</span>
          <span className="text-2xl font-bold text-primary">
            ${((parseFloat(stake) || 0) * (parseFloat(totalOdds) || 0)).toFixed(2)}
          </span>
        </div>

        <div className="flex gap-4 justify-end pt-4">
          <button 
            onClick={onCancel}
            className="px-6 py-3 rounded-lg font-medium text-slate-400 hover:text-white hover:bg-slate-800 transition-colors"
          >
            Cancel
          </button>
          <button 
            onClick={handleSave}
            className="px-8 py-3 rounded-lg font-bold bg-primary hover:bg-blue-600 text-white shadow-lg shadow-blue-500/20 transition-all flex items-center gap-2"
          >
            <Save size={18} /> Save Bet Slip
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { ChevronDown, ChevronUp, RefreshCw, Trophy, XCircle, Clock, Check, ExternalLink } from 'lucide-react';
import { Slip, SlipStatus, Leg, LegStatus } from '../types';
import { validateSlipWithGemini } from '../services/geminiService';

interface SlipListProps {
  slips: Slip[];
  onUpdateSlip: (updatedSlip: Slip) => void;
}

export const SlipList: React.FC<SlipListProps> = ({ slips, onUpdateSlip }) => {
  if (slips.length === 0) {
    return (
      <div className="text-center py-20 bg-surface rounded-xl border border-slate-700">
        <div className="inline-block p-4 rounded-full bg-slate-800 mb-4">
          <Trophy className="text-slate-600" size={32} />
        </div>
        <h3 className="text-lg font-medium text-white">No active bets</h3>
        <p className="text-slate-400">Create a new bet slip to get started.</p>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {slips.map(slip => (
        <SlipCard key={slip.id} slip={slip} onUpdate={onUpdateSlip} />
      ))}
    </div>
  );
};

interface SlipCardProps {
  slip: Slip;
  onUpdate: (slip: Slip) => void;
}

const SlipCard: React.FC<SlipCardProps> = ({ slip, onUpdate }) => {
  const [expanded, setExpanded] = useState(false);
  const [checking, setChecking] = useState(false);

  const getStatusColor = (status: SlipStatus | LegStatus) => {
    switch (status) {
      case 'WON': return 'text-success bg-success/10 border-success/20';
      case 'LOST': return 'text-danger bg-danger/10 border-danger/20';
      case 'VOID': return 'text-warning bg-warning/10 border-warning/20';
      default: return 'text-slate-400 bg-slate-700/50 border-slate-600';
    }
  };

  const getStatusIcon = (status: SlipStatus | LegStatus) => {
    switch (status) {
      case 'WON': return <Check size={16} />;
      case 'LOST': return <XCircle size={16} />;
      case 'PENDING': return <Clock size={16} />;
      default: return null;
    }
  };

  const handleAICheck = async (e: React.MouseEvent) => {
    e.stopPropagation();
    if (checking || slip.status !== SlipStatus.PENDING) return;

    setChecking(true);
    try {
      const response = await validateSlipWithGemini(slip);

      const updatedLegs = slip.legs.map(leg => {
        const update = response.results.find(r => r.legId === leg.id);
        if (update) {
          return { ...leg, status: update.status, resultScore: update.score };
        }
        return leg;
      });

      // Determine overall slip status
      let newStatus = SlipStatus.WON;
      if (updatedLegs.some(l => l.status === LegStatus.LOST)) newStatus = SlipStatus.LOST;
      else if (updatedLegs.some(l => l.status === LegStatus.PENDING)) newStatus = SlipStatus.PENDING;
      else if (updatedLegs.every(l => l.status === LegStatus.VOID)) newStatus = SlipStatus.VOID;

      onUpdate({
        ...slip,
        legs: updatedLegs,
        status: newStatus,
        groundingUrls: response.sources
      });
    } catch (error) {
      alert("Failed to update matches via AI. Please try again.");
    } finally {
      setChecking(false);
    }
  };

  return (
    <div className={`bg-surface rounded-xl border transition-all overflow-hidden ${slip.status === SlipStatus.WON ? 'border-success/30 shadow-success/5' : slip.status === SlipStatus.LOST ? 'border-danger/30' : 'border-slate-700'}`}>
      {/* Header */}
      <div 
        className="p-5 flex items-center justify-between cursor-pointer hover:bg-slate-800/50 transition-colors"
        onClick={() => setExpanded(!expanded)}
      >
        <div className="flex items-center gap-4">
          <div className={`w-10 h-10 rounded-full flex items-center justify-center border ${getStatusColor(slip.status)}`}>
            {getStatusIcon(slip.status)}
          </div>
          <div>
             <div className="flex items-center gap-2">
               <h4 className="font-bold text-white text-lg">
                 {slip.legs.length} Match Accumulator
               </h4>
               <span className="text-xs text-slate-500 font-mono">
                 {new Date(slip.createdAt).toLocaleDateString()}
               </span>
             </div>
             <p className="text-slate-400 text-sm">
               Stake: <span className="text-white font-medium">${slip.stake}</span> • 
               Odds: <span className="text-white font-medium">{slip.odds}</span> • 
               Return: <span className={`font-bold ${slip.status === 'WON' ? 'text-success' : 'text-primary'}`}>${slip.potentialReturn.toFixed(2)}</span>
             </p>
          </div>
        </div>

        <div className="flex items-center gap-3">
          {slip.status === SlipStatus.PENDING && (
            <button 
              onClick={handleAICheck}
              disabled={checking}
              className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs font-bold uppercase tracking-wide transition-all ${checking ? 'bg-slate-700 text-slate-400' : 'bg-primary/20 text-primary hover:bg-primary/30'}`}
            >
              <RefreshCw size={14} className={checking ? "animate-spin" : ""} />
              {checking ? 'Checking AI...' : 'Check Status'}
            </button>
          )}

          {expanded ? <ChevronUp className="text-slate-500" /> : <ChevronDown className="text-slate-500" />}
        </div>
      </div>

      {/* Expanded Content */}
      {expanded && (
        <div className="border-t border-slate-700 bg-slate-900/30 p-4">
          <div className="space-y-2">
             {slip.legs.map((leg, idx) => (
                <div key={leg.id} className="flex items-center justify-between p-3 rounded-lg bg-slate-800/50 border border-slate-700/50">
                   <div className="flex-1">
                      <div className="flex justify-between items-start">
                         <h5 className="text-white font-medium">{leg.matchName}</h5>
                         <span className="text-xs text-slate-500">{leg.date}</span>
                      </div>
                      <div className="flex items-center gap-2 mt-1">
                         <span className="text-xs font-bold px-2 py-0.5 rounded bg-slate-700 text-slate-300">{leg.type}</span>
                         <span className="text-sm text-primary">Prediction: {leg.selection}</span>
                      </div>
                      {leg.resultScore && (
                        <div className="mt-2 text-xs text-slate-400 font-mono flex items-center gap-1">
                          Final Score: <span className="text-white font-bold">{leg.resultScore}</span>
                        </div>
                      )}
                   </div>
                   <div className="ml-4">
                      <span className={`text-xs font-bold px-2 py-1 rounded border ${getStatusColor(leg.status)}`}>
                        {leg.status}
                      </span>
                   </div>
                </div>
             ))}
          </div>

          {/* Grounding Sources */}
          {slip.groundingUrls && slip.groundingUrls.length > 0 && (
            <div className="mt-4 pt-4 border-t border-slate-700/50">
               <h6 className="text-xs font-bold text-slate-500 uppercase tracking-wider mb-2 flex items-center gap-1">
                 <ExternalLink size={10} /> Verified Sources
               </h6>
               <div className="flex flex-wrap gap-2">
                  {slip.groundingUrls.map((url, i) => (
                    <a 
                      key={i} 
                      href={url} 
                      target="_blank" 
                      rel="noopener noreferrer"
                      className="text-xs text-primary hover:underline truncate max-w-xs"
                    >
                      Source {i+1}
                    </a>
                  ))}
               </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { LayoutDashboard, PlusCircle, History, Wallet, TrendingUp, Trophy } from 'lucide-react';
import { Slip, SlipStatus, Stats } from './types';
import { StatsCard } from './components/StatsCard';
import { SlipList } from './components/SlipList';
import { NewSlipForm } from './components/NewSlipForm';

// Initial Mock Data
const MOCK_SLIPS: Slip[] = [];

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'active' | 'settled' | 'create'>('dashboard');
  const [slips, setSlips] = useState<Slip[]>(MOCK_SLIPS);
  const [stats, setStats] = useState<Stats>({
    totalSlips: 0,
    wins: 0,
    losses: 0,
    winRate: 0,
    totalStaked: 0,
    totalReturned: 0,
    profit: 0,
    roi: 0
  });

  // Calculate Stats
  useEffect(() => {
    const settledSlips = slips.filter(s => s.status === SlipStatus.WON || s.status === SlipStatus.LOST);
    const totalSlips = settledSlips.length;
    const wins = settledSlips.filter(s => s.status === SlipStatus.WON).length;
    const losses = settledSlips.filter(s => s.status === SlipStatus.LOST).length;
    const winRate = totalSlips > 0 ? (wins / totalSlips) * 100 : 0;

    const totalStaked = slips.reduce((acc, s) => acc + s.stake, 0);
    // Only count returns from settled wins
    const totalReturned = settledSlips
      .filter(s => s.status === SlipStatus.WON)
      .reduce((acc, s) => acc + s.potentialReturn, 0);

    // Profit considers all settled stakes vs returns
    // We should probably only subtract stake from settled bets for 'Profit' accuracy, 
    // but 'Total Staked' usually implies everything invested. 
    // Let's keep it simple: Profit = Returns - (Stakes of settled bets)
    const settledStaked = settledSlips.reduce((acc, s) => acc + s.stake, 0);
    const profit = totalReturned - settledStaked;
    const roi = settledStaked > 0 ? (profit / settledStaked) * 100 : 0;

    setStats({
      totalSlips,
      wins,
      losses,
      winRate,
      totalStaked,
      totalReturned,
      profit,
      roi
    });
  }, [slips]);

  const handleSaveSlip = (newSlip: Slip) => {
    setSlips([newSlip, ...slips]);
    setActiveTab('active');
  };

