             <NavButton active={activeTab === 'settled'} onClick={() => setActiveTab('settled')} icon={History} label="History" />
          </div>
          <button 
            onClick={() => setActiveTab('create')}
            className="bg-primary hover:bg-blue-600 text-white px-4 py-2 rounded-lg text-sm font-bold flex items-center gap-2 transition-colors shadow-lg shadow-blue-500/20"
          >
