        <MobileNavButton active={activeTab === 'dashboard'} onClick={() => setActiveTab('dashboard')} icon={LayoutDashboard} label="Overview" />
        <MobileNavButton active={activeTab === 'active'} onClick={() => setActiveTab('active')} icon={Wallet} label="Active" badge={activeSlips.length} />
        <MobileNavButton active={activeTab === 'settled'} onClick={() => setActiveTab('settled')} icon={History} label="History" />
        <MobileNavButton active={activeTab === 'create'} onClick={() => setActiveTab('create')} icon={PlusCircle} label="New" />
      </div>

      {/* Main Content */}
      <main className="max-w-5xl mx-auto px-4 py-8">

        {activeTab === 'dashboard' && (
