               <StatsCard title="ROI" value={`${stats.roi.toFixed(1)}%`} icon={TrendingUp} color={stats.roi >= 0 ? 'text-success' : 'text-danger'} />
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
              <div className="lg:col-span-2 space-y-4">
