import { GoogleGenAI } from "@google/genai";
import { Slip, Leg, LegStatus, ValidationResult } from "../types";

// Initialize Gemini Client
const apiKey = process.env.API_KEY || '';
const ai = new GoogleGenAI({ apiKey });

export interface ValidationResponse {
  results: ValidationResult[];
  sources: string[];
}

export const validateSlipWithGemini = async (slip: Slip): Promise<ValidationResponse> => {
  if (!apiKey) {
    throw new Error("API Key is missing.");
  }

  // Construct a prompt that describes the bet slip
  const legsDescription = slip.legs.map(leg => 
    `- ID: ${leg.id} | Match: ${leg.matchName} | Date: ${leg.date} | Bet Type: ${leg.type} | Selection: ${leg.selection}`
  ).join('\n');

  const prompt = `
    I have a sports betting slip with the following matches and predictions. 
    Please search for the final match results (scores) using Google Search.

    For each leg, determine if the bet is WON, LOST, or VOID based on the final score.

    Bet Types Logic:
    - 1X2: Home (1) means Home team wins, Draw (X) means draw, Away (2) means Away team wins.
    - BTTS: "Yes" means both teams scored > 0. "No" means at least one team scored 0.
    - OVER_UNDER: "Over X.5" means total goals > X.5. "Under X.5" means total goals < X.5.
    - DOUBLE_CHANCE: "1X" (Home Win or Draw), "X2" (Away Win or Draw), "12" (Home Win or Away Win).

    Bet Slip Details:
    ${legsDescription}

    IMPORTANT OUTPUT FORMAT:
    You must return the data in a raw JSON array format inside a code block, like this:
    \`\`\`json
    [
      { "legId": "...", "status": "WON", "score": "2-1" },
      { "legId": "...", "status": "LOST", "score": "0-0" }
    ]
    \`\`\`
    Valid statuses are: WON, LOST, VOID, PENDING (if match hasn't started/finished).
    If you cannot find a result, mark as PENDING and score as "?".
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
      },
    });

    const text = response.text || '';

    // Extract Grounding Metadata (Sources)
    const sources: string[] = [];
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
    chunks.forEach(chunk => {
      if (chunk.web?.uri) {
        sources.push(chunk.web.uri);
      }
    });

    // Extract JSON from text
    const jsonMatch = text.match(/```json\s*([\s\S]*?)\s*```/) || text.match(/\[\s*\{[\s\S]*\}\s*\]/);

    if (!jsonMatch) {
      console.error("Failed to parse JSON from Gemini response:", text);
      throw new Error("AI could not format the results correctly. Please try again.");
    }

    const jsonString = jsonMatch[1] || jsonMatch[0];
    const results = JSON.parse(jsonString) as ValidationResult[];

    return { results, sources };

  } catch (error) {
    console.error("Gemini Validation Error:", error);
    throw error;
  }
};

import React, { useState } from 'react';
import { Plus, Trash2, Save, Calendar, CheckCircle, ClipboardPaste, X } from 'lucide-react';
import { BetType, Leg, LegStatus, Slip, SlipStatus } from '../types';

interface NewSlipFormProps {
  onSave: (slip: Slip) => void;
  onCancel: () => void;
}

export const NewSlipForm: React.FC<NewSlipFormProps> = ({ onSave, onCancel }) => {
  const [stake, setStake] = useState<string>('10');
  const [legs, setLegs] = useState<Leg[]>([
    {
      id: crypto.randomUUID(),
      matchName: '',
      date: new Date().toISOString().split('T')[0],
      type: BetType.MATCH_WINNER,
      selection: 'Home',
      status: LegStatus.PENDING,
    }
  ]);
  const [totalOdds, setTotalOdds] = useState<string>('1.00');

  // Import State
  const [showImport, setShowImport] = useState(false);
  const [importText, setImportText] = useState('');

  const addLeg = () => {
    setLegs([
      ...legs,
      {
        id: crypto.randomUUID(),
        matchName: '',
        date: new Date().toISOString().split('T')[0],
        type: BetType.MATCH_WINNER,
        selection: 'Home',
        status: LegStatus.PENDING,
      }
    ]);
  };

  const removeLeg = (id: string) => {
    if (legs.length > 1) {
      setLegs(legs.filter(l => l.id !== id));
    }
  };

  const updateLeg = (id: string, field: keyof Leg, value: any) => {
    setLegs(legs.map(l => {
      if (l.id === id) {
        const updated = { ...l, [field]: value };
        // Reset selection if type changes to avoid invalid states
        if (field === 'type') {
           if (value === BetType.MATCH_WINNER) updated.selection = 'Home';
           if (value === BetType.BTTS) updated.selection = 'Yes';
           if (value === BetType.OVER_UNDER) updated.selection = 'Over 2.5';
           if (value === BetType.DOUBLE_CHANCE) updated.selection = '1X';
        }
        return updated;
      }
      return l;
    }));
  };

  const handleImport = () => {
    if (!importText.trim()) return;

    try {
      // Split by double newlines or detect blocks. 
      // The provided format has blocks of lines.
      // We will look for patterns of 4-5 lines.
      const lines = importText.split('\n').map(l => l.trim()).filter(l => l.length > 0);

      const newLegs: Leg[] = [];
      let calculatedOdds = 1;

      // We process the lines in chunks. 
      // Based on the example:
      // Line 1: Selection (Torino FC)
      // Line 2: Odds (2.00)
      // Line 3: Market (1X2)
      // Line 4: Match (Torino FC - US Cremonese)
      // Line 5: Date (Today 16:00)

      let i = 0;
      while (i < lines.length) {
        // Look ahead to find a valid block structure
        if (i + 4 > lines.length) break;

        const selectionRaw = lines[i];
        const oddsRaw = lines[i+1];
        const marketRaw = lines[i+2];
        const matchRaw = lines[i+3];
        const dateRaw = lines[i+4];

        // Validation check - Odds should be a number
        const oddsVal = parseFloat(oddsRaw);
        if (isNaN(oddsVal)) {
           // Maybe the block structure is shifted or variable?
           // Skip one line and try again to find alignment
           i++;
           continue;
        }

        i += 5; // Advance cursor

        calculatedOdds *= oddsVal;

        let type = BetType.MATCH_WINNER;
        let selection = 'Home';

        // Map Market & Selection
        if (marketRaw.includes('1X2') || marketRaw === 'Match Winner') {
          type = BetType.MATCH_WINNER;
          const teams = matchRaw.split(/\s+-\s+|\s+v\s+/i); // Split by " - " or " v "
          if (teams.length >= 2) {
             const home = teams[0].trim();
             const away = teams[1].trim();

             if (selectionRaw === home) selection = 'Home';
             else if (selectionRaw === away) selection = 'Away';
             else if (selectionRaw.toLowerCase().includes('draw')) selection = 'Draw';
             else selection = 'Home'; // Fallback
          }
        } 
        else if (marketRaw.includes('Total') || selectionRaw.includes('Over') || selectionRaw.includes('Under')) {
          type = BetType.OVER_UNDER;
          // Clean "Over (1.5)" to "Over 1.5"
          selection = selectionRaw.replace(/[()]/g, '').trim();
        } 
        else if (marketRaw.includes('Double Chance')) {
          type = BetType.DOUBLE_CHANCE;
          // Try to map "Team Or Draw" to 1X/X2
          const teams = matchRaw.split(/\s+-\s+|\s+v\s+/i);
          if (teams.length >= 2) {
            const home = teams[0].trim();
            const away = teams[1].trim();
            if (selectionRaw.includes(home)) selection = '1X';
            else if (selectionRaw.includes(away)) selection = 'X2';
            else selection = '12';
          } else {
             selection = '1X'; // Fallback
          }
        }
        else if (marketRaw.toLowerCase().includes('both teams')) {
           type = BetType.BTTS;
           selection = selectionRaw.toLowerCase().includes('yes') ? 'Yes' : 'No';
        }

        // Parse Date
        let date = new Date().toISOString().split('T')[0];
        if (dateRaw.toLowerCase().includes('today')) {
           date = new Date().toISOString().split('T')[0];
        } else if (dateRaw.toLowerCase().includes('tomorrow')) {
           const d = new Date();
           d.setDate(d.getDate() + 1);
           date = d.toISOString().split('T')[0];
        }

        newLegs.push({
          id: crypto.randomUUID(),
          matchName: matchRaw,
          date: date,
          type: type,
          selection: selection,
          status: LegStatus.PENDING
        });
      }

      if (newLegs.length > 0) {
        setLegs(newLegs);
        setTotalOdds(calculatedOdds.toFixed(2));
        setShowImport(false);
        setImportText('');
      } else {
        alert("Could not parse any bets. Please check the format.");
      }

    } catch (e) {
      console.error(e);
      alert("Error parsing the text.");
    }
  };

  const handleSave = () => {
    if (legs.some(l => !l.matchName)) {
      alert("Please enter all match names.");
      return;
    }

    const numStake = parseFloat(stake) || 0;
    const numOdds = parseFloat(totalOdds) || 1;

    const newSlip: Slip = {
      id: crypto.randomUUID(),
      createdAt: Date.now(),
      legs,
      stake: numStake,
      odds: numOdds,
      potentialReturn: numStake * numOdds,
      status: SlipStatus.PENDING,
    };

    onSave(newSlip);
  };

  return (
    <div className="bg-surface rounded-xl shadow-xl border border-slate-700 overflow-hidden relative">
      <div className="p-6 border-b border-slate-700 flex justify-between items-center bg-slate-800">
        <h2 className="text-xl font-bold text-white flex items-center gap-2">
          <Plus className="text-primary" /> Create New Bet Slip
        </h2>
        <button 
          onClick={() => setShowImport(true)}
          className="text-xs flex items-center gap-1 bg-slate-700 hover:bg-slate-600 text-white px-3 py-1.5 rounded transition-colors"
        >
          <ClipboardPaste size={14} /> Import from Text
        </button>
      </div>

      {/* Import Modal Overlay */}
      {showImport && (
        <div className="absolute inset-0 z-50 bg-slate-900/95 flex flex-col items-center justify-center p-6 animate-fade-in">
           <div className="w-full max-w-lg bg-surface border border-slate-600 rounded-xl p-6 shadow-2xl">
              <div className="flex justify-between items-center mb-4">
                 <h3 className="text-white font-bold flex items-center gap-2">
                   <ClipboardPaste className="text-primary" /> Paste Bet Slip
                 </h3>
                 <button onClick={() => setShowImport(false)} className="text-slate-400 hover:text-white">
                   <X size={20} />
                 </button>
              </div>
              <textarea
                value={importText}
                onChange={(e) => setImportText(e.target.value)}
                placeholder={`Paste your bet details here...\n\nExample:\nTorino FC\n2.00\n1X2\nTorino FC - US Cremonese\nToday 16:00`}
                className="w-full h-64 bg-slate-900 border border-slate-700 rounded-lg p-4 text-xs font-mono text-slate-300 focus:outline-none focus:border-primary resize-none"
              />
              <div className="mt-4 flex justify-end gap-3">
                 <button 
                   onClick={() => setShowImport(false)}
                   className="px-4 py-2 rounded text-slate-400 hover:text-white hover:bg-slate-800"
                 >
                   Cancel
                 </button>
                 <button 
                   onClick={handleImport}
                   className="px-6 py-2 rounded bg-primary text-white font-bold hover:bg-blue-600"
                 >
                   Parse & Import
                 </button>
              </div>
           </div>
        </div>
      )}

      <div className="p-6 space-y-6">

        {/* Legs Section */}
        <div className="space-y-4">
          <label className="text-sm font-medium text-slate-400 uppercase tracking-wider">Selections</label>

          {legs.map((leg, index) => (
            <div key={leg.id} className="grid grid-cols-1 md:grid-cols-12 gap-4 p-4 bg-slate-900/50 rounded-lg border border-slate-700 hover:border-slate-600 transition-colors">
              <div className="md:col-span-4 space-y-1">
                <label className="text-xs text-slate-500">Match</label>
                <input
                  type="text"
                  value={leg.matchName}
                  onChange={(e) => updateLeg(leg.id, 'matchName', e.target.value)}
                  placeholder="e.g. Arsenal vs Liverpool"
                  className="w-full bg-slate-800 border border-slate-600 rounded px-3 py-2 text-white text-sm focus:outline-none focus:border-primary placeholder-slate-600"
                />
              </div>

              <div className="md:col-span-2 space-y-1">
                <label className="text-xs text-slate-500">Date</label>
                <div className="relative">
                  <input
                    type="date"
                    value={leg.date}
                    onChange={(e) => updateLeg(leg.id, 'date', e.target.value)}
                    className="w-full bg-slate-800 border border-slate-600 rounded px-3 py-2 text-white text-sm focus:outline-none focus:border-primary"
                  />
                </div>
              </div>

              <div className="md:col-span-2 space-y-1">
                <label className="text-xs text-slate-500">Market</label>
                <select
                  value={leg.type}
                  onChange={(e) => updateLeg(leg.id, 'type', e.target.value)}
                  className="w-full bg-slate-800 border border-slate-600 rounded px-3 py-2 text-white text-sm focus:outline-none focus:border-primary"
                >
                  <option value={BetType.MATCH_WINNER}>1X2 Winner</option>
                  <option value={BetType.DOUBLE_CHANCE}>Double Chance</option>
                  <option value={BetType.BTTS}>Both Teams To Score</option>
                  <option value={BetType.OVER_UNDER}>Over/Under</option>
                </select>
              </div>

              <div className="md:col-span-3 space-y-1">
                <label className="text-xs text-slate-500">Selection</label>
                {leg.type === BetType.MATCH_WINNER && (
                  <select
                    value={leg.selection}
                    onChange={(e) => updateLeg(leg.id, 'selection', e.target.value)}
                    className="w-full bg-slate-800 border border-slate-600 rounded px-3 py-2 text-white text-sm focus:outline-none focus:border-primary"
                  >
                    <option value="Home">Home Win (1)</option>
                    <option value="Draw">Draw (X)</option>
                    <option value="Away">Away Win (2)</option>
                  </select>
                )}
                {leg.type === BetType.DOUBLE_CHANCE && (
                  <select
                    value={leg.selection}
                    onChange={(e) => updateLeg(leg.id, 'selection', e.target.value)}
                    className="w-full bg-slate-800 border border-slate-600 rounded px-3 py-2 text-white text-sm focus:outline-none focus:border-primary"
                  >
                    <option value="1X">Home or Draw (1X)</option>
                    <option value="X2">Away or Draw (X2)</option>
                    <option value="12">Home or Away (12)</option>
                  </select>
                )}
                {leg.type === BetType.BTTS && (
                  <select
                    value={leg.selection}
                    onChange={(e) => updateLeg(leg.id, 'selection', e.target.value)}
                    className="w-full bg-slate-800 border border-slate-600 rounded px-3 py-2 text-white text-sm focus:outline-none focus:border-primary"
                  >
                    <option value="Yes">Yes</option>
                    <option value="No">No</option>
                  </select>
                )}
                {leg.type === BetType.OVER_UNDER && (
                  <div className="flex gap-2">
                     <select
                        value={leg.selection.split(' ')[0]} // Over/Under
                        onChange={(e) => updateLeg(leg.id, 'selection', `${e.target.value} ${leg.selection.split(' ')[1] || '2.5'}`)}
                        className="w-1/2 bg-slate-800 border border-slate-600 rounded px-2 py-2 text-white text-sm"
                      >
                        <option value="Over">Over</option>
                        <option value="Under">Under</option>
                      </select>
                       <select
                        value={leg.selection.split(' ')[1]} // Val
                        onChange={(e) => updateLeg(leg.id, 'selection', `${leg.selection.split(' ')[0] || 'Over'} ${e.target.value}`)}
                        className="w-1/2 bg-slate-800 border border-slate-600 rounded px-2 py-2 text-white text-sm"
                      >
                        <option value="0.5">0.5</option>
                        <option value="1.5">1.5</option>
                        <option value="2.5">2.5</option>
                        <option value="3.5">3.5</option>
                        <option value="4.5">4.5</option>
                      </select>
                  </div>
                )}
              </div>

              <div className="md:col-span-1 flex items-end justify-center pb-1">
                <button 
                  onClick={() => removeLeg(leg.id)}
                  disabled={legs.length === 1}
                  className={`p-2 rounded hover:bg-red-500/20 text-red-400 hover:text-red-500 transition-colors ${legs.length === 1 ? 'opacity-50 cursor-not-allowed' : ''}`}
                >
                  <Trash2 size={18} />
                </button>
              </div>
            </div>
          ))}

          <button 
            onClick={addLeg}
            className="w-full py-3 border border-dashed border-slate-600 rounded-lg text-slate-400 hover:text-white hover:border-slate-500 hover:bg-slate-800 transition-all flex items-center justify-center gap-2"
          >
            <Plus size={18} /> Add Another Match
          </button>
        </div>

        {/* Totals Section */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 pt-6 border-t border-slate-700">
           <div>
              <label className="text-sm font-medium text-slate-400 block mb-2">Total Stake ($)</label>
              <input 
                type="number" 
                value={stake}
                onChange={(e) => setStake(e.target.value)}
                className="w-full bg-slate-800 border border-slate-600 rounded px-4 py-3 text-white font-bold focus:outline-none focus:border-primary"
              />
           </div>
           <div>
              <label className="text-sm font-medium text-slate-400 block mb-2">Total Odds</label>
              <input 
                type="number" 
                value={totalOdds}
                onChange={(e) => setTotalOdds(e.target.value)}
                className="w-full bg-slate-800 border border-slate-600 rounded px-4 py-3 text-white font-bold focus:outline-none focus:border-primary"
              />
           </div>
        </div>

        <div className="bg-primary/10 rounded-lg p-4 flex justify-between items-center border border-primary/20">
          <span className="text-primary font-medium">Potential Return</span>
          <span className="text-2xl font-bold text-primary">
            ${((parseFloat(stake) || 0) * (parseFloat(totalOdds) || 0)).toFixed(2)}
          </span>
        </div>

        <div className="flex gap-4 justify-end pt-4">
          <button 
            onClick={onCancel}
            className="px-6 py-3 rounded-lg font-medium text-slate-400 hover:text-white hover:bg-slate-800 transition-colors"
          >
            Cancel
          </button>
          <button 
            onClick={handleSave}
            className="px-8 py-3 rounded-lg font-bold bg-primary hover:bg-blue-600 text-white shadow-lg shadow-blue-500/20 transition-all flex items-center gap-2"
          >
            <Save size={18} /> Save Bet Slip
          </button>
        </div>
      </div>
    </div>
  );
};

export enum BetType {
  MATCH_WINNER = '1X2',
  BTTS = 'BTTS',
  OVER_UNDER = 'OVER_UNDER',
  DOUBLE_CHANCE = 'DOUBLE_CHANCE'
}

export enum LegStatus {
  PENDING = 'PENDING',
  WON = 'WON',
  LOST = 'LOST',
  VOID = 'VOID'
}

export enum SlipStatus {
  PENDING = 'PENDING',
  WON = 'WON',
  LOST = 'LOST',
  VOID = 'VOID'
}

