import { GoogleGenAI } from "@google/genai";
import { Slip, Leg, LegStatus, ValidationResult } from "../types";

// Initialize Gemini Client
const apiKey = process.env.API_KEY || '';
const ai = new GoogleGenAI({ apiKey });

export interface ValidationResponse {
  results: ValidationResult[];
  sources: string[];
}

export const validateSlipWithGemini = async (slip: Slip): Promise<ValidationResponse> => {
  if (!apiKey) {
    throw new Error("API Key is missing.");
  }

  // Construct a prompt that describes the bet slip
  const legsDescription = slip.legs.map(leg => 
    `- ID: ${leg.id} | Match: ${leg.matchName} | Date: ${leg.date} | Bet Type: ${leg.type} | Selection: ${leg.selection}`
  ).join('\n');

  const prompt = `
    I have a sports betting slip with the following matches and predictions. 
    Please search for the real-time match status and results using Google Search.

    CRITICAL EXECUTION RULES:
    1. **CHECK TIME/STATUS FIRST**: Look for "FT", "Full Time", "Finished", "Live", "HT", or minute markers (e.g. "65'").
    2. **LIVE MATCHES**: If the match is currently **LIVE**, **IN-PLAY**, **HALFTIME**, or **ONGOING**, the status MUST be "PENDING". Do NOT settle the bet yet, even if the condition is met (e.g. Over 0.5 goals scored).
    3. **FUTURE MATCHES**: If the match hasn't started, status is "PENDING".
    4. **FINISHED MATCHES**: Only if the match is "Finished" or "FT", determine WON/LOST/VOID.

    Bet Types Logic (Only apply if match is FINISHED):
    - 1X2: Home (1) means Home team wins, Draw (X) means draw, Away (2) means Away team wins.
    - BTTS: "Yes" means both teams scored > 0. "No" means at least one team scored 0.
    - OVER_UNDER: "Over X.5" means total goals > X.5. "Under X.5" means total goals < X.5.
    - DOUBLE_CHANCE: "1X" (Home Win or Draw), "X2" (Away Win or Draw), "12" (Home Win or Away Win).
    - DRAW_NO_BET: If Home wins, Home selection wins. If Away wins, Away selection wins. If Draw, the status is VOID.
    - TOTAL_CORNERS: You must find the corner count. "Over X" means total corners > X. "Under X" means total corners < X.
    - BOOKINGS: You must find the card count. "Over X" means total yellow/red cards > X. "Under X" means total cards < X.
    - SENDING_OFF: "Yes" means at least one Red Card was shown in the match. "No" means zero Red Cards.
    - EXACT_GOALS: Total goals in match must equal the selection exactly.
    - ODD_EVEN: Sum of total goals. 0, 2, 4... is EVEN. 1, 3, 5... is ODD.
    - HANDICAP: "Home -1.5" means you subtract 1.5 from Home's score. Then compare. e.g. Score 2-0 with Home -1.5 becomes 0.5-0 (Home wins). Score 1-0 with Home -1.5 becomes -0.5-0 (Away wins).

    Bet Slip Details:
    ${legsDescription}

    IMPORTANT OUTPUT FORMAT:
    You must return the data in a raw JSON array format inside a code block, like this:
    \`\`\`json
    [
      { "legId": "...", "status": "WON", "score": "2-1" },
      { "legId": "...", "status": "PENDING", "score": "1-0 (65')" },
      { "legId": "...", "status": "VOID", "score": "1-1" }
    ]
    \`\`\`
    Valid statuses are: WON, LOST, VOID, PENDING.
    If the match is LIVE, the score field MUST include the current score AND time (e.g. "2-1 (Live 75')").
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
      },
    });

    const text = response.text || '';

    // Extract Grounding Metadata (Sources)
    const sources: string[] = [];
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
    chunks.forEach(chunk => {
      if (chunk.web?.uri) {
        sources.push(chunk.web.uri);
      }
    });

    // Extract JSON from text
    const jsonMatch = text.match(/```json\s*([\s\S]*?)\s*```/) || text.match(/\[\s*\{[\s\S]*\}\s*\]/);

    if (!jsonMatch) {
      console.error("Failed to parse JSON from Gemini response:", text);
      throw new Error("AI could not format the results correctly. Please try again.");
    }

    const jsonString = jsonMatch[1] || jsonMatch[0];
    const results = JSON.parse(jsonString) as ValidationResult[];

    return { results, sources };

  } catch (error) {
    console.error("Gemini Validation Error:", error);
    throw error;
  }
};

import React, { useMemo } from 'react';
import { 
  TrendingUp, 
  TrendingDown, 
  Target, 
  PieChart, 
  BarChart3, 
  DollarSign, 
  Activity,
  Percent
} from 'lucide-react';
import { Slip, SlipStatus, LegStatus, BetType, Currency, CURRENCY_SYMBOLS } from '../types';

interface StatisticsPanelProps {
  slips: Slip[];
  currency: Currency;
}

export const StatisticsPanel: React.FC<StatisticsPanelProps> = ({ slips, currency }) => {
  const symbol = CURRENCY_SYMBOLS[currency];

  const stats = useMemo(() => {
    const settledSlips = slips.filter(s => s.status === SlipStatus.WON || s.status === SlipStatus.LOST);
    const settledLegs = settledSlips.flatMap(s => s.legs).filter(l => l.status === LegStatus.WON || l.status === LegStatus.LOST);

    // Financials
    const totalStaked = slips.reduce((acc, s) => acc + s.stake, 0);
    const totalReturned = settledSlips
      .filter(s => s.status === SlipStatus.WON)
      .reduce((acc, s) => acc + s.potentialReturn, 0);
    const settledStaked = settledSlips.reduce((acc, s) => acc + s.stake, 0);
    const profit = totalReturned - settledStaked;
    const roi = settledStaked > 0 ? (profit / settledStaked) * 100 : 0;

    // Slip Stats
    const totalSettledCount = settledSlips.length;
    const wins = settledSlips.filter(s => s.status === SlipStatus.WON).length;
    const winRate = totalSettledCount > 0 ? (wins / totalSettledCount) * 100 : 0;
    const avgOdds = totalSettledCount > 0 
      ? settledSlips.reduce((acc, s) => acc + s.odds, 0) / totalSettledCount 
      : 0;

    // Market Performance (Leg based)
    const marketStats: Record<string, { total: number; wins: number }> = {};

    Object.values(BetType).forEach(type => {
      marketStats[type] = { total: 0, wins: 0 };
    });

    settledLegs.forEach(leg => {
      if (!marketStats[leg.type]) marketStats[leg.type] = { total: 0, wins: 0 };
      marketStats[leg.type].total += 1;
      if (leg.status === LegStatus.WON) {
        marketStats[leg.type].wins += 1;
      }
    });

    // Filter out markets with no bets
    const activeMarkets = Object.entries(marketStats)
      .filter(([_, data]) => data.total > 0)
      .map(([type, data]) => ({
        type,
        total: data.total,
        wins: data.wins,
        rate: (data.wins / data.total) * 100
      }))
      .sort((a, b) => b.total - a.total); // Sort by volume

    // Recent Form (Last 10 settled)
    const form = settledSlips
      .sort((a, b) => b.createdAt - a.createdAt)
      .slice(0, 10)
      .map(s => s.status);

    return {
      totalStaked,
      profit,
      roi,
      winRate,
      avgOdds,
      activeMarkets,
      form,
      totalSettledCount
    };
  }, [slips]);

  if (stats.totalSettledCount === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-20 bg-surface rounded-xl border border-borderBase text-center">
        <div className="p-4 rounded-full bg-inputBg mb-4">
          <BarChart3 className="text-textMuted" size={32} />
