    return (localStorage.getItem('smartbet_theme') as 'light' | 'dark') || 'dark';
  });

  const [currency, setCurrency] = useState<Currency>(() => {
    return (localStorage.getItem('smartbet_currency') as Currency) || 'USD';
  });

  const [showSettings, setShowSettings] = useState(false);

  const [stats, setStats] = useState<Stats>({
    totalSlips: 0,
    wins: 0,
    losses: 0,
    winRate: 0,
    totalStaked: 0,
    totalReturned: 0,
    profit: 0,
    roi: 0
  });

  // Persist State
  useEffect(() => {
    localStorage.setItem('smartbet_slips', JSON.stringify(slips));
  }, [slips]);

  useEffect(() => {
    localStorage.setItem('smartbet_theme', theme);
    const root = window.document.documentElement;
    if (theme === 'dark') {
      root.classList.add('dark');
    } else {
      root.classList.remove('dark');
    }
  }, [theme]);

  useEffect(() => {
    localStorage.setItem('smartbet_currency', currency);
  }, [currency]);


  // Calculate Stats
  useEffect(() => {
    const settledSlips = slips.filter(s => s.status === SlipStatus.WON || s.status === SlipStatus.LOST);
    const totalSlips = settledSlips.length;
    const wins = settledSlips.filter(s => s.status === SlipStatus.WON).length;
    const losses = settledSlips.filter(s => s.status === SlipStatus.LOST).length;
    const winRate = totalSlips > 0 ? (wins / totalSlips) * 100 : 0;

    const totalStaked = slips.reduce((acc, s) => acc + s.stake, 0);
    const totalReturned = settledSlips
      .filter(s => s.status === SlipStatus.WON)
      .reduce((acc, s) => acc + s.potentialReturn, 0);

    const settledStaked = settledSlips.reduce((acc, s) => acc + s.stake, 0);
    const profit = totalReturned - settledStaked;
    const roi = settledStaked > 0 ? (profit / settledStaked) * 100 : 0;

    setStats({
      totalSlips,
      wins,
      losses,
      winRate,
      totalStaked,
      totalReturned,
      profit,
      roi
    });
  }, [slips]);

  const handleSaveSlip = (newSlip: Slip) => {
    setSlips([newSlip, ...slips]);
    setActiveTab('active');
  };

  const handleUpdateSlip = (updatedSlip: Slip) => {
    setSlips(slips.map(s => s.id === updatedSlip.id ? updatedSlip : s));
  };

