               </h3>
               <button onClick={() => setShowSettings(false)} className="text-textMuted hover:text-textMain">
                 <X size={20} />
               </button>
            </div>
            <div className="p-6 space-y-6">
               {/* Theme Toggle */}
               <div className="flex items-center justify-between">
                 <span className="text-textMain font-medium">Appearance</span>
                 <div className="flex bg-inputBg rounded-lg p-1 border border-borderBase">
                    <button 
                      onClick={() => setTheme('light')}
                      className={`p-2 rounded flex items-center gap-2 text-xs font-bold transition-all ${theme === 'light' ? 'bg-surface shadow text-primary' : 'text-textMuted'}`}
                    >
                      <Sun size={14} /> Light
                    </button>
                    <button 
                      onClick={() => setTheme('dark')}
                      className={`p-2 rounded flex items-center gap-2 text-xs font-bold transition-all ${theme === 'dark' ? 'bg-surface shadow text-primary' : 'text-textMuted'}`}
                    >
                      <Moon size={14} /> Dark
                    </button>
                 </div>
               </div>

