                 >
                   <option value="USD">USD ($)</option>
                   <option value="GBP">GBP (£)</option>
                   <option value="ZAR">ZAR (R)</option>
                 </select>
               </div>

               <div className="border-t border-borderBase pt-6">
                 <button 
                   onClick={handleResetStats}
                   className="w-full py-3 rounded-lg border border-danger/30 text-danger hover:bg-danger hover:text-white transition-all font-bold flex items-center justify-center gap-2"
                 >
                   <Trash2 size={18} /> Reset All Stats & Data
