      {/* Main Content */}
      <main className="max-w-5xl mx-auto px-4 py-8">

        {activeTab === 'dashboard' && (
          <div className="space-y-8 animate-fade-in">
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
               <StatsCard title="Net Profit" value={stats.profit.toFixed(2)} isMoney currency={currency} icon={Wallet} color={stats.profit >= 0 ? 'text-success' : 'text-danger'} />
               <StatsCard title="Win Rate" value={`${stats.winRate.toFixed(1)}%`} icon={Trophy} color="text-warning" />
               <StatsCard title="Total Staked" value={stats.totalStaked.toFixed(2)} isMoney currency={currency} icon={Wallet} color="text-blue-400" />
               <StatsCard title="ROI" value={`${stats.roi.toFixed(1)}%`} icon={TrendingUp} color={stats.roi >= 0 ? 'text-success' : 'text-danger'} />
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
              <div className="lg:col-span-2 space-y-4">
                <h2 className="text-xl font-bold text-textMain flex items-center gap-2">
                  <History className="text-textMuted" size={20} /> Recent Activity
                </h2>
                <SlipList slips={slips.slice(0, 5)} onUpdateSlip={handleUpdateSlip} currency={currency} />
              </div>
              <div className="space-y-4">
                 <div className="bg-surface p-6 rounded-xl border border-borderBase">
                    <h3 className="text-textMain font-bold mb-4">Performance</h3>
                    <div className="space-y-4">
                       <div className="flex justify-between text-sm">
                          <span className="text-textMuted">Wins</span>
                          <span className="text-success font-bold">{stats.wins}</span>
                       </div>
                       <div className="w-full bg-inputBg rounded-full h-2">
                          <div className="bg-success h-2 rounded-full" style={{ width: `${stats.totalSlips ? (stats.wins/stats.totalSlips)*100 : 0}%` }}></div>
                       </div>
                       <div className="flex justify-between text-sm">
                          <span className="text-textMuted">Losses</span>
                          <span className="text-danger font-bold">{stats.losses}</span>
                       </div>
                        <div className="w-full bg-inputBg rounded-full h-2">
                          <div className="bg-danger h-2 rounded-full" style={{ width: `${stats.totalSlips ? (stats.losses/stats.totalSlips)*100 : 0}%` }}></div>
                       </div>
                    </div>
                 </div>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'create' && (
          <div className="max-w-3xl mx-auto animate-fade-in">
             <NewSlipForm onSave={handleSaveSlip} onCancel={() => setActiveTab('dashboard')} currency={currency} />
          </div>
        )}

        {activeTab === 'stats' && (
           <StatisticsPanel slips={slips} currency={currency} />
        )}

        {activeTab === 'active' && (
          <div className="space-y-4 animate-fade-in">
             <h2 className="text-xl font-bold text-textMain mb-6">Active Slips</h2>
             <SlipList slips={activeSlips} onUpdateSlip={handleUpdateSlip} currency={currency} />
          </div>
        )}

        {activeTab === 'settled' && (
          <div className="space-y-4 animate-fade-in">
             <h2 className="text-xl font-bold text-textMain mb-6">Betting History</h2>
             <SlipList slips={settledSlips} onUpdateSlip={handleUpdateSlip} currency={currency} />
          </div>
        )}

      </main>
    </div>
  );
};

