export default App;

export enum BetType {
  MATCH_WINNER = '1X2',
  BTTS = 'BTTS',
  OVER_UNDER = 'OVER_UNDER',
  DOUBLE_CHANCE = 'DOUBLE_CHANCE',
  DRAW_NO_BET = 'DRAW_NO_BET',
  TOTAL_CORNERS = 'TOTAL_CORNERS',
  HANDICAP = 'HANDICAP',
  BOOKINGS = 'BOOKINGS',
  SENDING_OFF = 'SENDING_OFF',
  EXACT_GOALS = 'EXACT_GOALS',
  ODD_EVEN = 'ODD_EVEN',

  // Halves Markets
  HALF_TIME_WINNER = '1ST_HALF_1X2',
  HALF_TIME_DOUBLE_CHANCE = '1ST_HALF_DC',
  HALF_TIME_BTTS = '1ST_HALF_BTTS',
  HALVES_BTTS = '1ST_2ND_HALF_BTTS', // e.g. Yes/Yes
  HALF_TIME_1ST_GOAL = '1ST_HALF_1ST_GOAL',
  HALF_TIME_1ST_CORNER = '1ST_HALF_1ST_CORNER',
  HALF_TIME_WINNER_AND_BTTS = '1ST_HALF_1X2_BTTS',
}

export enum LegStatus {
  PENDING = 'PENDING',
  WON = 'WON',
  LOST = 'LOST',
  VOID = 'VOID'
}

export enum SlipStatus {
  PENDING = 'PENDING',
  WON = 'WON',
  LOST = 'LOST',
  VOID = 'VOID'
}

export type Currency = 'USD' | 'GBP' | 'ZAR';

export const CURRENCY_SYMBOLS: Record<Currency, string> = {
  USD: '$',
  GBP: '£',
  ZAR: 'R'
};

export interface Leg {
  id: string;
  matchName: string; // e.g., "Arsenal vs Liverpool"
  date: string; // YYYY-MM-DD
  type: BetType;
  selection: string; // e.g., "Home", "Yes", "Over 2.5", "Home -1.5"
  status: LegStatus;
  resultScore?: string; // e.g., "2-1"
  notes?: string;
}

export interface Slip {
  id: string;
  createdAt: number;
  legs: Leg[];
  stake: number;
  odds: number;
  potentialReturn: number;
  status: SlipStatus;
  groundingUrls?: string[]; // URLs used for verification
}

export interface ValidationResult {
  legId: string;
  status: LegStatus;
  score: string;
}

export interface Stats {
  totalSlips: number;
  wins: number;
  losses: number;
  winRate: number;
  totalStaked: number;
  totalReturned: number;
  profit: number;
  roi: number;
}

import React, { useState, useEffect } from 'react';
import { Plus, Trash2, Save, Calendar, CheckCircle, ClipboardPaste, X } from 'lucide-react';
import { BetType, Leg, LegStatus, Slip, SlipStatus, Currency, CURRENCY_SYMBOLS } from '../types';

interface NewSlipFormProps {
  onSave: (slip: Slip) => void;
  onCancel: () => void;
  currency: Currency;
}

// Robust ID generator that works in all environments (unlike crypto.randomUUID)
const generateId = () => {
  return Date.now().toString(36) + Math.random().toString(36).substring(2, 9);
};

export const NewSlipForm: React.FC<NewSlipFormProps> = ({ onSave, onCancel, currency }) => {
  // Initialize state from LocalStorage (Draft) if available, otherwise default
  const [stake, setStake] = useState<string>(() => {
    const saved = localStorage.getItem('smartbet_draft_stake');
    return saved || '10';
  });

  const [totalOdds, setTotalOdds] = useState<string>(() => {
    const saved = localStorage.getItem('smartbet_draft_odds');
    return saved || '1.00';
  });

  const [legs, setLegs] = useState<Leg[]>(() => {
    const saved = localStorage.getItem('smartbet_draft_legs');
    if (saved) {
      return JSON.parse(saved);
    }
    return [{
      id: generateId(),
      matchName: '',
      date: new Date().toISOString().split('T')[0],
      type: BetType.MATCH_WINNER,
      selection: 'Home',
      status: LegStatus.PENDING,
    }];
  });

  // Import State
  const [showImport, setShowImport] = useState(false);
  const [importText, setImportText] = useState('');

  const symbol = CURRENCY_SYMBOLS[currency];

  // Auto-Save Draft Effects
  useEffect(() => {
    localStorage.setItem('smartbet_draft_stake', stake);
  }, [stake]);

  useEffect(() => {
    localStorage.setItem('smartbet_draft_odds', totalOdds);
  }, [totalOdds]);

  useEffect(() => {
    localStorage.setItem('smartbet_draft_legs', JSON.stringify(legs));
  }, [legs]);

  const clearDraft = () => {
    localStorage.removeItem('smartbet_draft_stake');
    localStorage.removeItem('smartbet_draft_odds');
    localStorage.removeItem('smartbet_draft_legs');
  };

  const addLeg = () => {
    setLegs([
      ...legs,
      {
        id: generateId(),
        matchName: '',
        date: new Date().toISOString().split('T')[0],
        type: BetType.MATCH_WINNER,
        selection: 'Home',
        status: LegStatus.PENDING,
      }
    ]);
  };

  const removeLeg = (id: string) => {
    if (legs.length > 1) {
      setLegs(legs.filter(l => l.id !== id));
    }
  };

  const updateLeg = (id: string, field: keyof Leg, value: any) => {
    setLegs(legs.map(l => {
      if (l.id === id) {
        const updated = { ...l, [field]: value };
        // Reset selection if type changes to avoid invalid states
        if (field === 'type') {
           if (value === BetType.MATCH_WINNER) updated.selection = 'Home';
           if (value === BetType.BTTS) updated.selection = 'Yes';
           if (value === BetType.OVER_UNDER) updated.selection = 'Over 2.5';
           if (value === BetType.DOUBLE_CHANCE) updated.selection = '1X';
           if (value === BetType.DRAW_NO_BET) updated.selection = 'Home';
           if (value === BetType.TOTAL_CORNERS) updated.selection = 'Over 9.5';
           if (value === BetType.HANDICAP) updated.selection = 'Home -1.5';
           if (value === BetType.BOOKINGS) updated.selection = 'Over 3.5';
           if (value === BetType.SENDING_OFF) updated.selection = 'Yes';
           if (value === BetType.EXACT_GOALS) updated.selection = '1';
           if (value === BetType.ODD_EVEN) updated.selection = 'Odd';

           // New Halves Defaults
           if (value === BetType.HALF_TIME_WINNER) updated.selection = 'Home';
           if (value === BetType.HALF_TIME_DOUBLE_CHANCE) updated.selection = '1X';
           if (value === BetType.HALF_TIME_BTTS) updated.selection = 'Yes';
           if (value === BetType.HALVES_BTTS) updated.selection = 'Yes/Yes';
           if (value === BetType.HALF_TIME_1ST_GOAL) updated.selection = 'Home';
           if (value === BetType.HALF_TIME_1ST_CORNER) updated.selection = 'Home';
           if (value === BetType.HALF_TIME_WINNER_AND_BTTS) updated.selection = 'Home & Yes';
        }
        return updated;
      }
      return l;
    }));
  };

  const getTeamNames = (matchName: string) => {
    // Simple split attempt
    const parts = matchName.split(/\s+v\s+|\s+vs\.?\s+|\s+-\s+/i);
    return {
      home: parts[0]?.trim() || 'Home',
      away: parts[1]?.trim() || 'Away'
    };
  };

  // Helper to allow only valid numeric input (no sliders/spinners)
  const handleNumericChange = (value: string, setter: (v: string) => void) => {
    // Allow empty or strictly digits with optional single decimal point
    if (value === '' || /^\d*\.?\d*$/.test(value)) {
      setter(value);
    }
  };

  const handleImport = () => {
    if (!importText.trim()) return;

    try {
      const lines = importText.split('\n').map(l => l.trim()).filter(l => l.length > 0);

      const newLegs: Leg[] = [];
      let calculatedOdds = 1;

      let i = 0;
      while (i < lines.length) {
        if (i + 4 > lines.length) break;

        const selectionRaw = lines[i];
        const oddsRaw = lines[i+1];
        const marketRaw = lines[i+2];
        const matchRaw = lines[i+3];
        const dateRaw = lines[i+4];

        const oddsVal = parseFloat(oddsRaw);
        if (isNaN(oddsVal)) {
           i++;
           continue;
        }

        i += 5; // Advance cursor
        calculatedOdds *= oddsVal;

        let type = BetType.MATCH_WINNER;
        let selection = 'Home';

        // Parsing logic extended for Halves? (Basic implementation kept)
        if (marketRaw.includes('1X2') || marketRaw === 'Match Winner') {
          type = BetType.MATCH_WINNER;
          const teams = matchRaw.split(/\s+-\s+|\s+v\s+/i);
          if (teams.length >= 2) {
             const home = teams[0].trim();
             const away = teams[1].trim();
             if (selectionRaw === home) selection = 'Home';
             else if (selectionRaw === away) selection = 'Away';
             else if (selectionRaw.toLowerCase().includes('draw')) selection = 'Draw';
             else selection = 'Home';
          }
        } 
        // ... (Existing parsing logic)

        // Very basic fallback for imported new types - they will default to match winner if not caught
        // Implementing full text parser for all types is complex and brittle without strict format

        let date = new Date().toISOString().split('T')[0];
        if (dateRaw.toLowerCase().includes('today')) {
           date = new Date().toISOString().split('T')[0];
        } else if (dateRaw.toLowerCase().includes('tomorrow')) {
           const d = new Date();
           d.setDate(d.getDate() + 1);
           date = d.toISOString().split('T')[0];
        }

        newLegs.push({
          id: generateId(),
          matchName: matchRaw,
          date: date,
          type: type,
          selection: selection,
          status: LegStatus.PENDING
        });
      }

      if (newLegs.length > 0) {
        setLegs(newLegs);
        setTotalOdds(calculatedOdds.toFixed(2));
        setShowImport(false);
        setImportText('');
      } else {
        alert("Could not parse any bets. Please check the format.");
      }

    } catch (e) {
      console.error(e);
      alert("Error parsing the text.");
    }
  };

  const handleSave = () => {
    if (legs.some(l => !l.matchName)) {
      alert("Please enter all match names.");
      return;
    }

    const numStake = parseFloat(stake) || 0;
    const numOdds = parseFloat(totalOdds) || 1;

    const newSlip: Slip = {
      id: generateId(),
      createdAt: Date.now(),
      legs,
      stake: numStake,
      odds: numOdds,
      potentialReturn: numStake * numOdds,
      status: SlipStatus.PENDING,
    };

    onSave(newSlip);
    clearDraft();
  };

  const handleCancel = () => {
    onCancel();
  };

  return (
    <div className="bg-surface rounded-xl shadow-xl border border-borderBase overflow-hidden relative transition-colors">
      <div className="p-6 border-b border-borderBase flex justify-between items-center bg-inputBg">
        <h2 className="text-xl font-bold text-textMain flex items-center gap-2">
          <Plus className="text-primary" /> Create New Bet Slip
        </h2>
        <div className="flex gap-2">
          {/* Draft Indicator */}
          <span className="text-[10px] uppercase tracking-wider font-bold text-success/80 border border-success/20 px-2 py-1 rounded-full flex items-center bg-success/5">
             Auto-Saved
          </span>
          <button 
            onClick={() => setShowImport(true)}
            className="text-xs flex items-center gap-1 bg-surface border border-borderBase hover:bg-background text-textMain px-3 py-1.5 rounded transition-colors"
          >
            <ClipboardPaste size={14} /> Import from Text
          </button>
        </div>
      </div>

      {showImport && (
        <div className="absolute inset-0 z-50 bg-background/95 flex flex-col items-center justify-center p-6 animate-fade-in">
           <div className="w-full max-w-lg bg-surface border border-borderBase rounded-xl p-6 shadow-2xl">
              <div className="flex justify-between items-center mb-4">
                 <h3 className="text-textMain font-bold flex items-center gap-2">
                   <ClipboardPaste className="text-primary" /> Paste Bet Slip
                 </h3>
                 <button onClick={() => setShowImport(false)} className="text-textMuted hover:text-textMain">
                   <X size={20} />
                 </button>
              </div>
              <textarea
                value={importText}
                onChange={(e) => setImportText(e.target.value)}
                placeholder={`Paste your bet details here...\n\nExample:\nTorino FC\n2.00\n1X2\nTorino FC - US Cremonese\nToday 16:00`}
                className="w-full h-64 bg-inputBg border border-borderBase rounded-lg p-4 text-xs font-mono text-textMain focus:outline-none focus:border-primary resize-none placeholder-textMuted"
              />
              <div className="mt-4 flex justify-end gap-3">
                 <button 
                   onClick={() => setShowImport(false)}
                   className="px-4 py-2 rounded text-textMuted hover:text-textMain hover:bg-inputBg"
                 >
                   Cancel
                 </button>
                 <button 
                   onClick={handleImport}
                   className="px-6 py-2 rounded bg-primary text-white font-bold hover:bg-blue-600"
                 >
                   Parse & Import
                 </button>
              </div>
           </div>
        </div>
      )}

      <div className="p-6 space-y-6">
        <div className="space-y-4">
          <label className="text-sm font-medium text-textMuted uppercase tracking-wider">Selections</label>

          {legs.map((leg, index) => (
            <div key={leg.id} className="grid grid-cols-1 md:grid-cols-12 gap-4 p-4 bg-background rounded-lg border border-borderBase hover:border-textMuted transition-colors">
              <div className="md:col-span-4 space-y-1">
                <label className="text-xs text-textMuted">Match</label>
                <input
                  type="text"
                  value={leg.matchName}
                  onChange={(e) => updateLeg(leg.id, 'matchName', e.target.value)}
                  placeholder="e.g. Arsenal vs Liverpool"
                  className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary placeholder-textMuted/50"
                />
              </div>

              <div className="md:col-span-2 space-y-1">
                <label className="text-xs text-textMuted">Date</label>
                <div className="relative">
                  <input
                    type="date"
                    value={leg.date}
                    onChange={(e) => updateLeg(leg.id, 'date', e.target.value)}
                    className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                  />
                </div>
              </div>

              <div className="md:col-span-2 space-y-1">
                <label className="text-xs text-textMuted">Market</label>
                <select
                  value={leg.type}
                  onChange={(e) => updateLeg(leg.id, 'type', e.target.value)}
                  className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                >
                  <optgroup label="Full Time">
                    <option value={BetType.MATCH_WINNER}>1X2 Winner</option>
                    <option value={BetType.DOUBLE_CHANCE}>Double Chance</option>
                    <option value={BetType.BTTS}>Both Teams To Score</option>
                    <option value={BetType.OVER_UNDER}>Over/Under Goals</option>
                    <option value={BetType.DRAW_NO_BET}>Draw No Bet</option>
                    <option value={BetType.TOTAL_CORNERS}>Total Corners</option>
                    <option value={BetType.BOOKINGS}>Bookings (Cards)</option>
                    <option value={BetType.SENDING_OFF}>Sending Off</option>
                    <option value={BetType.EXACT_GOALS}>Exact Goals</option>
                    <option value={BetType.ODD_EVEN}>Odd/Even Goals</option>
                    <option value={BetType.HANDICAP}>Handicap</option>
                  </optgroup>
                  <optgroup label="Half Time">
                    <option value={BetType.HALF_TIME_WINNER}>1st Half - 1X2</option>
                    <option value={BetType.HALF_TIME_DOUBLE_CHANCE}>1st Half - Double Chance</option>
                    <option value={BetType.HALF_TIME_BTTS}>1st Half - BTTS</option>
                    <option value={BetType.HALVES_BTTS}>1st/2nd Half BTTS</option>
                    <option value={BetType.HALF_TIME_1ST_GOAL}>1st Half - 1st Goal</option>
                    <option value={BetType.HALF_TIME_1ST_CORNER}>1st Half - 1st Corner</option>
                    <option value={BetType.HALF_TIME_WINNER_AND_BTTS}>1st Half - 1X2 & BTTS</option>
                  </optgroup>
                </select>
              </div>

              <div className="md:col-span-3 space-y-1">
                <label className="text-xs text-textMuted">Selection</label>

                {(leg.type === BetType.MATCH_WINNER || leg.type === BetType.HALF_TIME_WINNER) && (
                  <select
