  onSave: (slip: Slip) => void;
  onCancel: () => void;
  currency: Currency;
}

// Robust ID generator that works in all environments (unlike crypto.randomUUID)
const generateId = () => {
  return Date.now().toString(36) + Math.random().toString(36).substring(2, 9);
};

export const NewSlipForm: React.FC<NewSlipFormProps> = ({ initialData, onSave, onCancel, currency }) => {
  // Initialize state from InitialData (Edit mode) or LocalStorage (Draft), otherwise default
  const [stake, setStake] = useState<string>(() => {
    if (initialData) return initialData.stake.toString();
    const saved = localStorage.getItem('smartbet_draft_stake');
    return saved || '10';
  });

  const [totalOdds, setTotalOdds] = useState<string>(() => {
    if (initialData) return initialData.odds.toString();
    const saved = localStorage.getItem('smartbet_draft_odds');
    return saved || '1.00';
  });

  const [legs, setLegs] = useState<Leg[]>(() => {
    if (initialData) return initialData.legs;
    const saved = localStorage.getItem('smartbet_draft_legs');
    if (saved) {
      return JSON.parse(saved);
    }
    return [{
      id: generateId(),
      matchName: '',
      date: new Date().toISOString().split('T')[0],
      type: BetType.MATCH_WINNER,
      selection: 'Home',
      status: LegStatus.PENDING,
    }];
  });

  // Import State
  const [showImport, setShowImport] = useState(false);
  const [importText, setImportText] = useState('');

  const symbol = CURRENCY_SYMBOLS[currency];
  const isEditing = !!initialData;

  // Auto-Save Draft Effects
  useEffect(() => {
    localStorage.setItem('smartbet_draft_stake', stake);
  }, [stake]);

  useEffect(() => {
    localStorage.setItem('smartbet_draft_odds', totalOdds);
  }, [totalOdds]);

  useEffect(() => {
    localStorage.setItem('smartbet_draft_legs', JSON.stringify(legs));
  }, [legs]);

  const clearDraft = () => {
    localStorage.removeItem('smartbet_draft_stake');
    localStorage.removeItem('smartbet_draft_odds');
    localStorage.removeItem('smartbet_draft_legs');
  };

  const addLeg = () => {
    setLegs([
      ...legs,
      {
        id: generateId(),
        matchName: '',
        date: new Date().toISOString().split('T')[0],
        type: BetType.MATCH_WINNER,
        selection: 'Home',
        status: LegStatus.PENDING,
      }
    ]);
  };

  const removeLeg = (id: string) => {
    if (legs.length > 1) {
      setLegs(legs.filter(l => l.id !== id));
    }
  };

  const updateLeg = (id: string, field: keyof Leg, value: any) => {
    setLegs(legs.map(l => {
      if (l.id === id) {
        const updated = { ...l, [field]: value };
        // Reset selection if type changes to avoid invalid states
        if (field === 'type') {
           if (value === BetType.MATCH_WINNER) updated.selection = 'Home';
           if (value === BetType.BTTS) updated.selection = 'Yes';
           if (value === BetType.OVER_UNDER) updated.selection = 'Over 2.5';
           if (value === BetType.DOUBLE_CHANCE) updated.selection = '1X';
           if (value === BetType.DRAW_NO_BET) updated.selection = 'Home';
           if (value === BetType.TOTAL_CORNERS) updated.selection = 'Over 9.5';
           if (value === BetType.HANDICAP) updated.selection = 'Home -1.5';
           if (value === BetType.BOOKINGS) updated.selection = 'Over 3.5';
           if (value === BetType.SENDING_OFF) updated.selection = 'Yes';
           if (value === BetType.EXACT_GOALS) updated.selection = '1';
           if (value === BetType.ODD_EVEN) updated.selection = 'Odd';
           if (value === BetType.WINNING_MARGIN) updated.selection = 'Home By 1';

           // New Halves Defaults
           if (value === BetType.HALF_TIME_WINNER) updated.selection = 'Home';
           if (value === BetType.HALF_TIME_DOUBLE_CHANCE) updated.selection = '1X';
           if (value === BetType.HALF_TIME_BTTS) updated.selection = 'Yes';
           if (value === BetType.HALVES_BTTS) updated.selection = 'Yes/Yes';
           if (value === BetType.HALF_TIME_1ST_GOAL) updated.selection = 'Home';
           if (value === BetType.HALF_TIME_1ST_CORNER) updated.selection = 'Home';
           if (value === BetType.HALF_TIME_WINNER_AND_BTTS) updated.selection = 'Home & Yes';
        }
        return updated;
      }
      return l;
    }));
  };

  const getTeamNames = (matchName: string) => {
    // Simple split attempt
    const parts = matchName.split(/\s+v\s+|\s+vs\.?\s+|\s+-\s+/i);
    return {
      home: parts[0]?.trim() || 'Home',
      away: parts[1]?.trim() || 'Away'
    };
  };

  // Helper to allow only valid numeric input (no sliders/spinners)
  const handleNumericChange = (value: string, setter: (v: string) => void) => {
    // Allow empty or strictly digits with optional single decimal point
    if (value === '' || /^\d*\.?\d*$/.test(value)) {
      setter(value);
    }
  };

  const handleImport = () => {
    if (!importText.trim()) return;

    try {
      const lines = importText.split('\n').map(l => l.trim()).filter(l => l.length > 0);

      const newLegs: Leg[] = [];
      let calculatedOdds = 1;

      let i = 0;
      while (i < lines.length) {
        if (i + 4 > lines.length) break;

        const selectionRaw = lines[i];
        const oddsRaw = lines[i+1];
        const marketRaw = lines[i+2];
        const matchRaw = lines[i+3];
        const dateRaw = lines[i+4];

        const oddsVal = parseFloat(oddsRaw);
        if (isNaN(oddsVal)) {
           i++;
           continue;
        }

        i += 5; // Advance cursor
        calculatedOdds *= oddsVal;

        let type = BetType.MATCH_WINNER;
        let selection = 'Home';

        // Parsing logic extended for Halves? (Basic implementation kept)
        if (marketRaw.includes('1X2') || marketRaw === 'Match Winner') {
          type = BetType.MATCH_WINNER;
          const teams = matchRaw.split(/\s+-\s+|\s+v\s+/i);
          if (teams.length >= 2) {
             const home = teams[0].trim();
             const away = teams[1].trim();
             if (selectionRaw === home) selection = 'Home';
             else if (selectionRaw === away) selection = 'Away';
             else if (selectionRaw.toLowerCase().includes('draw')) selection = 'Draw';
             else selection = 'Home';
          }
        } 
        // ... (Existing parsing logic)

        let date = new Date().toISOString().split('T')[0];
        if (dateRaw.toLowerCase().includes('today')) {
           date = new Date().toISOString().split('T')[0];
        } else if (dateRaw.toLowerCase().includes('tomorrow')) {
           const d = new Date();
           d.setDate(d.getDate() + 1);
           date = d.toISOString().split('T')[0];
        }

        newLegs.push({
          id: generateId(),
          matchName: matchRaw,
          date: date,
          type: type,
          selection: selection,
          status: LegStatus.PENDING
        });
      }

      if (newLegs.length > 0) {
        setLegs(newLegs);
        setTotalOdds(calculatedOdds.toFixed(2));
        setShowImport(false);
        setImportText('');
      } else {
        alert("Could not parse any bets. Please check the format.");
      }

    } catch (e) {
      console.error(e);
      alert("Error parsing the text.");
    }
  };

  const handleSave = () => {
    if (legs.some(l => !l.matchName)) {
      alert("Please enter all match names.");
      return;
    }

    const numStake = parseFloat(stake) || 0;
    const numOdds = parseFloat(totalOdds) || 1;

    const newSlip: Slip = {
      id: initialData ? initialData.id : generateId(),
      createdAt: initialData ? initialData.createdAt : Date.now(),
      legs,
      stake: numStake,
      odds: numOdds,
      potentialReturn: numStake * numOdds,
      status: initialData ? initialData.status : SlipStatus.PENDING,
    };

    onSave(newSlip);
