import React, { useState } from 'react';
import { ChevronDown, ChevronUp, RefreshCw, Trophy, XCircle, Clock, Check, ExternalLink, Pencil } from 'lucide-react';
import { Slip, SlipStatus, Leg, LegStatus, Currency, CURRENCY_SYMBOLS } from '../types';
import { validateSlipWithGemini } from '../services/geminiService';

interface SlipListProps {
  slips: Slip[];
  onUpdateSlip: (updatedSlip: Slip) => void;
  onEditSlip?: (slip: Slip) => void;
  currency: Currency;
}

export const SlipList: React.FC<SlipListProps> = ({ slips, onUpdateSlip, onEditSlip, currency }) => {
  const symbol = CURRENCY_SYMBOLS[currency];

  if (slips.length === 0) {
    return (
      <div className="text-center py-20 bg-surface rounded-xl border border-borderBase">
        <div className="inline-block p-4 rounded-full bg-inputBg mb-4">
          <Trophy className="text-textMuted" size={32} />
        </div>
        <h3 className="text-lg font-medium text-textMain">No active bets</h3>
        <p className="text-textMuted">Create a new bet slip to get started.</p>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {slips.map(slip => (
        <SlipCard key={slip.id} slip={slip} onUpdate={onUpdateSlip} onEdit={onEditSlip} symbol={symbol} />
      ))}
    </div>
  );
};

interface SlipCardProps {
  slip: Slip;
  onUpdate: (slip: Slip) => void;
  onEdit?: (slip: Slip) => void;
  symbol: string;
}

const SlipCard: React.FC<SlipCardProps> = ({ slip, onUpdate, onEdit, symbol }) => {
  const [expanded, setExpanded] = useState(false);
  const [checking, setChecking] = useState(false);

  const getStatusColor = (status: SlipStatus | LegStatus) => {
    switch (status) {
      case 'WON': return 'text-success bg-success/10 border-success/20';
      case 'LOST': return 'text-danger bg-danger/10 border-danger/20';
      case 'VOID': return 'text-warning bg-warning/10 border-warning/20';
      default: return 'text-textMuted bg-inputBg border-borderBase';
    }
  };

  const getStatusIcon = (status: SlipStatus | LegStatus) => {
    switch (status) {
      case 'WON': return <Check size={16} />;
      case 'LOST': return <XCircle size={16} />;
      case 'PENDING': return <Clock size={16} />;
      default: return null;
    }
  };

  const handleAICheck = async (e: React.MouseEvent) => {
    e.stopPropagation();
    if (checking || slip.status !== SlipStatus.PENDING) return;

    setChecking(true);
    try {
      const response = await validateSlipWithGemini(slip);

      const updatedLegs = slip.legs.map(leg => {
        const update = response.results.find(r => r.legId === leg.id);
        if (update) {
          return { ...leg, status: update.status, resultScore: update.score };
        }
        return leg;
      });

      // Determine overall slip status
      let newStatus = SlipStatus.WON;
      if (updatedLegs.some(l => l.status === LegStatus.LOST)) newStatus = SlipStatus.LOST;
      else if (updatedLegs.some(l => l.status === LegStatus.PENDING)) newStatus = SlipStatus.PENDING;
      else if (updatedLegs.every(l => l.status === LegStatus.VOID)) newStatus = SlipStatus.VOID;

      onUpdate({
        ...slip,
        legs: updatedLegs,
        status: newStatus,
        groundingUrls: response.sources
      });
    } catch (error) {
      alert("Failed to update matches via AI. Please try again.");
    } finally {
      setChecking(false);
    }
  };

  const handleEditClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (onEdit) onEdit(slip);
  };

  return (
