};

interface SlipCardProps {
  slip: Slip;
  onUpdate: (slip: Slip) => void;
  onEdit?: (slip: Slip) => void;
  symbol: string;
}

const SlipCard: React.FC<SlipCardProps> = ({ slip, onUpdate, onEdit, symbol }) => {
  const [expanded, setExpanded] = useState(false);
  const [checking, setChecking] = useState(false);

  // Manual Settlement State
  const [isSettling, setIsSettling] = useState(false);
  const [editedLegs, setEditedLegs] = useState<Leg[]>([]);

  const getStatusColor = (status: SlipStatus | LegStatus) => {
    switch (status) {
      case 'WON': return 'text-success bg-success/10 border-success/20';
      case 'LOST': return 'text-danger bg-danger/10 border-danger/20';
      case 'VOID': return 'text-warning bg-warning/10 border-warning/20';
      default: return 'text-textMuted bg-inputBg border-borderBase';
    }
  };

  const getStatusIcon = (status: SlipStatus | LegStatus) => {
    switch (status) {
      case 'WON': return <Check size={16} />;
      case 'LOST': return <XCircle size={16} />;
      case 'PENDING': return <Clock size={16} />;
      case 'VOID': return <Ban size={16} />;
      default: return null;
    }
  };

  const calculateSlipStatus = (legs: Leg[]): SlipStatus => {
    if (legs.some(l => l.status === LegStatus.LOST)) return SlipStatus.LOST;
    if (legs.some(l => l.status === LegStatus.PENDING)) return SlipStatus.PENDING;
    if (legs.every(l => l.status === LegStatus.VOID)) return SlipStatus.VOID;
    return SlipStatus.WON;
  };

  const handleAICheck = async (e: React.MouseEvent) => {
    e.stopPropagation();
    if (checking || slip.status !== SlipStatus.PENDING) return;

    setChecking(true);
    try {
      const response = await validateSlipWithGemini(slip);

      const updatedLegs = slip.legs.map(leg => {
        const update = response.results.find(r => r.legId === leg.id);
        if (update) {
          return { ...leg, status: update.status, resultScore: update.score };
        }
        return leg;
      });

      const newStatus = calculateSlipStatus(updatedLegs);

      onUpdate({
        ...slip,
        legs: updatedLegs,
        status: newStatus,
        groundingUrls: response.sources
      });
    } catch (error) {
      alert("Failed to update matches via AI. Please try again.");
    } finally {
      setChecking(false);
    }
  };

  const handleEditClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (onEdit) onEdit(slip);
  };

  // Manual Settlement Handlers
  const startSettling = (e: React.MouseEvent) => {
    e.stopPropagation();
    setEditedLegs([...slip.legs]);
    setIsSettling(true);
    setExpanded(true);
  };

  const cancelSettling = (e: React.MouseEvent) => {
    e.stopPropagation();
    setIsSettling(false);
    setEditedLegs([]);
  };

  const saveSettlement = (e: React.MouseEvent) => {
    e.stopPropagation();
    const newStatus = calculateSlipStatus(editedLegs);
    onUpdate({
      ...slip,
      legs: editedLegs,
      status: newStatus
    });
    setIsSettling(false);
  };

  const updateLegStatus = (legId: string, status: LegStatus) => {
    setEditedLegs(prev => prev.map(l => l.id === legId ? { ...l, status } : l));
  };

  const updateLegScore = (legId: string, score: string) => {
    setEditedLegs(prev => prev.map(l => l.id === legId ? { ...l, resultScore: score } : l));
  };

  return (
    <div className={`bg-surface rounded-xl border transition-all overflow-hidden ${slip.status === SlipStatus.WON ? 'border-success/30 shadow-success/5' : slip.status === SlipStatus.LOST ? 'border-danger/30' : 'border-borderBase'}`}>
      {/* Header */}
      <div 
        className="p-5 flex items-center justify-between cursor-pointer hover:bg-inputBg transition-colors"
        onClick={() => !isSettling && setExpanded(!expanded)}
      >
        <div className="flex items-center gap-4">
          <div className={`w-10 h-10 rounded-full flex items-center justify-center border ${getStatusColor(slip.status)}`}>
            {getStatusIcon(slip.status)}
          </div>
          <div>
             <div className="flex items-center gap-2">
               <h4 className="font-bold text-textMain text-lg">
                 {slip.legs.length} Match Accumulator
               </h4>
               <span className="text-xs text-textMuted font-mono">
                 {new Date(slip.createdAt).toLocaleDateString()}
               </span>
             </div>
             <p className="text-textMuted text-sm">
               Stake: <span className="text-textMain font-medium">{symbol}{slip.stake}</span> • 
               Odds: <span className="text-textMain font-medium">{slip.odds}</span> • 
               Return: <span className={`font-bold ${slip.status === 'WON' ? 'text-success' : 'text-primary'}`}>{symbol}{slip.potentialReturn.toFixed(2)}</span>
             </p>
          </div>
        </div>

        <div className="flex items-center gap-2">
          {isSettling ? (
            <div className="flex gap-2">
               <button 
                 onClick={cancelSettling}
                 className="p-2 rounded-lg bg-surface border border-borderBase text-textMuted hover:text-textMain hover:bg-inputBg transition-colors"
                 title="Cancel"
               >
                 <X size={18} />
               </button>
               <button 
                 onClick={saveSettlement}
                 className="px-4 py-2 rounded-lg bg-primary text-white font-bold flex items-center gap-2 hover:bg-blue-600 transition-colors shadow-lg shadow-blue-500/20"
                 title="Save Changes"
               >
                 <Save size={18} /> Save
               </button>
            </div>
          ) : (
            <div className="flex items-center gap-2">
              {/* Manual Settle Button - Available for all slips to correct errors */}
              <button 
                onClick={startSettling}
                className="p-2 rounded-lg text-textMuted hover:text-primary hover:bg-primary/10 transition-colors"
                title="Manual Settlement"
              >
                <Gavel size={16} />
              </button>

              {slip.status === SlipStatus.PENDING && (
                <>
                  {onEdit && (
                    <button 
                      onClick={handleEditClick}
                      className="p-2 rounded-lg text-textMuted hover:text-textMain hover:bg-surface border border-transparent hover:border-borderBase transition-all"
                      title="Edit Bet Slip"
                    >
                      <Pencil size={14} />
                    </button>
                  )}
                  <button 
                    onClick={handleAICheck}
                    disabled={checking}
                    className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs font-bold uppercase tracking-wide transition-all ${checking ? 'bg-inputBg text-textMuted' : 'bg-primary/20 text-primary hover:bg-primary/30'}`}
                  >
                    <RefreshCw size={14} className={checking ? "animate-spin" : ""} />
                    {checking ? 'Checking...' : 'Check'}
                  </button>
                </>
              )}

              <div className="pl-2 border-l border-borderBase ml-2">
                {expanded ? <ChevronUp className="text-textMuted" size={20} /> : <ChevronDown className="text-textMuted" size={20} />}
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Expanded Content */}
      {expanded && (
        <div className="border-t border-borderBase bg-background/30 p-4">
          <div className="space-y-2">
             {(isSettling ? editedLegs : slip.legs).map((leg, idx) => (
                <div key={leg.id} className={`flex flex-col md:flex-row md:items-center justify-between p-3 rounded-lg border ${isSettling ? 'bg-surface border-primary/30 shadow-sm' : 'bg-inputBg border-borderBase'}`}>
                   <div className="flex-1 mb-3 md:mb-0">
                      <div className="flex justify-between items-start">
                         <h5 className="text-textMain font-medium">{leg.matchName}</h5>
                         {!isSettling && <span className="text-xs text-textMuted">{leg.date}</span>}
                      </div>
                      <div className="flex items-center gap-2 mt-1">
                         <span className="text-xs font-bold px-2 py-0.5 rounded bg-surface border border-borderBase text-textMuted">{leg.type}</span>
                         <span className="text-sm text-primary">Prediction: {leg.selection}</span>
                      </div>

                      {isSettling ? (
                         <div className="mt-3">
                           <label className="text-[10px] uppercase text-textMuted font-bold mb-1 block">Score / Result</label>
                           <input 
                             type="text" 
                             value={leg.resultScore || ''} 
                             onChange={(e) => updateLegScore(leg.id, e.target.value)}
                             placeholder="e.g. 2-1"
                             className="w-full md:w-48 bg-inputBg border border-borderBase rounded px-2 py-1 text-sm text-textMain"
                           />
                         </div>
                      ) : (
                        leg.resultScore && (
                          <div className="mt-2 text-xs text-textMuted font-mono flex items-center gap-1">
                            Final Score: <span className="text-textMain font-bold">{leg.resultScore}</span>
                          </div>
                        )
                      )}
                   </div>

                   <div className="ml-0 md:ml-4 flex items-center gap-2">
                      {isSettling ? (
                        <div className="flex gap-1 bg-inputBg p-1 rounded-lg border border-borderBase">
                          <button 
                             onClick={() => updateLegStatus(leg.id, LegStatus.WON)}
                             className={`p-1.5 rounded text-xs font-bold transition-colors ${leg.status === LegStatus.WON ? 'bg-success text-white shadow' : 'text-textMuted hover:bg-background'}`}
                             title="Mark as Won"
                          >
                            <Check size={14} />
                          </button>
                          <button 
                             onClick={() => updateLegStatus(leg.id, LegStatus.LOST)}
                             className={`p-1.5 rounded text-xs font-bold transition-colors ${leg.status === LegStatus.LOST ? 'bg-danger text-white shadow' : 'text-textMuted hover:bg-background'}`}
                             title="Mark as Lost"
                          >
                            <XCircle size={14} />
                          </button>
                          <button 
                             onClick={() => updateLegStatus(leg.id, LegStatus.VOID)}
                             className={`p-1.5 rounded text-xs font-bold transition-colors ${leg.status === LegStatus.VOID ? 'bg-warning text-white shadow' : 'text-textMuted hover:bg-background'}`}
                             title="Mark as Void"
                          >
                            <Ban size={14} />
                          </button>
                          <button 
                             onClick={() => updateLegStatus(leg.id, LegStatus.PENDING)}
                             className={`p-1.5 rounded text-xs font-bold transition-colors ${leg.status === LegStatus.PENDING ? 'bg-surface text-textMain shadow' : 'text-textMuted hover:bg-background'}`}
                             title="Mark as Pending"
                          >
                            <Clock size={14} />
                          </button>
                        </div>
                      ) : (
                        <span className={`text-xs font-bold px-2 py-1 rounded border ${getStatusColor(leg.status)}`}>
                          {leg.status}
                        </span>
                      )}
                   </div>
                </div>
             ))}
          </div>

          {/* Grounding Sources (Only show in view mode) */}
          {!isSettling && slip.groundingUrls && slip.groundingUrls.length > 0 && (
            <div className="mt-4 pt-4 border-t border-borderBase">
               <h6 className="text-xs font-bold text-textMuted uppercase tracking-wider mb-2 flex items-center gap-1">
                 <ExternalLink size={10} /> Verified Sources
               </h6>
               <div className="flex flex-wrap gap-2">
                  {slip.groundingUrls.map((url, i) => (
                    <a 
                      key={i} 
                      href={url} 
                      target="_blank" 
                      rel="noopener noreferrer"
                      className="text-xs text-primary hover:underline truncate max-w-xs"
                    >
                      Source {i+1}
                    </a>
                  ))}
               </div>
            </div>
          )}

          {isSettling && (
            <div className="mt-4 pt-4 border-t border-borderBase text-center text-xs text-textMuted">
              Adjusting leg statuses will automatically recalculate the overall slip status.
            </div>
          )}
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Plus, Trash2, Save, Calendar, CheckCircle, ClipboardPaste, X, Edit3 } from 'lucide-react';
import { BetType, Leg, LegStatus, Slip, SlipStatus, Currency, CURRENCY_SYMBOLS } from '../types';

interface NewSlipFormProps {
  initialData?: Slip;
  onSave: (slip: Slip) => void;
  onCancel: () => void;
  currency: Currency;
}

// Robust ID generator that works in all environments (unlike crypto.randomUUID)
const generateId = () => {
  return Date.now().toString(36) + Math.random().toString(36).substring(2, 9);
};

export const NewSlipForm: React.FC<NewSlipFormProps> = ({ initialData, onSave, onCancel, currency }) => {
  // Initialize state from InitialData (Edit mode) or LocalStorage (Draft), otherwise default
  const [stake, setStake] = useState<string>(() => {
    if (initialData) return initialData.stake.toString();
    const saved = localStorage.getItem('smartbet_draft_stake');
    return saved || '10';
  });

  const [totalOdds, setTotalOdds] = useState<string>(() => {
    if (initialData) return initialData.odds.toString();
    const saved = localStorage.getItem('smartbet_draft_odds');
    return saved || '1.00';
  });

  const [legs, setLegs] = useState<Leg[]>(() => {
    if (initialData) return initialData.legs;
    const saved = localStorage.getItem('smartbet_draft_legs');
    if (saved) {
      return JSON.parse(saved);
    }
    return [{
      id: generateId(),
      matchName: '',
      date: new Date().toISOString().split('T')[0],
      type: BetType.MATCH_WINNER,
      selection: 'Home',
      status: LegStatus.PENDING,
    }];
  });

  // Import State
  const [showImport, setShowImport] = useState(false);
  const [importText, setImportText] = useState('');

  const symbol = CURRENCY_SYMBOLS[currency];
  const isEditing = !!initialData;

  // Auto-Save Draft Effects
  useEffect(() => {
    localStorage.setItem('smartbet_draft_stake', stake);
  }, [stake]);

  useEffect(() => {
    localStorage.setItem('smartbet_draft_odds', totalOdds);
  }, [totalOdds]);

  useEffect(() => {
    localStorage.setItem('smartbet_draft_legs', JSON.stringify(legs));
  }, [legs]);

  const clearDraft = () => {
    localStorage.removeItem('smartbet_draft_stake');
    localStorage.removeItem('smartbet_draft_odds');
    localStorage.removeItem('smartbet_draft_legs');
  };

  const addLeg = () => {
    setLegs([
      ...legs,
      {
        id: generateId(),
        matchName: '',
        date: new Date().toISOString().split('T')[0],
        type: BetType.MATCH_WINNER,
        selection: 'Home',
        status: LegStatus.PENDING,
      }
    ]);
  };

  const removeLeg = (id: string) => {
    if (legs.length > 1) {
      setLegs(legs.filter(l => l.id !== id));
    }
  };

  const updateLeg = (id: string, field: keyof Leg, value: any) => {
    setLegs(legs.map(l => {
      if (l.id === id) {
        const updated = { ...l, [field]: value };
        // Reset selection if type changes to avoid invalid states
        if (field === 'type') {
           if (value === BetType.MATCH_WINNER) updated.selection = 'Home';
           if (value === BetType.BTTS) updated.selection = 'Yes';
           if (value === BetType.OVER_UNDER) updated.selection = 'Over 2.5';
           if (value === BetType.DOUBLE_CHANCE) updated.selection = '1X';
           if (value === BetType.DRAW_NO_BET) updated.selection = 'Home';
           if (value === BetType.TOTAL_CORNERS) updated.selection = 'Over 9.5';
           if (value === BetType.HANDICAP) updated.selection = 'Home -1.5';
           if (value === BetType.BOOKINGS) updated.selection = 'Over 3.5';
           if (value === BetType.SENDING_OFF) updated.selection = 'Yes';
           if (value === BetType.EXACT_GOALS) updated.selection = '1';
           if (value === BetType.ODD_EVEN) updated.selection = 'Odd';
           if (value === BetType.WINNING_MARGIN) updated.selection = 'Home By 1';

           // New Halves Defaults
           if (value === BetType.HALF_TIME_WINNER) updated.selection = 'Home';
           if (value === BetType.HALF_TIME_DOUBLE_CHANCE) updated.selection = '1X';
           if (value === BetType.HALF_TIME_BTTS) updated.selection = 'Yes';
           if (value === BetType.HALVES_BTTS) updated.selection = 'Yes/Yes';
           if (value === BetType.HALF_TIME_1ST_GOAL) updated.selection = 'Home';
           if (value === BetType.HALF_TIME_1ST_CORNER) updated.selection = 'Home';
           if (value === BetType.HALF_TIME_WINNER_AND_BTTS) updated.selection = 'Home & Yes';
        }
        return updated;
      }
      return l;
    }));
  };

  const getTeamNames = (matchName: string) => {
    // Simple split attempt
    const parts = matchName.split(/\s+v\s+|\s+vs\.?\s+|\s+-\s+/i);
    return {
      home: parts[0]?.trim() || 'Home',
      away: parts[1]?.trim() || 'Away'
    };
  };

  // Helper to allow only valid numeric input (no sliders/spinners)
  const handleNumericChange = (value: string, setter: (v: string) => void) => {
    // Allow empty or strictly digits with optional single decimal point
    if (value === '' || /^\d*\.?\d*$/.test(value)) {
      setter(value);
    }
  };

  const handleImport = () => {
    if (!importText.trim()) return;

    try {
      const lines = importText.split('\n').map(l => l.trim()).filter(l => l.length > 0);

      const newLegs: Leg[] = [];
      let calculatedOdds = 1;

      let i = 0;
      while (i < lines.length) {
        // Try to handle blocks of 4 or 5 lines
        // Typical structure:
        // Selection
        // Odds
        // Market
        // Match
        // Date (Optional/Sometimes on same line)

        if (i + 3 > lines.length) break; // Need at least 4 lines for a valid bet block

        const selectionRaw = lines[i];
        const oddsRaw = lines[i+1];
        const marketRaw = lines[i+2];
        const matchRaw = lines[i+3];

        // Check if next line is a date or start of new bet (Odds are usually numbers)
        let dateRaw = new Date().toISOString().split('T')[0]; // Default today
        let consumedLines = 4;

        if (i + 4 < lines.length) {
          const potentialDate = lines[i+4];
          // If potentialDate is not a number (not odds of next bet) and contains date-like keywords
          const isDate = potentialDate.match(/\d{2}:\d{2}|Today|Tomorrow|\d{2}\/\d{2}/i);
          const nextIsOdds = /^\d+\.?\d*$/.test(lines[i+5] || 'text'); // Look ahead if possible

          if (isDate || !/^\d+\.?\d*$/.test(potentialDate)) {
             // likely a date line
             if (potentialDate.toLowerCase().includes('tomorrow')) {
                 const d = new Date();
                 d.setDate(d.getDate() + 1);
                 dateRaw = d.toISOString().split('T')[0];
             } else if (!potentialDate.toLowerCase().includes('today')) {
                 // Try parse specific date if needed, else default today
             }
             consumedLines = 5;
          }
        }

        const oddsVal = parseFloat(oddsRaw);
        if (isNaN(oddsVal)) {
           // Heuristic failed, maybe not a bet block, skip one line
           i++;
           continue;
        }

        i += consumedLines;
        calculatedOdds *= oddsVal;

        // --- INTELLIGENT PARSING LOGIC ---
        let type = BetType.MATCH_WINNER;
        let selection = 'Home';

        const marketUpper = marketRaw.toUpperCase();
        const selectionUpper = selectionRaw.toUpperCase();

        // Match Parsing
        const teams = matchRaw.split(/\s+-\s+|\s+v\s+|\s+vs\.?\s+/i);
        const homeTeam = teams[0]?.trim();
        const awayTeam = teams[1]?.trim();

        // 1. BTTS
        if (marketUpper.includes('BOTH TEAMS TO SCORE') || marketUpper.includes('BTTS') || marketUpper.includes('GG/NG') || marketUpper.includes('GOAL/GOAL')) {
            type = BetType.BTTS;
            if (selectionUpper.includes('YES') || selectionUpper === 'GG' || selectionUpper.includes('GOAL/GOAL')) selection = 'Yes';
            else selection = 'No';
        }
        // 2. Over/Under
        else if (marketUpper.includes('OVER') || marketUpper.includes('UNDER') || marketUpper.includes('TOTAL GOALS')) {
             type = BetType.OVER_UNDER;
             // Case A: Selection is "Over 2.5"
             if (selectionRaw.match(/(Over|Under)\s+\d+\.?\d*/i)) {
                 const parts = selectionRaw.split(' ');
                 const dir = parts[0].charAt(0).toUpperCase() + parts[0].slice(1).toLowerCase();
                 const val = parts[1] || '2.5';
                 selection = `${dir} ${val}`;
             }
             // Case B: Selection is "Over", Market is "Over/Under 2.5"
             else {
                  const match = marketRaw.match(/(\d+\.?\d*)/);
                  const line = match ? match[0] : '2.5';
                  if (selectionUpper.includes('OVER')) selection = `Over ${line}`;
                  else if (selectionUpper.includes('UNDER')) selection = `Under ${line}`;
                  else selection = `Over ${line}`; // Fallback
             }
        }
        // 3. Double Chance
        else if (marketUpper.includes('DOUBLE CHANCE')) {
            type = BetType.DOUBLE_CHANCE;
            if (selectionUpper === '1X' || (selectionUpper.includes('HOME') && selectionUpper.includes('DRAW')) || selectionUpper.includes(homeTeam?.toUpperCase() || '$$$')) selection = '1X';
            else if (selectionUpper === 'X2' || (selectionUpper.includes('AWAY') && selectionUpper.includes('DRAW')) || selectionUpper.includes(awayTeam?.toUpperCase() || '$$$')) selection = 'X2';
            else selection = '12';
        }
        // 4. Draw No Bet
        else if (marketUpper.includes('DRAW NO BET') || marketUpper.includes('DNB')) {
            type = BetType.DRAW_NO_BET;
            if (selectionRaw === homeTeam || selectionUpper === '1' || selectionUpper.includes('HOME')) selection = 'Home';
            else selection = 'Away';
        }
        // 5. Winning Margin
        else if (marketUpper.includes('WINNING MARGIN')) {
            type = BetType.WINNING_MARGIN;
            selection = selectionRaw; // Preserve exact text for margin
        }
        // 6. Handicap
        else if (marketUpper.includes('HANDICAP')) {
            type = BetType.HANDICAP;
            selection = selectionRaw;
        }
        // 7. Corners
        else if (marketUpper.includes('CORNER')) {
            type = BetType.TOTAL_CORNERS;
            selection = selectionRaw;
        }
        // Default: 1X2 (Match Winner)
        else {
            type = BetType.MATCH_WINNER;
            // Try to map selection to Home/Away/Draw
            if (selectionRaw === homeTeam || selectionRaw === '1' || selectionUpper.includes('HOME')) selection = 'Home';
            else if (selectionRaw === awayTeam || selectionRaw === '2' || selectionUpper.includes('AWAY')) selection = 'Away';
            else if (selectionUpper.includes('DRAW') || selectionRaw === 'X') selection = 'Draw';
            else selection = 'Home'; // Fallback
        }

        newLegs.push({
          id: generateId(),
          matchName: matchRaw,
          date: dateRaw,
          type: type,
          selection: selection,
          status: LegStatus.PENDING
        });
      }

      if (newLegs.length > 0) {
        setLegs(newLegs);
        setTotalOdds(calculatedOdds.toFixed(2));
        setShowImport(false);
        setImportText('');
      } else {
        alert("Could not parse any bets. Please check the format.");
      }

    } catch (e) {
      console.error(e);
      alert("Error parsing the text.");
    }
  };

