            className="px-8 py-3 rounded-lg font-bold bg-primary hover:bg-blue-600 text-white shadow-lg shadow-blue-500/20 transition-all flex items-center gap-2"
          >
            <Save size={18} /> {isEditing ? 'Update Bet Slip' : 'Save Bet Slip'}
          </button>
        </div>
      </div>
    </div>
  );
};

export enum BetType {
  MATCH_WINNER = '1X2',
  BTTS = 'BTTS',
  OVER_UNDER = 'OVER_UNDER',
  DOUBLE_CHANCE = 'DOUBLE_CHANCE',
  DRAW_NO_BET = 'DRAW_NO_BET',
  TOTAL_CORNERS = 'TOTAL_CORNERS',
  HANDICAP = 'HANDICAP',
  BOOKINGS = 'BOOKINGS',
  SENDING_OFF = 'SENDING_OFF',
  EXACT_GOALS = 'EXACT_GOALS',
  ODD_EVEN = 'ODD_EVEN',
  WINNING_MARGIN = 'WINNING_MARGIN',

  // Halves Markets
  HALF_TIME_WINNER = '1ST_HALF_1X2',
  HALF_TIME_DOUBLE_CHANCE = '1ST_HALF_DC',
  HALF_TIME_BTTS = '1ST_HALF_BTTS',
  HALVES_BTTS = '1ST_2ND_HALF_BTTS', // e.g. Yes/Yes
  HALF_TIME_1ST_GOAL = '1ST_HALF_1ST_GOAL',
  HALF_TIME_1ST_CORNER = '1ST_HALF_1ST_CORNER',
  HALF_TIME_WINNER_AND_BTTS = '1ST_HALF_1X2_BTTS',
  WIN_EITHER_HALF = 'WIN_EITHER_HALF',
}

export enum LegStatus {
  PENDING = 'PENDING',
  WON = 'WON',
  LOST = 'LOST',
  VOID = 'VOID'
}

export enum SlipStatus {
  PENDING = 'PENDING',
  WON = 'WON',
  LOST = 'LOST',
  VOID = 'VOID'
}

export type Currency = 'USD' | 'GBP' | 'ZAR';

export const CURRENCY_SYMBOLS: Record<Currency, string> = {
  USD: '$',
  GBP: '£',
  ZAR: 'R'
};

export interface Leg {
  id: string;
  matchName: string; // e.g., "Arsenal vs Liverpool"
  date: string; // YYYY-MM-DD
  type: BetType;
  selection: string; // e.g., "Home", "Yes", "Over 2.5", "Home -1.5"
  status: LegStatus;
  resultScore?: string; // e.g., "2-1"
  notes?: string;
}

export interface Slip {
  id: string;
  createdAt: number;
  legs: Leg[];
  stake: number;
  odds: number;
  potentialReturn: number;
  status: SlipStatus;
  groundingUrls?: string[]; // URLs used for verification
}

export interface ValidationResult {
  legId: string;
  status: LegStatus;
  score: string;
}

export interface Stats {
  totalSlips: number;
  wins: number;
  losses: number;
  winRate: number;
  totalStaked: number;
  totalReturned: number;
  profit: number;
  roi: number;
}

import React, { useState, useEffect } from 'react';
import { Plus, Trash2, Save, Calendar, CheckCircle, ClipboardPaste, X, Edit3 } from 'lucide-react';
import { BetType, Leg, LegStatus, Slip, SlipStatus, Currency, CURRENCY_SYMBOLS } from '../types';

interface NewSlipFormProps {
  initialData?: Slip;
  onSave: (slip: Slip) => void;
  onCancel: () => void;
  currency: Currency;
}

// Robust ID generator that works in all environments (unlike crypto.randomUUID)
const generateId = () => {
  return Date.now().toString(36) + Math.random().toString(36).substring(2, 9);
};

export const NewSlipForm: React.FC<NewSlipFormProps> = ({ initialData, onSave, onCancel, currency }) => {
  // Initialize state from InitialData (Edit mode) or LocalStorage (Draft), otherwise default
  const [stake, setStake] = useState<string>(() => {
    if (initialData) return initialData.stake.toString();
    const saved = localStorage.getItem('smartbet_draft_stake');
    return saved || '10';
  });

  const [totalOdds, setTotalOdds] = useState<string>(() => {
    if (initialData) return initialData.odds.toString();
    const saved = localStorage.getItem('smartbet_draft_odds');
    return saved || '1.00';
  });

  const [legs, setLegs] = useState<Leg[]>(() => {
    if (initialData) return initialData.legs;
    const saved = localStorage.getItem('smartbet_draft_legs');
    if (saved) {
      return JSON.parse(saved);
    }
    return [{
      id: generateId(),
      matchName: '',
      date: new Date().toISOString().split('T')[0],
      type: BetType.MATCH_WINNER,
      selection: 'Home',
      status: LegStatus.PENDING,
    }];
  });

  // Import State
  const [showImport, setShowImport] = useState(false);
  const [importText, setImportText] = useState('');

  const symbol = CURRENCY_SYMBOLS[currency];
  const isEditing = !!initialData;

  // Auto-Save Draft Effects
  useEffect(() => {
    localStorage.setItem('smartbet_draft_stake', stake);
  }, [stake]);

  useEffect(() => {
    localStorage.setItem('smartbet_draft_odds', totalOdds);
  }, [totalOdds]);

  useEffect(() => {
    localStorage.setItem('smartbet_draft_legs', JSON.stringify(legs));
  }, [legs]);

  const clearDraft = () => {
    localStorage.removeItem('smartbet_draft_stake');
    localStorage.removeItem('smartbet_draft_odds');
    localStorage.removeItem('smartbet_draft_legs');
  };

  const addLeg = () => {
    setLegs([
      ...legs,
      {
        id: generateId(),
        matchName: '',
        date: new Date().toISOString().split('T')[0],
        type: BetType.MATCH_WINNER,
        selection: 'Home',
        status: LegStatus.PENDING,
      }
    ]);
  };

  const removeLeg = (id: string) => {
    if (legs.length > 1) {
      setLegs(legs.filter(l => l.id !== id));
    }
  };

  const updateLeg = (id: string, field: keyof Leg, value: any) => {
    setLegs(legs.map(l => {
      if (l.id === id) {
        const updated = { ...l, [field]: value };
        // Reset selection if type changes to avoid invalid states
        if (field === 'type') {
           if (value === BetType.MATCH_WINNER) updated.selection = 'Home';
           if (value === BetType.BTTS) updated.selection = 'Yes';
           if (value === BetType.OVER_UNDER) updated.selection = 'Over 2.5';
           if (value === BetType.DOUBLE_CHANCE) updated.selection = '1X';
           if (value === BetType.DRAW_NO_BET) updated.selection = 'Home';
           if (value === BetType.TOTAL_CORNERS) updated.selection = 'Over 9.5';
           if (value === BetType.HANDICAP) updated.selection = 'Home -1.5';
           if (value === BetType.BOOKINGS) updated.selection = 'Over 3.5';
           if (value === BetType.SENDING_OFF) updated.selection = 'Yes';
           if (value === BetType.EXACT_GOALS) updated.selection = '1';
           if (value === BetType.ODD_EVEN) updated.selection = 'Odd';
           if (value === BetType.WINNING_MARGIN) updated.selection = 'Home By 1';

           // New Halves Defaults
           if (value === BetType.HALF_TIME_WINNER) updated.selection = 'Home';
           if (value === BetType.HALF_TIME_DOUBLE_CHANCE) updated.selection = '1X';
           if (value === BetType.HALF_TIME_BTTS) updated.selection = 'Yes';
           if (value === BetType.HALVES_BTTS) updated.selection = 'Yes/Yes';
           if (value === BetType.HALF_TIME_1ST_GOAL) updated.selection = 'Home';
           if (value === BetType.HALF_TIME_1ST_CORNER) updated.selection = 'Home';
           if (value === BetType.HALF_TIME_WINNER_AND_BTTS) updated.selection = 'Home & Yes';
           if (value === BetType.WIN_EITHER_HALF) updated.selection = 'Home';
        }
        return updated;
      }
      return l;
    }));
  };

  const getTeamNames = (matchName: string) => {
    // Simple split attempt
    const parts = matchName.split(/\s+v\s+|\s+vs\.?\s+|\s+-\s+/i);
    return {
      home: parts[0]?.trim() || 'Home',
      away: parts[1]?.trim() || 'Away'
    };
  };

  // Helper to allow only valid numeric input (no sliders/spinners)
  const handleNumericChange = (value: string, setter: (v: string) => void) => {
    // Allow empty or strictly digits with optional single decimal point
    if (value === '' || /^\d*\.?\d*$/.test(value)) {
      setter(value);
    }
  };

  const handleImport = () => {
    if (!importText.trim()) return;

    try {
      const lines = importText.split('\n').map(l => l.trim()).filter(l => l.length > 0);

      const newLegs: Leg[] = [];
      let calculatedOdds = 1;

      let i = 0;
      while (i < lines.length) {
        // Try to handle blocks of 4 or 5 lines
        // Typical structure:
        // Selection
        // Odds
        // Market
        // Match
        // Date (Optional/Sometimes on same line)

        if (i + 3 > lines.length) break; // Need at least 4 lines for a valid bet block

        const selectionRaw = lines[i];
        const oddsRaw = lines[i+1];
        const marketRaw = lines[i+2];
        const matchRaw = lines[i+3];

        // Check if next line is a date or start of new bet (Odds are usually numbers)
        let dateRaw = new Date().toISOString().split('T')[0]; // Default today
        let consumedLines = 4;

        if (i + 4 < lines.length) {
          const potentialDate = lines[i+4];
          // If potentialDate is not a number (not odds of next bet) and contains date-like keywords
          const isDate = potentialDate.match(/\d{2}:\d{2}|Today|Tomorrow|\d{2}\/\d{2}/i);
          const nextIsOdds = /^\d+\.?\d*$/.test(lines[i+5] || 'text'); // Look ahead if possible

          if (isDate || !/^\d+\.?\d*$/.test(potentialDate)) {
             // likely a date line
             if (potentialDate.toLowerCase().includes('tomorrow')) {
                 const d = new Date();
                 d.setDate(d.getDate() + 1);
                 dateRaw = d.toISOString().split('T')[0];
             } else if (!potentialDate.toLowerCase().includes('today')) {
                 // Try parse specific date if needed, else default today
             }
             consumedLines = 5;
          }
        }

        const oddsVal = parseFloat(oddsRaw);
        if (isNaN(oddsVal)) {
           // Heuristic failed, maybe not a bet block, skip one line
           i++;
           continue;
        }

        i += consumedLines;
        calculatedOdds *= oddsVal;

        // --- INTELLIGENT PARSING LOGIC ---
        let type = BetType.MATCH_WINNER;
        let selection = 'Home';

        const marketUpper = marketRaw.toUpperCase();
        const selectionUpper = selectionRaw.toUpperCase();

        // Match Parsing
        const teams = matchRaw.split(/\s+-\s+|\s+v\s+|\s+vs\.?\s+/i);
        const homeTeam = teams[0]?.trim();
        const awayTeam = teams[1]?.trim();

        // 1. BTTS
        if (marketUpper.includes('BOTH TEAMS TO SCORE') || marketUpper.includes('BTTS') || marketUpper.includes('GG/NG') || marketUpper.includes('GOAL/GOAL')) {
            type = BetType.BTTS;
            if (selectionUpper.includes('YES') || selectionUpper === 'GG' || selectionUpper.includes('GOAL/GOAL')) selection = 'Yes';
            else selection = 'No';
        }
        // 2. Over/Under
        else if (marketUpper.includes('OVER') || marketUpper.includes('UNDER') || marketUpper.includes('TOTAL GOALS')) {
             type = BetType.OVER_UNDER;
             // Case A: Selection is "Over 2.5"
             if (selectionRaw.match(/(Over|Under)\s+\d+\.?\d*/i)) {
                 const parts = selectionRaw.split(' ');
                 const dir = parts[0].charAt(0).toUpperCase() + parts[0].slice(1).toLowerCase();
                 const val = parts[1] || '2.5';
                 selection = `${dir} ${val}`;
             }
             // Case B: Selection is "Over", Market is "Over/Under 2.5"
             else {
                  const match = marketRaw.match(/(\d+\.?\d*)/);
                  const line = match ? match[0] : '2.5';
                  if (selectionUpper.includes('OVER')) selection = `Over ${line}`;
                  else if (selectionUpper.includes('UNDER')) selection = `Under ${line}`;
                  else selection = `Over ${line}`; // Fallback
             }
        }
        // 3. Double Chance
        else if (marketUpper.includes('DOUBLE CHANCE')) {
            type = BetType.DOUBLE_CHANCE;
            if (selectionUpper === '1X' || (selectionUpper.includes('HOME') && selectionUpper.includes('DRAW')) || selectionUpper.includes(homeTeam?.toUpperCase() || '$$$')) selection = '1X';
            else if (selectionUpper === 'X2' || (selectionUpper.includes('AWAY') && selectionUpper.includes('DRAW')) || selectionUpper.includes(awayTeam?.toUpperCase() || '$$$')) selection = 'X2';
            else selection = '12';
        }
        // 4. Draw No Bet
        else if (marketUpper.includes('DRAW NO BET') || marketUpper.includes('DNB')) {
            type = BetType.DRAW_NO_BET;
            if (selectionRaw === homeTeam || selectionUpper === '1' || selectionUpper.includes('HOME')) selection = 'Home';
            else selection = 'Away';
        }
        // 5. Winning Margin
        else if (marketUpper.includes('WINNING MARGIN')) {
            type = BetType.WINNING_MARGIN;
            selection = selectionRaw; // Preserve exact text for margin
        }
        // 6. Handicap
        else if (marketUpper.includes('HANDICAP')) {
            type = BetType.HANDICAP;
            selection = selectionRaw;
        }
        // 7. Corners
        else if (marketUpper.includes('CORNER')) {
            type = BetType.TOTAL_CORNERS;
            selection = selectionRaw;
        }
        // 8. Win Either Half
        else if (marketUpper.includes('WIN EITHER HALF') || marketUpper.includes('TO WIN EITHER HALF')) {
            type = BetType.WIN_EITHER_HALF;
            if (selectionUpper.includes('HOME') || selectionUpper === '1' || selectionRaw === homeTeam) selection = 'Home';
            else selection = 'Away';
        }
        // Default: 1X2 (Match Winner)
        else {
            type = BetType.MATCH_WINNER;
            // Try to map selection to Home/Away/Draw
            if (selectionRaw === homeTeam || selectionRaw === '1' || selectionUpper.includes('HOME')) selection = 'Home';
            else if (selectionRaw === awayTeam || selectionRaw === '2' || selectionUpper.includes('AWAY')) selection = 'Away';
            else if (selectionUpper.includes('DRAW') || selectionRaw === 'X') selection = 'Draw';
            else selection = 'Home'; // Fallback
        }

        newLegs.push({
          id: generateId(),
          matchName: matchRaw,
          date: dateRaw,
          type: type,
          selection: selection,
          status: LegStatus.PENDING
        });
      }

      if (newLegs.length > 0) {
        setLegs(newLegs);
        setTotalOdds(calculatedOdds.toFixed(2));
        setShowImport(false);
        setImportText('');
      } else {
        alert("Could not parse any bets. Please check the format.");
      }

    } catch (e) {
      console.error(e);
      alert("Error parsing the text.");
    }
  };

  const handleSave = () => {
    if (legs.some(l => !l.matchName)) {
      alert("Please enter all match names.");
      return;
    }

    const numStake = parseFloat(stake) || 0;
    const numOdds = parseFloat(totalOdds) || 1;

    const newSlip: Slip = {
      id: initialData ? initialData.id : generateId(),
      createdAt: initialData ? initialData.createdAt : Date.now(),
      legs,
      stake: numStake,
      odds: numOdds,
      potentialReturn: numStake * numOdds,
      status: initialData ? initialData.status : SlipStatus.PENDING,
    };

    onSave(newSlip);
    clearDraft();
  };

  const handleCancel = () => {
    onCancel();
  };

  return (
    <div className="bg-surface rounded-xl shadow-xl border border-borderBase overflow-hidden relative transition-colors">
      <div className="p-6 border-b border-borderBase flex justify-between items-center bg-inputBg">
        <h2 className="text-xl font-bold text-textMain flex items-center gap-2">
          {isEditing ? <Edit3 className="text-primary" /> : <Plus className="text-primary" />} 
          {isEditing ? 'Edit Bet Slip' : 'Create New Bet Slip'}
        </h2>
        <div className="flex gap-2">
          {/* Draft Indicator */}
          {!isEditing && (
            <span className="text-[10px] uppercase tracking-wider font-bold text-success/80 border border-success/20 px-2 py-1 rounded-full flex items-center bg-success/5">
              Auto-Saved
            </span>
          )}
          <button 
            onClick={() => setShowImport(true)}
            className="text-xs flex items-center gap-1 bg-surface border border-borderBase hover:bg-background text-textMain px-3 py-1.5 rounded transition-colors"
          >
            <ClipboardPaste size={14} /> Import from Text
          </button>
        </div>
      </div>

      {showImport && (
        <div className="absolute inset-0 z-50 bg-background/95 flex flex-col items-center justify-center p-6 animate-fade-in">
           <div className="w-full max-w-lg bg-surface border border-borderBase rounded-xl p-6 shadow-2xl">
              <div className="flex justify-between items-center mb-4">
                 <h3 className="text-textMain font-bold flex items-center gap-2">
                   <ClipboardPaste className="text-primary" /> Paste Bet Slip
                 </h3>
                 <button onClick={() => setShowImport(false)} className="text-textMuted hover:text-textMain">
                   <X size={20} />
                 </button>
              </div>
              <textarea
                value={importText}
                onChange={(e) => setImportText(e.target.value)}
                placeholder={`Paste your bet details here...\n\nExample:\nYes\n1.48\nBoth Teams To Score (GG/NG)\nManchester United - Bournemouth\nToday 16:00`}
                className="w-full h-64 bg-inputBg border border-borderBase rounded-lg p-4 text-xs font-mono text-textMain focus:outline-none focus:border-primary resize-none placeholder-textMuted"
              />
              <div className="mt-4 flex justify-end gap-3">
                 <button 
                   onClick={() => setShowImport(false)}
                   className="px-4 py-2 rounded text-textMuted hover:text-textMain hover:bg-inputBg"
                 >
                   Cancel
                 </button>
                 <button 
                   onClick={handleImport}
                   className="px-6 py-2 rounded bg-primary text-white font-bold hover:bg-blue-600"
                 >
                   Parse & Import
                 </button>
              </div>
           </div>
        </div>
      )}

      <div className="p-6 space-y-6">
        <div className="space-y-4">
          <label className="text-sm font-medium text-textMuted uppercase tracking-wider">Selections</label>

          {legs.map((leg, index) => (
            <div key={leg.id} className="grid grid-cols-1 md:grid-cols-12 gap-4 p-4 bg-background rounded-lg border border-borderBase hover:border-textMuted transition-colors">
              <div className="md:col-span-4 space-y-1">
                <label className="text-xs text-textMuted">Match</label>
                <input
                  type="text"
                  value={leg.matchName}
                  onChange={(e) => updateLeg(leg.id, 'matchName', e.target.value)}
                  placeholder="e.g. Arsenal vs Liverpool"
                  className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary placeholder-textMuted/50"
                />
              </div>

              <div className="md:col-span-2 space-y-1">
                <label className="text-xs text-textMuted">Date</label>
                <div className="relative">
                  <input
                    type="date"
                    value={leg.date}
                    onChange={(e) => updateLeg(leg.id, 'date', e.target.value)}
                    className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                  />
                </div>
              </div>

              <div className="md:col-span-2 space-y-1">
                <label className="text-xs text-textMuted">Market</label>
                <select
                  value={leg.type}
                  onChange={(e) => updateLeg(leg.id, 'type', e.target.value)}
                  className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                >
                  <optgroup label="Full Time">
                    <option value={BetType.MATCH_WINNER}>1X2 Winner</option>
                    <option value={BetType.DOUBLE_CHANCE}>Double Chance</option>
                    <option value={BetType.BTTS}>Both Teams To Score</option>
                    <option value={BetType.OVER_UNDER}>Over/Under Goals</option>
                    <option value={BetType.DRAW_NO_BET}>Draw No Bet</option>
                    <option value={BetType.TOTAL_CORNERS}>Total Corners</option>
                    <option value={BetType.BOOKINGS}>Bookings (Cards)</option>
                    <option value={BetType.SENDING_OFF}>Sending Off</option>
                    <option value={BetType.EXACT_GOALS}>Exact Goals</option>
                    <option value={BetType.ODD_EVEN}>Odd/Even Goals</option>
                    <option value={BetType.HANDICAP}>Handicap</option>
                    <option value={BetType.WINNING_MARGIN}>Winning Margin</option>
                  </optgroup>
                  <optgroup label="Half Time">
                    <option value={BetType.HALF_TIME_WINNER}>1st Half - 1X2</option>
                    <option value={BetType.HALF_TIME_DOUBLE_CHANCE}>1st Half - Double Chance</option>
                    <option value={BetType.HALF_TIME_BTTS}>1st Half - BTTS</option>
                    <option value={BetType.HALVES_BTTS}>1st/2nd Half BTTS</option>
                    <option value={BetType.HALF_TIME_1ST_GOAL}>1st Half - 1st Goal</option>
                    <option value={BetType.HALF_TIME_1ST_CORNER}>1st Half - 1st Corner</option>
                    <option value={BetType.HALF_TIME_WINNER_AND_BTTS}>1st Half - 1X2 & BTTS</option>
                    <option value={BetType.WIN_EITHER_HALF}>Win Either Half</option>
                  </optgroup>
                </select>
              </div>

              <div className="md:col-span-3 space-y-1">
                <label className="text-xs text-textMuted">Selection</label>

                {(leg.type === BetType.MATCH_WINNER || leg.type === BetType.HALF_TIME_WINNER) && (
                  <select
                    value={leg.selection}
                    onChange={(e) => updateLeg(leg.id, 'selection', e.target.value)}
                    className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                  >
                    <option value="Home">Home Win (1)</option>
                    <option value="Draw">Draw (X)</option>
                    <option value="Away">Away Win (2)</option>
                  </select>
                )}

                {(leg.type === BetType.DOUBLE_CHANCE || leg.type === BetType.HALF_TIME_DOUBLE_CHANCE) && (
                  <select
                    value={leg.selection}
                    onChange={(e) => updateLeg(leg.id, 'selection', e.target.value)}
                    className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                  >
                    <option value="1X">Home or Draw (1X)</option>
                    <option value="X2">Away or Draw (X2)</option>
                    <option value="12">Home or Away (12)</option>
                  </select>
                )}

                {(leg.type === BetType.BTTS || leg.type === BetType.HALF_TIME_BTTS) && (
                  <select
                    value={leg.selection}
                    onChange={(e) => updateLeg(leg.id, 'selection', e.target.value)}
                    className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                  >
                    <option value="Yes">Yes</option>
                    <option value="No">No</option>
                  </select>
                )}

                {leg.type === BetType.HALVES_BTTS && (
                  <select
                    value={leg.selection}
                    onChange={(e) => updateLeg(leg.id, 'selection', e.target.value)}
                    className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                  >
                    <option value="Yes/Yes">1st: Yes / 2nd: Yes</option>
                    <option value="Yes/No">1st: Yes / 2nd: No</option>
                    <option value="No/Yes">1st: No / 2nd: Yes</option>
                    <option value="No/No">1st: No / 2nd: No</option>
                  </select>
                )}

                {leg.type === BetType.HALF_TIME_WINNER_AND_BTTS && (
                   <select
                    value={leg.selection}
                    onChange={(e) => updateLeg(leg.id, 'selection', e.target.value)}
                    className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                  >
                    <option value="Home & Yes">Home & Yes</option>
                    <option value="Home & No">Home & No</option>
                    <option value="Draw & Yes">Draw & Yes</option>
                    <option value="Draw & No">Draw & No</option>
                    <option value="Away & Yes">Away & Yes</option>
                    <option value="Away & No">Away & No</option>
                  </select>
                )}

                {(leg.type === BetType.HALF_TIME_1ST_GOAL || leg.type === BetType.HALF_TIME_1ST_CORNER) && (
                   <select
                    value={leg.selection}
                    onChange={(e) => updateLeg(leg.id, 'selection', e.target.value)}
                    className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                  >
                    <option value="Home">{getTeamNames(leg.matchName).home}</option>
                    <option value="Away">{getTeamNames(leg.matchName).away}</option>
                    <option value="None">None</option>
                  </select>
                )}

                {leg.type === BetType.SENDING_OFF && (
                  <select
                    value={leg.selection}
                    onChange={(e) => updateLeg(leg.id, 'selection', e.target.value)}
                    className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                  >
                    <option value="Yes">Yes (Red Card Shown)</option>
                    <option value="No">No (No Red Card)</option>
                  </select>
                )}

                {leg.type === BetType.ODD_EVEN && (
                  <select
                    value={leg.selection}
                    onChange={(e) => updateLeg(leg.id, 'selection', e.target.value)}
                    className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                  >
                    <option value="Odd">Odd</option>
                    <option value="Even">Even (0 is Even)</option>
                  </select>
                )}

                {leg.type === BetType.DRAW_NO_BET && (
                  <select
                    value={leg.selection}
                    onChange={(e) => updateLeg(leg.id, 'selection', e.target.value)}
                    className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                  >
                    <option value="Home">Home</option>
                    <option value="Away">Away</option>
                  </select>
                )}

                {leg.type === BetType.WIN_EITHER_HALF && (
                  <select
                    value={leg.selection}
                    onChange={(e) => updateLeg(leg.id, 'selection', e.target.value)}
                    className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                  >
                    <option value="Home">Home</option>
                    <option value="Away">Away</option>
                  </select>
                )}

                {leg.type === BetType.OVER_UNDER && (
                  <div className="flex gap-2">
                     <select
                        value={leg.selection.split(' ')[0]}
                        onChange={(e) => updateLeg(leg.id, 'selection', `${e.target.value} ${leg.selection.split(' ')[1] || '2.5'}`)}
                        className="w-1/2 bg-inputBg border border-borderBase rounded px-2 py-2 text-textMain text-sm"
                      >
                        <option value="Over">Over</option>
                        <option value="Under">Under</option>
                      </select>
                       <select
                        value={leg.selection.split(' ')[1]}
                        onChange={(e) => updateLeg(leg.id, 'selection', `${leg.selection.split(' ')[0] || 'Over'} ${e.target.value}`)}
                        className="w-1/2 bg-inputBg border border-borderBase rounded px-2 py-2 text-textMain text-sm"
                      >
                        <option value="0.5">0.5</option>
                        <option value="1.5">1.5</option>
                        <option value="2.5">2.5</option>
                        <option value="3.5">3.5</option>
                        <option value="4.5">4.5</option>
                      </select>
                  </div>
                )}

                {(leg.type === BetType.TOTAL_CORNERS || leg.type === BetType.BOOKINGS) && (
                  <div className="flex gap-2">
                     <select
                        value={leg.selection.split(' ')[0]}
                        onChange={(e) => updateLeg(leg.id, 'selection', `${e.target.value} ${leg.selection.split(' ')[1] || (leg.type === BetType.TOTAL_CORNERS ? '9.5' : '3.5')}`)}
                        className="w-1/2 bg-inputBg border border-borderBase rounded px-2 py-2 text-textMain text-sm"
                      >
                        <option value="Over">Over</option>
                        <option value="Under">Under</option>
                      </select>
                      <input 
                        type="text"
                        inputMode="decimal"
                        value={leg.selection.split(' ')[1] || (leg.type === BetType.TOTAL_CORNERS ? '9.5' : '3.5')}
                        onChange={(e) => {
                          const val = e.target.value;
                          if (val === '' || /^\d*\.?\d*$/.test(val)) {
                             updateLeg(leg.id, 'selection', `${leg.selection.split(' ')[0] || 'Over'} ${val}`);
                          }
                        }}
                        className="w-1/2 bg-inputBg border border-borderBase rounded px-2 py-2 text-textMain text-sm"
                      />
                  </div>
                )}

                {leg.type === BetType.EXACT_GOALS && (
                   <div className="flex gap-2">
                      <input 
                        type="text"
                        inputMode="numeric"
                        placeholder="e.g. 2"
                        value={leg.selection}
                        onChange={(e) => {
                          const val = e.target.value;
                          if (val === '' || /^\d+$/.test(val)) {
                             updateLeg(leg.id, 'selection', val);
                          }
                        }}
                        className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm"
                      />
                   </div>
                )}

                {leg.type === BetType.HANDICAP && (
                  <div className="flex gap-2">
                     <select
                        value={leg.selection.split(' ')[0]}
                        onChange={(e) => updateLeg(leg.id, 'selection', `${e.target.value} ${leg.selection.split(' ')[1] || '-1.5'}`)}
                        className="w-1/2 bg-inputBg border border-borderBase rounded px-2 py-2 text-textMain text-sm"
                      >
                        <option value="Home">Home</option>
                        <option value="Away">Away</option>
                      </select>
                      <input 
                        type="text"
                        value={leg.selection.split(' ').slice(1).join(' ') || '-1.5'}
                        onChange={(e) => {
                          const val = e.target.value;
                           updateLeg(leg.id, 'selection', `${leg.selection.split(' ')[0] || 'Home'} ${val}`);
                        }}
                        placeholder="-1.5"
                        className="w-1/2 bg-inputBg border border-borderBase rounded px-2 py-2 text-textMain text-sm"
                      />
                  </div>
                )}

                {leg.type === BetType.WINNING_MARGIN && (
                  <div className="flex gap-2">
                    <select
                      value={leg.selection === 'Draw' ? 'Draw' : leg.selection.split(' By ')[0]}
                      onChange={(e) => {
                        const val = e.target.value;
                        if (val === 'Draw') {
                           updateLeg(leg.id, 'selection', 'Draw');
                        } else {
                           // Preserve margin if switching between Home/Away, default to 1 if coming from Draw
                           const currentMargin = leg.selection.includes('By') ? leg.selection.split(' By ')[1] : '1';
                           updateLeg(leg.id, 'selection', `${val} By ${currentMargin}`);
                        }
                      }}
                      className="w-1/2 bg-inputBg border border-borderBase rounded px-2 py-2 text-textMain text-sm"
                    >
                      <option value="Home">Home</option>
                      <option value="Away">Away</option>
                      <option value="Draw">Draw</option>
                    </select>

                    {leg.selection !== 'Draw' && (
                       <select
                        value={leg.selection.split(' By ')[1] || '1'}
                        onChange={(e) => {
                          const side = leg.selection.split(' By ')[0] || 'Home';
                          updateLeg(leg.id, 'selection', `${side} By ${e.target.value}`);
                        }}
                        className="w-1/2 bg-inputBg border border-borderBase rounded px-2 py-2 text-textMain text-sm"
                      >
                        <option value="1">By 1</option>
                        <option value="2">By 2</option>
                        <option value="3+">By 3+</option>
                      </select>
                    )}
                  </div>
                )}
              </div>

              <div className="md:col-span-1 flex items-end justify-center pb-1">
                <button 
                  onClick={() => removeLeg(leg.id)}
                  disabled={legs.length === 1}
                  className={`p-2 rounded hover:bg-danger/20 text-danger/80 hover:text-danger transition-colors ${legs.length === 1 ? 'opacity-50 cursor-not-allowed' : ''}`}
                >
                  <Trash2 size={18} />
                </button>
              </div>
            </div>
          ))}

          <button 
            onClick={addLeg}
            className="w-full py-3 border border-dashed border-borderBase rounded-lg text-textMuted hover:text-textMain hover:border-textMuted hover:bg-inputBg transition-all flex items-center justify-center gap-2"
          >
            <Plus size={18} /> Add Another Match
          </button>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 pt-6 border-t border-borderBase">
           <div>
              <label className="text-sm font-medium text-textMuted block mb-2">Total Stake ({symbol})</label>
              <input 
                type="text" 
                inputMode="decimal"
                value={stake}
                onChange={(e) => handleNumericChange(e.target.value, setStake)}
                className="w-full bg-inputBg border border-borderBase rounded px-4 py-3 text-textMain font-bold focus:outline-none focus:border-primary"
                placeholder="0.00"
              />
           </div>
           <div>
              <label className="text-sm font-medium text-textMuted block mb-2">Total Odds</label>
              <input 
                type="text" 
                inputMode="decimal"
                value={totalOdds}
                onChange={(e) => handleNumericChange(e.target.value, setTotalOdds)}
                className="w-full bg-inputBg border border-borderBase rounded px-4 py-3 text-textMain font-bold focus:outline-none focus:border-primary"
                placeholder="1.00"
              />
           </div>
        </div>

        <div className="bg-primary/10 rounded-lg p-4 flex justify-between items-center border border-primary/20">
          <span className="text-primary font-medium">Potential Return</span>
          <span className="text-2xl font-bold text-primary">
            {symbol}{((parseFloat(stake) || 0) * (parseFloat(totalOdds) || 0)).toFixed(2)}
          </span>
        </div>

        <div className="flex gap-4 justify-end pt-4">
          <button 
            onClick={handleCancel}
            className="px-6 py-3 rounded-lg font-medium text-textMuted hover:text-textMain hover:bg-inputBg transition-colors"
          >
            Cancel
          </button>
          <button 
            onClick={handleSave}
            className="px-8 py-3 rounded-lg font-bold bg-primary hover:bg-blue-600 text-white shadow-lg shadow-blue-500/20 transition-all flex items-center gap-2"
          >
            <Save size={18} /> {isEditing ? 'Update Bet Slip' : 'Save Bet Slip'}
          </button>
        </div>
      </div>
    </div>
  );
};

import { GoogleGenAI } from "@google/genai";
import { Slip, Leg, LegStatus, ValidationResult } from "../types";

// Initialize Gemini Client
const apiKey = process.env.API_KEY || '';
const ai = new GoogleGenAI({ apiKey });

export interface ValidationResponse {
  results: ValidationResult[];
  sources: string[];
}

export const validateSlipWithGemini = async (slip: Slip): Promise<ValidationResponse> => {
  if (!apiKey) {
    throw new Error("API Key is missing.");
  }

  // Construct a prompt that describes the bet slip
  const legsDescription = slip.legs.map(leg => 
    `- ID: ${leg.id} | Match: ${leg.matchName} | Date: ${leg.date} | Bet Type: ${leg.type} | Selection: ${leg.selection}`
  ).join('\n');

  const prompt = `
    I have a sports betting slip with the following matches and predictions. 
    Please search for the real-time match status and results using Google Search.

    CRITICAL EXECUTION RULES:
    1. **CHECK TIME/STATUS FIRST**: Look for "FT", "Full Time", "Finished", "Live", "HT", or minute markers (e.g. "65'").
    2. **LIVE MATCHES**: If the match is currently **LIVE**, **IN-PLAY**, **HALFTIME**, or **ONGOING**, the status MUST be "PENDING". Do NOT settle the bet yet, even if the condition is met (e.g. Over 0.5 goals scored).
    3. **FUTURE MATCHES**: If the match hasn't started, status is "PENDING".
    4. **FINISHED MATCHES**: Only if the match is "Finished" or "FT", determine WON/LOST/VOID.

    Bet Types Logic (Only apply if match is FINISHED):
    - 1X2: Home (1) means Home team wins, Draw (X) means draw, Away (2) means Away team wins.
    - BTTS: "Yes" means both teams scored > 0. "No" means at least one team scored 0.
    - OVER_UNDER: "Over X.5" means total goals > X.5. "Under X.5" means total goals < X.5.
    - DOUBLE_CHANCE: "1X" (Home Win or Draw), "X2" (Away Win or Draw), "12" (Home Win or Away Win).
    - DRAW_NO_BET: If Home wins, Home selection wins. If Away wins, Away selection wins. If Draw, the status is VOID.
    - TOTAL_CORNERS: You must find the corner count. "Over X" means total corners > X. "Under X" means total corners < X.
    - BOOKINGS: You must find the card count. "Over X" means total yellow/red cards > X. "Under X" means total cards < X.
    - SENDING_OFF: "Yes" means at least one Red Card was shown in the match. "No" means zero Red Cards.
    - EXACT_GOALS: Total goals in match must equal the selection exactly.
    - ODD_EVEN: Sum of total goals. 0, 2, 4... is EVEN. 1, 3, 5... is ODD.
    - HANDICAP: "Home -1.5" means you subtract 1.5 from Home's score. Then compare. e.g. Score 2-0 with Home -1.5 becomes 0.5-0 (Home wins). Score 1-0 with Home -1.5 becomes -0.5-0 (Away wins).
    - WINNING_MARGIN: The exact goal difference at Full Time. 
      - "Draw": Difference is 0.
      - "Home By X": Home Score - Away Score = X.
      - "Away By X": Away Score - Home Score = X.
      - "Home By 3+": Home Score - Away Score >= 3.
      - "Away By 3+": Away Score - Home Score >= 3.

    **HALF TIME / HALVES MARKETS**:
    - 1ST_HALF_1X2: Result at Half Time (45:00).
    - 1ST_HALF_DC: Double Chance based on Half Time score.
    - 1ST_HALF_BTTS: Did both teams score in the 1st Half (0-45 mins)?
    - 1ST_2ND_HALF_BTTS: Format is "1st Half BTTS / 2nd Half BTTS". 
      - To determine 2nd Half BTTS: Check if both teams scored goals specifically in the 2nd half (FT Score - HT Score).
      - Example: HT 1-1, FT 1-1. 1st Half BTTS=Yes. 2nd Half Score is 0-0. 2nd Half BTTS=No. Result: Yes/No.
    - 1ST_HALF_1ST_GOAL: Which team scored the first goal of the match within the 1st Half? If 0-0 at HT, result is "None".
    - 1ST_HALF_1ST_CORNER: Which team took the first corner of the match within the 1st Half?
    - 1ST_HALF_1X2_BTTS: Combined condition. 1st Half must match result AND 1st Half BTTS must match selection.
    - WIN_EITHER_HALF: 
      - "Home": Home team scores more than Away team in 1st Half OR Home team scores more than Away team in 2nd Half. 
         - Note: 2nd Half score is calculated separately (FT Score - HT Score).
         - Example: HT 0-1, FT 1-1. 1st Half: 0-1 (Away wins). 2nd Half: 1-0 (Home wins). Result: WON (because Home won 2nd half).
      - "Away": Away team wins 1st Half OR Away team wins 2nd Half.

    Bet Slip Details:
    ${legsDescription}

    IMPORTANT OUTPUT FORMAT:
    You must return the data in a raw JSON array format inside a code block, like this:
    \`\`\`json
    [
      { "legId": "...", "status": "WON", "score": "2-1" },
      { "legId": "...", "status": "PENDING", "score": "1-0 (65')" },
      { "legId": "...", "status": "VOID", "score": "1-1" }
    ]
    \`\`\`
    Valid statuses are: WON, LOST, VOID, PENDING.
    If the match is LIVE, the score field MUST include the current score AND time (e.g. "2-1 (Live 75')").
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
      },
    });

    const text = response.text || '';

    // Extract Grounding Metadata (Sources)
    const sources: string[] = [];
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
    chunks.forEach(chunk => {
      if (chunk.web?.uri) {
        sources.push(chunk.web.uri);
      }
    });

    // Extract JSON from text
    const jsonMatch = text.match(/```json\s*([\s\S]*?)\s*```/) || text.match(/\[\s*\{[\s\S]*\}\s*\]/);

    if (!jsonMatch) {
      console.error("Failed to parse JSON from Gemini response:", text);
      throw new Error("AI could not format the results correctly. Please try again.");
    }

    const jsonString = jsonMatch[1] || jsonMatch[0];
    const results = JSON.parse(jsonString) as ValidationResult[];

    return { results, sources };

  } catch (error) {
    console.error("Gemini Validation Error:", error);
    throw error;
  }
};

import React, { useState, useEffect } from 'react';
import { Plus, Trash2, Save, Calendar, CheckCircle, ClipboardPaste, X, Edit3 } from 'lucide-react';
import { BetType, Leg, LegStatus, Slip, SlipStatus, Currency, CURRENCY_SYMBOLS } from '../types';

interface NewSlipFormProps {
  initialData?: Slip;
  onSave: (slip: Slip) => void;
  onCancel: () => void;
  currency: Currency;
}

// Robust ID generator that works in all environments (unlike crypto.randomUUID)
const generateId = () => {
  return Date.now().toString(36) + Math.random().toString(36).substring(2, 9);
};

export const NewSlipForm: React.FC<NewSlipFormProps> = ({ initialData, onSave, onCancel, currency }) => {
  // Initialize state from InitialData (Edit mode) or LocalStorage (Draft), otherwise default
  const [stake, setStake] = useState<string>(() => {
    if (initialData) return initialData.stake.toString();
    const saved = localStorage.getItem('smartbet_draft_stake');
    return saved || '10';
  });

  const [totalOdds, setTotalOdds] = useState<string>(() => {
    if (initialData) return initialData.odds.toString();
    const saved = localStorage.getItem('smartbet_draft_odds');
    return saved || '1.00';
  });

  const [legs, setLegs] = useState<Leg[]>(() => {
    if (initialData) return initialData.legs;
    const saved = localStorage.getItem('smartbet_draft_legs');
    if (saved) {
      return JSON.parse(saved);
    }
    return [{
      id: generateId(),
      matchName: '',
      date: new Date().toISOString().split('T')[0],
      type: BetType.MATCH_WINNER,
      selection: 'Home',
      status: LegStatus.PENDING,
    }];
  });

  // Import State
  const [showImport, setShowImport] = useState(false);
  const [importText, setImportText] = useState('');

  const symbol = CURRENCY_SYMBOLS[currency];
  const isEditing = !!initialData;

  // Auto-Save Draft Effects
  useEffect(() => {
    localStorage.setItem('smartbet_draft_stake', stake);
  }, [stake]);

  useEffect(() => {
    localStorage.setItem('smartbet_draft_odds', totalOdds);
  }, [totalOdds]);

  useEffect(() => {
    localStorage.setItem('smartbet_draft_legs', JSON.stringify(legs));
  }, [legs]);

  const clearDraft = () => {
    localStorage.removeItem('smartbet_draft_stake');
    localStorage.removeItem('smartbet_draft_odds');
    localStorage.removeItem('smartbet_draft_legs');
  };

  const addLeg = () => {
    setLegs([
      ...legs,
      {
        id: generateId(),
        matchName: '',
        date: new Date().toISOString().split('T')[0],
        type: BetType.MATCH_WINNER,
        selection: 'Home',
        status: LegStatus.PENDING,
      }
    ]);
  };

  const removeLeg = (id: string) => {
    if (legs.length > 1) {
      setLegs(legs.filter(l => l.id !== id));
    }
  };

  const updateLeg = (id: string, field: keyof Leg, value: any) => {
    setLegs(legs.map(l => {
      if (l.id === id) {
        const updated = { ...l, [field]: value };
        // Reset selection if type changes to avoid invalid states
        if (field === 'type') {
           if (value === BetType.MATCH_WINNER) updated.selection = 'Home';
           if (value === BetType.BTTS) updated.selection = 'Yes';
           if (value === BetType.OVER_UNDER) updated.selection = 'Over 2.5';
           if (value === BetType.DOUBLE_CHANCE) updated.selection = '1X';
           if (value === BetType.DRAW_NO_BET) updated.selection = 'Home';
           if (value === BetType.TOTAL_CORNERS) updated.selection = 'Over 9.5';
           if (value === BetType.HANDICAP) updated.selection = 'Home -1.5';
           if (value === BetType.BOOKINGS) updated.selection = 'Over 3.5';
           if (value === BetType.SENDING_OFF) updated.selection = 'Yes';
           if (value === BetType.EXACT_GOALS) updated.selection = '1';
           if (value === BetType.ODD_EVEN) updated.selection = 'Odd';
           if (value === BetType.WINNING_MARGIN) updated.selection = 'Home By 1';

           // New Halves Defaults
           if (value === BetType.HALF_TIME_WINNER) updated.selection = 'Home';
           if (value === BetType.HALF_TIME_DOUBLE_CHANCE) updated.selection = '1X';
           if (value === BetType.HALF_TIME_BTTS) updated.selection = 'Yes';
           if (value === BetType.HALVES_BTTS) updated.selection = 'Yes/Yes';
           if (value === BetType.HALF_TIME_1ST_GOAL) updated.selection = 'Home';
           if (value === BetType.HALF_TIME_1ST_CORNER) updated.selection = 'Home';
           if (value === BetType.HALF_TIME_WINNER_AND_BTTS) updated.selection = 'Home & Yes';
           if (value === BetType.WIN_EITHER_HALF) updated.selection = 'Home';
        }
        return updated;
      }
      return l;
    }));
  };

  const getTeamNames = (matchName: string) => {
    // Simple split attempt
    const parts = matchName.split(/\s+v\s+|\s+vs\.?\s+|\s+-\s+/i);
    return {
      home: parts[0]?.trim() || 'Home',
      away: parts[1]?.trim() || 'Away'
    };
  };

  // Helper to allow only valid numeric input (no sliders/spinners)
  const handleNumericChange = (value: string, setter: (v: string) => void) => {
    // Allow empty or strictly digits with optional single decimal point
    if (value === '' || /^\d*\.?\d*$/.test(value)) {
      setter(value);
    }
  };

  const handleImport = () => {
    if (!importText.trim()) return;

    try {
      const lines = importText.split('\n').map(l => l.trim()).filter(l => l.length > 0);

      const newLegs: Leg[] = [];
      let calculatedOdds = 1;

      let i = 0;
      while (i < lines.length) {
        // Try to handle blocks of 4 or 5 lines
        // Typical structure:
        // Selection
        // Odds
        // Market
        // Match
        // Date (Optional/Sometimes on same line)

        if (i + 3 > lines.length) break; // Need at least 4 lines for a valid bet block

        const selectionRaw = lines[i];
        const oddsRaw = lines[i+1];
        const marketRaw = lines[i+2];
        const matchRaw = lines[i+3];

        // Check if next line is a date or start of new bet (Odds are usually numbers)
        let dateRaw = new Date().toISOString().split('T')[0]; // Default today
        let consumedLines = 4;

        if (i + 4 < lines.length) {
          const potentialDate = lines[i+4];
          // If potentialDate is not a number (not odds of next bet) and contains date-like keywords
          const isDate = potentialDate.match(/\d{2}:\d{2}|Today|Tomorrow|\d{2}\/\d{2}/i);
          const nextIsOdds = /^\d+\.?\d*$/.test(lines[i+5] || 'text'); // Look ahead if possible

          if (isDate || !/^\d+\.?\d*$/.test(potentialDate)) {
             // likely a date line
             if (potentialDate.toLowerCase().includes('tomorrow')) {
                 const d = new Date();
                 d.setDate(d.getDate() + 1);
                 dateRaw = d.toISOString().split('T')[0];
             } else if (!potentialDate.toLowerCase().includes('today')) {
                 // Try parse specific date if needed, else default today
             }
             consumedLines = 5;
          }
        }

        const oddsVal = parseFloat(oddsRaw);
        if (isNaN(oddsVal)) {
           // Heuristic failed, maybe not a bet block, skip one line
           i++;
           continue;
        }

        i += consumedLines;
        calculatedOdds *= oddsVal;

        // --- INTELLIGENT PARSING LOGIC ---
        let type = BetType.MATCH_WINNER;
        let selection = 'Home';

        const marketUpper = marketRaw.toUpperCase();
        const selectionUpper = selectionRaw.toUpperCase();

        // Match Parsing
        const teams = matchRaw.split(/\s+-\s+|\s+v\s+|\s+vs\.?\s+/i);
        const homeTeam = teams[0]?.trim();
        const awayTeam = teams[1]?.trim();

        // 1. BTTS
        if (marketUpper.includes('BOTH TEAMS TO SCORE') || marketUpper.includes('BTTS') || marketUpper.includes('GG/NG') || marketUpper.includes('GOAL/GOAL')) {
            type = BetType.BTTS;
            if (selectionUpper.includes('YES') || selectionUpper === 'GG' || selectionUpper.includes('GOAL/GOAL')) selection = 'Yes';
            else selection = 'No';
        }
        // 2. Over/Under (Enhanced Detection)
        // Checks selection text first for "Over/Under X.X" format, then checks Market for typical O/U keywords
        else if (selectionRaw.match(/^(Over|Under)\s+(\d+\.?\d*)/i) || marketUpper.includes('OVER') || marketUpper.includes('UNDER') || marketUpper.includes('TOTAL GOALS') || marketUpper.includes('MATCH GOALS') || marketUpper.includes('GOAL LINE')) {

             const ouMatch = selectionRaw.match(/^(Over|Under)\s+(\d+\.?\d*)/i);

             // Check context (Corners vs Cards vs Goals)
             let isCorners = marketUpper.includes('CORNER');
             let isCards = marketUpper.includes('CARD') || marketUpper.includes('BOOKING');

             if (ouMatch) {
                 // Explicit selection "Over 2.5" found in selection text
                 const dir = ouMatch[1].charAt(0).toUpperCase() + ouMatch[1].slice(1).toLowerCase();
                 const val = ouMatch[2];
                 selection = `${dir} ${val}`; // Standardize to "Over 2.5"
             } else {
                 // Implicit selection "Over" (without number) but number is likely in market name
                 const match = marketRaw.match(/(\d+\.?\d*)/);
                 const line = match ? match[0] : '2.5';

                 if (selectionUpper.includes('OVER')) selection = `Over ${line}`;
                 else if (selectionUpper.includes('UNDER')) selection = `Under ${line}`;
                 else selection = `Over ${line}`; // Fallback
             }

             if (isCorners) type = BetType.TOTAL_CORNERS;
             else if (isCards) type = BetType.BOOKINGS;
             else type = BetType.OVER_UNDER;
        }
        // 3. Double Chance
        else if (marketUpper.includes('DOUBLE CHANCE')) {
            type = BetType.DOUBLE_CHANCE;
            if (selectionUpper === '1X' || (selectionUpper.includes('HOME') && selectionUpper.includes('DRAW')) || selectionUpper.includes(homeTeam?.toUpperCase() || '$$$')) selection = '1X';
            else if (selectionUpper === 'X2' || (selectionUpper.includes('AWAY') && selectionUpper.includes('DRAW')) || selectionUpper.includes(awayTeam?.toUpperCase() || '$$$')) selection = 'X2';
            else selection = '12';
        }
        // 4. Draw No Bet
        else if (marketUpper.includes('DRAW NO BET') || marketUpper.includes('DNB')) {
            type = BetType.DRAW_NO_BET;
            if (selectionRaw === homeTeam || selectionUpper === '1' || selectionUpper.includes('HOME')) selection = 'Home';
            else selection = 'Away';
        }
        // 5. Winning Margin
        else if (marketUpper.includes('WINNING MARGIN')) {
            type = BetType.WINNING_MARGIN;
            selection = selectionRaw; // Preserve exact text for margin
        }
        // 6. Handicap
        else if (marketUpper.includes('HANDICAP')) {
            type = BetType.HANDICAP;
            selection = selectionRaw;
        }
        // 7. Corners (Explicit Market)
        else if (marketUpper.includes('CORNER')) {
            type = BetType.TOTAL_CORNERS;
            selection = selectionRaw;
        }
        // 8. Win Either Half
        else if (marketUpper.includes('WIN EITHER HALF') || marketUpper.includes('TO WIN EITHER HALF')) {
            type = BetType.WIN_EITHER_HALF;
            if (selectionUpper.includes('HOME') || selectionUpper === '1' || selectionRaw === homeTeam) selection = 'Home';
            else selection = 'Away';
        }
        // Default: 1X2 (Match Winner)
        else {
            type = BetType.MATCH_WINNER;
            // Try to map selection to Home/Away/Draw
            if (selectionRaw === homeTeam || selectionRaw === '1' || selectionUpper.includes('HOME')) selection = 'Home';
            else if (selectionRaw === awayTeam || selectionRaw === '2' || selectionUpper.includes('AWAY')) selection = 'Away';
            else if (selectionUpper.includes('DRAW') || selectionRaw === 'X') selection = 'Draw';
            else selection = 'Home'; // Fallback
        }

        newLegs.push({
          id: generateId(),
          matchName: matchRaw,
          date: dateRaw,
          type: type,
          selection: selection,
          status: LegStatus.PENDING
        });
      }

      if (newLegs.length > 0) {
        setLegs(newLegs);
        setTotalOdds(calculatedOdds.toFixed(2));
        setShowImport(false);
        setImportText('');
      } else {
        alert("Could not parse any bets. Please check the format.");
      }

    } catch (e) {
      console.error(e);
      alert("Error parsing the text.");
    }
  };

