import React, { useMemo } from 'react';
import { 
  TrendingUp, 
  TrendingDown, 
  Target, 
  PieChart, 
  BarChart3, 
  DollarSign, 
  Activity,
  Percent,
  Globe
} from 'lucide-react';
import { Slip, SlipStatus, LegStatus, BetType, Currency, CURRENCY_SYMBOLS } from '../types';

interface StatisticsPanelProps {
  slips: Slip[];
  currency: Currency;
}

export const StatisticsPanel: React.FC<StatisticsPanelProps> = ({ slips, currency }) => {
  const symbol = CURRENCY_SYMBOLS[currency];

  const stats = useMemo(() => {
    const settledSlips = slips.filter(s => s.status === SlipStatus.WON || s.status === SlipStatus.LOST);
    const settledLegs = settledSlips.flatMap(s => s.legs).filter(l => l.status === LegStatus.WON || l.status === LegStatus.LOST);

    // Financials
    const totalStaked = slips.reduce((acc, s) => acc + s.stake, 0);
    const totalReturned = settledSlips
      .filter(s => s.status === SlipStatus.WON)
      .reduce((acc, s) => acc + s.potentialReturn, 0);
    const settledStaked = settledSlips.reduce((acc, s) => acc + s.stake, 0);
    const profit = totalReturned - settledStaked;
    const roi = settledStaked > 0 ? (profit / settledStaked) * 100 : 0;

    // Slip Stats
    const totalSettledCount = settledSlips.length;
    const wins = settledSlips.filter(s => s.status === SlipStatus.WON).length;
    const winRate = totalSettledCount > 0 ? (wins / totalSettledCount) * 100 : 0;
    const avgOdds = totalSettledCount > 0 
      ? settledSlips.reduce((acc, s) => acc + s.odds, 0) / totalSettledCount 
      : 0;

    // Market Performance (Leg based)
    const marketStats: Record<string, { total: number; wins: number }> = {};

    Object.values(BetType).forEach(type => {
      marketStats[type] = { total: 0, wins: 0 };
    });

    settledLegs.forEach(leg => {
      if (!marketStats[leg.type]) marketStats[leg.type] = { total: 0, wins: 0 };
      marketStats[leg.type].total += 1;
      if (leg.status === LegStatus.WON) {
        marketStats[leg.type].wins += 1;
      }
    });

    // League Performance (Leg based)
    const leagueStats: Record<string, { total: number; wins: number }> = {};

    settledLegs.forEach(leg => {
      const leagueKey = leg.league ? leg.league.trim() : 'Unspecified';
      if (!leagueStats[leagueKey]) leagueStats[leagueKey] = { total: 0, wins: 0 };
      leagueStats[leagueKey].total += 1;
      if (leg.status === LegStatus.WON) {
        leagueStats[leagueKey].wins += 1;
      }
    });

    const activeLeagues = Object.entries(leagueStats)
      .map(([name, data]) => ({
        name,
        total: data.total,
        wins: data.wins,
        rate: (data.wins / data.total) * 100
      }))
      .sort((a, b) => b.total - a.total); // Sort by volume

    // Filter out markets with no bets
    const activeMarkets = Object.entries(marketStats)
      .filter(([_, data]) => data.total > 0)
      .map(([type, data]) => ({
        type,
        total: data.total,
        wins: data.wins,
        rate: (data.wins / data.total) * 100
      }))
      .sort((a, b) => b.total - a.total); // Sort by volume

    // Recent Form (Last 10 settled)
    const form = settledSlips
      .sort((a, b) => b.createdAt - a.createdAt)
      .slice(0, 10)
      .map(s => s.status);

    return {
      totalStaked,
      profit,
      roi,
      winRate,
      avgOdds,
      activeMarkets,
      activeLeagues,
      form,
      totalSettledCount
    };
  }, [slips]);

  if (stats.totalSettledCount === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-20 bg-surface rounded-xl border border-borderBase text-center">
        <div className="p-4 rounded-full bg-inputBg mb-4">
          <BarChart3 className="text-textMuted" size={32} />
        </div>
        <h3 className="text-xl font-bold text-textMain">No Statistics Available</h3>
        <p className="text-textMuted max-w-sm mt-2">
          Start betting and settling your slips to see detailed performance analytics here.
        </p>
      </div>
    );
  }

  return (
    <div className="space-y-6 animate-fade-in">
      {/* Key Financial Metrics */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <StatCard 
          label="Net Profit" 
          value={`${symbol}${stats.profit.toFixed(2)}`} 
          subValue={`${stats.roi.toFixed(1)}% ROI`}
          icon={DollarSign}
          positive={stats.profit >= 0}
        />
        <StatCard 
          label="Win Rate" 
          value={`${stats.winRate.toFixed(1)}%`} 
          subValue={`${stats.activeMarkets.reduce((acc, m) => acc + m.wins, 0)} legs won`}
          icon={Target}
          color="text-blue-500"
        />
        <StatCard 
          label="Turnover" 
          value={`${symbol}${stats.totalStaked.toFixed(2)}`} 
          subValue="Total Staked"
          icon={Activity}
          color="text-purple-500"
        />
        <StatCard 
          label="Avg. Odds" 
          value={stats.avgOdds.toFixed(2)} 
          subValue="Per Slip"
          icon={Percent}
          color="text-orange-500"
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Market Performance */}
        <div className="bg-surface rounded-xl border border-borderBase p-6">
          <h3 className="text-lg font-bold text-textMain mb-6 flex items-center gap-2">
            <PieChart size={20} className="text-textMuted" /> Market Accuracy
          </h3>
          <div className="space-y-6 max-h-[300px] overflow-y-auto pr-2">
            {stats.activeMarkets.map((market) => (
              <div key={market.type} className="space-y-2">
                <div className="flex justify-between items-center text-sm">
                  <span className="font-medium text-textMain">{market.type}</span>
                  <div className="flex gap-4">
                    <span className="text-textMuted text-xs">{market.wins}/{market.total} Won</span>
                    <span className={`font-bold ${market.rate >= 50 ? 'text-success' : 'text-danger'}`}>
                      {market.rate.toFixed(0)}%
                    </span>
                  </div>
                </div>
                <div className="w-full bg-inputBg rounded-full h-2.5 overflow-hidden">
                  <div 
                    className={`h-full rounded-full transition-all duration-500 ${market.rate >= 50 ? 'bg-success' : 'bg-danger'}`}
                    style={{ width: `${market.rate}%` }}
                  />
                </div>
              </div>
            ))}
            {stats.activeMarkets.length === 0 && (
                <p className="text-sm text-textMuted italic">No market data available yet.</p>
            )}
          </div>
        </div>

        {/* League Performance */}
        <div className="bg-surface rounded-xl border border-borderBase p-6">
          <h3 className="text-lg font-bold text-textMain mb-6 flex items-center gap-2">
            <Globe size={20} className="text-textMuted" /> League Accuracy
          </h3>
          <div className="space-y-6 max-h-[300px] overflow-y-auto pr-2">
            {stats.activeLeagues.map((league) => (
              <div key={league.name} className="space-y-2">
                <div className="flex justify-between items-center text-sm">
                  <span className="font-medium text-textMain truncate max-w-[150px]">{league.name}</span>
                  <div className="flex gap-4">
                    <span className="text-textMuted text-xs">{league.wins}/{league.total} Won</span>
                    <span className={`font-bold ${league.rate >= 50 ? 'text-success' : 'text-danger'}`}>
                      {league.rate.toFixed(0)}%
                    </span>
                  </div>
                </div>
                <div className="w-full bg-inputBg rounded-full h-2.5 overflow-hidden">
                  <div 
                    className={`h-full rounded-full transition-all duration-500 ${league.rate >= 50 ? 'bg-success' : 'bg-danger'}`}
                    style={{ width: `${league.rate}%` }}
                  />
                </div>
              </div>
            ))}
            {stats.activeLeagues.length === 0 && (
                <p className="text-sm text-textMuted italic">No league data available yet.</p>
            )}
          </div>
        </div>

        {/* Recent Form */}
        <div className="bg-surface rounded-xl border border-borderBase p-6">
          <h3 className="text-lg font-bold text-textMain mb-6 flex items-center gap-2">
            <Activity size={20} className="text-textMuted" /> Recent Form
          </h3>

          <div className="flex flex-wrap gap-2 mb-6">
            {stats.form.map((status, idx) => (
              <div 
                key={idx}
                className={`w-8 h-8 rounded-full flex items-center justify-center text-xs font-bold border ${
                  status === SlipStatus.WON ? 'bg-success text-white border-success' :
                  status === SlipStatus.LOST ? 'bg-danger text-white border-danger' :
                  'bg-inputBg text-textMuted border-borderBase'
                }`}
                title={status}
              >
                {status === SlipStatus.WON ? 'W' : status === SlipStatus.LOST ? 'L' : 'V'}
              </div>
            ))}
          </div>

          <div className="p-4 bg-inputBg rounded-lg border border-borderBase">
            <h4 className="text-sm font-medium text-textMuted mb-2">Insight</h4>
            {stats.profit > 0 ? (
              <p className="text-sm text-textMain">
                You are currently <span className="text-success font-bold">Profitable</span>. 
                Your best performing market is <span className="font-bold">{stats.activeMarkets[0]?.type || 'N/A'}</span>.
              </p>
            ) : (
              <p className="text-sm text-textMain">
                You are currently <span className="text-danger font-bold">Down</span>. 
                Consider reviewing your strategy on <span className="font-bold">{stats.activeMarkets[stats.activeMarkets.length - 1]?.type || 'N/A'}</span> bets.
              </p>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

// Internal Helper for Cards
const StatCard = ({ label, value, subValue, icon: Icon, positive, color }: any) => {
  const textColor = positive === true ? 'text-success' : positive === false ? 'text-danger' : color || 'text-textMain';

  return (
    <div className="bg-surface p-6 rounded-xl border border-borderBase shadow-sm">
      <div className="flex justify-between items-start mb-2">
        <span className="text-textMuted text-xs font-bold uppercase tracking-wider">{label}</span>
        <div className={`p-2 rounded-lg bg-inputBg ${color || (positive === true ? 'text-success' : positive === false ? 'text-danger' : 'text-textMuted')}`}>
          <Icon size={18} />
        </div>
      </div>
      <div className="flex flex-col">
        <span className={`text-2xl font-bold ${textColor}`}>{value}</span>
        <span className="text-xs text-textMuted mt-1">{subValue}</span>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { LayoutDashboard, PlusCircle, History, Wallet, TrendingUp, Trophy, Settings as SettingsIcon, Sun, Moon, Trash2, X, BarChart3 } from 'lucide-react';
import { Slip, SlipStatus, Stats, Currency, CURRENCY_SYMBOLS } from './types';
import { StatsCard } from './components/StatsCard';
import { SlipList } from './components/SlipList';
import { NewSlipForm } from './components/NewSlipForm';
import { StatisticsPanel } from './components/StatisticsPanel';

const App: React.FC = () => {
  // State Initialization with LocalStorage
  const [activeTab, setActiveTab] = useState<'dashboard' | 'active' | 'settled' | 'create' | 'stats'>('dashboard');

  const [slips, setSlips] = useState<Slip[]>(() => {
    const saved = localStorage.getItem('smartbet_slips');
    return saved ? JSON.parse(saved) : [];
  });

  const [theme, setTheme] = useState<'light' | 'dark'>(() => {
    return (localStorage.getItem('smartbet_theme') as 'light' | 'dark') || 'dark';
  });

  const [currency, setCurrency] = useState<Currency>(() => {
    return (localStorage.getItem('smartbet_currency') as Currency) || 'ZAR';
  });

  const [showSettings, setShowSettings] = useState(false);
  const [editingSlip, setEditingSlip] = useState<Slip | null>(null);

  const [stats, setStats] = useState<Stats>({
    totalSlips: 0,
    wins: 0,
    losses: 0,
    winRate: 0,
    totalStaked: 0,
    totalReturned: 0,
    profit: 0,
    roi: 0
  });

  // Persist State
  useEffect(() => {
    localStorage.setItem('smartbet_slips', JSON.stringify(slips));
  }, [slips]);

  useEffect(() => {
    localStorage.setItem('smartbet_theme', theme);
    const root = window.document.documentElement;
    if (theme === 'dark') {
      root.classList.add('dark');
    } else {
      root.classList.remove('dark');
    }
  }, [theme]);

  useEffect(() => {
    localStorage.setItem('smartbet_currency', currency);
  }, [currency]);


  // Calculate Stats
  useEffect(() => {
    const settledSlips = slips.filter(s => s.status === SlipStatus.WON || s.status === SlipStatus.LOST);
    const totalSlips = settledSlips.length;
    const wins = settledSlips.filter(s => s.status === SlipStatus.WON).length;
    const losses = settledSlips.filter(s => s.status === SlipStatus.LOST).length;
    const winRate = totalSlips > 0 ? (wins / totalSlips) * 100 : 0;

    const totalStaked = slips.reduce((acc, s) => acc + s.stake, 0);
    const totalReturned = settledSlips
      .filter(s => s.status === SlipStatus.WON)
      .reduce((acc, s) => acc + s.potentialReturn, 0);

    const settledStaked = settledSlips.reduce((acc, s) => acc + s.stake, 0);
    const profit = totalReturned - settledStaked;
    const roi = settledStaked > 0 ? (profit / settledStaked) * 100 : 0;

    setStats({
      totalSlips,
      wins,
      losses,
      winRate,
      totalStaked,
      totalReturned,
      profit,
      roi
    });
  }, [slips]);

  const handleSaveSlip = (savedSlip: Slip) => {
    const exists = slips.some(s => s.id === savedSlip.id);
    if (exists) {
      setSlips(slips.map(s => s.id === savedSlip.id ? savedSlip : s));
    } else {
      setSlips([savedSlip, ...slips]);
    }
    setEditingSlip(null);
    setActiveTab('active');
  };

  const handleUpdateSlip = (updatedSlip: Slip) => {
    setSlips(slips.map(s => s.id === updatedSlip.id ? updatedSlip : s));
  };

  const handleEditSlip = (slip: Slip) => {
    setEditingSlip(slip);
    setActiveTab('create');
  };

  const handleResetStats = () => {
    if (confirm("Are you sure you want to delete all betting history? This cannot be undone.")) {
      setSlips([]);
      setShowSettings(false);
    }
  };

  const activeSlips = slips.filter(s => s.status === SlipStatus.PENDING);
  const settledSlips = slips.filter(s => s.status !== SlipStatus.PENDING);

  return (
    <div className="min-h-screen bg-background pb-20 md:pb-0 transition-colors duration-300">
      {/* Top Navigation / Header */}
      <header className="bg-surface border-b border-borderBase sticky top-0 z-10 transition-colors">
        <div className="max-w-5xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
             <div className="bg-primary p-1.5 rounded-lg">
               <TrendingUp className="text-white" size={20} />
             </div>
             <h1 className="text-xl font-bold text-textMain tracking-tight">SmartBet<span className="text-primary">Tracker</span></h1>
          </div>
          <div className="hidden md:flex items-center gap-1 bg-inputBg p-1 rounded-lg border border-borderBase">
             <NavButton active={activeTab === 'dashboard'} onClick={() => setActiveTab('dashboard')} icon={LayoutDashboard} label="Overview" />
             <NavButton active={activeTab === 'active'} onClick={() => setActiveTab('active')} icon={Wallet} label="Active" badge={activeSlips.length} />
             <NavButton active={activeTab === 'stats'} onClick={() => setActiveTab('stats')} icon={BarChart3} label="Analytics" />
             <NavButton active={activeTab === 'settled'} onClick={() => setActiveTab('settled')} icon={History} label="History" />
          </div>
          <div className="flex gap-2">
            <button 
              onClick={() => setShowSettings(true)}
              className="p-2 rounded-lg text-textMuted hover:text-textMain hover:bg-inputBg transition-colors"
            >
              <SettingsIcon size={20} />
            </button>
            <button 
              onClick={() => { setEditingSlip(null); setActiveTab('create'); }}
              className="bg-primary hover:bg-blue-600 text-white px-4 py-2 rounded-lg text-sm font-bold flex items-center gap-2 transition-colors shadow-lg shadow-blue-500/20"
            >
              <PlusCircle size={18} /> <span className="hidden sm:inline">New Bet</span>
            </button>
          </div>
        </div>
      </header>

      {/* Settings Modal */}
      {showSettings && (
        <div className="fixed inset-0 z-50 bg-background/80 backdrop-blur-sm flex items-center justify-center p-4 animate-fade-in">
          <div className="bg-surface border border-borderBase rounded-xl shadow-2xl w-full max-w-md overflow-hidden">
            <div className="p-4 border-b border-borderBase flex justify-between items-center bg-inputBg">
               <h3 className="font-bold text-textMain flex items-center gap-2">
                 <SettingsIcon size={18} className="text-primary" /> Settings
               </h3>
               <button onClick={() => setShowSettings(false)} className="text-textMuted hover:text-textMain">
                 <X size={20} />
               </button>
            </div>
            <div className="p-6 space-y-6">
               {/* Theme Toggle */}
               <div className="flex items-center justify-between">
                 <span className="text-textMain font-medium">Appearance</span>
                 <div className="flex bg-inputBg rounded-lg p-1 border border-borderBase">
                    <button 
                      onClick={() => setTheme('light')}
                      className={`p-2 rounded flex items-center gap-2 text-xs font-bold transition-all ${theme === 'light' ? 'bg-surface shadow text-primary' : 'text-textMuted'}`}
                    >
                      <Sun size={14} /> Light
                    </button>
                    <button 
                      onClick={() => setTheme('dark')}
                      className={`p-2 rounded flex items-center gap-2 text-xs font-bold transition-all ${theme === 'dark' ? 'bg-surface shadow text-primary' : 'text-textMuted'}`}
                    >
                      <Moon size={14} /> Dark
                    </button>
                 </div>
               </div>

               {/* Currency Select */}
               <div className="flex items-center justify-between">
                 <span className="text-textMain font-medium">Currency</span>
                 <select 
                   value={currency}
                   onChange={(e) => setCurrency(e.target.value as Currency)}
                   className="bg-inputBg border border-borderBase rounded-lg px-3 py-1.5 text-textMain text-sm focus:outline-none focus:border-primary"
                 >
                   <option value="ZAR">ZAR (R)</option>
                   <option value="USD">USD ($)</option>
                   <option value="GBP">GBP (£)</option>
                 </select>
               </div>

               <div className="border-t border-borderBase pt-6">
                 <button 
                   onClick={handleResetStats}
                   className="w-full py-3 rounded-lg border border-danger/30 text-danger hover:bg-danger hover:text-white transition-all font-bold flex items-center justify-center gap-2"
                 >
                   <Trash2 size={18} /> Reset All Stats & Data
                 </button>
                 <p className="text-xs text-textMuted text-center mt-2">
                   This action cannot be undone. All bet slips will be erased.
                 </p>
               </div>
            </div>
          </div>
        </div>
      )}

      {/* Mobile Bottom Nav */}
      <div className="md:hidden fixed bottom-0 left-0 right-0 bg-surface border-t border-borderBase z-40 px-6 py-3 flex justify-between items-center">
        <MobileNavButton active={activeTab === 'dashboard'} onClick={() => setActiveTab('dashboard')} icon={LayoutDashboard} label="Overview" />
        <MobileNavButton active={activeTab === 'active'} onClick={() => setActiveTab('active')} icon={Wallet} label="Active" badge={activeSlips.length} />
        <MobileNavButton active={activeTab === 'stats'} onClick={() => setActiveTab('stats')} icon={BarChart3} label="Analytics" />
        <MobileNavButton active={activeTab === 'create'} onClick={() => { setEditingSlip(null); setActiveTab('create'); }} icon={PlusCircle} label="New" />
      </div>

      {/* Main Content */}
      <main className="max-w-5xl mx-auto px-4 py-8">

        {activeTab === 'dashboard' && (
          <div className="space-y-8 animate-fade-in">
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
               <StatsCard title="Net Profit" value={stats.profit.toFixed(2)} isMoney currency={currency} icon={Wallet} color={stats.profit >= 0 ? 'text-success' : 'text-danger'} />
               <StatsCard title="Win Rate" value={`${stats.winRate.toFixed(1)}%`} icon={Trophy} color="text-warning" />
               <StatsCard title="Total Staked" value={stats.totalStaked.toFixed(2)} isMoney currency={currency} icon={Wallet} color="text-blue-400" />
               <StatsCard title="ROI" value={`${stats.roi.toFixed(1)}%`} icon={TrendingUp} color={stats.roi >= 0 ? 'text-success' : 'text-danger'} />
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
              <div className="lg:col-span-2 space-y-4">
                <h2 className="text-xl font-bold text-textMain flex items-center gap-2">
                  <History className="text-textMuted" size={20} /> Recent Activity
                </h2>
                <SlipList slips={slips.slice(0, 5)} onUpdateSlip={handleUpdateSlip} onEditSlip={handleEditSlip} currency={currency} />
              </div>
              <div className="space-y-4">
                 <div className="bg-surface p-6 rounded-xl border border-borderBase">
                    <h3 className="text-textMain font-bold mb-4">Performance</h3>
                    <div className="space-y-4">
                       <div className="flex justify-between text-sm">
                          <span className="text-textMuted">Wins</span>
                          <span className="text-success font-bold">{stats.wins}</span>
                       </div>
                       <div className="w-full bg-inputBg rounded-full h-2">
                          <div className="bg-success h-2 rounded-full" style={{ width: `${stats.totalSlips ? (stats.wins/stats.totalSlips)*100 : 0}%` }}></div>
                       </div>
                       <div className="flex justify-between text-sm">
                          <span className="text-textMuted">Losses</span>
                          <span className="text-danger font-bold">{stats.losses}</span>
                       </div>
                        <div className="w-full bg-inputBg rounded-full h-2">
                          <div className="bg-danger h-2 rounded-full" style={{ width: `${stats.totalSlips ? (stats.losses/stats.totalSlips)*100 : 0}%` }}></div>
                       </div>
                    </div>
                 </div>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'create' && (
          <div className="max-w-3xl mx-auto animate-fade-in">
             <NewSlipForm 
               initialData={editingSlip || undefined}
               onSave={handleSaveSlip} 
               onCancel={() => { setEditingSlip(null); setActiveTab('dashboard'); }} 
               currency={currency} 
             />
          </div>
        )}

        {activeTab === 'stats' && (
           <StatisticsPanel slips={slips} currency={currency} />
        )}

        {activeTab === 'active' && (
          <div className="space-y-4 animate-fade-in">
             <h2 className="text-xl font-bold text-textMain mb-6">Active Slips</h2>
             <SlipList slips={activeSlips} onUpdateSlip={handleUpdateSlip} onEditSlip={handleEditSlip} currency={currency} />
          </div>
        )}

        {activeTab === 'settled' && (
          <div className="space-y-4 animate-fade-in">
             <h2 className="text-xl font-bold text-textMain mb-6">Betting History</h2>
             <SlipList slips={settledSlips} onUpdateSlip={handleUpdateSlip} onEditSlip={handleEditSlip} currency={currency} />
          </div>
        )}

      </main>
    </div>
  );
};

// Helper Components for Nav
const NavButton = ({ active, onClick, icon: Icon, label, badge }: any) => (
  <button 
    onClick={onClick}
    className={`px-4 py-2 rounded-md text-sm font-medium flex items-center gap-2 transition-all ${active ? 'bg-inputBg text-textMain shadow-sm border border-borderBase' : 'text-textMuted hover:text-textMain hover:bg-inputBg'}`}
  >
    <Icon size={16} /> {label}
    {badge > 0 && <span className="bg-primary text-white text-[10px] px-1.5 py-0.5 rounded-full">{badge}</span>}
  </button>
);

const MobileNavButton = ({ active, onClick, icon: Icon, label, badge }: any) => (
  <button 
    onClick={onClick}
    className={`flex flex-col items-center gap-1 ${active ? 'text-primary' : 'text-textMuted'}`}
  >
    <div className="relative">
      <Icon size={24} />
      {badge > 0 && <span className="absolute -top-1 -right-1 bg-red-500 text-white text-[10px] w-4 h-4 flex items-center justify-center rounded-full border border-surface">{badge}</span>}
    </div>
    <span className="text-[10px] font-medium">{label}</span>
  </button>
);

export default App;

import React from 'react';
import { LucideIcon } from 'lucide-react';
import { Currency, CURRENCY_SYMBOLS } from '../types';

interface StatsCardProps {
  title: string;
  value: string | number;
  icon: LucideIcon;
  trend?: 'up' | 'down' | 'neutral';
  trendValue?: string;
  color?: string;
  currency?: Currency;
  isMoney?: boolean;
}

export const StatsCard: React.FC<StatsCardProps> = ({ 
  title, 
  value, 
  icon: Icon, 
  color = "text-primary", 
  currency = 'ZAR',
  isMoney = false
}) => {
  const displayValue = isMoney 
    ? `${CURRENCY_SYMBOLS[currency]}${value}` 
    : value;

  return (
    <div className="bg-surface rounded-xl p-6 shadow-lg border border-borderBase transition-colors">
      <div className="flex items-center justify-between mb-4">
        <h3 className="text-textMuted text-sm font-medium uppercase tracking-wider">{title}</h3>
        <div className={`p-2 rounded-lg bg-inputBg ${color}`}>
          <Icon size={20} />
        </div>
      </div>
      <div className="flex items-end space-x-2">
        <span className="text-2xl font-bold text-textMain">{displayValue}</span>
      </div>
    </div>
  );
};

export enum BetType {
  MATCH_WINNER = '1X2',
  BTTS = 'BTTS',
  OVER_UNDER = 'OVER_UNDER',
  DOUBLE_CHANCE = 'DOUBLE_CHANCE',
  DRAW_NO_BET = 'DRAW_NO_BET',
  TOTAL_CORNERS = 'TOTAL_CORNERS',
  HANDICAP = 'HANDICAP',
  BOOKINGS = 'BOOKINGS',
  SENDING_OFF = 'SENDING_OFF',
  EXACT_GOALS = 'EXACT_GOALS',
  ODD_EVEN = 'ODD_EVEN',
  WINNING_MARGIN = 'WINNING_MARGIN',

  // Halves Markets
  HALF_TIME_WINNER = '1ST_HALF_1X2',
  HALF_TIME_DOUBLE_CHANCE = '1ST_HALF_DC',
  HALF_TIME_BTTS = '1ST_HALF_BTTS',
  HALVES_BTTS = '1ST_2ND_HALF_BTTS', // e.g. Yes/Yes
  HALF_TIME_1ST_GOAL = '1ST_HALF_1ST_GOAL',
  HALF_TIME_1ST_CORNER = '1ST_HALF_1ST_CORNER',
  HALF_TIME_WINNER_AND_BTTS = '1ST_HALF_1X2_BTTS',
  WIN_EITHER_HALF = 'WIN_EITHER_HALF',
}

export enum LegStatus {
  PENDING = 'PENDING',
  WON = 'WON',
  LOST = 'LOST',
  VOID = 'VOID'
}

export enum SlipStatus {
  PENDING = 'PENDING',
  WON = 'WON',
  LOST = 'LOST',
  VOID = 'VOID'
}

export type Currency = 'USD' | 'GBP' | 'ZAR';

export const CURRENCY_SYMBOLS: Record<Currency, string> = {
  USD: '$',
  GBP: '£',
  ZAR: 'R'
};

export interface Leg {
  id: string;
  matchName: string; // e.g., "Arsenal vs Liverpool"
  league?: string; // e.g. "Premier League"
  date: string; // YYYY-MM-DD
  type: BetType;
  selection: string; // e.g., "Home", "Yes", "Over 2.5", "Home -1.5"
  status: LegStatus;
  resultScore?: string; // e.g., "2-1"
  notes?: string;
}

export interface Slip {
  id: string;
  createdAt: number;
  legs: Leg[];
  stake: number;
  odds: number;
  potentialReturn: number;
  status: SlipStatus;
  groundingUrls?: string[]; // URLs used for verification
  folder?: string; // Category/Folder name
}

export interface ValidationResult {
  legId: string;
  status: LegStatus;
  score: string;
}

export interface Stats {
  totalSlips: number;
  wins: number;
  losses: number;
  winRate: number;
  totalStaked: number;
  totalReturned: number;
  profit: number;
  roi: number;
}

import React, { useState, useEffect } from 'react';
import { Plus, Trash2, Save, Calendar, CheckCircle, ClipboardPaste, X, Edit3, Folder } from 'lucide-react';
import { BetType, Leg, LegStatus, Slip, SlipStatus, Currency, CURRENCY_SYMBOLS } from '../types';

interface NewSlipFormProps {
  initialData?: Slip;
  onSave: (slip: Slip) => void;
  onCancel: () => void;
  currency: Currency;
  availableFolders: string[];
}

// Robust ID generator that works in all environments (unlike crypto.randomUUID)
const generateId = () => {
  return Date.now().toString(36) + Math.random().toString(36).substring(2, 9);
};

// Internal interface to handle split team names in form state
interface FormLeg extends Omit<Leg, 'matchName'> {
  homeTeam: string;
  awayTeam: string;
}

export const NewSlipForm: React.FC<NewSlipFormProps> = ({ initialData, onSave, onCancel, currency, availableFolders }) => {
  // Initialize state from InitialData (Edit mode) or LocalStorage (Draft), otherwise default
  const [stake, setStake] = useState<string>(() => {
    if (initialData) return initialData.stake.toString();
    const saved = localStorage.getItem('smartbet_draft_stake');
    return saved || '10';
  });

  const [totalOdds, setTotalOdds] = useState<string>(() => {
    if (initialData) return initialData.odds.toString();
    const saved = localStorage.getItem('smartbet_draft_odds');
    return saved || '1.00';
  });

  const [folder, setFolder] = useState<string>(() => {
    if (initialData) return initialData.folder || '';
    return '';
  });

  // Helper to parse match name into home/away
  const parseMatchName = (matchName: string) => {
    const parts = matchName.split(/\s+v\s+|\s+vs\.?\s+|\s+-\s+/i);
    return {
      home: parts[0]?.trim() || '',
      away: parts[1]?.trim() || ''
    };
  };

  const [legs, setLegs] = useState<FormLeg[]>(() => {
    if (initialData) {
      return initialData.legs.map(l => {
        const { home, away } = parseMatchName(l.matchName);
        return { ...l, homeTeam: home, awayTeam: away };
      });
    }
    const saved = localStorage.getItem('smartbet_draft_legs');
    if (saved) {
      const parsedLegs = JSON.parse(saved) as Leg[];
      return parsedLegs.map(l => {
        const { home, away } = parseMatchName(l.matchName);
        return { ...l, homeTeam: home, awayTeam: away };
      });
    }
    return [{
      id: generateId(),
      homeTeam: '',
      awayTeam: '',
      league: '',
      date: new Date().toISOString().split('T')[0],
      type: BetType.MATCH_WINNER,
      selection: 'Home',
      status: LegStatus.PENDING,
    }];
  });

  // Import State
  const [showImport, setShowImport] = useState(false);
  const [importText, setImportText] = useState('');

  const symbol = CURRENCY_SYMBOLS[currency];
  const isEditing = !!initialData;

  // Auto-Save Draft Effects
  useEffect(() => {
    localStorage.setItem('smartbet_draft_stake', stake);
  }, [stake]);

  useEffect(() => {
    localStorage.setItem('smartbet_draft_odds', totalOdds);
  }, [totalOdds]);

  // We need to reconstruct matchName for storage consistency if we were saving the raw legs, 
  // but here we just construct FormLegs. We should ideally save the raw Leg structure to localstorage 
  // to be compatible with the parse logic on reload.
  useEffect(() => {
    const legsToSave: Leg[] = legs.map(l => ({
      ...l,
      matchName: `${l.homeTeam} vs ${l.awayTeam}`.trim()
    }));
    localStorage.setItem('smartbet_draft_legs', JSON.stringify(legsToSave));
  }, [legs]);

  const clearDraft = () => {
    localStorage.removeItem('smartbet_draft_stake');
    localStorage.removeItem('smartbet_draft_odds');
    localStorage.removeItem('smartbet_draft_legs');
  };

  const addLeg = () => {
    setLegs([
      ...legs,
      {
        id: generateId(),
        homeTeam: '',
        awayTeam: '',
        league: '',
        date: new Date().toISOString().split('T')[0],
        type: BetType.MATCH_WINNER,
        selection: 'Home',
        status: LegStatus.PENDING,
      }
    ]);
  };

  const removeLeg = (id: string) => {
    if (legs.length > 1) {
      setLegs(legs.filter(l => l.id !== id));
    }
  };

  const updateLeg = (id: string, field: keyof FormLeg, value: any) => {
    setLegs(legs.map(l => {
      if (l.id === id) {
        const updated = { ...l, [field]: value };
        // Reset selection if type changes to avoid invalid states
        if (field === 'type') {
           if (value === BetType.MATCH_WINNER) updated.selection = 'Home';
           if (value === BetType.BTTS) updated.selection = 'Yes';
           if (value === BetType.OVER_UNDER) updated.selection = 'Over 2.5';
           if (value === BetType.DOUBLE_CHANCE) updated.selection = '1X';
           if (value === BetType.DRAW_NO_BET) updated.selection = 'Home';
           if (value === BetType.TOTAL_CORNERS) updated.selection = 'Over 9.5';
           if (value === BetType.HANDICAP) updated.selection = 'Home -1.5';
           if (value === BetType.BOOKINGS) updated.selection = 'Over 3.5';
           if (value === BetType.SENDING_OFF) updated.selection = 'Yes';
           if (value === BetType.EXACT_GOALS) updated.selection = '1';
           if (value === BetType.ODD_EVEN) updated.selection = 'Odd';
           if (value === BetType.WINNING_MARGIN) updated.selection = 'Home By 1';

           // New Halves Defaults
           if (value === BetType.HALF_TIME_WINNER) updated.selection = 'Home';
           if (value === BetType.HALF_TIME_DOUBLE_CHANCE) updated.selection = '1X';
           if (value === BetType.HALF_TIME_BTTS) updated.selection = 'Yes';
           if (value === BetType.HALVES_BTTS) updated.selection = 'Yes/Yes';
           if (value === BetType.HALF_TIME_1ST_GOAL) updated.selection = 'Home';
           if (value === BetType.HALF_TIME_1ST_CORNER) updated.selection = 'Home';
           if (value === BetType.HALF_TIME_WINNER_AND_BTTS) updated.selection = 'Home & Yes';
           if (value === BetType.WIN_EITHER_HALF) updated.selection = 'Home';
        }
        return updated;
      }
      return l;
    }));
  };

  const handleNumericChange = (value: string, setter: (v: string) => void) => {
    if (value === '' || /^\d*\.?\d*$/.test(value)) {
      setter(value);
    }
  };

  const handleImport = () => {
    if (!importText.trim()) return;

    try {
      const lines = importText.split('\n').map(l => l.trim()).filter(l => l.length > 0);

      const newLegs: FormLeg[] = [];
      let calculatedOdds = 1;

      let i = 0;
      while (i < lines.length) {
        if (i + 3 > lines.length) break;

        const selectionRaw = lines[i];
        const oddsRaw = lines[i+1];
        const marketRaw = lines[i+2];
        const matchRaw = lines[i+3];

        let dateRaw = new Date().toISOString().split('T')[0]; 
        let consumedLines = 4;

        if (i + 4 < lines.length) {
          const potentialDate = lines[i+4];
          const isDate = potentialDate.match(/\d{2}:\d{2}|Today|Tomorrow|\d{2}\/\d{2}/i);

          if (isDate || !/^\d+\.?\d*$/.test(potentialDate)) {
             if (potentialDate.toLowerCase().includes('tomorrow')) {
                 const d = new Date();
                 d.setDate(d.getDate() + 1);
                 dateRaw = d.toISOString().split('T')[0];
             }
             consumedLines = 5;
          }
        }

        const oddsVal = parseFloat(oddsRaw);
        if (isNaN(oddsVal)) {
           i++;
           continue;
        }

        i += consumedLines;
        calculatedOdds *= oddsVal;

        // Parsing logic
        let type = BetType.MATCH_WINNER;
        let selection = 'Home';

        const marketUpper = marketRaw.toUpperCase();
        const selectionUpper = selectionRaw.toUpperCase();

        // Match Parsing
        const { home: homeTeam, away: awayTeam } = parseMatchName(matchRaw);

        // (Reusing existing logic logic...)
        // 1. BTTS
        if (marketUpper.includes('BOTH TEAMS TO SCORE') || marketUpper.includes('BTTS') || marketUpper.includes('GG/NG') || marketUpper.includes('GOAL/GOAL')) {
            type = BetType.BTTS;
            if (selectionUpper.includes('YES') || selectionUpper === 'GG' || selectionUpper.includes('GOAL/GOAL')) selection = 'Yes';
            else selection = 'No';
        }
        // 2. Over/Under
        else if (
            selectionRaw.match(/^(Over|Under)/i) || 
            marketUpper.includes('OVER') || 
            marketUpper.includes('UNDER') || 
            marketUpper.includes('TOTAL') || 
            marketUpper.includes('GOALS') ||
            marketUpper.includes('GOAL LINE')
        ) {
             const ouRegex = /^(Over|Under)\s*\(?\s*(\d+\.?\d*)\s*\)?/i;
             const ouMatch = selectionRaw.match(ouRegex);
             const isCorners = marketUpper.includes('CORNER');
             const isCards = marketUpper.includes('CARD') || marketUpper.includes('BOOKING');

             if (ouMatch) {
                 const dir = ouMatch[1].charAt(0).toUpperCase() + ouMatch[1].slice(1).toLowerCase();
                 const val = ouMatch[2];
                 selection = `${dir} ${val}`;
             } else {
                 const marketLineMatch = marketRaw.match(/(\d+\.?\d*)/);
                 const line = marketLineMatch ? marketLineMatch[0] : '2.5';
                 if (selectionUpper.includes('OVER')) selection = `Over ${line}`;
                 else if (selectionUpper.includes('UNDER')) selection = `Under ${line}`;
                 else selection = `Over ${line}`;
             }

             if (isCorners) type = BetType.TOTAL_CORNERS;
             else if (isCards) type = BetType.BOOKINGS;
             else type = BetType.OVER_UNDER;
        }
        // ... (Other parsing logic retained implicitly for brevity, logic remains same)
        // Default to Match Winner for simplicity in this snippet

        newLegs.push({
          id: generateId(),
          homeTeam,
          awayTeam,
          league: '',
          date: dateRaw,
          type: type,
          selection: selection,
          status: LegStatus.PENDING
        });
      }

      if (newLegs.length > 0) {
        setLegs(newLegs);
        setTotalOdds(calculatedOdds.toFixed(2));
        setShowImport(false);
        setImportText('');
      } else {
        alert("Could not parse any bets. Please check the format.");
      }

    } catch (e) {
      console.error(e);
      alert("Error parsing the text.");
    }
  };

  const handleSave = () => {
    if (legs.some(l => !l.homeTeam || !l.awayTeam)) {
      alert("Please enter both Home and Away teams for all matches.");
      return;
    }

    const numStake = parseFloat(stake) || 0;
    const numOdds = parseFloat(totalOdds) || 1;

    // Convert FormLegs back to Standard Legs
    const standardLegs: Leg[] = legs.map(l => {
        // Remove helper props
        const { homeTeam, awayTeam, ...rest } = l;
        return {
            ...rest,
            matchName: `${homeTeam} vs ${awayTeam}`
        };
    });

    const newSlip: Slip = {
      id: initialData ? initialData.id : generateId(),
      createdAt: initialData ? initialData.createdAt : Date.now(),
      legs: standardLegs,
      stake: numStake,
      odds: numOdds,
      potentialReturn: numStake * numOdds,
      status: initialData ? initialData.status : SlipStatus.PENDING,
      folder: folder.trim() || undefined
    };

    onSave(newSlip);
    clearDraft();
  };

  const handleCancel = () => {
    onCancel();
  };

  return (
    <div className="bg-surface rounded-xl shadow-xl border border-borderBase overflow-hidden relative transition-colors">
      <div className="p-6 border-b border-borderBase flex justify-between items-center bg-inputBg">
        <h2 className="text-xl font-bold text-textMain flex items-center gap-2">
          {isEditing ? <Edit3 className="text-primary" /> : <Plus className="text-primary" />} 
          {isEditing ? 'Edit Bet Slip' : 'Create New Bet Slip'}
        </h2>
        <div className="flex gap-2">
          {!isEditing && (
            <span className="text-[10px] uppercase tracking-wider font-bold text-success/80 border border-success/20 px-2 py-1 rounded-full flex items-center bg-success/5">
              Auto-Saved
            </span>
          )}
          <button 
            onClick={() => setShowImport(true)}
            className="text-xs flex items-center gap-1 bg-surface border border-borderBase hover:bg-background text-textMain px-3 py-1.5 rounded transition-colors"
          >
            <ClipboardPaste size={14} /> Import
          </button>
        </div>
      </div>

      {showImport && (
        <div className="absolute inset-0 z-50 bg-background/95 flex flex-col items-center justify-center p-6 animate-fade-in">
           {/* Import Modal Content */}
           <div className="w-full max-w-lg bg-surface border border-borderBase rounded-xl p-6 shadow-2xl">
              <div className="flex justify-between items-center mb-4">
                 <h3 className="text-textMain font-bold flex items-center gap-2">
                   <ClipboardPaste className="text-primary" /> Paste Bet Slip
                 </h3>
                 <button onClick={() => setShowImport(false)} className="text-textMuted hover:text-textMain">
                   <X size={20} />
                 </button>
              </div>
              <textarea
                value={importText}
                onChange={(e) => setImportText(e.target.value)}
                placeholder={`Paste your bet details here...`}
                className="w-full h-64 bg-inputBg border border-borderBase rounded-lg p-4 text-xs font-mono text-textMain focus:outline-none focus:border-primary resize-none placeholder-textMuted"
              />
              <div className="mt-4 flex justify-end gap-3">
                 <button onClick={() => setShowImport(false)} className="px-4 py-2 rounded text-textMuted hover:text-textMain">Cancel</button>
                 <button onClick={handleImport} className="px-6 py-2 rounded bg-primary text-white font-bold hover:bg-blue-600">Parse & Import</button>
              </div>
           </div>
        </div>
      )}

      <div className="p-6 space-y-6">

        {/* Betting Folder Selection */}
        <div className="bg-inputBg/50 p-4 rounded-lg border border-borderBase">
            <label className="text-sm font-medium text-textMain mb-2 flex items-center gap-2">
                <Folder size={16} className="text-primary" /> Betting Folder
            </label>
            <p className="text-xs text-textMuted mb-2">Organize your bets into folders (e.g., "Safe Bets", "Premier League", "High Risk").</p>
            <div className="relative">
                <input
                    type="text"
                    list="folders-list"
                    value={folder}
                    onChange={(e) => setFolder(e.target.value)}
                    placeholder="Select or Create a Folder"
                    className="w-full bg-surface border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                />
                <datalist id="folders-list">
                    {availableFolders.map(f => (
                        <option key={f} value={f} />
                    ))}
                </datalist>
            </div>
        </div>

        <div className="space-y-4">
          <label className="text-sm font-medium text-textMuted uppercase tracking-wider">Selections</label>

          {legs.map((leg, index) => (
            <div key={leg.id} className="grid grid-cols-1 md:grid-cols-12 gap-4 p-4 bg-background rounded-lg border border-borderBase hover:border-textMuted transition-colors">

              {/* Split Team Inputs */}
              <div className="md:col-span-4 grid grid-cols-2 gap-2">
                 <div className="space-y-1">
                    <label className="text-xs text-textMuted">Home Team</label>
                    <input
                      type="text"
                      value={leg.homeTeam}
                      onChange={(e) => updateLeg(leg.id, 'homeTeam', e.target.value)}
                      placeholder="Home Team"
                      className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary placeholder-textMuted/50"
                    />
                 </div>
                 <div className="space-y-1">
                    <label className="text-xs text-textMuted">Away Team</label>
                    <input
                      type="text"
                      value={leg.awayTeam}
                      onChange={(e) => updateLeg(leg.id, 'awayTeam', e.target.value)}
                      placeholder="Away Team"
                      className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary placeholder-textMuted/50"
                    />
                 </div>
              </div>

              <div className="md:col-span-2 space-y-1">
                 <label className="text-xs text-textMuted">League</label>
                 <input
                  type="text"
                  value={leg.league || ''}
                  onChange={(e) => updateLeg(leg.id, 'league', e.target.value)}
                  placeholder="e.g. EPL"
                  className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary placeholder-textMuted/50"
                />
              </div>

              <div className="md:col-span-2 space-y-1">
                <label className="text-xs text-textMuted">Date</label>
                <div className="relative">
                  <input
                    type="date"
                    value={leg.date}
                    onChange={(e) => updateLeg(leg.id, 'date', e.target.value)}
                    className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                  />
                </div>
              </div>

              <div className="md:col-span-2 space-y-1">
                <label className="text-xs text-textMuted">Market</label>
                <select
                  value={leg.type}
                  onChange={(e) => updateLeg(leg.id, 'type', e.target.value)}
                  className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                >
                  <optgroup label="Full Time">
                    <option value={BetType.MATCH_WINNER}>1X2 Winner</option>
                    <option value={BetType.DOUBLE_CHANCE}>Double Chance</option>
                    <option value={BetType.BTTS}>Both Teams To Score</option>
                    <option value={BetType.OVER_UNDER}>Over/Under Goals</option>
                    <option value={BetType.DRAW_NO_BET}>Draw No Bet</option>
                    <option value={BetType.TOTAL_CORNERS}>Total Corners</option>
                    <option value={BetType.BOOKINGS}>Bookings (Cards)</option>
                    <option value={BetType.SENDING_OFF}>Sending Off</option>
                    <option value={BetType.EXACT_GOALS}>Exact Goals</option>
                    <option value={BetType.ODD_EVEN}>Odd/Even Goals</option>
                    <option value={BetType.HANDICAP}>Handicap</option>
                    <option value={BetType.WINNING_MARGIN}>Winning Margin</option>
                  </optgroup>
                  <optgroup label="Half Time">
                    <option value={BetType.HALF_TIME_WINNER}>1st Half - 1X2</option>
                    <option value={BetType.HALF_TIME_DOUBLE_CHANCE}>1st Half - Double Chance</option>
                    <option value={BetType.HALF_TIME_BTTS}>1st Half - BTTS</option>
                    <option value={BetType.HALVES_BTTS}>1st/2nd Half BTTS</option>
                    <option value={BetType.HALF_TIME_1ST_GOAL}>1st Half - 1st Goal</option>
                    <option value={BetType.HALF_TIME_1ST_CORNER}>1st Half - 1st Corner</option>
                    <option value={BetType.HALF_TIME_WINNER_AND_BTTS}>1st Half - 1X2 & BTTS</option>
                    <option value={BetType.WIN_EITHER_HALF}>Win Either Half</option>
                  </optgroup>
                </select>
              </div>

              <div className="md:col-span-2 space-y-1">
                <label className="text-xs text-textMuted">Selection</label>

                {(leg.type === BetType.MATCH_WINNER || leg.type === BetType.HALF_TIME_WINNER) && (
                  <select
                    value={leg.selection}
                    onChange={(e) => updateLeg(leg.id, 'selection', e.target.value)}
                    className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                  >
                    <option value="Home">Home Win (1)</option>
                    <option value="Draw">Draw (X)</option>
                    <option value="Away">Away Win (2)</option>
                  </select>
                )}

                {/* ... (Other selection logic remains same, updating Over/Under below) ... */}

                {(leg.type === BetType.DOUBLE_CHANCE || leg.type === BetType.HALF_TIME_DOUBLE_CHANCE) && (
                  <select
                    value={leg.selection}
                    onChange={(e) => updateLeg(leg.id, 'selection', e.target.value)}
                    className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                  >
                    <option value="1X">Home or Draw (1X)</option>
                    <option value="X2">Away or Draw (X2)</option>
                    <option value="12">Home or Away (12)</option>
                  </select>
                )}

                {(leg.type === BetType.BTTS || leg.type === BetType.HALF_TIME_BTTS) && (
                  <select
                    value={leg.selection}
                    onChange={(e) => updateLeg(leg.id, 'selection', e.target.value)}
                    className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                  >
                    <option value="Yes">Yes</option>
                    <option value="No">No</option>
                  </select>
                )}

                {leg.type === BetType.HALVES_BTTS && (
                  <select
                    value={leg.selection}
                    onChange={(e) => updateLeg(leg.id, 'selection', e.target.value)}
                    className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                  >
                    <option value="Yes/Yes">1st: Yes / 2nd: Yes</option>
                    <option value="Yes/No">1st: Yes / 2nd: No</option>
                    <option value="No/Yes">1st: No / 2nd: Yes</option>
                    <option value="No/No">1st: No / 2nd: No</option>
                  </select>
                )}

                {leg.type === BetType.HALF_TIME_WINNER_AND_BTTS && (
                   <select
                    value={leg.selection}
                    onChange={(e) => updateLeg(leg.id, 'selection', e.target.value)}
                    className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                  >
                    <option value="Home & Yes">Home & Yes</option>
                    <option value="Home & No">Home & No</option>
                    <option value="Draw & Yes">Draw & Yes</option>
                    <option value="Draw & No">Draw & No</option>
                    <option value="Away & Yes">Away & Yes</option>
                    <option value="Away & No">Away & No</option>
                  </select>
                )}

                {(leg.type === BetType.HALF_TIME_1ST_GOAL || leg.type === BetType.HALF_TIME_1ST_CORNER) && (
                   <select
                    value={leg.selection}
                    onChange={(e) => updateLeg(leg.id, 'selection', e.target.value)}
                    className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                  >
                    <option value="Home">{leg.homeTeam || 'Home'}</option>
                    <option value="Away">{leg.awayTeam || 'Away'}</option>
                    <option value="None">None</option>
                  </select>
                )}

                {leg.type === BetType.SENDING_OFF && (
                  <select
                    value={leg.selection}
                    onChange={(e) => updateLeg(leg.id, 'selection', e.target.value)}
                    className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                  >
                    <option value="Yes">Yes (Red Card Shown)</option>
                    <option value="No">No (No Red Card)</option>
                  </select>
                )}

                {leg.type === BetType.ODD_EVEN && (
                  <select
                    value={leg.selection}
                    onChange={(e) => updateLeg(leg.id, 'selection', e.target.value)}
                    className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                  >
                    <option value="Odd">Odd</option>
                    <option value="Even">Even (0 is Even)</option>
                  </select>
                )}

                {leg.type === BetType.DRAW_NO_BET && (
                  <select
                    value={leg.selection}
                    onChange={(e) => updateLeg(leg.id, 'selection', e.target.value)}
                    className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                  >
                    <option value="Home">Home</option>
                    <option value="Away">Away</option>
                  </select>
                )}

                {leg.type === BetType.WIN_EITHER_HALF && (
                  <select
                    value={leg.selection}
                    onChange={(e) => updateLeg(leg.id, 'selection', e.target.value)}
                    className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                  >
                    <option value="Home">Home</option>
                    <option value="Away">Away</option>
                  </select>
                )}

                {leg.type === BetType.OVER_UNDER && (
                  <div className="flex gap-2">
                     <select
                        value={leg.selection.split(' ')[0]}
                        onChange={(e) => updateLeg(leg.id, 'selection', `${e.target.value} ${leg.selection.split(' ')[1] || '2.5'}`)}
                        className="w-1/2 bg-inputBg border border-borderBase rounded px-2 py-2 text-textMain text-sm"
                      >
                        <option value="Over">Over</option>
                        <option value="Under">Under</option>
                      </select>
                       <select
                        value={leg.selection.split(' ')[1]}
                        onChange={(e) => updateLeg(leg.id, 'selection', `${leg.selection.split(' ')[0] || 'Over'} ${e.target.value}`)}
                        className="w-1/2 bg-inputBg border border-borderBase rounded px-2 py-2 text-textMain text-sm"
                      >
                        <option value="0.5">0.5</option>
                        <option value="1.5">1.5</option>
                        <option value="2.5">2.5</option>
                        <option value="3.5">3.5</option>
                        <option value="4.5">4.5</option>
                        <option value="5.5">5.5</option>
                      </select>
                  </div>
                )}

                {(leg.type === BetType.TOTAL_CORNERS || leg.type === BetType.BOOKINGS) && (
                  <div className="flex gap-2">
                     <select
                        value={leg.selection.split(' ')[0]}
                        onChange={(e) => updateLeg(leg.id, 'selection', `${e.target.value} ${leg.selection.split(' ')[1] || (leg.type === BetType.TOTAL_CORNERS ? '9.5' : '3.5')}`)}
                        className="w-1/2 bg-inputBg border border-borderBase rounded px-2 py-2 text-textMain text-sm"
                      >
                        <option value="Over">Over</option>
                        <option value="Under">Under</option>
                      </select>
                      <input 
                        type="text"
                        inputMode="decimal"
                        value={leg.selection.split(' ')[1] || (leg.type === BetType.TOTAL_CORNERS ? '9.5' : '3.5')}
                        onChange={(e) => {
                          const val = e.target.value;
                          if (val === '' || /^\d*\.?\d*$/.test(val)) {
                             updateLeg(leg.id, 'selection', `${leg.selection.split(' ')[0] || 'Over'} ${val}`);
                          }
                        }}
                        className="w-1/2 bg-inputBg border border-borderBase rounded px-2 py-2 text-textMain text-sm"
                      />
                  </div>
                )}

                {leg.type === BetType.EXACT_GOALS && (
                   <div className="flex gap-2">
                      <input 
                        type="text"
                        inputMode="numeric"
                        placeholder="e.g. 2"
                        value={leg.selection}
                        onChange={(e) => {
                          const val = e.target.value;
                          if (val === '' || /^\d+$/.test(val)) {
                             updateLeg(leg.id, 'selection', val);
                          }
                        }}
                        className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm"
                      />
                   </div>
                )}

                {leg.type === BetType.HANDICAP && (
                  <div className="flex gap-2">
                     <select
                        value={leg.selection.split(' ')[0]}
                        onChange={(e) => updateLeg(leg.id, 'selection', `${e.target.value} ${leg.selection.split(' ')[1] || '-1.5'}`)}
                        className="w-1/2 bg-inputBg border border-borderBase rounded px-2 py-2 text-textMain text-sm"
                      >
                        <option value="Home">Home</option>
                        <option value="Away">Away</option>
                      </select>
                      <input 
                        type="text"
                        value={leg.selection.split(' ').slice(1).join(' ') || '-1.5'}
                        onChange={(e) => {
                          const val = e.target.value;
                           updateLeg(leg.id, 'selection', `${leg.selection.split(' ')[0] || 'Home'} ${val}`);
                        }}
                        placeholder="-1.5"
                        className="w-1/2 bg-inputBg border border-borderBase rounded px-2 py-2 text-textMain text-sm"
                      />
                  </div>
                )}

                {leg.type === BetType.WINNING_MARGIN && (
                  <div className="flex gap-2">
                    <select
                      value={leg.selection === 'Draw' ? 'Draw' : leg.selection.split(' By ')[0]}
                      onChange={(e) => {
                        const val = e.target.value;
                        if (val === 'Draw') {
                           updateLeg(leg.id, 'selection', 'Draw');
                        } else {
                           // Preserve margin if switching between Home/Away, default to 1 if coming from Draw
                           const currentMargin = leg.selection.includes('By') ? leg.selection.split(' By ')[1] : '1';
                           updateLeg(leg.id, 'selection', `${val} By ${currentMargin}`);
                        }
                      }}
                      className="w-1/2 bg-inputBg border border-borderBase rounded px-2 py-2 text-textMain text-sm"
                    >
                      <option value="Home">Home</option>
                      <option value="Away">Away</option>
                      <option value="Draw">Draw</option>
                    </select>

                    {leg.selection !== 'Draw' && (
                       <select
                        value={leg.selection.split(' By ')[1] || '1'}
                        onChange={(e) => {
                          const side = leg.selection.split(' By ')[0] || 'Home';
                          updateLeg(leg.id, 'selection', `${side} By ${e.target.value}`);
                        }}
                        className="w-1/2 bg-inputBg border border-borderBase rounded px-2 py-2 text-textMain text-sm"
                      >
                        <option value="1">By 1</option>
                        <option value="2">By 2</option>
                        <option value="3+">By 3+</option>
                      </select>
                    )}
                  </div>
                )}
              </div>

              <div className="md:col-span-1 flex items-end justify-center pb-1">
                <button 
                  onClick={() => removeLeg(leg.id)}
                  disabled={legs.length === 1}
                  className={`p-2 rounded hover:bg-danger/20 text-danger/80 hover:text-danger transition-colors ${legs.length === 1 ? 'opacity-50 cursor-not-allowed' : ''}`}
                >
                  <Trash2 size={18} />
                </button>
              </div>
            </div>
          ))}

          <button 
            onClick={addLeg}
            className="w-full py-3 border border-dashed border-borderBase rounded-lg text-textMuted hover:text-textMain hover:border-textMuted hover:bg-inputBg transition-all flex items-center justify-center gap-2"
          >
            <Plus size={18} /> Add Another Match
          </button>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 pt-6 border-t border-borderBase">
           <div>
              <label className="text-sm font-medium text-textMuted block mb-2">Total Stake ({symbol})</label>
              <input 
                type="text" 
                inputMode="decimal"
                value={stake}
                onChange={(e) => handleNumericChange(e.target.value, setStake)}
                className="w-full bg-inputBg border border-borderBase rounded px-4 py-3 text-textMain font-bold focus:outline-none focus:border-primary"
                placeholder="0.00"
              />
           </div>
           <div>
              <label className="text-sm font-medium text-textMuted block mb-2">Total Odds</label>
              <input 
                type="text" 
                inputMode="decimal"
                value={totalOdds}
                onChange={(e) => handleNumericChange(e.target.value, setTotalOdds)}
                className="w-full bg-inputBg border border-borderBase rounded px-4 py-3 text-textMain font-bold focus:outline-none focus:border-primary"
                placeholder="1.00"
              />
           </div>
        </div>

        <div className="bg-primary/10 rounded-lg p-4 flex justify-between items-center border border-primary/20">
          <span className="text-primary font-medium">Potential Return</span>
          <span className="text-2xl font-bold text-primary">
            {symbol}{((parseFloat(stake) || 0) * (parseFloat(totalOdds) || 0)).toFixed(2)}
          </span>
        </div>

        <div className="flex gap-4 justify-end pt-4">
          <button 
            onClick={handleCancel}
            className="px-6 py-3 rounded-lg font-medium text-textMuted hover:text-textMain hover:bg-inputBg transition-colors"
          >
            Cancel
          </button>
          <button 
            onClick={handleSave}
            className="px-8 py-3 rounded-lg font-bold bg-primary hover:bg-blue-600 text-white shadow-lg shadow-blue-500/20 transition-all flex items-center gap-2"
          >
            <Save size={18} /> {isEditing ? 'Update Bet Slip' : 'Save Bet Slip'}
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { LayoutDashboard, PlusCircle, History, Wallet, TrendingUp, Trophy, Settings as SettingsIcon, Sun, Moon, Trash2, X, BarChart3, FolderOpen } from 'lucide-react';
import { Slip, SlipStatus, Stats, Currency, CURRENCY_SYMBOLS } from './types';
import { StatsCard } from './components/StatsCard';
import { SlipList } from './components/SlipList';
import { NewSlipForm } from './components/NewSlipForm';
import { StatisticsPanel } from './components/StatisticsPanel';

const App: React.FC = () => {
  // State Initialization with LocalStorage
  const [activeTab, setActiveTab] = useState<'dashboard' | 'active' | 'settled' | 'create' | 'stats'>('dashboard');

  const [slips, setSlips] = useState<Slip[]>(() => {
    const saved = localStorage.getItem('smartbet_slips');
    return saved ? JSON.parse(saved) : [];
  });

  const [theme, setTheme] = useState<'light' | 'dark'>(() => {
    return (localStorage.getItem('smartbet_theme') as 'light' | 'dark') || 'dark';
  });

  const [currency, setCurrency] = useState<Currency>(() => {
    return (localStorage.getItem('smartbet_currency') as Currency) || 'ZAR';
  });

  // Folder state
  const [selectedFolder, setSelectedFolder] = useState<string>('All');

  const [showSettings, setShowSettings] = useState(false);
  const [editingSlip, setEditingSlip] = useState<Slip | null>(null);

  const [stats, setStats] = useState<Stats>({
    totalSlips: 0,
    wins: 0,
    losses: 0,
    winRate: 0,
    totalStaked: 0,
    totalReturned: 0,
    profit: 0,
    roi: 0
  });

  // Derived state for unique folders
  const uniqueFolders = React.useMemo(() => {
    const folders = new Set<string>();
    slips.forEach(s => {
      if (s.folder) folders.add(s.folder);
    });
    return Array.from(folders).sort();
  }, [slips]);

  // Persist State
  useEffect(() => {
    localStorage.setItem('smartbet_slips', JSON.stringify(slips));
  }, [slips]);

  useEffect(() => {
    localStorage.setItem('smartbet_theme', theme);
    const root = window.document.documentElement;
    if (theme === 'dark') {
      root.classList.add('dark');
    } else {
      root.classList.remove('dark');
    }
  }, [theme]);

  useEffect(() => {
    localStorage.setItem('smartbet_currency', currency);
  }, [currency]);


  // Calculate Stats
  useEffect(() => {
    const settledSlips = slips.filter(s => s.status === SlipStatus.WON || s.status === SlipStatus.LOST);
    const totalSlips = settledSlips.length;
    const wins = settledSlips.filter(s => s.status === SlipStatus.WON).length;
    const losses = settledSlips.filter(s => s.status === SlipStatus.LOST).length;
    const winRate = totalSlips > 0 ? (wins / totalSlips) * 100 : 0;

    const totalStaked = slips.reduce((acc, s) => acc + s.stake, 0);
    const totalReturned = settledSlips
      .filter(s => s.status === SlipStatus.WON)
      .reduce((acc, s) => acc + s.potentialReturn, 0);

    const settledStaked = settledSlips.reduce((acc, s) => acc + s.stake, 0);
    const profit = totalReturned - settledStaked;
    const roi = settledStaked > 0 ? (profit / settledStaked) * 100 : 0;

    setStats({
      totalSlips,
      wins,
      losses,
      winRate,
      totalStaked,
      totalReturned,
      profit,
      roi
    });
  }, [slips]);

  const handleSaveSlip = (savedSlip: Slip) => {
    const exists = slips.some(s => s.id === savedSlip.id);
    if (exists) {
      setSlips(slips.map(s => s.id === savedSlip.id ? savedSlip : s));
    } else {
      setSlips([savedSlip, ...slips]);
    }
    setEditingSlip(null);
    setActiveTab('active');
  };

  const handleUpdateSlip = (updatedSlip: Slip) => {
    setSlips(slips.map(s => s.id === updatedSlip.id ? updatedSlip : s));
  };

  const handleEditSlip = (slip: Slip) => {
    setEditingSlip(slip);
    setActiveTab('create');
  };

  const handleResetStats = () => {
    if (confirm("Are you sure you want to delete all betting history? This cannot be undone.")) {
      setSlips([]);
      setShowSettings(false);
    }
  };

  // Filter Slips based on status AND selected folder
  const activeSlips = slips.filter(s => 
    s.status === SlipStatus.PENDING && 
    (selectedFolder === 'All' || s.folder === selectedFolder)
  );

  const settledSlips = slips.filter(s => 
    s.status !== SlipStatus.PENDING && 
    (selectedFolder === 'All' || s.folder === selectedFolder)
  );

  const filteredSlipsForOverview = slips.filter(s => 
    selectedFolder === 'All' || s.folder === selectedFolder
  );

  return (
    <div className="min-h-screen bg-background pb-20 md:pb-0 transition-colors duration-300">
      {/* Top Navigation / Header */}
      <header className="bg-surface border-b border-borderBase sticky top-0 z-10 transition-colors">
        <div className="max-w-5xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
             <div className="bg-primary p-1.5 rounded-lg">
               <TrendingUp className="text-white" size={20} />
             </div>
             <h1 className="text-xl font-bold text-textMain tracking-tight">SmartBet<span className="text-primary">Tracker</span></h1>
          </div>
          <div className="hidden md:flex items-center gap-1 bg-inputBg p-1 rounded-lg border border-borderBase">
             <NavButton active={activeTab === 'dashboard'} onClick={() => setActiveTab('dashboard')} icon={LayoutDashboard} label="Overview" />
             <NavButton active={activeTab === 'active'} onClick={() => setActiveTab('active')} icon={Wallet} label="Active" badge={slips.filter(s => s.status === SlipStatus.PENDING).length} />
             <NavButton active={activeTab === 'stats'} onClick={() => setActiveTab('stats')} icon={BarChart3} label="Analytics" />
             <NavButton active={activeTab === 'settled'} onClick={() => setActiveTab('settled')} icon={History} label="History" />
          </div>
          <div className="flex gap-2">
            <button 
              onClick={() => setShowSettings(true)}
              className="p-2 rounded-lg text-textMuted hover:text-textMain hover:bg-inputBg transition-colors"
            >
              <SettingsIcon size={20} />
            </button>
            <button 
              onClick={() => { setEditingSlip(null); setActiveTab('create'); }}
              className="bg-primary hover:bg-blue-600 text-white px-4 py-2 rounded-lg text-sm font-bold flex items-center gap-2 transition-colors shadow-lg shadow-blue-500/20"
            >
              <PlusCircle size={18} /> <span className="hidden sm:inline">New Bet</span>
            </button>
          </div>
        </div>
      </header>

      {/* Settings Modal */}
      {showSettings && (
        <div className="fixed inset-0 z-50 bg-background/80 backdrop-blur-sm flex items-center justify-center p-4 animate-fade-in">
          <div className="bg-surface border border-borderBase rounded-xl shadow-2xl w-full max-w-md overflow-hidden">
            <div className="p-4 border-b border-borderBase flex justify-between items-center bg-inputBg">
               <h3 className="font-bold text-textMain flex items-center gap-2">
                 <SettingsIcon size={18} className="text-primary" /> Settings
               </h3>
               <button onClick={() => setShowSettings(false)} className="text-textMuted hover:text-textMain">
                 <X size={20} />
               </button>
            </div>
            <div className="p-6 space-y-6">
               {/* Theme Toggle */}
               <div className="flex items-center justify-between">
                 <span className="text-textMain font-medium">Appearance</span>
                 <div className="flex bg-inputBg rounded-lg p-1 border border-borderBase">
                    <button 
                      onClick={() => setTheme('light')}
                      className={`p-2 rounded flex items-center gap-2 text-xs font-bold transition-all ${theme === 'light' ? 'bg-surface shadow text-primary' : 'text-textMuted'}`}
                    >
                      <Sun size={14} /> Light
                    </button>
                    <button 
                      onClick={() => setTheme('dark')}
                      className={`p-2 rounded flex items-center gap-2 text-xs font-bold transition-all ${theme === 'dark' ? 'bg-surface shadow text-primary' : 'text-textMuted'}`}
                    >
                      <Moon size={14} /> Dark
                    </button>
                 </div>
               </div>

               {/* Currency Select */}
               <div className="flex items-center justify-between">
                 <span className="text-textMain font-medium">Currency</span>
                 <select 
                   value={currency}
                   onChange={(e) => setCurrency(e.target.value as Currency)}
                   className="bg-inputBg border border-borderBase rounded-lg px-3 py-1.5 text-textMain text-sm focus:outline-none focus:border-primary"
                 >
                   <option value="ZAR">ZAR (R)</option>
                   <option value="USD">USD ($)</option>
                   <option value="GBP">GBP (£)</option>
                 </select>
               </div>

               <div className="border-t border-borderBase pt-6">
                 <button 
                   onClick={handleResetStats}
                   className="w-full py-3 rounded-lg border border-danger/30 text-danger hover:bg-danger hover:text-white transition-all font-bold flex items-center justify-center gap-2"
                 >
                   <Trash2 size={18} /> Reset All Stats & Data
                 </button>
                 <p className="text-xs text-textMuted text-center mt-2">
                   This action cannot be undone. All bet slips will be erased.
                 </p>
               </div>
            </div>
          </div>
        </div>
      )}

      {/* Mobile Bottom Nav */}
      <div className="md:hidden fixed bottom-0 left-0 right-0 bg-surface border-t border-borderBase z-40 px-6 py-3 flex justify-between items-center">
        <MobileNavButton active={activeTab === 'dashboard'} onClick={() => setActiveTab('dashboard')} icon={LayoutDashboard} label="Overview" />
        <MobileNavButton active={activeTab === 'active'} onClick={() => setActiveTab('active')} icon={Wallet} label="Active" badge={activeSlips.length} />
        <MobileNavButton active={activeTab === 'stats'} onClick={() => setActiveTab('stats')} icon={BarChart3} label="Analytics" />
        <MobileNavButton active={activeTab === 'create'} onClick={() => { setEditingSlip(null); setActiveTab('create'); }} icon={PlusCircle} label="New" />
      </div>

      {/* Main Content */}
      <main className="max-w-5xl mx-auto px-4 py-8">

        {/* Betting Folders Filter (Main Panel) */}
        {uniqueFolders.length > 0 && activeTab !== 'create' && (
          <div className="mb-6 overflow-x-auto pb-2 scrollbar-hide">
             <div className="flex gap-2">
               <button
                 onClick={() => setSelectedFolder('All')}
                 className={`px-4 py-2 rounded-full text-xs font-bold whitespace-nowrap border transition-all ${
                   selectedFolder === 'All' 
                     ? 'bg-primary text-white border-primary' 
                     : 'bg-surface text-textMuted border-borderBase hover:bg-inputBg'
                 }`}
               >
                 All Bets
               </button>
               {uniqueFolders.map(folder => (
                 <button
                   key={folder}
                   onClick={() => setSelectedFolder(folder)}
                   className={`px-4 py-2 rounded-full text-xs font-bold whitespace-nowrap border flex items-center gap-2 transition-all ${
                     selectedFolder === folder 
                       ? 'bg-primary text-white border-primary' 
                       : 'bg-surface text-textMuted border-borderBase hover:bg-inputBg'
                   }`}
                 >
                   <FolderOpen size={14} /> {folder}
                 </button>
               ))}
             </div>
          </div>
        )}

        {activeTab === 'dashboard' && (
          <div className="space-y-8 animate-fade-in">
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
               <StatsCard title="Net Profit" value={stats.profit.toFixed(2)} isMoney currency={currency} icon={Wallet} color={stats.profit >= 0 ? 'text-success' : 'text-danger'} />
               <StatsCard title="Win Rate" value={`${stats.winRate.toFixed(1)}%`} icon={Trophy} color="text-warning" />
               <StatsCard title="Total Staked" value={stats.totalStaked.toFixed(2)} isMoney currency={currency} icon={Wallet} color="text-blue-400" />
               <StatsCard title="ROI" value={`${stats.roi.toFixed(1)}%`} icon={TrendingUp} color={stats.roi >= 0 ? 'text-success' : 'text-danger'} />
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
              <div className="lg:col-span-2 space-y-4">
                <h2 className="text-xl font-bold text-textMain flex items-center gap-2">
                  <History className="text-textMuted" size={20} /> Recent Activity {selectedFolder !== 'All' && `(${selectedFolder})`}
                </h2>
                <SlipList slips={filteredSlipsForOverview.slice(0, 5)} onUpdateSlip={handleUpdateSlip} onEditSlip={handleEditSlip} currency={currency} />
              </div>
              <div className="space-y-4">
                 <div className="bg-surface p-6 rounded-xl border border-borderBase">
                    <h3 className="text-textMain font-bold mb-4">Performance</h3>
                    <div className="space-y-4">
                       <div className="flex justify-between text-sm">
                          <span className="text-textMuted">Wins</span>
                          <span className="text-success font-bold">{stats.wins}</span>
                       </div>
                       <div className="w-full bg-inputBg rounded-full h-2">
                          <div className="bg-success h-2 rounded-full" style={{ width: `${stats.totalSlips ? (stats.wins/stats.totalSlips)*100 : 0}%` }}></div>
                       </div>
                       <div className="flex justify-between text-sm">
                          <span className="text-textMuted">Losses</span>
                          <span className="text-danger font-bold">{stats.losses}</span>
                       </div>
                        <div className="w-full bg-inputBg rounded-full h-2">
                          <div className="bg-danger h-2 rounded-full" style={{ width: `${stats.totalSlips ? (stats.losses/stats.totalSlips)*100 : 0}%` }}></div>
                       </div>
                    </div>
                 </div>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'create' && (
          <div className="max-w-3xl mx-auto animate-fade-in">
             <NewSlipForm 
               initialData={editingSlip || undefined}
               onSave={handleSaveSlip} 
               onCancel={() => { setEditingSlip(null); setActiveTab('dashboard'); }} 
               currency={currency}
               availableFolders={uniqueFolders}
             />
          </div>
        )}

        {activeTab === 'stats' && (
           <StatisticsPanel slips={filteredSlipsForOverview} currency={currency} />
        )}

        {activeTab === 'active' && (
          <div className="space-y-4 animate-fade-in">
             <h2 className="text-xl font-bold text-textMain mb-6">Active Slips {selectedFolder !== 'All' && `(${selectedFolder})`}</h2>
             <SlipList slips={activeSlips} onUpdateSlip={handleUpdateSlip} onEditSlip={handleEditSlip} currency={currency} />
          </div>
        )}

        {activeTab === 'settled' && (
          <div className="space-y-4 animate-fade-in">
             <h2 className="text-xl font-bold text-textMain mb-6">Betting History {selectedFolder !== 'All' && `(${selectedFolder})`}</h2>
             <SlipList slips={settledSlips} onUpdateSlip={handleUpdateSlip} onEditSlip={handleEditSlip} currency={currency} />
          </div>
        )}

      </main>
    </div>
  );
};

// Helper Components for Nav
const NavButton = ({ active, onClick, icon: Icon, label, badge }: any) => (
  <button 
    onClick={onClick}
    className={`px-4 py-2 rounded-md text-sm font-medium flex items-center gap-2 transition-all ${active ? 'bg-inputBg text-textMain shadow-sm border border-borderBase' : 'text-textMuted hover:text-textMain hover:bg-inputBg'}`}
  >
    <Icon size={16} /> {label}
    {badge > 0 && <span className="bg-primary text-white text-[10px] px-1.5 py-0.5 rounded-full">{badge}</span>}
  </button>
);

const MobileNavButton = ({ active, onClick, icon: Icon, label, badge }: any) => (
  <button 
    onClick={onClick}
    className={`flex flex-col items-center gap-1 ${active ? 'text-primary' : 'text-textMuted'}`}
  >
    <div className="relative">
      <Icon size={24} />
      {badge > 0 && <span className="absolute -top-1 -right-1 bg-red-500 text-white text-[10px] w-4 h-4 flex items-center justify-center rounded-full border border-surface">{badge}</span>}
    </div>
    <span className="text-[10px] font-medium">{label}</span>
  </button>
);

export default App;

import React, { useState, useEffect } from 'react';
import { ChevronDown, ChevronUp, RefreshCw, Trophy, XCircle, Clock, Check, ExternalLink, Pencil, Gavel, Save, X, Ban, Folder } from 'lucide-react';
import { Slip, SlipStatus, Leg, LegStatus, Currency, CURRENCY_SYMBOLS } from '../types';
import { validateSlipWithGemini } from '../services/geminiService';

interface SlipListProps {
  slips: Slip[];
  onUpdateSlip: (updatedSlip: Slip) => void;
  onEditSlip?: (slip: Slip) => void;
  currency: Currency;
}

export const SlipList: React.FC<SlipListProps> = ({ slips, onUpdateSlip, onEditSlip, currency }) => {
  const symbol = CURRENCY_SYMBOLS[currency];

  if (slips.length === 0) {
    return (
      <div className="text-center py-20 bg-surface rounded-xl border border-borderBase">
        <div className="inline-block p-4 rounded-full bg-inputBg mb-4">
          <Trophy className="text-textMuted" size={32} />
        </div>
        <h3 className="text-lg font-medium text-textMain">No bets found</h3>
        <p className="text-textMuted">Create a new bet slip to get started.</p>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {slips.map(slip => (
        <SlipCard key={slip.id} slip={slip} onUpdate={onUpdateSlip} onEdit={onEditSlip} symbol={symbol} />
      ))}
    </div>
  );
};

interface SlipCardProps {
  slip: Slip;
  onUpdate: (slip: Slip) => void;
  onEdit?: (slip: Slip) => void;
  symbol: string;
}

const SlipCard: React.FC<SlipCardProps> = ({ slip, onUpdate, onEdit, symbol }) => {
  const [expanded, setExpanded] = useState(false);
  const [checking, setChecking] = useState(false);

  // Manual Settlement State
  const [isSettling, setIsSettling] = useState(false);
  const [editedLegs, setEditedLegs] = useState<Leg[]>([]);

  const getStatusColor = (status: SlipStatus | LegStatus) => {
    switch (status) {
      case 'WON': return 'text-success bg-success/10 border-success/20';
      case 'LOST': return 'text-danger bg-danger/10 border-danger/20';
      case 'VOID': return 'text-warning bg-warning/10 border-warning/20';
      default: return 'text-textMuted bg-inputBg border-borderBase';
    }
  };

  const getStatusIcon = (status: SlipStatus | LegStatus) => {
    switch (status) {
      case 'WON': return <Check size={16} />;
      case 'LOST': return <XCircle size={16} />;
      case 'PENDING': return <Clock size={16} />;
      case 'VOID': return <Ban size={16} />;
      default: return null;
    }
  };

  const calculateSlipStatus = (legs: Leg[]): SlipStatus => {
    if (legs.some(l => l.status === LegStatus.LOST)) return SlipStatus.LOST;
    if (legs.some(l => l.status === LegStatus.PENDING)) return SlipStatus.PENDING;
    if (legs.every(l => l.status === LegStatus.VOID)) return SlipStatus.VOID;
    return SlipStatus.WON;
  };

  const handleAICheck = async (e: React.MouseEvent) => {
    e.stopPropagation();
    if (checking || slip.status !== SlipStatus.PENDING) return;

    setChecking(true);
    try {
      const response = await validateSlipWithGemini(slip);

      const updatedLegs = slip.legs.map(leg => {
        const update = response.results.find(r => r.legId === leg.id);
        if (update) {
          return { ...leg, status: update.status, resultScore: update.score };
        }
        return leg;
      });

      const newStatus = calculateSlipStatus(updatedLegs);

      onUpdate({
        ...slip,
        legs: updatedLegs,
        status: newStatus,
        groundingUrls: response.sources
      });
    } catch (error) {
      alert("Failed to update matches via AI. Please try again.");
    } finally {
      setChecking(false);
    }
  };

  const handleEditClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (onEdit) onEdit(slip);
  };

  // Manual Settlement Handlers
  const startSettling = (e: React.MouseEvent) => {
    e.stopPropagation();
    setEditedLegs([...slip.legs]);
    setIsSettling(true);
    setExpanded(true);
  };

  const cancelSettling = (e: React.MouseEvent) => {
    e.stopPropagation();
    setIsSettling(false);
    setEditedLegs([]);
  };

  const saveSettlement = (e: React.MouseEvent) => {
    e.stopPropagation();
    const newStatus = calculateSlipStatus(editedLegs);
    onUpdate({
      ...slip,
      legs: editedLegs,
      status: newStatus
    });
    setIsSettling(false);
  };

  const updateLegStatus = (legId: string, status: LegStatus) => {
    setEditedLegs(prev => prev.map(l => l.id === legId ? { ...l, status } : l));
  };

  const updateLegScore = (legId: string, score: string) => {
    setEditedLegs(prev => prev.map(l => l.id === legId ? { ...l, resultScore: score } : l));
  };

  return (
    <div className={`bg-surface rounded-xl border transition-all overflow-hidden ${slip.status === SlipStatus.WON ? 'border-success/30 shadow-success/5' : slip.status === SlipStatus.LOST ? 'border-danger/30' : 'border-borderBase'}`}>
      {/* Header */}
      <div 
        className="p-5 flex items-center justify-between cursor-pointer hover:bg-inputBg transition-colors"
        onClick={() => !isSettling && setExpanded(!expanded)}
      >
        <div className="flex items-center gap-4">
          <div className={`w-10 h-10 rounded-full flex items-center justify-center border ${getStatusColor(slip.status)}`}>
            {getStatusIcon(slip.status)}
          </div>
          <div>
             <div className="flex items-center gap-2 flex-wrap">
               <h4 className="font-bold text-textMain text-lg">
                 {slip.legs.length} Match Accumulator
               </h4>
               {slip.folder && (
                  <span className="flex items-center gap-1 text-[10px] font-bold text-textMuted uppercase tracking-wide bg-inputBg border border-borderBase px-2 py-0.5 rounded-full">
                    <Folder size={10} /> {slip.folder}
                  </span>
               )}
               <span className="text-xs text-textMuted font-mono">
                 {new Date(slip.createdAt).toLocaleDateString()}
               </span>
             </div>
             <p className="text-textMuted text-sm">
               Stake: <span className="text-textMain font-medium">{symbol}{slip.stake}</span> • 
               Odds: <span className="text-textMain font-medium">{slip.odds}</span> • 
               Return: <span className={`font-bold ${slip.status === 'WON' ? 'text-success' : 'text-primary'}`}>{symbol}{slip.potentialReturn.toFixed(2)}</span>
             </p>
          </div>
        </div>

        <div className="flex items-center gap-2">
          {isSettling ? (
            <div className="flex gap-2">
               <button 
                 onClick={cancelSettling}
                 className="p-2 rounded-lg bg-surface border border-borderBase text-textMuted hover:text-textMain hover:bg-inputBg transition-colors"
                 title="Cancel"
               >
                 <X size={18} />
               </button>
               <button 
                 onClick={saveSettlement}
                 className="px-4 py-2 rounded-lg bg-primary text-white font-bold flex items-center gap-2 hover:bg-blue-600 transition-colors shadow-lg shadow-blue-500/20"
                 title="Save Changes"
               >
                 <Save size={18} /> Save
               </button>
            </div>
          ) : (
            <div className="flex items-center gap-2">
              {/* Manual Settle Button - Available for all slips to correct errors */}
              <button 
                onClick={startSettling}
                className="p-2 rounded-lg text-textMuted hover:text-primary hover:bg-primary/10 transition-colors"
                title="Manual Settlement"
              >
                <Gavel size={16} />
              </button>

              {slip.status === SlipStatus.PENDING && (
                <>
                  {onEdit && (
                    <button 
                      onClick={handleEditClick}
                      className="p-2 rounded-lg text-textMuted hover:text-textMain hover:bg-surface border border-transparent hover:border-borderBase transition-all"
                      title="Edit Bet Slip"
                    >
                      <Pencil size={14} />
                    </button>
                  )}
                  <button 
                    onClick={handleAICheck}
                    disabled={checking}
                    className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs font-bold uppercase tracking-wide transition-all ${checking ? 'bg-inputBg text-textMuted' : 'bg-primary/20 text-primary hover:bg-primary/30'}`}
                  >
                    <RefreshCw size={14} className={checking ? "animate-spin" : ""} />
                    {checking ? 'Checking...' : 'Check'}
                  </button>
                </>
              )}

              <div className="pl-2 border-l border-borderBase ml-2">
                {expanded ? <ChevronUp className="text-textMuted" size={20} /> : <ChevronDown className="text-textMuted" size={20} />}
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Expanded Content */}
      {expanded && (
        <div className="border-t border-borderBase bg-background/30 p-4">
          <div className="space-y-2">
             {(isSettling ? editedLegs : slip.legs).map((leg, idx) => (
                <div key={leg.id} className={`flex flex-col md:flex-row md:items-center justify-between p-3 rounded-lg border ${isSettling ? 'bg-surface border-primary/30 shadow-sm' : 'bg-inputBg border-borderBase'}`}>
                   <div className="flex-1 mb-3 md:mb-0">
                      <div className="flex justify-between items-start">
                         <h5 className="text-textMain font-medium">{leg.matchName}</h5>
                         {!isSettling && <span className="text-xs text-textMuted">{leg.date}</span>}
                      </div>
                      <div className="flex items-center gap-2 mt-1">
                         <span className="text-xs font-bold px-2 py-0.5 rounded bg-surface border border-borderBase text-textMuted">{leg.type}</span>
                         <span className="text-sm text-primary">Prediction: {leg.selection}</span>
                      </div>

                      {isSettling ? (
                         <div className="mt-3">
                           <label className="text-[10px] uppercase text-textMuted font-bold mb-1 block">Score / Result</label>
                           <input 
                             type="text" 
                             value={leg.resultScore || ''} 
                             onChange={(e) => updateLegScore(leg.id, e.target.value)}
                             placeholder="e.g. 2-1"
                             className="w-full md:w-48 bg-inputBg border border-borderBase rounded px-2 py-1 text-sm text-textMain"
                           />
                         </div>
                      ) : (
                        leg.resultScore && (
                          <div className="mt-2 text-xs text-textMuted font-mono flex items-center gap-1">
                            Final Score: <span className="text-textMain font-bold">{leg.resultScore}</span>
                          </div>
                        )
                      )}
                   </div>

                   <div className="ml-0 md:ml-4 flex items-center gap-2">
                      {isSettling ? (
                        <div className="flex gap-1 bg-inputBg p-1 rounded-lg border border-borderBase">
                          <button 
                             onClick={() => updateLegStatus(leg.id, LegStatus.WON)}
                             className={`p-1.5 rounded text-xs font-bold transition-colors ${leg.status === LegStatus.WON ? 'bg-success text-white shadow' : 'text-textMuted hover:bg-background'}`}
                             title="Mark as Won"
                          >
                            <Check size={14} />
                          </button>
                          <button 
                             onClick={() => updateLegStatus(leg.id, LegStatus.LOST)}
                             className={`p-1.5 rounded text-xs font-bold transition-colors ${leg.status === LegStatus.LOST ? 'bg-danger text-white shadow' : 'text-textMuted hover:bg-background'}`}
                             title="Mark as Lost"
                          >
                            <XCircle size={14} />
                          </button>
                          <button 
                             onClick={() => updateLegStatus(leg.id, LegStatus.VOID)}
                             className={`p-1.5 rounded text-xs font-bold transition-colors ${leg.status === LegStatus.VOID ? 'bg-warning text-white shadow' : 'text-textMuted hover:bg-background'}`}
                             title="Mark as Void"
                          >
                            <Ban size={14} />
                          </button>
                          <button 
                             onClick={() => updateLegStatus(leg.id, LegStatus.PENDING)}
                             className={`p-1.5 rounded text-xs font-bold transition-colors ${leg.status === LegStatus.PENDING ? 'bg-surface text-textMain shadow' : 'text-textMuted hover:bg-background'}`}
                             title="Mark as Pending"
                          >
                            <Clock size={14} />
                          </button>
                        </div>
                      ) : (
                        <span className={`text-xs font-bold px-2 py-1 rounded border ${getStatusColor(leg.status)}`}>
                          {leg.status}
                        </span>
                      )}
                   </div>
                </div>
             ))}
          </div>

          {/* Grounding Sources (Only show in view mode) */}
          {!isSettling && slip.groundingUrls && slip.groundingUrls.length > 0 && (
            <div className="mt-4 pt-4 border-t border-borderBase">
               <h6 className="text-xs font-bold text-textMuted uppercase tracking-wider mb-2 flex items-center gap-1">
                 <ExternalLink size={10} /> Verified Sources
               </h6>
               <div className="flex flex-wrap gap-2">
                  {slip.groundingUrls.map((url, i) => (
                    <a 
                      key={i} 
                      href={url} 
                      target="_blank" 
                      rel="noopener noreferrer"
                      className="text-xs text-primary hover:underline truncate max-w-xs"
                    >
                      Source {i+1}
                    </a>
                  ))}
               </div>
            </div>
          )}

          {isSettling && (
            <div className="mt-4 pt-4 border-t border-borderBase text-center text-xs text-textMuted">
              Adjusting leg statuses will automatically recalculate the overall slip status.
            </div>
          )}
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { LayoutDashboard, PlusCircle, History, Wallet, TrendingUp, Trophy, Settings as SettingsIcon, Sun, Moon, Trash2, X, BarChart3, FolderOpen, Edit2, Check } from 'lucide-react';
import { Slip, SlipStatus, Stats, Currency, CURRENCY_SYMBOLS } from './types';
import { StatsCard } from './components/StatsCard';
import { SlipList } from './components/SlipList';
import { NewSlipForm } from './components/NewSlipForm';
import { StatisticsPanel } from './components/StatisticsPanel';

const App: React.FC = () => {
  // State Initialization with LocalStorage
  const [activeTab, setActiveTab] = useState<'dashboard' | 'active' | 'settled' | 'create' | 'stats'>('dashboard');

  const [slips, setSlips] = useState<Slip[]>(() => {
    const saved = localStorage.getItem('smartbet_slips');
    return saved ? JSON.parse(saved) : [];
  });

  const [theme, setTheme] = useState<'light' | 'dark'>(() => {
    return (localStorage.getItem('smartbet_theme') as 'light' | 'dark') || 'dark';
  });

  const [currency, setCurrency] = useState<Currency>(() => {
    return (localStorage.getItem('smartbet_currency') as Currency) || 'ZAR';
  });

  // Folder state
  const [selectedFolder, setSelectedFolder] = useState<string>('All');

  const [showSettings, setShowSettings] = useState(false);
  const [editingSlip, setEditingSlip] = useState<Slip | null>(null);

  const [stats, setStats] = useState<Stats>({
    totalSlips: 0,
    wins: 0,
    losses: 0,
    winRate: 0,
    totalStaked: 0,
    totalReturned: 0,
    profit: 0,
    roi: 0
  });

  // Derived state for unique folders
  const uniqueFolders = React.useMemo(() => {
    const folders = new Set<string>();
    slips.forEach(s => {
      if (s.folder) folders.add(s.folder);
    });
    return Array.from(folders).sort();
  }, [slips]);

  // Persist State
  useEffect(() => {
    localStorage.setItem('smartbet_slips', JSON.stringify(slips));
  }, [slips]);

  useEffect(() => {
    localStorage.setItem('smartbet_theme', theme);
    const root = window.document.documentElement;
    if (theme === 'dark') {
      root.classList.add('dark');
    } else {
      root.classList.remove('dark');
    }
  }, [theme]);

  useEffect(() => {
    localStorage.setItem('smartbet_currency', currency);
  }, [currency]);


  // Calculate Stats
  useEffect(() => {
    const settledSlips = slips.filter(s => s.status === SlipStatus.WON || s.status === SlipStatus.LOST);
    const totalSlips = settledSlips.length;
    const wins = settledSlips.filter(s => s.status === SlipStatus.WON).length;
    const losses = settledSlips.filter(s => s.status === SlipStatus.LOST).length;
    const winRate = totalSlips > 0 ? (wins / totalSlips) * 100 : 0;

    const totalStaked = slips.reduce((acc, s) => acc + s.stake, 0);
    const totalReturned = settledSlips
      .filter(s => s.status === SlipStatus.WON)
      .reduce((acc, s) => acc + s.potentialReturn, 0);

    const settledStaked = settledSlips.reduce((acc, s) => acc + s.stake, 0);
    const profit = totalReturned - settledStaked;
    const roi = settledStaked > 0 ? (profit / settledStaked) * 100 : 0;

    setStats({
      totalSlips,
      wins,
      losses,
      winRate,
      totalStaked,
      totalReturned,
      profit,
      roi
    });
  }, [slips]);

  const handleSaveSlip = (savedSlip: Slip) => {
    const exists = slips.some(s => s.id === savedSlip.id);
    if (exists) {
      setSlips(slips.map(s => s.id === savedSlip.id ? savedSlip : s));
    } else {
      setSlips([savedSlip, ...slips]);
    }
    setEditingSlip(null);
    setActiveTab('active');
  };

  const handleUpdateSlip = (updatedSlip: Slip) => {
    setSlips(slips.map(s => s.id === updatedSlip.id ? updatedSlip : s));
  };

  const handleEditSlip = (slip: Slip) => {
    setEditingSlip(slip);
    setActiveTab('create');
  };

  const handleResetStats = () => {
    if (confirm("Are you sure you want to delete all betting history? This cannot be undone.")) {
      setSlips([]);
      setShowSettings(false);
    }
  };

  const handleRenameFolder = (oldName: string, newName: string) => {
    const trimmed = newName.trim();
    if (!trimmed || trimmed === oldName) return;

    if (uniqueFolders.includes(trimmed)) {
      if (!confirm(`Folder "${trimmed}" already exists. Do you want to merge "${oldName}" into it?`)) {
        return;
      }
    }

    setSlips(slips.map(s => s.folder === oldName ? { ...s, folder: trimmed } : s));
    if (selectedFolder === oldName) setSelectedFolder(trimmed);
  };

  const handleDeleteFolder = (folderName: string) => {
    if (confirm(`Are you sure you want to delete folder "${folderName}"? The bets will remain but will be ungrouped.`)) {
      setSlips(slips.map(s => s.folder === folderName ? { ...s, folder: undefined } : s));
      if (selectedFolder === folderName) setSelectedFolder('All');
    }
  };

  // Filter Slips based on status AND selected folder
  const activeSlips = slips.filter(s => 
    s.status === SlipStatus.PENDING && 
    (selectedFolder === 'All' || s.folder === selectedFolder)
  );

  const settledSlips = slips.filter(s => 
    s.status !== SlipStatus.PENDING && 
    (selectedFolder === 'All' || s.folder === selectedFolder)
  );

  const filteredSlipsForOverview = slips.filter(s => 
    selectedFolder === 'All' || s.folder === selectedFolder
  );

  return (
    <div className="min-h-screen bg-background pb-20 md:pb-0 transition-colors duration-300">
      {/* Top Navigation / Header */}
      <header className="bg-surface border-b border-borderBase sticky top-0 z-10 transition-colors">
        <div className="max-w-5xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
             <div className="bg-primary p-1.5 rounded-lg">
               <TrendingUp className="text-white" size={20} />
             </div>
             <h1 className="text-xl font-bold text-textMain tracking-tight">SmartBet<span className="text-primary">Tracker</span></h1>
          </div>
          <div className="hidden md:flex items-center gap-1 bg-inputBg p-1 rounded-lg border border-borderBase">
             <NavButton active={activeTab === 'dashboard'} onClick={() => setActiveTab('dashboard')} icon={LayoutDashboard} label="Overview" />
             <NavButton active={activeTab === 'active'} onClick={() => setActiveTab('active')} icon={Wallet} label="Active" badge={slips.filter(s => s.status === SlipStatus.PENDING).length} />
             <NavButton active={activeTab === 'stats'} onClick={() => setActiveTab('stats')} icon={BarChart3} label="Analytics" />
             <NavButton active={activeTab === 'settled'} onClick={() => setActiveTab('settled')} icon={History} label="History" />
          </div>
          <div className="flex gap-2">
            <button 
              onClick={() => setShowSettings(true)}
              className="p-2 rounded-lg text-textMuted hover:text-textMain hover:bg-inputBg transition-colors"
            >
              <SettingsIcon size={20} />
            </button>
            <button 
              onClick={() => { setEditingSlip(null); setActiveTab('create'); }}
              className="bg-primary hover:bg-blue-600 text-white px-4 py-2 rounded-lg text-sm font-bold flex items-center gap-2 transition-colors shadow-lg shadow-blue-500/20"
            >
              <PlusCircle size={18} /> <span className="hidden sm:inline">New Bet</span>
            </button>
          </div>
        </div>
      </header>

      {/* Settings Modal */}
      {showSettings && (
        <div className="fixed inset-0 z-50 bg-background/80 backdrop-blur-sm flex items-center justify-center p-4 animate-fade-in">
          <div className="bg-surface border border-borderBase rounded-xl shadow-2xl w-full max-w-md overflow-hidden max-h-[90vh] flex flex-col">
            <div className="p-4 border-b border-borderBase flex justify-between items-center bg-inputBg">
               <h3 className="font-bold text-textMain flex items-center gap-2">
                 <SettingsIcon size={18} className="text-primary" /> Settings
               </h3>
               <button onClick={() => setShowSettings(false)} className="text-textMuted hover:text-textMain">
                 <X size={20} />
               </button>
            </div>
            <div className="p-6 space-y-6 overflow-y-auto">
               {/* Theme Toggle */}
               <div className="flex items-center justify-between">
                 <span className="text-textMain font-medium">Appearance</span>
                 <div className="flex bg-inputBg rounded-lg p-1 border border-borderBase">
                    <button 
                      onClick={() => setTheme('light')}
                      className={`p-2 rounded flex items-center gap-2 text-xs font-bold transition-all ${theme === 'light' ? 'bg-surface shadow text-primary' : 'text-textMuted'}`}
                    >
                      <Sun size={14} /> Light
                    </button>
                    <button 
                      onClick={() => setTheme('dark')}
                      className={`p-2 rounded flex items-center gap-2 text-xs font-bold transition-all ${theme === 'dark' ? 'bg-surface shadow text-primary' : 'text-textMuted'}`}
                    >
                      <Moon size={14} /> Dark
                    </button>
                 </div>
               </div>

               {/* Currency Select */}
               <div className="flex items-center justify-between">
                 <span className="text-textMain font-medium">Currency</span>
                 <select 
                   value={currency}
                   onChange={(e) => setCurrency(e.target.value as Currency)}
                   className="bg-inputBg border border-borderBase rounded-lg px-3 py-1.5 text-textMain text-sm focus:outline-none focus:border-primary"
                 >
                   <option value="ZAR">ZAR (R)</option>
                   <option value="USD">USD ($)</option>
                   <option value="GBP">GBP (£)</option>
                 </select>
               </div>

               {/* Folder Management */}
               <div className="space-y-3 pt-2 border-t border-borderBase">
                  <span className="text-textMain font-medium flex items-center gap-2">
                    <FolderOpen size={16} /> Manage Folders
                  </span>
                  <div className="bg-background/50 rounded-lg border border-borderBase p-2 max-h-48 overflow-y-auto space-y-2">
                    {uniqueFolders.length === 0 ? (
                      <p className="text-xs text-textMuted italic text-center py-2">No folders created yet.</p>
                    ) : (
                      uniqueFolders.map(folder => (
                        <FolderRow 
                          key={folder} 
                          name={folder} 
                          onRename={handleRenameFolder} 
                          onDelete={handleDeleteFolder} 
                        />
                      ))
                    )}
                  </div>
               </div>

               <div className="border-t border-borderBase pt-6">
                 <button 
                   onClick={handleResetStats}
