import { GoogleGenAI } from "@google/genai";
import { Slip, Leg, LegStatus, ValidationResult } from "../types";

// Initialize Gemini Client
const apiKey = process.env.API_KEY || '';
const ai = new GoogleGenAI({ apiKey });

export interface ValidationResponse {
  results: ValidationResult[];
  sources: string[];
}

export const validateSlipWithGemini = async (slip: Slip): Promise<ValidationResponse> => {
  if (!apiKey) {
    throw new Error("API Key is missing.");
  }

  // Construct a prompt that describes the bet slip
  const legsDescription = slip.legs.map(leg => 
    `- ID: ${leg.id} | Match: ${leg.matchName} | Date: ${leg.date} | Bet Type: ${leg.type} | Selection: ${leg.selection}`
  ).join('\n');

  const prompt = `
    I have a sports betting slip with the following matches and predictions. 
    Please search for the real-time match status and results using Google Search.

    CRITICAL EXECUTION RULES:
    1. **CHECK TIME/STATUS FIRST**: Identify "FT", "HT", "Live", or time markers (e.g. "65'").

    2. **EARLY SETTLEMENT (WON)**: 
       - If a "YES" or "OVER" condition is ALREADY met during live play, mark it as "WON".
       - Example: BTTS "Yes" is WON if the live score is 1-1. 
       - Example: Over 2.5 is WON if the live score is 2-1.
       - This applies to BTTS, Over/Under, Half Time BTTS, and Win Either Half.

    3. **HALF TIME SETTLEMENT**:
       - Any "1ST_HALF" market MUST be settled as "WON" or "LOST" as soon as the match reaches "HT" (Half Time) or beyond.
       - If the match is in the 2nd half and a 1st half condition (like 1st Half BTTS "Yes") was not met, it is "LOST".

    4. **PENDING STATUS**: 
       - A bet is "PENDING" only if the outcome is still undecided AND the relevant period (Half or Full Match) is still ongoing.
       - Example: Under 2.5 is "PENDING" if the score is 0-0 at 70'.
       - Example: 1X2 Winner is "PENDING" if the match is Live.

    5. **FINISHED MATCHES**:
       - Once "FT" (Full Time), all undecided bets for that match must be settled as "WON", "LOST", or "VOID".

    Bet Types Logic:
    - 1X2: Home (1), Draw (X), Away (2).
    - BTTS: Both teams scored > 0.
    - OVER_UNDER: "Over X.5" means total goals > X.5.
    - DRAW_NO_BET: Draw results in "VOID".
    - HANDICAP: Calculated by applying the spread to the final or current score.
    - WIN_EITHER_HALF: "Home" wins if Home won the 1st Half OR Home won the 2nd Half (scored more goals in that specific period).
    - 1ST_2ND_HALF_BTTS: Both halves must meet their specific BTTS condition.

    Bet Slip Details:
    ${legsDescription}

    IMPORTANT OUTPUT FORMAT:
    You must return the data in a raw JSON array format inside a code block, like this:
    \`\`\`json
    [
      { "legId": "...", "status": "WON", "score": "2-1" },
      { "legId": "...", "status": "PENDING", "score": "1-0 (65')" },
      { "legId": "...", "status": "LOST", "score": "0-0 (HT)" }
    ]
    \`\`\`
    Valid statuses: WON, LOST, VOID, PENDING.
    For score, include current time if live/HT (e.g. "1-1 (Live 82')").
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
      },
    });

    const text = response.text || '';

    // Extract Grounding Metadata (Sources)
    const sources: string[] = [];
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
    chunks.forEach(chunk => {
      if (chunk.web?.uri) {
        sources.push(chunk.web.uri);
      }
    });

    // Extract JSON from text
    const jsonMatch = text.match(/```json\s*([\s\S]*?)\s*```/) || text.match(/\[\s*\{[\s\S]*\}\s*\]/);

    if (!jsonMatch) {
      console.error("Failed to parse JSON from Gemini response:", text);
      throw new Error("AI could not format the results correctly. Please try again.");
    }

    const jsonString = jsonMatch[1] || jsonMatch[0];
    const results = JSON.parse(jsonString) as ValidationResult[];

    return { results, sources };

  } catch (error) {
    console.error("Gemini Validation Error:", error);
    throw error;
  }
};

