interface SlipCardProps {
  slip: Slip;
  onUpdate: (slip: Slip) => void;
  onEdit?: (slip: Slip) => void;
  symbol: string;
}

const SlipCard: React.FC<SlipCardProps> = ({ slip, onUpdate, onEdit, symbol }) => {
  const [expanded, setExpanded] = useState(false);
  const [checking, setChecking] = useState(false);
  const [checkingLegs, setCheckingLegs] = useState<Set<string>>(new Set());

  // Manual Settlement State
  const [isSettling, setIsSettling] = useState(false);
  const [editedLegs, setEditedLegs] = useState<Leg[]>([]);

  const getStatusColor = (status: SlipStatus | LegStatus) => {
    switch (status) {
      case 'WON': return 'text-success bg-success/10 border-success/20';
      case 'LOST': return 'text-danger bg-danger/10 border-danger/20';
      case 'VOID': return 'text-warning bg-warning/10 border-warning/20';
      default: return 'text-textMuted bg-inputBg border-borderBase';
    }
  };

  const getStatusIcon = (status: SlipStatus | LegStatus) => {
    switch (status) {
      case 'WON': return <Check size={16} />;
      case 'LOST': return <XCircle size={16} />;
      case 'PENDING': return <Clock size={16} />;
      case 'VOID': return <Ban size={16} />;
      default: return null;
    }
  };

  const calculateSlipStatus = (legs: Leg[]): SlipStatus => {
    if (legs.some(l => l.status === LegStatus.LOST)) return SlipStatus.LOST;
    if (legs.some(l => l.status === LegStatus.PENDING)) return SlipStatus.PENDING;
    if (legs.every(l => l.status === LegStatus.VOID)) return SlipStatus.VOID;
    return SlipStatus.WON;
  };

  const handleAICheck = async (e: React.MouseEvent) => {
    e.stopPropagation();
    if (checking || slip.status !== SlipStatus.PENDING) return;

    setChecking(true);
    try {
      const response = await validateSlipWithGemini(slip);

      const updatedLegs = slip.legs.map(leg => {
        const update = response.results.find(r => r.legId === leg.id);
        if (update) {
          return { ...leg, status: update.status, resultScore: update.score };
        }
        return leg;
      });

      const newStatus = calculateSlipStatus(updatedLegs);

      onUpdate({
        ...slip,
        legs: updatedLegs,
        status: newStatus,
        groundingUrls: response.sources
      });
    } catch (error) {
      alert("Failed to update matches via AI. Please try again.");
    } finally {
      setChecking(false);
    }
  };

  const handleLegAICheck = async (legId: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (checkingLegs.has(legId)) return;

    setCheckingLegs(prev => new Set(prev).add(legId));
    try {
      // Create a temporary slip with just this leg for focused AI check
      const legToCheck = slip.legs.find(l => l.id === legId);
      if (!legToCheck) return;

      const tempSlip: Slip = { ...slip, legs: [legToCheck] };
      const response = await validateSlipWithGemini(tempSlip);

      const update = response.results.find(r => r.legId === legId);
      if (update) {
        const updatedLegs = slip.legs.map(l => 
          l.id === legId ? { ...l, status: update.status, resultScore: update.score } : l
        );
        const newStatus = calculateSlipStatus(updatedLegs);

        // Merge grounding URLs
        const existingUrls = slip.groundingUrls || [];
        const newUrls = Array.from(new Set([...existingUrls, ...response.sources]));

        onUpdate({
          ...slip,
          legs: updatedLegs,
          status: newStatus,
          groundingUrls: newUrls
        });
      }
    } catch (error) {
      alert("Failed to check leg status. Please try again.");
    } finally {
      setCheckingLegs(prev => {
        const next = new Set(prev);
        next.delete(legId);
        return next;
      });
    }
  };

  const handleEditClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (onEdit) onEdit(slip);
  };

  // Manual Settlement Handlers
  const startSettling = (e: React.MouseEvent) => {
    e.stopPropagation();
    setEditedLegs([...slip.legs]);
    setIsSettling(true);
    setExpanded(true);
  };

  const cancelSettling = (e: React.MouseEvent) => {
    e.stopPropagation();
    setIsSettling(false);
    setEditedLegs([]);
  };

  const saveSettlement = (e: React.MouseEvent) => {
    e.stopPropagation();
    const newStatus = calculateSlipStatus(editedLegs);
    onUpdate({
      ...slip,
      legs: editedLegs,
      status: newStatus
    });
    setIsSettling(false);
  };

  const updateLegStatus = (legId: string, status: LegStatus) => {
    setEditedLegs(prev => prev.map(l => l.id === legId ? { ...l, status } : l));
  };

  const updateLegScore = (legId: string, score: string) => {
    setEditedLegs(prev => prev.map(l => l.id === legId ? { ...l, resultScore: score } : l));
  };

  return (
    <div className={`bg-surface rounded-xl border transition-all overflow-hidden ${slip.status === SlipStatus.WON ? 'border-success/30 shadow-success/5' : slip.status === SlipStatus.LOST ? 'border-danger/30' : 'border-borderBase'}`}>
      {/* Header */}
      <div 
        className="p-5 flex items-center justify-between cursor-pointer hover:bg-inputBg transition-colors"
        onClick={() => !isSettling && setExpanded(!expanded)}
      >
        <div className="flex items-center gap-4">
          <div className={`w-10 h-10 rounded-full flex items-center justify-center border ${getStatusColor(slip.status)}`}>
            {getStatusIcon(slip.status)}
          </div>
          <div>
             <div className="flex items-center gap-2 flex-wrap">
               <h4 className="font-bold text-textMain text-lg">
                 {slip.legs.length} Match Accumulator
               </h4>
               {slip.folder && (
                  <span className="flex items-center gap-1 text-[10px] font-bold text-textMuted uppercase tracking-wide bg-inputBg border border-borderBase px-2 py-0.5 rounded-full">
                    <Folder size={10} /> {slip.folder}
                  </span>
               )}
               <span className="text-xs text-textMuted font-mono">
                 {new Date(slip.createdAt).toLocaleDateString()}
               </span>
             </div>
             <p className="text-textMuted text-sm">
               Stake: <span className="text-textMain font-medium">{symbol}{slip.stake}</span> • 
               Odds: <span className="text-textMain font-medium">{slip.odds}</span> • 
               Return: <span className={`font-bold ${slip.status === 'WON' ? 'text-success' : 'text-primary'}`}>{symbol}{slip.potentialReturn.toFixed(2)}</span>
             </p>
          </div>
        </div>

        <div className="flex items-center gap-2">
          {isSettling ? (
            <div className="flex gap-2">
               <button 
                 onClick={cancelSettling}
                 className="p-2 rounded-lg bg-surface border border-borderBase text-textMuted hover:text-textMain hover:bg-inputBg transition-colors"
                 title="Cancel"
               >
                 <X size={18} />
               </button>
               <button 
                 onClick={saveSettlement}
                 className="px-4 py-2 rounded-lg bg-primary text-white font-bold flex items-center gap-2 hover:bg-blue-600 transition-colors shadow-lg shadow-blue-500/20"
                 title="Save Changes"
               >
                 <Save size={18} /> Save
               </button>
            </div>
          ) : (
            <div className="flex items-center gap-2">
              {/* Manual Settle Button - Available for all slips to correct errors */}
              <button 
                onClick={startSettling}
                className="p-2 rounded-lg text-textMuted hover:text-primary hover:bg-primary/10 transition-colors"
                title="Manual Settlement"
              >
                <Gavel size={16} />
              </button>

              {slip.status === SlipStatus.PENDING && (
                <>
                  {onEdit && (
                    <button 
                      onClick={handleEditClick}
                      className="p-2 rounded-lg text-textMuted hover:text-textMain hover:bg-surface border border-transparent hover:border-borderBase transition-all"
                      title="Edit Bet Slip"
                    >
                      <Pencil size={14} />
                    </button>
                  )}
                  <button 
                    onClick={handleAICheck}
                    disabled={checking}
                    className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs font-bold uppercase tracking-wide transition-all ${checking ? 'bg-inputBg text-textMuted' : 'bg-primary/20 text-primary hover:bg-primary/30'}`}
                  >
                    <RefreshCw size={14} className={checking ? "animate-spin" : ""} />
                    {checking ? 'Checking...' : 'Check All'}
                  </button>
                </>
              )}

              <div className="pl-2 border-l border-borderBase ml-2">
                {expanded ? <ChevronUp className="text-textMuted" size={20} /> : <ChevronDown className="text-textMuted" size={20} />}
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Expanded Content */}
      {expanded && (
        <div className="border-t border-borderBase bg-background/30 p-4">
          <div className="space-y-2">
             {(isSettling ? editedLegs : slip.legs).map((leg, idx) => (
                <div key={leg.id} className={`flex flex-col md:flex-row md:items-center justify-between p-3 rounded-lg border ${isSettling ? 'bg-surface border-primary/30 shadow-sm' : 'bg-inputBg border-borderBase'}`}>
                   <div className="flex-1 mb-3 md:mb-0">
                      <div className="flex justify-between items-start">
                         <h5 className="text-textMain font-medium">{leg.matchName}</h5>
                         {!isSettling && <span className="text-xs text-textMuted">{leg.date}</span>}
                      </div>
                      <div className="flex items-center gap-2 mt-1">
                         <span className="text-xs font-bold px-2 py-0.5 rounded bg-surface border border-borderBase text-textMuted">{leg.type}</span>
                         <span className="text-sm text-primary">Prediction: {leg.selection}</span>
                      </div>

                      {isSettling ? (
                         <div className="mt-3">
                           <label className="text-[10px] uppercase text-textMuted font-bold mb-1 block">Score / Result</label>
                           <input 
                             type="text" 
                             value={leg.resultScore || ''} 
                             onChange={(e) => updateLegScore(leg.id, e.target.value)}
                             placeholder="e.g. 2-1"
                             className="w-full md:w-48 bg-inputBg border border-borderBase rounded px-2 py-1 text-sm text-textMain"
                           />
                         </div>
                      ) : (
                        leg.resultScore && (
                          <div className="mt-2 text-xs text-textMuted font-mono flex items-center gap-1">
                            Final Score: <span className="text-textMain font-bold">{leg.resultScore}</span>
                          </div>
                        )
                      )}
                   </div>

                   <div className="ml-0 md:ml-4 flex items-center gap-3">
                      {!isSettling && (
                        <button 
                          onClick={(e) => handleLegAICheck(leg.id, e)}
                          disabled={checkingLegs.has(leg.id)}
                          className={`p-1.5 rounded-lg border transition-all ${checkingLegs.has(leg.id) ? 'bg-inputBg text-textMuted border-borderBase' : 'bg-surface border-borderBase text-textMuted hover:text-primary hover:border-primary/50'}`}
                          title="Verify this match"
                        >
                          <RefreshCw size={12} className={checkingLegs.has(leg.id) ? "animate-spin" : ""} />
                        </button>
                      )}

                      {isSettling ? (
                        <div className="flex gap-1 bg-inputBg p-1 rounded-lg border border-borderBase">
                          <button 
                             onClick={() => updateLegStatus(leg.id, LegStatus.WON)}
                             className={`p-1.5 rounded text-xs font-bold transition-colors ${leg.status === LegStatus.WON ? 'bg-success text-white shadow' : 'text-textMuted hover:bg-background'}`}
                             title="Mark as Won"
                          >
                            <Check size={14} />
                          </button>
                          <button 
                             onClick={() => updateLegStatus(leg.id, LegStatus.LOST)}
                             className={`p-1.5 rounded text-xs font-bold transition-colors ${leg.status === LegStatus.LOST ? 'bg-danger text-white shadow' : 'text-textMuted hover:bg-background'}`}
                             title="Mark as Lost"
                          >
                            <XCircle size={14} />
                          </button>
                          <button 
                             onClick={() => updateLegStatus(leg.id, LegStatus.VOID)}
                             className={`p-1.5 rounded text-xs font-bold transition-colors ${leg.status === LegStatus.VOID ? 'bg-warning text-white shadow' : 'text-textMuted hover:bg-background'}`}
                             title="Mark as Void"
                          >
                            <Ban size={14} />
                          </button>
                          <button 
                             onClick={() => updateLegStatus(leg.id, LegStatus.PENDING)}
                             className={`p-1.5 rounded text-xs font-bold transition-colors ${leg.status === LegStatus.PENDING ? 'bg-surface text-textMain shadow' : 'text-textMuted hover:bg-background'}`}
                             title="Mark as Pending"
                          >
                            <Clock size={14} />
                          </button>
                        </div>
                      ) : (
                        <span className={`text-xs font-bold px-2 py-1 rounded border min-w-[70px] text-center ${getStatusColor(leg.status)}`}>
                          {leg.status}
                        </span>
                      )}
                   </div>
                </div>
             ))}
          </div>

          {/* Grounding Sources (Only show in view mode) */}
          {!isSettling && slip.groundingUrls && slip.groundingUrls.length > 0 && (
            <div className="mt-4 pt-4 border-t border-borderBase">
               <h6 className="text-xs font-bold text-textMuted uppercase tracking-wider mb-2 flex items-center gap-1">
                 <ExternalLink size={10} /> Verified Sources
               </h6>
               <div className="flex flex-wrap gap-2">
                  {slip.groundingUrls.map((url, i) => (
                    <a 
                      key={i} 
                      href={url} 
                      target="_blank" 
                      rel="noopener noreferrer"
                      className="text-xs text-primary hover:underline truncate max-w-xs"
                    >
                      Source {i+1}
                    </a>
                  ))}
               </div>
            </div>
          )}

          {isSettling && (
            <div className="mt-4 pt-4 border-t border-borderBase text-center text-xs text-textMuted">
              Adjusting leg statuses will automatically recalculate the overall slip status.
            </div>
          )}
        </div>
      )}
    </div>
  );
};

import { GoogleGenAI } from "@google/genai";
import { Slip, Leg, LegStatus, ValidationResult } from "../types";

// Initialize Gemini Client
const apiKey = process.env.API_KEY || '';
const ai = new GoogleGenAI({ apiKey });

export interface ValidationResponse {
  results: ValidationResult[];
  sources: string[];
}

/**
 * Validates bet slip legs using Gemini 3 Pro with Google Search grounding.
 * Refined for higher accuracy in team mapping and complex market settlement.
 */
export const validateSlipWithGemini = async (slip: Slip): Promise<ValidationResponse> => {
  if (!apiKey) {
    throw new Error("API Key is missing.");
  }

  // Construct a clear description of the matches to minimize ambiguity
  const legsDescription = slip.legs.map(leg => {
    const parts = leg.matchName.split(/\s+v\s+|\s+vs\.?\s+|\s+-\s+/i);
    const homeTeam = parts[0]?.trim() || 'Home Team';
    const awayTeam = parts[1]?.trim() || 'Away Team';

    return `- ID: ${leg.id} 
  Match: ${leg.matchName} (Home: "${homeTeam}", Away: "${awayTeam}")
  Date: ${leg.date} 
  Market: ${leg.type} 
  Selection: ${leg.selection}`;
  }).join('\n\n');

  const prompt = `
    You are a professional sports data analyst and betting settlement expert. 
    Your task is to verify the results of the following bet selections using Google Search.

    ACCURACY REQUIREMENTS:
    1. **Identify Teams Correctly**: Use the "Home" and "Away" team hints provided. Search for the specific match on the given date.
    2. **Period-Specific Scoring**: 
       - For "Half Time" markets, look specifically for the score at the 45th minute (plus injury time).
       - For "Win Either Half", you must check if (Home Goals > Away Goals) occurred in the 1st half OR if (Home Goals > Away Goals) occurred in the 2nd half independently.
    3. **Early Settlement (Efficiency)**:
       - If a "YES" or "OVER" condition is mathematically guaranteed by the current live score, mark as "WON" immediately.
       - If a "NO" or "UNDER" condition is mathematically impossible to hit given the current score, mark as "LOST".
    4. **VOID Conditions**: Mark as "VOID" if the match is postponed, cancelled, or if a "Draw No Bet" selection results in a draw.

    SETTLEMENT LOGIC:
    - **1X2**: Standard match winner at FT.
    - **BTTS**: Both teams scored at least 1 goal.
    - **OVER_UNDER**: Total goals exceeds the decimal line.
    - **DOUBLE_CHANCE**: 1X (Home/Draw), X2 (Away/Draw), 12 (Home/Away).
    - **HANDICAP**: Apply the numeric handicap to the score.
    - **WIN_EITHER_HALF**: True if the selected team "wins" the 1st half (e.g. 1-0 at HT) OR "wins" the 2nd half (e.g. 1-1 at HT but 1-2 at FT means Away won the 2nd half 0-1).

    BET SLIP SELECTIONS:
    ${legsDescription}

    OUTPUT INSTRUCTIONS:
    - Search for reliable sources like Flashscore, ESPN, BBC Sport, or official league sites.
    - Return a JSON array of results.
    - Include the "score" with context, e.g., "2-1 (FT)", "1-0 (HT)", "0-0 (Live 22')", "Postponed".

    \`\`\`json
    [
      { "legId": "...", "status": "WON", "score": "...", "reason": "Brief explanation of result" },
      ...
    ]
    \`\`\`
    Valid statuses: WON, LOST, VOID, PENDING.
  `;

  try {
    // Using gemini-3-pro-preview for complex reasoning over search results
    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        temperature: 0, // Lower temperature for more deterministic/accurate factual extraction
      },
    });

    const text = response.text || '';

    // Extract Grounding Metadata (Sources)
    const sources: string[] = [];
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
    chunks.forEach(chunk => {
      if (chunk.web?.uri) {
        sources.push(chunk.web.uri);
      }
    });

    // Extract JSON from text
    const jsonMatch = text.match(/```json\s*([\s\S]*?)\s*```/) || text.match(/\[\s*\{[\s\S]*\}\s*\]/);

    if (!jsonMatch) {
      console.error("AI Response non-JSON:", text);
      throw new Error("AI could not extract structured results. Check your connection.");
    }

    const jsonString = jsonMatch[1] || jsonMatch[0];
    const results = JSON.parse(jsonString) as ValidationResult[];

    return { results, sources };

  } catch (error) {
    console.error("Gemini Validation Error:", error);
    throw error;
  }
};

import React, { useState, useEffect } from 'react';
import { ChevronDown, ChevronUp, RefreshCw, Trophy, XCircle, Clock, Check, ExternalLink, Pencil, Gavel, Save, X, Ban, Folder, Info } from 'lucide-react';
import { Slip, SlipStatus, Leg, LegStatus, Currency, CURRENCY_SYMBOLS } from '../types';
import { validateSlipWithGemini } from '../services/geminiService';

interface SlipListProps {
  slips: Slip[];
  onUpdateSlip: (updatedSlip: Slip) => void;
  onEditSlip?: (slip: Slip) => void;
  currency: Currency;
}

export const SlipList: React.FC<SlipListProps> = ({ slips, onUpdateSlip, onEditSlip, currency }) => {
  const symbol = CURRENCY_SYMBOLS[currency];

  if (slips.length === 0) {
    return (
      <div className="text-center py-20 bg-surface rounded-xl border border-borderBase">
        <div className="inline-block p-4 rounded-full bg-inputBg mb-4">
          <Trophy className="text-textMuted" size={32} />
        </div>
        <h3 className="text-lg font-medium text-textMain">No bets found</h3>
        <p className="text-textMuted">Create a new bet slip to get started.</p>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {slips.map(slip => (
        <SlipCard key={slip.id} slip={slip} onUpdate={onUpdateSlip} onEdit={onEditSlip} symbol={symbol} />
      ))}
    </div>
  );
};

interface SlipCardProps {
  slip: Slip;
  onUpdate: (slip: Slip) => void;
  onEdit?: (slip: Slip) => void;
  symbol: string;
}

const SlipCard: React.FC<SlipCardProps> = ({ slip, onUpdate, onEdit, symbol }) => {
  const [expanded, setExpanded] = useState(false);
  const [checking, setChecking] = useState(false);
  const [checkingLegs, setCheckingLegs] = useState<Set<string>>(new Set());

  // Manual Settlement State
  const [isSettling, setIsSettling] = useState(false);
  const [editedLegs, setEditedLegs] = useState<Leg[]>([]);

  const getStatusColor = (status: SlipStatus | LegStatus) => {
    switch (status) {
      case 'WON': return 'text-success bg-success/10 border-success/20';
      case 'LOST': return 'text-danger bg-danger/10 border-danger/20';
      case 'VOID': return 'text-warning bg-warning/10 border-warning/20';
      default: return 'text-textMuted bg-inputBg border-borderBase';
    }
  };

  const getStatusIcon = (status: SlipStatus | LegStatus) => {
    switch (status) {
      case 'WON': return <Check size={16} />;
      case 'LOST': return <XCircle size={16} />;
      case 'PENDING': return <Clock size={16} />;
      case 'VOID': return <Ban size={16} />;
      default: return null;
    }
  };

  const calculateSlipStatus = (legs: Leg[]): SlipStatus => {
    if (legs.some(l => l.status === LegStatus.LOST)) return SlipStatus.LOST;
    if (legs.some(l => l.status === LegStatus.PENDING)) return SlipStatus.PENDING;
    if (legs.every(l => l.status === LegStatus.VOID)) return SlipStatus.VOID;
    return SlipStatus.WON;
  };

  const handleAICheck = async (e: React.MouseEvent) => {
    e.stopPropagation();
    // Only check if slip is pending or some legs are pending
    const pendingLegs = slip.legs.filter(l => l.status === LegStatus.PENDING);
    if (checking || (slip.status !== SlipStatus.PENDING && pendingLegs.length === 0)) return;

    setChecking(true);
    try {
      // Efficiency: Only send pending legs to AI for checking
      const slipWithOnlyPending = { ...slip, legs: pendingLegs };
      const response = await validateSlipWithGemini(slipWithOnlyPending);

      const updatedLegs = slip.legs.map(leg => {
        const update = response.results.find(r => r.legId === leg.id);
        if (update) {
          // Preserve notes/other fields, update status, score, and potentially a reason
          return { 
            ...leg, 
            status: update.status, 
            resultScore: update.score,
            notes: (update as any).reason || leg.notes 
          };
        }
        return leg;
      });

      const newStatus = calculateSlipStatus(updatedLegs);

      onUpdate({
        ...slip,
        legs: updatedLegs,
        status: newStatus,
        groundingUrls: Array.from(new Set([...(slip.groundingUrls || []), ...response.sources]))
      });
    } catch (error) {
      console.error(error);
      alert("Failed to update matches via AI. Please try again.");
    } finally {
      setChecking(false);
    }
  };

  const handleLegAICheck = async (legId: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (checkingLegs.has(legId)) return;

    setCheckingLegs(prev => new Set(prev).add(legId));
    try {
      const legToCheck = slip.legs.find(l => l.id === legId);
      if (!legToCheck) return;

      const tempSlip: Slip = { ...slip, legs: [legToCheck] };
      const response = await validateSlipWithGemini(tempSlip);

      const update = response.results.find(r => r.legId === legId);
      if (update) {
        const updatedLegs = slip.legs.map(l => 
          l.id === legId ? { 
            ...l, 
            status: update.status, 
            resultScore: update.score,
            notes: (update as any).reason || l.notes 
          } : l
        );
        const newStatus = calculateSlipStatus(updatedLegs);

        onUpdate({
          ...slip,
          legs: updatedLegs,
          status: newStatus,
          groundingUrls: Array.from(new Set([...(slip.groundingUrls || []), ...response.sources]))
        });
      }
    } catch (error) {
      alert("Failed to check leg status.");
    } finally {
      setCheckingLegs(prev => {
        const next = new Set(prev);
        next.delete(legId);
        return next;
      });
    }
  };

  const handleEditClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (onEdit) onEdit(slip);
  };

  const startSettling = (e: React.MouseEvent) => {
    e.stopPropagation();
    setEditedLegs([...slip.legs]);
    setIsSettling(true);
    setExpanded(true);
  };

  const cancelSettling = (e: React.MouseEvent) => {
    e.stopPropagation();
    setIsSettling(false);
    setEditedLegs([]);
  };

  const saveSettlement = (e: React.MouseEvent) => {
    e.stopPropagation();
    const newStatus = calculateSlipStatus(editedLegs);
    onUpdate({
      ...slip,
      legs: editedLegs,
      status: newStatus
    });
    setIsSettling(false);
  };

  const updateLegStatus = (legId: string, status: LegStatus) => {
    setEditedLegs(prev => prev.map(l => l.id === legId ? { ...l, status } : l));
  };

  const updateLegScore = (legId: string, score: string) => {
