                          <button onClick={() => updateLegStatus(leg.id, LegStatus.VOID)} className={`p-1.5 rounded text-xs font-bold transition-colors ${leg.status === LegStatus.VOID ? 'bg-warning text-white shadow' : 'text-textMuted hover:bg-background'}`}><Ban size={14} /></button>
                          <button onClick={() => updateLegStatus(leg.id, LegStatus.PENDING)} className={`p-1.5 rounded text-xs font-bold transition-colors ${leg.status === LegStatus.PENDING ? 'bg-surface text-textMain shadow' : 'text-textMuted hover:bg-background'}`}><Clock size={14} /></button>
                        </div>
                      ) : (
