          )}
        </div>
      )}
    </div>
  );
};

import { GoogleGenAI } from "@google/genai";
import { Slip, Leg, LegStatus, ValidationResult } from "../types";

// Initialize Gemini Client
const apiKey = process.env.API_KEY || '';
const ai = new GoogleGenAI({ apiKey });

export interface ValidationResponse {
  results: ValidationResult[];
  sources: string[];
}

/**
 * Validates bet slip legs using Gemini 3 Flash for maximum speed.
 * Uses a highly optimized prompt for rapid sports data extraction.
 */
export const validateSlipWithGemini = async (slip: Slip): Promise<ValidationResponse> => {
  if (!apiKey) {
    throw new Error("API Key is missing.");
  }

  // Construct a concise description to save tokens and speed up inference
  const legsDescription = slip.legs.map(leg => {
    const parts = leg.matchName.split(/\s+v\s+|\s+vs\.?\s+|\s+-\s+/i);
    const home = parts[0]?.trim() || 'Home';
    const away = parts[1]?.trim() || 'Away';

    return `ID:${leg.id}|Match:${home} vs ${away}|Date:${leg.date}|Market:${leg.type}|Selection:${leg.selection}`;
  }).join('\n');

  const prompt = `
    Find scores for these football/sports matches. Be extremely fast and direct.

    RULES:
    1. Search for: "[Home Team] vs [Away Team] result [Date]".
    2. Identify if status is FT (Full Time), HT (Half Time), Live (include minute), or Postponed.
    3. Determine if the selection WON, LOST, VOID, or is PENDING.
    4. Market Logic:
       - 1X2: Final result.
       - BTTS: Both scored? (Yes/No).
       - OVER_UNDER: Total goals > line?
       - WIN_EITHER_HALF: Did selection score more than opponent in either 45min period?
       - HALF_TIME: Result exactly at HT.

    INPUTS:
    ${legsDescription}

    OUTPUT ONLY JSON ARRAY:
    \`\`\`json
    [
      { "legId": "...", "status": "WON|LOST|VOID|PENDING", "score": "X-Y (Status)", "reason": "Quick fact" }
    ]
    \`\`\`
  `;

  try {
    // Switching back to flash for speed as requested
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        temperature: 0,
      },
    });

    const text = response.text || '';

    // Extract Grounding Metadata (Sources) - We still collect them but won't show them in UI
    const sources: string[] = [];
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
    chunks.forEach(chunk => {
      if (chunk.web?.uri) {
        sources.push(chunk.web.uri);
      }
    });

    const jsonMatch = text.match(/```json\s*([\s\S]*?)\s*```/) || text.match(/\[\s*\{[\s\S]*\}\s*\]/);

    if (!jsonMatch) {
      throw new Error("No structured results found.");
    }

    const jsonString = jsonMatch[1] || jsonMatch[0];
    const results = JSON.parse(jsonString) as ValidationResult[];

    return { results, sources };

  } catch (error) {
    console.error("Gemini Validation Error:", error);
    throw error;
  }
};

import React, { useState, useEffect } from 'react';
import { ChevronDown, ChevronUp, RefreshCw, Trophy, XCircle, Clock, Check, Pencil, Gavel, Save, X, Ban, Folder, Info } from 'lucide-react';
