interface SlipCardProps {
  slip: Slip;
  onUpdate: (slip: Slip) => void;
  onEdit?: (slip: Slip) => void;
  symbol: string;
}

const SlipCard: React.FC<SlipCardProps> = ({ slip, onUpdate, onEdit, symbol }) => {
  const [expanded, setExpanded] = useState(false);
  const [checking, setChecking] = useState(false);
  const [checkingLegs, setCheckingLegs] = useState<Set<string>>(new Set());

  const [isSettling, setIsSettling] = useState(false);
  const [editedLegs, setEditedLegs] = useState<Leg[]>([]);

  const getStatusColor = (status: SlipStatus | LegStatus) => {
    switch (status) {
      case 'WON': return 'text-success bg-success/10 border-success/20';
      case 'LOST': return 'text-danger bg-danger/10 border-danger/20';
      case 'VOID': return 'text-warning bg-warning/10 border-warning/20';
      default: return 'text-textMuted bg-inputBg border-borderBase';
    }
  };

  const getStatusIcon = (status: SlipStatus | LegStatus) => {
    switch (status) {
      case 'WON': return <Check size={16} />;
      case 'LOST': return <XCircle size={16} />;
      case 'PENDING': return <Clock size={16} />;
      case 'VOID': return <Ban size={16} />;
      default: return null;
    }
  };

  const calculateSlipStatus = (legs: Leg[]): SlipStatus => {
    if (legs.some(l => l.status === LegStatus.LOST)) return SlipStatus.LOST;
    if (legs.some(l => l.status === LegStatus.PENDING)) return SlipStatus.PENDING;
    if (legs.every(l => l.status === LegStatus.VOID)) return SlipStatus.VOID;
    return SlipStatus.WON;
  };

  const handleAICheck = async (e: React.MouseEvent) => {
    e.stopPropagation();
    // We check both pending legs and any leg that has a result but might be "live" (non-FT)
    // though the new AI prompt should handle returning PENDING for non-FT results.
    if (checking || slip.legs.length === 0) return;

    setChecking(true);
    try {
      const response = await validateSlipWithGemini(slip);

      const updatedLegs = slip.legs.map(leg => {
        const update = response.results.find(r => r.legId === leg.id);
        if (update) {
          return { 
            ...leg, 
            status: update.status, 
            resultScore: update.score,
            notes: (update as any).reason || leg.notes 
          };
        }
        return leg;
      });

      const newStatus = calculateSlipStatus(updatedLegs);

      onUpdate({
        ...slip,
        legs: updatedLegs,
        status: newStatus,
        groundingUrls: Array.from(new Set([...(slip.groundingUrls || []), ...response.sources]))
      });
    } catch (error) {
      console.error(error);
      alert("Verification failed. Please try again.");
    } finally {
      setChecking(false);
    }
  };

  const handleLegAICheck = async (legId: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (checkingLegs.has(legId)) return;

    setCheckingLegs(prev => new Set(prev).add(legId));
    try {
      const legToCheck = slip.legs.find(l => l.id === legId);
      if (!legToCheck) return;

      const tempSlip: Slip = { ...slip, legs: [legToCheck] };
      const response = await validateSlipWithGemini(tempSlip);

      const update = response.results.find(r => r.legId === legId);
      if (update) {
        const updatedLegs = slip.legs.map(l => 
          l.id === legId ? { 
            ...l, 
            status: update.status, 
            resultScore: update.score,
            notes: (update as any).reason || l.notes 
          } : l
        );
        const newStatus = calculateSlipStatus(updatedLegs);

        onUpdate({
          ...slip,
          legs: updatedLegs,
          status: newStatus,
          groundingUrls: Array.from(new Set([...(slip.groundingUrls || []), ...response.sources]))
        });
      }
    } catch (error) {
      alert("Failed to fetch score.");
    } finally {
      setCheckingLegs(prev => {
        const next = new Set(prev);
        next.delete(legId);
        return next;
      });
    }
  };

  const startSettling = (e: React.MouseEvent) => {
    e.stopPropagation();
    setEditedLegs([...slip.legs]);
    setIsSettling(true);
    setExpanded(true);
  };

  const cancelSettling = (e: React.MouseEvent) => { e.stopPropagation(); setIsSettling(false); };

  const saveSettlement = (e: React.MouseEvent) => {
    e.stopPropagation();
    const newStatus = calculateSlipStatus(editedLegs);
    onUpdate({ ...slip, legs: editedLegs, status: newStatus });
    setIsSettling(false);
  };

  const updateLegStatus = (legId: string, status: LegStatus) => {
    setEditedLegs(prev => prev.map(l => l.id === legId ? { ...l, status } : l));
  };

  const updateLegScore = (legId: string, score: string) => {
    setEditedLegs(prev => prev.map(l => l.id === legId ? { ...l, resultScore: score } : l));
  };

  return (
    <div className={`bg-surface rounded-xl border transition-all overflow-hidden ${slip.status === SlipStatus.WON ? 'border-success/30 shadow-success/5' : slip.status === SlipStatus.LOST ? 'border-danger/30' : 'border-borderBase'}`}>
      <div 
        className="p-5 flex items-center justify-between cursor-pointer hover:bg-inputBg transition-colors"
        onClick={() => !isSettling && setExpanded(!expanded)}
      >
        <div className="flex items-center gap-4">
          <div className={`w-10 h-10 rounded-full flex items-center justify-center border ${getStatusColor(slip.status)}`}>
            {getStatusIcon(slip.status)}
          </div>
          <div>
             <div className="flex items-center gap-2 flex-wrap">
               <h4 className="font-bold text-textMain text-lg">
                 {slip.legs.length} Match Accumulator
               </h4>
               {slip.folder && (
                  <span className="flex items-center gap-1 text-[10px] font-bold text-textMuted uppercase tracking-wide bg-inputBg border border-borderBase px-2 py-0.5 rounded-full">
                    <Folder size={10} /> {slip.folder}
                  </span>
               )}
               <span className="text-xs text-textMuted font-mono">
                 {new Date(slip.createdAt).toLocaleDateString()}
               </span>
             </div>
             <p className="text-textMuted text-sm">
               Stake: <span className="text-textMain font-medium">{symbol}{slip.stake}</span> • 
               Odds: <span className="text-textMain font-medium">{slip.odds}</span> • 
               Return: <span className={`font-bold ${slip.status === 'WON' ? 'text-success' : 'text-primary'}`}>{symbol}{slip.potentialReturn.toFixed(2)}</span>
             </p>
          </div>
        </div>

        <div className="flex items-center gap-2">
          {isSettling ? (
            <div className="flex gap-2">
               <button onClick={cancelSettling} className="p-2 rounded-lg bg-surface border border-borderBase text-textMuted hover:text-textMain transition-colors"><X size={18} /></button>
               <button onClick={saveSettlement} className="px-4 py-2 rounded-lg bg-primary text-white font-bold flex items-center gap-2 hover:bg-blue-600 transition-colors shadow-lg"><Save size={18} /> Save</button>
            </div>
          ) : (
            <div className="flex items-center gap-2">
              <button onClick={startSettling} className="p-2 rounded-lg text-textMuted hover:text-primary hover:bg-primary/10 transition-colors" title="Manual Settlement"><Gavel size={16} /></button>
              {(slip.status === SlipStatus.PENDING || slip.legs.some(l => l.status === LegStatus.PENDING)) && (
                <button 
                  onClick={handleAICheck}
                  disabled={checking}
                  className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs font-bold uppercase tracking-wide transition-all ${checking ? 'bg-inputBg text-textMuted' : 'bg-primary/20 text-primary hover:bg-primary/30'}`}
                >
                  <RefreshCw size={14} className={checking ? "animate-spin" : ""} />
                  {checking ? 'Checking...' : 'Check All'}
                </button>
              )}
              {onEdit && <button onClick={(e) => { e.stopPropagation(); onEdit(slip); }} className="p-2 rounded-lg text-textMuted hover:text-textMain transition-all"><Pencil size={14} /></button>}
              <div className="pl-2 border-l border-borderBase ml-2">
                {expanded ? <ChevronUp className="text-textMuted" size={20} /> : <ChevronDown className="text-textMuted" size={20} />}
              </div>
            </div>
          )}
        </div>
      </div>

      {expanded && (
        <div className="border-t border-borderBase bg-background/30 p-4">
          <div className="space-y-2">
             {(isSettling ? editedLegs : slip.legs).map((leg) => {
                const isLive = leg.resultScore && !leg.resultScore.includes('FT') && !leg.resultScore.includes('PPD');

                return (
                  <div key={leg.id} className={`flex flex-col md:flex-row md:items-center justify-between p-3 rounded-lg border ${isSettling ? 'bg-surface border-primary/30 shadow-sm' : 'bg-inputBg border-borderBase'}`}>
                    <div className="flex-1 mb-3 md:mb-0">
                        <div className="flex justify-between items-start">
                          <h5 className="text-textMain font-medium">{leg.matchName}</h5>
                          {!isSettling && <span className="text-xs text-textMuted">{leg.date}</span>}
                        </div>
                        <div className="flex items-center gap-2 mt-1">
                          <span className="text-xs font-bold px-2 py-0.5 rounded bg-surface border border-borderBase text-textMuted">{leg.type}</span>
                          <span className="text-sm text-primary font-medium">Bet: {leg.selection}</span>
                        </div>

                        {isSettling ? (
                          <div className="mt-3">
                            <label className="text-[10px] uppercase text-textMuted font-bold mb-1 block">Manual Result (e.g. 2-1 FT)</label>
                            <input type="text" value={leg.resultScore || ''} onChange={(e) => updateLegScore(leg.id, e.target.value)} className="w-full md:w-48 bg-inputBg border border-borderBase rounded px-2 py-1 text-sm text-textMain" />
                          </div>
                        ) : (
                          <div className="flex flex-col gap-1 mt-2">
                            {leg.resultScore && (
                              <div className="flex items-center gap-2">
                                <span className={`text-xs font-mono font-bold px-2 py-0.5 rounded ${isLive ? 'bg-warning/20 text-warning animate-pulse' : 'bg-inputBg text-textMain'}`}>
                                  {isLive && <Activity size={10} className="inline mr-1" />}
                                  {leg.resultScore}
                                </span>
                              </div>
                            )}
                            {leg.notes && (
                              <div className="text-[10px] text-textMuted italic flex items-center gap-1">
                                <Info size={10} className="text-primary" /> {leg.notes}
                              </div>
                            )}
                          </div>
                        )}
                    </div>

                    <div className="ml-0 md:ml-4 flex items-center gap-3">
                        {!isSettling && (
                          <button 
                            onClick={(e) => handleLegAICheck(leg.id, e)}
                            disabled={checkingLegs.has(leg.id)}
                            className={`p-1.5 rounded-lg border transition-all ${checkingLegs.has(leg.id) ? 'bg-inputBg text-textMuted' : 'bg-surface hover:text-primary'}`}
                          >
                            <RefreshCw size={12} className={checkingLegs.has(leg.id) ? "animate-spin" : ""} />
                          </button>
                        )}

                        {isSettling ? (
                          <div className="flex gap-1 bg-inputBg p-1 rounded-lg border border-borderBase">
                            <button onClick={() => updateLegStatus(leg.id, LegStatus.WON)} className={`p-1.5 rounded ${leg.status === LegStatus.WON ? 'bg-success text-white' : 'text-textMuted'}`}><Check size={14} /></button>
                            <button onClick={() => updateLegStatus(leg.id, LegStatus.LOST)} className={`p-1.5 rounded ${leg.status === LegStatus.LOST ? 'bg-danger text-white' : 'text-textMuted'}`}><XCircle size={14} /></button>
                            <button onClick={() => updateLegStatus(leg.id, LegStatus.PENDING)} className={`p-1.5 rounded ${leg.status === LegStatus.PENDING ? 'bg-surface text-textMain' : 'text-textMuted'}`}><Clock size={14} /></button>
                          </div>
                        ) : (
                          <span className={`text-xs font-bold px-2 py-1 rounded border min-w-[70px] text-center ${getStatusColor(leg.status)}`}>
                            {leg.status}
                          </span>
                        )}
                    </div>
                  </div>
                );
             })}
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Plus, Trash2, Save, ClipboardPaste, X, Edit3, Folder, Globe } from 'lucide-react';
import { BetType, Leg, LegStatus, Slip, SlipStatus, Currency, CURRENCY_SYMBOLS } from '../types';

interface NewSlipFormProps {
  initialData?: Slip;
  onSave: (slip: Slip) => void;
  onCancel: () => void;
  currency: Currency;
  availableFolders: string[];
  availableLeagues: string[];
}

// Robust ID generator
const generateId = () => {
  return Date.now().toString(36) + Math.random().toString(36).substring(2, 9);
};

export const NewSlipForm: React.FC<NewSlipFormProps> = ({ initialData, onSave, onCancel, currency, availableFolders, availableLeagues }) => {
  const [stake, setStake] = useState<string>(() => {
    if (initialData) return initialData.stake.toString();
    const saved = localStorage.getItem('smartbet_draft_stake');
    return saved || '10';
  });

  const [totalOdds, setTotalOdds] = useState<string>(() => {
    if (initialData) return initialData.odds.toString();
    const saved = localStorage.getItem('smartbet_draft_odds');
    return saved || '1.00';
  });

  const [folder, setFolder] = useState<string>(() => {
    if (initialData) return initialData.folder || '';
    return '';
  });

  const [legs, setLegs] = useState<Leg[]>(() => {
    if (initialData) return initialData.legs;
    const saved = localStorage.getItem('smartbet_draft_legs');
    if (saved) return JSON.parse(saved);
    return [{
      id: generateId(),
      matchName: '',
      league: '',
      date: new Date().toISOString().split('T')[0],
      type: BetType.MATCH_WINNER,
      selection: 'Home',
      status: LegStatus.PENDING,
    }];
  });

  const [showImport, setShowImport] = useState(false);
  const [importText, setImportText] = useState('');

  const symbol = CURRENCY_SYMBOLS[currency];
  const isEditing = !!initialData;

  useEffect(() => {
    if (!isEditing) {
      localStorage.setItem('smartbet_draft_stake', stake);
      localStorage.setItem('smartbet_draft_odds', totalOdds);
      localStorage.setItem('smartbet_draft_legs', JSON.stringify(legs));
    }
  }, [stake, totalOdds, legs, isEditing]);

  const clearDraft = () => {
    localStorage.removeItem('smartbet_draft_stake');
    localStorage.removeItem('smartbet_draft_odds');
    localStorage.removeItem('smartbet_draft_legs');
  };

  const addLeg = () => {
    setLegs([
      ...legs,
      {
        id: generateId(),
        matchName: '',
        league: '',
        date: new Date().toISOString().split('T')[0],
        type: BetType.MATCH_WINNER,
        selection: 'Home',
        status: LegStatus.PENDING,
      }
    ]);
  };

  const removeLeg = (id: string) => {
    if (legs.length > 1) {
      setLegs(legs.filter(l => l.id !== id));
    }
  };

  const updateLeg = (id: string, field: keyof Leg, value: any) => {
    setLegs(legs.map(l => {
      if (l.id === id) {
        const updated = { ...l, [field]: value };
        if (field === 'type') {
           if (value === BetType.MATCH_WINNER) updated.selection = 'Home';
           if (value === BetType.BTTS) updated.selection = 'Yes';
           if (value === BetType.OVER_UNDER) updated.selection = 'Over 2.5';
           if (value === BetType.DOUBLE_CHANCE) updated.selection = '1X';
           if (value === BetType.DRAW_NO_BET) updated.selection = 'Home';
        }
        return updated;
      }
      return l;
    }));
  };

  const parseTeams = (matchName: string) => {
    const parts = matchName.split(/\s+v\s+|\s+vs\.?\s+|\s+-\s+/i);
    return {
      home: parts[0]?.trim() || 'Home',
      away: parts[1]?.trim() || 'Away'
    };
  };

  const handleNumericChange = (value: string, setter: (v: string) => void) => {
    if (value === '' || /^\d*\.?\d*$/.test(value)) {
      setter(value);
    }
  };

  const handleImport = () => {
    if (!importText.trim()) return;

    try {
      const lines = importText.split('\n').map(l => l.trim()).filter(l => l.length > 0);

      const newLegs: Leg[] = [];
      let calculatedOdds = 1;

      // Common pattern: 
      // Line 1: Selection (Home)
      // Line 2: Odds (1.50)
      // Line 3: Market (Match Winner)
      // Line 4: Match (Team A vs Team B)
      // Optional Line 5: Date

      let i = 0;
      while (i < lines.length) {
        // Look for odds-like number in the second or next position
        const selectionRaw = lines[i];
        const oddsRaw = lines[i+1];
        const marketRaw = lines[i+2];
        const matchRaw = lines[i+3];

        if (!selectionRaw || !oddsRaw || !marketRaw || !matchRaw) {
          i++;
          continue;
        }

        const oddsVal = parseFloat(oddsRaw.replace(/[^0-9.]/g, ''));
        if (isNaN(oddsVal)) {
           // If second line isn't odds, maybe format is different, skip one line and retry
           i++;
           continue;
        }

        let dateRaw = new Date().toISOString().split('T')[0];
        let consumedLines = 4;

        // Try to peek for date
        if (i + 4 < lines.length) {
          const potentialDate = lines[i+4];
          if (potentialDate.match(/\d{2}[/.-]\d{2}/) || potentialDate.toLowerCase().includes('today') || potentialDate.toLowerCase().includes('tomorrow')) {
             if (potentialDate.toLowerCase().includes('tomorrow')) {
               const d = new Date(); d.setDate(d.getDate() + 1);
               dateRaw = d.toISOString().split('T')[0];
             }
             consumedLines = 5;
          }
        }

        calculatedOdds *= oddsVal;

        // Intelligent mapping
        let type = BetType.MATCH_WINNER;
        let selection = 'Home';
        const mUpper = marketRaw.toUpperCase();
        const sUpper = selectionRaw.toUpperCase();
        const { home, away } = parseTeams(matchRaw);

        if (mUpper.includes('BOTH') || mUpper.includes('BTTS')) {
          type = BetType.BTTS;
          selection = sUpper.includes('YES') || sUpper === 'GG' ? 'Yes' : 'No';
        } else if (mUpper.includes('OVER') || mUpper.includes('UNDER') || mUpper.includes('TOTAL')) {
          type = BetType.OVER_UNDER;
          const match = selectionRaw.match(/(\d+\.?\d*)/);
          const val = match ? match[1] : '2.5';
          selection = `${sUpper.includes('UNDER') ? 'Under' : 'Over'} ${val}`;
        } else if (mUpper.includes('DOUBLE') || mUpper.includes('DC')) {
          type = BetType.DOUBLE_CHANCE;
          if (sUpper.includes('1X') || (sUpper.includes('HOME') && sUpper.includes('DRAW'))) selection = '1X';
          else if (sUpper.includes('X2') || (sUpper.includes('AWAY') && sUpper.includes('DRAW'))) selection = 'X2';
          else selection = '12';
        } else if (mUpper.includes('1X2') || mUpper.includes('WINNER') || mUpper.includes('RESULT')) {
          type = BetType.MATCH_WINNER;
          if (sUpper.includes(away.toUpperCase()) || sUpper === '2') selection = 'Away';
          else if (sUpper.includes('DRAW') || sUpper === 'X') selection = 'Draw';
          else selection = 'Home';
        }

        newLegs.push({
          id: generateId(),
          matchName: matchRaw,
          league: '',
          date: dateRaw,
          type,
          selection,
          status: LegStatus.PENDING
        });

        i += consumedLines;
      }

      if (newLegs.length > 0) {
        setLegs(newLegs);
        setTotalOdds(calculatedOdds.toFixed(2));
        setShowImport(false);
        setImportText('');
      } else {
        alert("Couldn't find valid bet selections. Ensure the format is Selection, Odds, Market, then Match name on separate lines.");
      }
    } catch (e) {
      alert("Error parsing bet slip.");
    }
  };

  const handleSave = () => {
    if (legs.some(l => !l.matchName)) {
      alert("Please enter a match name for all selections.");
      return;
    }
    const numStake = parseFloat(stake) || 0;
    const numOdds = parseFloat(totalOdds) || 1;
    const newSlip: Slip = {
      id: initialData ? initialData.id : generateId(),
      createdAt: initialData ? initialData.createdAt : Date.now(),
      legs,
      stake: numStake,
      odds: numOdds,
      potentialReturn: numStake * numOdds,
      status: initialData ? initialData.status : SlipStatus.PENDING,
      folder: folder.trim() || undefined
    };
    onSave(newSlip);
    clearDraft();
  };

  return (
    <div className="bg-surface rounded-xl shadow-xl border border-borderBase overflow-hidden relative transition-colors">
      <div className="p-6 border-b border-borderBase flex justify-between items-center bg-inputBg">
        <h2 className="text-xl font-bold text-textMain flex items-center gap-2">
          {isEditing ? <Edit3 className="text-primary" /> : <Plus className="text-primary" />} 
          {isEditing ? 'Edit Bet Slip' : 'Create New Bet Slip'}
        </h2>
        <div className="flex gap-2">
          {!isEditing && (
            <span className="text-[10px] uppercase tracking-wider font-bold text-success/80 border border-success/20 px-2 py-1 rounded-full flex items-center bg-success/5">
              Auto-Saved
            </span>
          )}
          <button 
            onClick={() => setShowImport(true)}
            className="text-xs flex items-center gap-1 bg-surface border border-borderBase hover:bg-background text-textMain px-3 py-1.5 rounded transition-colors"
          >
            <ClipboardPaste size={14} /> Import
          </button>
        </div>
      </div>

      <div className="p-6 space-y-6">
        <div className="bg-inputBg/50 p-4 rounded-lg border border-borderBase">
            <label className="text-sm font-medium text-textMain mb-2 flex items-center gap-2">
                <Folder size={16} className="text-primary" /> Betting Folder
            </label>
            <div className="relative">
                <input
                    type="text"
                    list="folders-list"
                    value={folder}
                    onChange={(e) => setFolder(e.target.value)}
                    placeholder="e.g. Accumulator, High Stakes..."
                    className="w-full bg-surface border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                />
                <datalist id="folders-list">
                    {availableFolders.map(f => <option key={f} value={f} />)}
                </datalist>
            </div>
        </div>

        <div className="space-y-4">
          <label className="text-sm font-medium text-textMuted uppercase tracking-wider">Match Selections</label>
          {legs.map((leg, index) => (
            <div key={leg.id} className="p-4 bg-background rounded-lg border border-borderBase hover:border-textMuted transition-colors space-y-4">
              <div className="grid grid-cols-1 md:grid-cols-12 gap-4">
                <div className="md:col-span-8 space-y-1">
                  <label className="text-xs text-textMuted font-bold uppercase">Match Name</label>
                  <input
                    type="text"
                    value={leg.matchName}
                    onChange={(e) => updateLeg(leg.id, 'matchName', e.target.value)}
                    placeholder="e.g. Man City vs Arsenal"
                    className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                  />
                </div>
                <div className="md:col-span-3 space-y-1">
                  <label className="text-xs text-textMuted font-bold uppercase">Date</label>
                  <input
                    type="date"
                    value={leg.date}
                    onChange={(e) => updateLeg(leg.id, 'date', e.target.value)}
                    className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                  />
                </div>
                <div className="md:col-span-1 flex items-end justify-center pb-1">
                  <button 
                    onClick={() => removeLeg(leg.id)}
                    disabled={legs.length === 1}
                    className="p-2 rounded hover:bg-danger/20 text-danger/80 transition-colors disabled:opacity-30"
                  >
                    <Trash2 size={18} />
                  </button>
                </div>
              </div>

              {/* League Selection - Structured like Market/Selection */}
              <div className="space-y-3 bg-inputBg/30 p-3 rounded-lg border border-borderBase/50">
                <div className="flex flex-col md:flex-row md:items-center gap-4">
                  <div className="flex-1 space-y-1">
                    <label className="text-xs text-textMuted font-bold uppercase flex items-center gap-1">
                      <Globe size={12} className="text-primary" /> League
                    </label>
                    <select
                      value={availableLeagues.includes(leg.league || '') ? (leg.league || '') : 'other'}
                      onChange={(e) => {
                        const val = e.target.value;
                        if (val !== 'other') updateLeg(leg.id, 'league', val);
                      }}
                      className="w-full bg-surface border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                    >
                      <option value="">Select League...</option>
                      {availableLeagues.map(l => <option key={l} value={l}>{l}</option>)}
                      <option value="other">Manual Entry...</option>
                    </select>
                  </div>

                  {(!availableLeagues.includes(leg.league || '') || leg.league === '') && (
                    <div className="flex-1 space-y-1">
                      <label className="text-xs text-textMuted font-bold uppercase">Manual League Name</label>
                      <input
                        type="text"
                        placeholder="Type league name..."
                        value={leg.league || ''}
                        onChange={(e) => updateLeg(leg.id, 'league', e.target.value)}
                        className="w-full bg-surface border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                      />
                    </div>
                  )}
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-xs text-textMuted font-bold uppercase">Market</label>
                  <select
                    value={leg.type}
                    onChange={(e) => updateLeg(leg.id, 'type', e.target.value)}
                    className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                  >
                    <optgroup label="Popular">
                      <option value={BetType.MATCH_WINNER}>1X2 (Full Time)</option>
                      <option value={BetType.BTTS}>BTTS</option>
                      <option value={BetType.OVER_UNDER}>Over/Under Goals</option>
                      <option value={BetType.DOUBLE_CHANCE}>Double Chance</option>
                    </optgroup>
                    <optgroup label="Other Markets">
                      <option value={BetType.DRAW_NO_BET}>Draw No Bet</option>
                      <option value={BetType.HANDICAP}>Handicap</option>
                      <option value={BetType.WIN_EITHER_HALF}>Win Either Half</option>
                      <option value={BetType.TOTAL_CORNERS}>Total Corners</option>
                    </optgroup>
                  </select>
                </div>
                <div className="space-y-1">
                  <label className="text-xs text-textMuted font-bold uppercase">Selection</label>
                  <select
                    value={leg.selection}
                    onChange={(e) => updateLeg(leg.id, 'selection', e.target.value)}
                    className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                  >
                    {leg.type === BetType.MATCH_WINNER && (
                      <>
                        <option value="Home">Home Win (1)</option>
                        <option value="Draw">Draw (X)</option>
                        <option value="Away">Away Win (2)</option>
                      </>
                    )}
                    {leg.type === BetType.BTTS && (
                      <>
                        <option value="Yes">Yes</option>
                        <option value="No">No</option>
                      </>
                    )}
                    {leg.type === BetType.DOUBLE_CHANCE && (
                      <>
                        <option value="1X">1X (Home or Draw)</option>
                        <option value="X2">X2 (Away or Draw)</option>
                        <option value="12">12 (Home or Away)</option>
                      </>
                    )}
                    {leg.type === BetType.OVER_UNDER && (
                      <>
                        <option value="Over 2.5">Over 2.5</option>
                        <option value="Under 2.5">Under 2.5</option>
                        <option value="Over 1.5">Over 1.5</option>
                        <option value="Under 1.5">Under 1.5</option>
                        <option value="Over 3.5">Over 3.5</option>
                      </>
                    )}
                    {!([BetType.MATCH_WINNER, BetType.BTTS, BetType.DOUBLE_CHANCE, BetType.OVER_UNDER].includes(leg.type as BetType)) && (
                      <option value={leg.selection}>{leg.selection}</option>
                    )}
                  </select>
                </div>
              </div>
            </div>
          ))}

          <button 
            onClick={addLeg}
            className="w-full py-3 border border-dashed border-borderBase rounded-lg text-textMuted hover:text-textMain hover:bg-inputBg transition-all flex items-center justify-center gap-2"
          >
            <Plus size={18} /> Add Match
          </button>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 pt-6 border-t border-borderBase">
           <div className="space-y-1">
              <label className="text-xs font-bold text-textMuted uppercase">Stake ({symbol})</label>
              <input 
                type="text" 
                inputMode="decimal"
                value={stake}
                onChange={(e) => handleNumericChange(e.target.value, setStake)}
                className="w-full bg-inputBg border border-borderBase rounded px-4 py-3 text-textMain font-bold focus:outline-none focus:border-primary"
              />
           </div>
           <div className="space-y-1">
              <label className="text-xs font-bold text-textMuted uppercase">Total Odds</label>
              <input 
                type="text" 
                inputMode="decimal"
                value={totalOdds}
                onChange={(e) => handleNumericChange(e.target.value, setTotalOdds)}
                className="w-full bg-inputBg border border-borderBase rounded px-4 py-3 text-textMain font-bold focus:outline-none focus:border-primary"
              />
           </div>
        </div>

        <div className="bg-primary/10 rounded-lg p-4 flex justify-between items-center border border-primary/20">
          <span className="text-primary font-medium">Potential Return</span>
          <span className="text-2xl font-bold text-primary">
            {symbol}{((parseFloat(stake) || 0) * (parseFloat(totalOdds) || 0)).toFixed(2)}
          </span>
        </div>

        <div className="flex gap-4 justify-end pt-4">
          <button onClick={onCancel} className="px-6 py-3 text-textMuted hover:text-textMain">Cancel</button>
          <button 
            onClick={handleSave}
            className="px-8 py-3 rounded-lg font-bold bg-primary hover:bg-blue-600 text-white shadow-lg transition-all flex items-center gap-2"
          >
            <Save size={18} /> {isEditing ? 'Update Slip' : 'Save Bet Slip'}
          </button>
        </div>
      </div>

      {showImport && (
        <div className="fixed inset-0 z-[60] bg-background/95 flex items-center justify-center p-6 animate-fade-in">
           <div className="w-full max-w-lg bg-surface border border-borderBase rounded-xl p-6 shadow-2xl">
              <div className="flex justify-between items-center mb-4">
                 <h3 className="text-textMain font-bold flex items-center gap-2">
                   <ClipboardPaste size={18} className="text-primary" /> Import Selections
                 </h3>
                 <button onClick={() => setShowImport(false)} className="text-textMuted hover:text-textMain"><X size={20} /></button>
              </div>
              <p className="text-xs text-textMuted mb-4 italic">
                Format: Selection, Odds, Market, Match on separate lines.
              </p>
              <textarea
                value={importText}
                onChange={(e) => setImportText(e.target.value)}
                placeholder="Arsenal&#10;1.85&#10;Match Result&#10;Arsenal vs Liverpool&#10;---&#10;Over 2.5&#10;2.10&#10;Total Goals&#10;Chelsea vs Spurs"
                className="w-full h-64 bg-inputBg border border-borderBase rounded-lg p-4 text-xs font-mono text-textMain focus:outline-none focus:border-primary resize-none"
              />
              <div className="mt-4 flex justify-end gap-3">
                 <button onClick={() => setShowImport(false)} className="px-4 py-2 text-textMuted font-medium">Cancel</button>
                 <button 
                   onClick={handleImport} 
                   className="px-6 py-2 bg-primary text-white rounded-lg font-bold hover:bg-blue-600 transition-colors shadow-lg shadow-blue-500/20"
                 >
                   Process & Import
                 </button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Plus, Trash2, Save, ClipboardPaste, X, Edit3, Folder, Globe } from 'lucide-react';
import { BetType, Leg, LegStatus, Slip, SlipStatus, Currency, CURRENCY_SYMBOLS } from '../types';

interface NewSlipFormProps {
  initialData?: Slip;
  onSave: (slip: Slip) => void;
  onCancel: () => void;
  currency: Currency;
  availableFolders: string[];
  availableLeagues: string[];
}

// Robust ID generator
const generateId = () => {
  return Date.now().toString(36) + Math.random().toString(36).substring(2, 9);
};

export const NewSlipForm: React.FC<NewSlipFormProps> = ({ initialData, onSave, onCancel, currency, availableFolders, availableLeagues }) => {
  const [stake, setStake] = useState<string>(() => {
    if (initialData) return initialData.stake.toString();
    const saved = localStorage.getItem('smartbet_draft_stake');
    return saved || '10';
  });

  const [totalOdds, setTotalOdds] = useState<string>(() => {
    if (initialData) return initialData.odds.toString();
    const saved = localStorage.getItem('smartbet_draft_odds');
    return saved || '1.00';
  });

  const [folder, setFolder] = useState<string>(() => {
    if (initialData) return initialData.folder || '';
    return '';
  });

  const [legs, setLegs] = useState<Leg[]>(() => {
    if (initialData) return initialData.legs;
    const saved = localStorage.getItem('smartbet_draft_legs');
    if (saved) return JSON.parse(saved);
    return [{
      id: generateId(),
      matchName: '',
      league: '',
      date: new Date().toISOString().split('T')[0],
      type: BetType.MATCH_WINNER,
      selection: 'Home',
      status: LegStatus.PENDING,
    }];
  });

  const [showImport, setShowImport] = useState(false);
  const [importText, setImportText] = useState('');

  const symbol = CURRENCY_SYMBOLS[currency];
  const isEditing = !!initialData;

  useEffect(() => {
    if (!isEditing) {
      localStorage.setItem('smartbet_draft_stake', stake);
      localStorage.setItem('smartbet_draft_odds', totalOdds);
      localStorage.setItem('smartbet_draft_legs', JSON.stringify(legs));
    }
  }, [stake, totalOdds, legs, isEditing]);

  const clearDraft = () => {
    localStorage.removeItem('smartbet_draft_stake');
    localStorage.removeItem('smartbet_draft_odds');
    localStorage.removeItem('smartbet_draft_legs');
  };

  const addLeg = () => {
    setLegs([
      ...legs,
      {
        id: generateId(),
        matchName: '',
        league: '',
        date: new Date().toISOString().split('T')[0],
        type: BetType.MATCH_WINNER,
        selection: 'Home',
        status: LegStatus.PENDING,
      }
    ]);
  };

  const removeLeg = (id: string) => {
    if (legs.length > 1) {
      setLegs(legs.filter(l => l.id !== id));
    }
  };

  const updateLeg = (id: string, field: keyof Leg, value: any) => {
    setLegs(legs.map(l => {
      if (l.id === id) {
        const updated = { ...l, [field]: value };
        if (field === 'type') {
           if (value === BetType.MATCH_WINNER) updated.selection = 'Home';
           if (value === BetType.BTTS) updated.selection = 'Yes';
           if (value === BetType.OVER_UNDER) updated.selection = 'Over 2.5';
           if (value === BetType.DOUBLE_CHANCE) updated.selection = '1X';
           if (value === BetType.DRAW_NO_BET) updated.selection = 'Home';
           if (value === BetType.WIN_EITHER_HALF) updated.selection = 'Home';
        }
        return updated;
      }
      return l;
    }));
  };

  const parseTeams = (matchName: string) => {
    const parts = matchName.split(/\s+v\s+|\s+vs\.?\s+|\s+-\s+/i);
    return {
      home: parts[0]?.trim() || 'Home',
      away: parts[1]?.trim() || 'Away'
    };
  };

  const handleNumericChange = (value: string, setter: (v: string) => void) => {
    if (value === '' || /^\d*\.?\d*$/.test(value)) {
      setter(value);
    }
  };

  const handleImport = () => {
    if (!importText.trim()) return;

    try {
      const lines = importText.split('\n').map(l => l.trim()).filter(l => l.length > 0);

      const newLegs: Leg[] = [];
      let calculatedOdds = 1;

      // Common pattern: 
      // Line 1: Selection (Home)
      // Line 2: Odds (1.50)
      // Line 3: Market (Match Winner)
      // Line 4: Match (Team A vs Team B)
      // Optional Line 5: Date

      let i = 0;
      while (i < lines.length) {
        // Look for odds-like number in the second or next position
        const selectionRaw = lines[i];
        const oddsRaw = lines[i+1];
        const marketRaw = lines[i+2];
        const matchRaw = lines[i+3];

        if (!selectionRaw || !oddsRaw || !marketRaw || !matchRaw) {
          i++;
          continue;
        }

        const oddsVal = parseFloat(oddsRaw.replace(/[^0-9.]/g, ''));
        if (isNaN(oddsVal)) {
           // If second line isn't odds, maybe format is different, skip one line and retry
           i++;
           continue;
        }

        let dateRaw = new Date().toISOString().split('T')[0];
        let consumedLines = 4;

        // Try to peek for date
        if (i + 4 < lines.length) {
          const potentialDate = lines[i+4];
          if (potentialDate.match(/\d{2}[/.-]\d{2}/) || potentialDate.toLowerCase().includes('today') || potentialDate.toLowerCase().includes('tomorrow')) {
             if (potentialDate.toLowerCase().includes('tomorrow')) {
               const d = new Date(); d.setDate(d.getDate() + 1);
               dateRaw = d.toISOString().split('T')[0];
             }
             consumedLines = 5;
          }
        }

        calculatedOdds *= oddsVal;

        // Intelligent mapping
        let type = BetType.MATCH_WINNER;
        let selection = 'Home';
        const mUpper = marketRaw.toUpperCase();
        const sUpper = selectionRaw.toUpperCase();
        const { home, away } = parseTeams(matchRaw);

        if (mUpper.includes('BOTH') || mUpper.includes('BTTS')) {
          type = BetType.BTTS;
          selection = sUpper.includes('YES') || sUpper === 'GG' ? 'Yes' : 'No';
        } else if (mUpper.includes('OVER') || mUpper.includes('UNDER') || mUpper.includes('TOTAL')) {
          type = BetType.OVER_UNDER;
          const match = selectionRaw.match(/(\d+\.?\d*)/);
          const val = match ? match[1] : '2.5';
          selection = `${sUpper.includes('UNDER') ? 'Under' : 'Over'} ${val}`;
        } else if (mUpper.includes('DOUBLE') || mUpper.includes('DC')) {
          type = BetType.DOUBLE_CHANCE;
          if (sUpper.includes('1X') || (sUpper.includes('HOME') && sUpper.includes('DRAW'))) selection = '1X';
          else if (sUpper.includes('X2') || (sUpper.includes('AWAY') && sUpper.includes('DRAW'))) selection = 'X2';
          else selection = '12';
        } else if (mUpper.includes('1X2') || mUpper.includes('WINNER') || mUpper.includes('RESULT')) {
          type = BetType.MATCH_WINNER;
          if (sUpper.includes(away.toUpperCase()) || sUpper === '2') selection = 'Away';
          else if (sUpper.includes('DRAW') || sUpper === 'X') selection = 'Draw';
          else selection = 'Home';
        }

        newLegs.push({
          id: generateId(),
          matchName: matchRaw,
          league: '',
          date: dateRaw,
          type,
          selection,
          status: LegStatus.PENDING
        });

        i += consumedLines;
      }

      if (newLegs.length > 0) {
        setLegs(newLegs);
        setTotalOdds(calculatedOdds.toFixed(2));
        setShowImport(false);
        setImportText('');
      } else {
        alert("Couldn't find valid bet selections. Ensure the format is Selection, Odds, Market, then Match name on separate lines.");
      }
    } catch (e) {
      alert("Error parsing bet slip.");
    }
  };

  const handleSave = () => {
    if (legs.some(l => !l.matchName)) {
      alert("Please enter a match name for all selections.");
      return;
    }
    const numStake = parseFloat(stake) || 0;
    const numOdds = parseFloat(totalOdds) || 1;
    const newSlip: Slip = {
      id: initialData ? initialData.id : generateId(),
      createdAt: initialData ? initialData.createdAt : Date.now(),
      legs,
      stake: numStake,
      odds: numOdds,
      potentialReturn: numStake * numOdds,
      status: initialData ? initialData.status : SlipStatus.PENDING,
      folder: folder.trim() || undefined
    };
    onSave(newSlip);
    clearDraft();
  };

  return (
    <div className="bg-surface rounded-xl shadow-xl border border-borderBase overflow-hidden relative transition-colors">
      <div className="p-6 border-b border-borderBase flex justify-between items-center bg-inputBg">
        <h2 className="text-xl font-bold text-textMain flex items-center gap-2">
          {isEditing ? <Edit3 className="text-primary" /> : <Plus className="text-primary" />} 
          {isEditing ? 'Edit Bet Slip' : 'Create New Bet Slip'}
        </h2>
        <div className="flex gap-2">
          {!isEditing && (
            <span className="text-[10px] uppercase tracking-wider font-bold text-success/80 border border-success/20 px-2 py-1 rounded-full flex items-center bg-success/5">
              Auto-Saved
            </span>
          )}
          <button 
            onClick={() => setShowImport(true)}
            className="text-xs flex items-center gap-1 bg-surface border border-borderBase hover:bg-background text-textMain px-3 py-1.5 rounded transition-colors"
          >
            <ClipboardPaste size={14} /> Import
          </button>
        </div>
      </div>

      <div className="p-6 space-y-6">
        <div className="bg-inputBg/50 p-4 rounded-lg border border-borderBase">
            <label className="text-sm font-medium text-textMain mb-2 flex items-center gap-2">
                <Folder size={16} className="text-primary" /> Betting Folder
            </label>
            <div className="relative">
                <input
                    type="text"
                    list="folders-list"
                    value={folder}
                    onChange={(e) => setFolder(e.target.value)}
                    placeholder="e.g. Accumulator, High Stakes..."
                    className="w-full bg-surface border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                />
                <datalist id="folders-list">
                    {availableFolders.map(f => <option key={f} value={f} />)}
                </datalist>
            </div>
        </div>

        <div className="space-y-4">
          <label className="text-sm font-medium text-textMuted uppercase tracking-wider">Match Selections</label>
          {legs.map((leg, index) => (
            <div key={leg.id} className="p-4 bg-background rounded-lg border border-borderBase hover:border-textMuted transition-colors space-y-4">
              <div className="grid grid-cols-1 md:grid-cols-12 gap-4">
                <div className="md:col-span-8 space-y-1">
                  <label className="text-xs text-textMuted font-bold uppercase">Match Name</label>
                  <input
                    type="text"
                    value={leg.matchName}
                    onChange={(e) => updateLeg(leg.id, 'matchName', e.target.value)}
                    placeholder="e.g. Man City vs Arsenal"
                    className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                  />
                </div>
                <div className="md:col-span-3 space-y-1">
                  <label className="text-xs text-textMuted font-bold uppercase">Date</label>
                  <input
                    type="date"
                    value={leg.date}
                    onChange={(e) => updateLeg(leg.id, 'date', e.target.value)}
                    className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                  />
                </div>
                <div className="md:col-span-1 flex items-end justify-center pb-1">
                  <button 
                    onClick={() => removeLeg(leg.id)}
                    disabled={legs.length === 1}
                    className="p-2 rounded hover:bg-danger/20 text-danger/80 transition-colors disabled:opacity-30"
                  >
                    <Trash2 size={18} />
                  </button>
                </div>
              </div>

              {/* League Selection - Structured like Market/Selection */}
              <div className="space-y-3 bg-inputBg/30 p-3 rounded-lg border border-borderBase/50">
                <div className="flex flex-col md:flex-row md:items-center gap-4">
                  <div className="flex-1 space-y-1">
                    <label className="text-xs text-textMuted font-bold uppercase flex items-center gap-1">
                      <Globe size={12} className="text-primary" /> League
                    </label>
                    <select
                      value={availableLeagues.includes(leg.league || '') ? (leg.league || '') : 'other'}
                      onChange={(e) => {
                        const val = e.target.value;
                        if (val !== 'other') updateLeg(leg.id, 'league', val);
                      }}
                      className="w-full bg-surface border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                    >
                      <option value="">Select League...</option>
                      {availableLeagues.map(l => <option key={l} value={l}>{l}</option>)}
                      <option value="other">Manual Entry...</option>
                    </select>
                  </div>

                  {(!availableLeagues.includes(leg.league || '') || leg.league === '') && (
                    <div className="flex-1 space-y-1">
                      <label className="text-xs text-textMuted font-bold uppercase">Manual League Name</label>
                      <input
                        type="text"
                        placeholder="Type league name..."
                        value={leg.league || ''}
                        onChange={(e) => updateLeg(leg.id, 'league', e.target.value)}
                        className="w-full bg-surface border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                      />
                    </div>
                  )}
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-xs text-textMuted font-bold uppercase">Market</label>
                  <select
                    value={leg.type}
                    onChange={(e) => updateLeg(leg.id, 'type', e.target.value)}
                    className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                  >
                    <optgroup label="Popular">
                      <option value={BetType.MATCH_WINNER}>1X2 (Full Time)</option>
                      <option value={BetType.BTTS}>BTTS</option>
                      <option value={BetType.OVER_UNDER}>Over/Under Goals</option>
                      <option value={BetType.DOUBLE_CHANCE}>Double Chance</option>
                    </optgroup>
                    <optgroup label="Other Markets">
                      <option value={BetType.DRAW_NO_BET}>Draw No Bet</option>
                      <option value={BetType.HANDICAP}>Handicap</option>
                      <option value={BetType.WIN_EITHER_HALF}>Win Either Half</option>
                      <option value={BetType.TOTAL_CORNERS}>Total Corners</option>
                    </optgroup>
                  </select>
                </div>
                <div className="space-y-1">
                  <label className="text-xs text-textMuted font-bold uppercase">Selection</label>
                  <select
                    value={leg.selection}
                    onChange={(e) => updateLeg(leg.id, 'selection', e.target.value)}
                    className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                  >
                    {leg.type === BetType.MATCH_WINNER && (
                      <>
                        <option value="Home">Home Win (1)</option>
                        <option value="Draw">Draw (X)</option>
                        <option value="Away">Away Win (2)</option>
                      </>
                    )}
                    {leg.type === BetType.BTTS && (
                      <>
                        <option value="Yes">Yes</option>
                        <option value="No">No</option>
                      </>
                    )}
                    {leg.type === BetType.DOUBLE_CHANCE && (
                      <>
                        <option value="1X">1X (Home or Draw)</option>
                        <option value="X2">X2 (Away or Draw)</option>
                        <option value="12">12 (Home or Away)</option>
                      </>
                    )}
                    {leg.type === BetType.OVER_UNDER && (
                      <>
                        <option value="Over 2.5">Over 2.5</option>
                        <option value="Under 2.5">Under 2.5</option>
                        <option value="Over 1.5">Over 1.5</option>
                        <option value="Under 1.5">Under 1.5</option>
                        <option value="Over 3.5">Over 3.5</option>
                      </>
                    )}
                    {leg.type === BetType.WIN_EITHER_HALF && (
                      <>
                        <option value="Home">Home (1)</option>
                        <option value="Away">Away (2)</option>
                      </>
                    )}
                    {!([BetType.MATCH_WINNER, BetType.BTTS, BetType.DOUBLE_CHANCE, BetType.OVER_UNDER, BetType.WIN_EITHER_HALF].includes(leg.type as BetType)) && (
                      <option value={leg.selection}>{leg.selection}</option>
                    )}
                  </select>
                </div>
              </div>
            </div>
          ))}

          <button 
            onClick={addLeg}
            className="w-full py-3 border border-dashed border-borderBase rounded-lg text-textMuted hover:text-textMain hover:bg-inputBg transition-all flex items-center justify-center gap-2"
          >
            <Plus size={18} /> Add Match
          </button>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 pt-6 border-t border-borderBase">
           <div className="space-y-1">
              <label className="text-xs font-bold text-textMuted uppercase">Stake ({symbol})</label>
              <input 
                type="text" 
                inputMode="decimal"
                value={stake}
                onChange={(e) => handleNumericChange(e.target.value, setStake)}
                className="w-full bg-inputBg border border-borderBase rounded px-4 py-3 text-textMain font-bold focus:outline-none focus:border-primary"
              />
           </div>
           <div className="space-y-1">
              <label className="text-xs font-bold text-textMuted uppercase">Total Odds</label>
              <input 
                type="text" 
                inputMode="decimal"
                value={totalOdds}
                onChange={(e) => handleNumericChange(e.target.value, setTotalOdds)}
                className="w-full bg-inputBg border border-borderBase rounded px-4 py-3 text-textMain font-bold focus:outline-none focus:border-primary"
              />
           </div>
        </div>

        <div className="bg-primary/10 rounded-lg p-4 flex justify-between items-center border border-primary/20">
          <span className="text-primary font-medium">Potential Return</span>
          <span className="text-2xl font-bold text-primary">
            {symbol}{((parseFloat(stake) || 0) * (parseFloat(totalOdds) || 0)).toFixed(2)}
          </span>
        </div>

        <div className="flex gap-4 justify-end pt-4">
          <button onClick={onCancel} className="px-6 py-3 text-textMuted hover:text-textMain">Cancel</button>
          <button 
            onClick={handleSave}
            className="px-8 py-3 rounded-lg font-bold bg-primary hover:bg-blue-600 text-white shadow-lg transition-all flex items-center gap-2"
          >
            <Save size={18} /> {isEditing ? 'Update Slip' : 'Save Bet Slip'}
          </button>
        </div>
      </div>

      {showImport && (
        <div className="fixed inset-0 z-[60] bg-background/95 flex items-center justify-center p-6 animate-fade-in">
           <div className="w-full max-w-lg bg-surface border border-borderBase rounded-xl p-6 shadow-2xl">
              <div className="flex justify-between items-center mb-4">
                 <h3 className="text-textMain font-bold flex items-center gap-2">
                   <ClipboardPaste size={18} className="text-primary" /> Import Selections
                 </h3>
                 <button onClick={() => setShowImport(false)} className="text-textMuted hover:text-textMain"><X size={20} /></button>
              </div>
              <p className="text-xs text-textMuted mb-4 italic">
                Format: Selection, Odds, Market, Match on separate lines.
              </p>
              <textarea
                value={importText}
                onChange={(e) => setImportText(e.target.value)}
                placeholder="Arsenal&#10;1.85&#10;Match Result&#10;Arsenal vs Liverpool&#10;---&#10;Over 2.5&#10;2.10&#10;Total Goals&#10;Chelsea vs Spurs"
                className="w-full h-64 bg-inputBg border border-borderBase rounded-lg p-4 text-xs font-mono text-textMain focus:outline-none focus:border-primary resize-none"
              />
              <div className="mt-4 flex justify-end gap-3">
                 <button onClick={() => setShowImport(false)} className="px-4 py-2 text-textMuted font-medium">Cancel</button>
                 <button 
                   onClick={handleImport} 
                   className="px-6 py-2 bg-primary text-white rounded-lg font-bold hover:bg-blue-600 transition-colors shadow-lg shadow-blue-500/20"
                 >
                   Process & Import
                 </button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Plus, Trash2, Save, ClipboardPaste, X, Edit3, Folder, Globe } from 'lucide-react';
import { BetType, Leg, LegStatus, Slip, SlipStatus, Currency, CURRENCY_SYMBOLS } from '../types';

interface NewSlipFormProps {
  initialData?: Slip;
  onSave: (slip: Slip) => void;
  onCancel: () => void;
  currency: Currency;
  availableFolders: string[];
  availableLeagues: string[];
}

// Robust ID generator
const generateId = () => {
  return Date.now().toString(36) + Math.random().toString(36).substring(2, 9);
};

export const NewSlipForm: React.FC<NewSlipFormProps> = ({ initialData, onSave, onCancel, currency, availableFolders, availableLeagues }) => {
  const [stake, setStake] = useState<string>(() => {
    if (initialData) return initialData.stake.toString();
    const saved = localStorage.getItem('smartbet_draft_stake');
    return saved || '10';
  });

  const [totalOdds, setTotalOdds] = useState<string>(() => {
    if (initialData) return initialData.odds.toString();
    const saved = localStorage.getItem('smartbet_draft_odds');
    return saved || '1.00';
  });

  const [folder, setFolder] = useState<string>(() => {
    if (initialData) return initialData.folder || '';
    return '';
  });

  const [legs, setLegs] = useState<Leg[]>(() => {
    if (initialData) return initialData.legs;
    const saved = localStorage.getItem('smartbet_draft_legs');
    if (saved) return JSON.parse(saved);
    return [{
      id: generateId(),
      matchName: '',
      league: '',
      date: new Date().toISOString().split('T')[0],
      type: BetType.MATCH_WINNER,
      selection: 'Home',
      status: LegStatus.PENDING,
    }];
  });

  const [showImport, setShowImport] = useState(false);
  const [importText, setImportText] = useState('');

  const symbol = CURRENCY_SYMBOLS[currency];
  const isEditing = !!initialData;

  useEffect(() => {
    if (!isEditing) {
      localStorage.setItem('smartbet_draft_stake', stake);
      localStorage.setItem('smartbet_draft_odds', totalOdds);
      localStorage.setItem('smartbet_draft_legs', JSON.stringify(legs));
    }
  }, [stake, totalOdds, legs, isEditing]);

  const clearDraft = () => {
    localStorage.removeItem('smartbet_draft_stake');
    localStorage.removeItem('smartbet_draft_odds');
    localStorage.removeItem('smartbet_draft_legs');
  };

  const addLeg = () => {
    setLegs([
      ...legs,
      {
        id: generateId(),
        matchName: '',
        league: '',
        date: new Date().toISOString().split('T')[0],
        type: BetType.MATCH_WINNER,
        selection: 'Home',
        status: LegStatus.PENDING,
      }
    ]);
  };

  const removeLeg = (id: string) => {
    if (legs.length > 1) {
      setLegs(legs.filter(l => l.id !== id));
    }
  };

  const updateLeg = (id: string, field: keyof Leg, value: any) => {
    setLegs(legs.map(l => {
      if (l.id === id) {
        const updated = { ...l, [field]: value };
        if (field === 'type') {
           if (value === BetType.MATCH_WINNER) updated.selection = 'Home';
           if (value === BetType.BTTS) updated.selection = 'Yes';
           if (value === BetType.OVER_UNDER) updated.selection = 'Over 2.5';
           if (value === BetType.DOUBLE_CHANCE) updated.selection = '1X';
           if (value === BetType.DRAW_NO_BET) updated.selection = 'Home';
           if (value === BetType.WIN_EITHER_HALF) updated.selection = 'Home';
           if (value === BetType.HANDICAP) updated.selection = 'Home (+0.5)';
        }
        return updated;
      }
      return l;
    }));
  };

  const parseTeams = (matchName: string) => {
    const parts = matchName.split(/\s+v\s+|\s+vs\.?\s+|\s+-\s+/i);
    return {
      home: parts[0]?.trim() || 'Home',
      away: parts[1]?.trim() || 'Away'
    };
  };

  const handleNumericChange = (value: string, setter: (v: string) => void) => {
    if (value === '' || /^\d*\.?\d*$/.test(value)) {
      setter(value);
    }
  };

  const handleImport = () => {
    if (!importText.trim()) return;

    try {
      const lines = importText.split('\n').map(l => l.trim()).filter(l => l.length > 0);

      const newLegs: Leg[] = [];
      let calculatedOdds = 1;

      let i = 0;
      while (i < lines.length) {
        const selectionRaw = lines[i];
        const oddsRaw = lines[i+1];
        const marketRaw = lines[i+2];
        const matchRaw = lines[i+3];

        if (!selectionRaw || !oddsRaw || !marketRaw || !matchRaw) {
          i++;
          continue;
        }

        const oddsVal = parseFloat(oddsRaw.replace(/[^0-9.]/g, ''));
        if (isNaN(oddsVal)) {
           i++;
           continue;
        }

        let dateRaw = new Date().toISOString().split('T')[0];
        let consumedLines = 4;

        if (i + 4 < lines.length) {
          const potentialDate = lines[i+4];
          if (potentialDate.match(/\d{2}[/.-]\d{2}/) || potentialDate.toLowerCase().includes('today') || potentialDate.toLowerCase().includes('tomorrow')) {
             if (potentialDate.toLowerCase().includes('tomorrow')) {
               const d = new Date(); d.setDate(d.getDate() + 1);
               dateRaw = d.toISOString().split('T')[0];
             }
             consumedLines = 5;
          }
        }

        calculatedOdds *= oddsVal;

        let type = BetType.MATCH_WINNER;
        let selection = 'Home';
        const mUpper = marketRaw.toUpperCase();
        const sUpper = selectionRaw.toUpperCase();
        const { home, away } = parseTeams(matchRaw);

        if (mUpper.includes('BOTH') || mUpper.includes('BTTS')) {
          type = BetType.BTTS;
          selection = sUpper.includes('YES') || sUpper === 'GG' ? 'Yes' : 'No';
        } else if (mUpper.includes('OVER') || mUpper.includes('UNDER') || mUpper.includes('TOTAL')) {
          type = BetType.OVER_UNDER;
          const match = selectionRaw.match(/(\d+\.?\d*)/);
          const val = match ? match[1] : '2.5';
          selection = `${sUpper.includes('UNDER') ? 'Under' : 'Over'} ${val}`;
        } else if (mUpper.includes('DOUBLE') || mUpper.includes('DC')) {
          type = BetType.DOUBLE_CHANCE;
          if (sUpper.includes('1X') || (sUpper.includes('HOME') && sUpper.includes('DRAW'))) selection = '1X';
          else if (sUpper.includes('X2') || (sUpper.includes('AWAY') && sUpper.includes('DRAW'))) selection = 'X2';
          else selection = '12';
        } else if (mUpper.includes('1X2') || mUpper.includes('WINNER') || mUpper.includes('RESULT')) {
          type = BetType.MATCH_WINNER;
          if (sUpper.includes(away.toUpperCase()) || sUpper === '2') selection = 'Away';
          else if (sUpper.includes('DRAW') || sUpper === 'X') selection = 'Draw';
          else selection = 'Home';
        }

        newLegs.push({
          id: generateId(),
          matchName: matchRaw,
          league: '',
          date: dateRaw,
          type,
          selection,
          status: LegStatus.PENDING
        });

        i += consumedLines;
      }

      if (newLegs.length > 0) {
        setLegs(newLegs);
        setTotalOdds(calculatedOdds.toFixed(2));
        setShowImport(false);
        setImportText('');
      } else {
        alert("Couldn't find valid bet selections. Ensure the format is Selection, Odds, Market, then Match name on separate lines.");
      }
    } catch (e) {
      alert("Error parsing bet slip.");
    }
  };

  const handleSave = () => {
    if (legs.some(l => !l.matchName)) {
      alert("Please enter a match name for all selections.");
      return;
    }
    const numStake = parseFloat(stake) || 0;
    const numOdds = parseFloat(totalOdds) || 1;
    const newSlip: Slip = {
      id: initialData ? initialData.id : generateId(),
      createdAt: initialData ? initialData.createdAt : Date.now(),
      legs,
      stake: numStake,
      odds: numOdds,
      potentialReturn: numStake * numOdds,
      status: initialData ? initialData.status : SlipStatus.PENDING,
      folder: folder.trim() || undefined
    };
    onSave(newSlip);
    clearDraft();
  };

  return (
    <div className="bg-surface rounded-xl shadow-xl border border-borderBase overflow-hidden relative transition-colors">
      <div className="p-6 border-b border-borderBase flex justify-between items-center bg-inputBg">
        <h2 className="text-xl font-bold text-textMain flex items-center gap-2">
          {isEditing ? <Edit3 className="text-primary" /> : <Plus className="text-primary" />} 
          {isEditing ? 'Edit Bet Slip' : 'Create New Bet Slip'}
        </h2>
        <div className="flex gap-2">
          {!isEditing && (
            <span className="text-[10px] uppercase tracking-wider font-bold text-success/80 border border-success/20 px-2 py-1 rounded-full flex items-center bg-success/5">
              Auto-Saved
            </span>
          )}
          <button 
            onClick={() => setShowImport(true)}
            className="text-xs flex items-center gap-1 bg-surface border border-borderBase hover:bg-background text-textMain px-3 py-1.5 rounded transition-colors"
          >
            <ClipboardPaste size={14} /> Import
          </button>
        </div>
      </div>

      <div className="p-6 space-y-6">
        <div className="bg-inputBg/50 p-4 rounded-lg border border-borderBase">
            <label className="text-sm font-medium text-textMain mb-2 flex items-center gap-2">
                <Folder size={16} className="text-primary" /> Betting Folder
            </label>
            <div className="relative">
                <input
                    type="text"
                    list="folders-list"
                    value={folder}
                    onChange={(e) => setFolder(e.target.value)}
                    placeholder="e.g. Accumulator, High Stakes..."
                    className="w-full bg-surface border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                />
                <datalist id="folders-list">
                    {availableFolders.map(f => <option key={f} value={f} />)}
                </datalist>
            </div>
        </div>

        <div className="space-y-4">
          <label className="text-sm font-medium text-textMuted uppercase tracking-wider">Match Selections</label>
          {legs.map((leg, index) => (
            <div key={leg.id} className="p-4 bg-background rounded-lg border border-borderBase hover:border-textMuted transition-colors space-y-4">
              <div className="grid grid-cols-1 md:grid-cols-12 gap-4">
                <div className="md:col-span-8 space-y-1">
                  <label className="text-xs text-textMuted font-bold uppercase">Match Name</label>
                  <input
                    type="text"
                    value={leg.matchName}
                    onChange={(e) => updateLeg(leg.id, 'matchName', e.target.value)}
                    placeholder="e.g. Man City vs Arsenal"
                    className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                  />
                </div>
                <div className="md:col-span-3 space-y-1">
                  <label className="text-xs text-textMuted font-bold uppercase">Date</label>
                  <input
                    type="date"
                    value={leg.date}
                    onChange={(e) => updateLeg(leg.id, 'date', e.target.value)}
                    className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                  />
                </div>
                <div className="md:col-span-1 flex items-end justify-center pb-1">
                  <button 
                    onClick={() => removeLeg(leg.id)}
                    disabled={legs.length === 1}
                    className="p-2 rounded hover:bg-danger/20 text-danger/80 transition-colors disabled:opacity-30"
                  >
                    <Trash2 size={18} />
                  </button>
                </div>
              </div>

              {/* League Selection */}
              <div className="space-y-3 bg-inputBg/30 p-3 rounded-lg border border-borderBase/50">
                <div className="flex flex-col md:flex-row md:items-center gap-4">
                  <div className="flex-1 space-y-1">
                    <label className="text-xs text-textMuted font-bold uppercase flex items-center gap-1">
                      <Globe size={12} className="text-primary" /> League
                    </label>
                    <select
                      value={availableLeagues.includes(leg.league || '') ? (leg.league || '') : 'other'}
                      onChange={(e) => {
                        const val = e.target.value;
                        if (val !== 'other') updateLeg(leg.id, 'league', val);
                      }}
                      className="w-full bg-surface border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                    >
                      <option value="">Select League...</option>
                      {availableLeagues.map(l => <option key={l} value={l}>{l}</option>)}
                      <option value="other">Manual Entry...</option>
                    </select>
                  </div>

                  {(!availableLeagues.includes(leg.league || '') || leg.league === '') && (
                    <div className="flex-1 space-y-1">
                      <label className="text-xs text-textMuted font-bold uppercase">Manual League Name</label>
                      <input
                        type="text"
                        placeholder="Type league name..."
                        value={leg.league || ''}
                        onChange={(e) => updateLeg(leg.id, 'league', e.target.value)}
                        className="w-full bg-surface border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                      />
                    </div>
                  )}
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-xs text-textMuted font-bold uppercase">Market</label>
                  <select
                    value={leg.type}
                    onChange={(e) => updateLeg(leg.id, 'type', e.target.value)}
                    className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                  >
                    <optgroup label="Popular">
                      <option value={BetType.MATCH_WINNER}>1X2 (Full Time)</option>
                      <option value={BetType.BTTS}>BTTS</option>
                      <option value={BetType.OVER_UNDER}>Over/Under Goals</option>
                      <option value={BetType.DOUBLE_CHANCE}>Double Chance</option>
                    </optgroup>
                    <optgroup label="Other Markets">
                      <option value={BetType.DRAW_NO_BET}>Draw No Bet</option>
                      <option value={BetType.HANDICAP}>Handicap (2-Way)</option>
                      <option value={BetType.WIN_EITHER_HALF}>Win Either Half</option>
                      <option value={BetType.TOTAL_CORNERS}>Total Corners</option>
                    </optgroup>
                  </select>
                </div>
                <div className="space-y-1">
                  <label className="text-xs text-textMuted font-bold uppercase">Selection</label>
                  <select
                    value={leg.selection}
                    onChange={(e) => updateLeg(leg.id, 'selection', e.target.value)}
                    className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                  >
                    {leg.type === BetType.MATCH_WINNER && (
                      <>
                        <option value="Home">Home Win (1)</option>
                        <option value="Draw">Draw (X)</option>
                        <option value="Away">Away Win (2)</option>
                      </>
                    )}
                    {leg.type === BetType.BTTS && (
                      <>
                        <option value="Yes">Yes</option>
                        <option value="No">No</option>
                      </>
                    )}
                    {leg.type === BetType.DOUBLE_CHANCE && (
                      <>
                        <option value="1X">1X (Home or Draw)</option>
                        <option value="X2">X2 (Away or Draw)</option>
                        <option value="12">12 (Home or Away)</option>
                      </>
                    )}
                    {leg.type === BetType.OVER_UNDER && (
                      <>
                        <option value="Over 2.5">Over 2.5</option>
                        <option value="Under 2.5">Under 2.5</option>
                        <option value="Over 1.5">Over 1.5</option>
                        <option value="Under 1.5">Under 1.5</option>
                        <option value="Over 3.5">Over 3.5</option>
                      </>
                    )}
                    {leg.type === BetType.WIN_EITHER_HALF && (
                      <>
                        <option value="Home">Home (1)</option>
                        <option value="Away">Away (2)</option>
                      </>
                    )}
                    {leg.type === BetType.HANDICAP && (
                      <>
                        <optgroup label="0.5 Handicap">
                          <option value="Home (+0.5)">Home (0.5 : 0)</option>
                          <option value="Away (-0.5)">Away (0 : 0.5)</option>
                        </optgroup>
                        <optgroup label="1.5 Handicap">
                          <option value="Home (+1.5)">Home (1.5 : 0)</option>
                          <option value="Away (-1.5)">Away (0 : 1.5)</option>
                        </optgroup>
                        <optgroup label="2.5 Handicap">
                          <option value="Home (+2.5)">Home (2.5 : 0)</option>
                          <option value="Away (-2.5)">Away (0 : 2.5)</option>
                        </optgroup>
                      </>
                    )}
                    {!([BetType.MATCH_WINNER, BetType.BTTS, BetType.DOUBLE_CHANCE, BetType.OVER_UNDER, BetType.WIN_EITHER_HALF, BetType.HANDICAP].includes(leg.type as BetType)) && (
                      <option value={leg.selection}>{leg.selection}</option>
                    )}
                  </select>
                </div>
              </div>
            </div>
          ))}

          <button 
            onClick={addLeg}
            className="w-full py-3 border border-dashed border-borderBase rounded-lg text-textMuted hover:text-textMain hover:bg-inputBg transition-all flex items-center justify-center gap-2"
          >
            <Plus size={18} /> Add Match
          </button>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 pt-6 border-t border-borderBase">
           <div className="space-y-1">
              <label className="text-xs font-bold text-textMuted uppercase">Stake ({symbol})</label>
              <input 
                type="text" 
                inputMode="decimal"
                value={stake}
                onChange={(e) => handleNumericChange(e.target.value, setStake)}
                className="w-full bg-inputBg border border-borderBase rounded px-4 py-3 text-textMain font-bold focus:outline-none focus:border-primary"
              />
           </div>
           <div className="space-y-1">
              <label className="text-xs font-bold text-textMuted uppercase">Total Odds</label>
              <input 
                type="text" 
                inputMode="decimal"
                value={totalOdds}
                onChange={(e) => handleNumericChange(e.target.value, setTotalOdds)}
                className="w-full bg-inputBg border border-borderBase rounded px-4 py-3 text-textMain font-bold focus:outline-none focus:border-primary"
              />
           </div>
        </div>

        <div className="bg-primary/10 rounded-lg p-4 flex justify-between items-center border border-primary/20">
          <span className="text-primary font-medium">Potential Return</span>
          <span className="text-2xl font-bold text-primary">
            {symbol}{((parseFloat(stake) || 0) * (parseFloat(totalOdds) || 0)).toFixed(2)}
          </span>
        </div>

        <div className="flex gap-4 justify-end pt-4">
          <button onClick={onCancel} className="px-6 py-3 text-textMuted hover:text-textMain">Cancel</button>
          <button 
            onClick={handleSave}
            className="px-8 py-3 rounded-lg font-bold bg-primary hover:bg-blue-600 text-white shadow-lg transition-all flex items-center gap-2"
          >
            <Save size={18} /> {isEditing ? 'Update Slip' : 'Save Bet Slip'}
          </button>
        </div>
      </div>

      {showImport && (
        <div className="fixed inset-0 z-[60] bg-background/95 flex items-center justify-center p-6 animate-fade-in">
           <div className="w-full max-w-lg bg-surface border border-borderBase rounded-xl p-6 shadow-2xl">
              <div className="flex justify-between items-center mb-4">
                 <h3 className="text-textMain font-bold flex items-center gap-2">
                   <ClipboardPaste size={18} className="text-primary" /> Import Selections
                 </h3>
                 <button onClick={() => setShowImport(false)} className="text-textMuted hover:text-textMain"><X size={20} /></button>
              </div>
              <p className="text-xs text-textMuted mb-4 italic">
                Format: Selection, Odds, Market, Match on separate lines.
              </p>
              <textarea
                value={importText}
                onChange={(e) => setImportText(e.target.value)}
                placeholder="Arsenal&#10;1.85&#10;Match Result&#10;Arsenal vs Liverpool&#10;---&#10;Over 2.5&#10;2.10&#10;Total Goals&#10;Chelsea vs Spurs"
                className="w-full h-64 bg-inputBg border border-borderBase rounded-lg p-4 text-xs font-mono text-textMain focus:outline-none focus:border-primary resize-none"
              />
              <div className="mt-4 flex justify-end gap-3">
                 <button onClick={() => setShowImport(false)} className="px-4 py-2 text-textMuted font-medium">Cancel</button>
                 <button 
                   onClick={handleImport} 
                   className="px-6 py-2 bg-primary text-white rounded-lg font-bold hover:bg-blue-600 transition-colors shadow-lg shadow-blue-500/20"
                 >
                   Process & Import
                 </button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Plus, Trash2, Save, ClipboardPaste, X, Edit3, Folder, Globe } from 'lucide-react';
import { BetType, Leg, LegStatus, Slip, SlipStatus, Currency, CURRENCY_SYMBOLS } from '../types';

interface NewSlipFormProps {
  initialData?: Slip;
  onSave: (slip: Slip) => void;
  onCancel: () => void;
  currency: Currency;
  availableFolders: string[];
  availableLeagues: string[];
}

// Robust ID generator
const generateId = () => {
  return Date.now().toString(36) + Math.random().toString(36).substring(2, 9);
};

export const NewSlipForm: React.FC<NewSlipFormProps> = ({ initialData, onSave, onCancel, currency, availableFolders, availableLeagues }) => {
  const [stake, setStake] = useState<string>(() => {
    if (initialData) return initialData.stake.toString();
    const saved = localStorage.getItem('smartbet_draft_stake');
    return saved || '10';
  });

  const [totalOdds, setTotalOdds] = useState<string>(() => {
    if (initialData) return initialData.odds.toString();
    const saved = localStorage.getItem('smartbet_draft_odds');
    return saved || '1.00';
  });

  const [folder, setFolder] = useState<string>(() => {
    if (initialData) return initialData.folder || '';
    return '';
  });

  const [legs, setLegs] = useState<Leg[]>(() => {
    if (initialData) return initialData.legs;
    const saved = localStorage.getItem('smartbet_draft_legs');
    if (saved) return JSON.parse(saved);
    return [{
      id: generateId(),
      matchName: '',
      league: '',
      date: new Date().toISOString().split('T')[0],
      type: BetType.MATCH_WINNER,
      selection: 'Home',
      status: LegStatus.PENDING,
    }];
  });

  const [showImport, setShowImport] = useState(false);
  const [importText, setImportText] = useState('');

  const symbol = CURRENCY_SYMBOLS[currency];
  const isEditing = !!initialData;

  useEffect(() => {
    if (!isEditing) {
      localStorage.setItem('smartbet_draft_stake', stake);
      localStorage.setItem('smartbet_draft_odds', totalOdds);
      localStorage.setItem('smartbet_draft_legs', JSON.stringify(legs));
    }
  }, [stake, totalOdds, legs, isEditing]);

  const clearDraft = () => {
    localStorage.removeItem('smartbet_draft_stake');
    localStorage.removeItem('smartbet_draft_odds');
    localStorage.removeItem('smartbet_draft_legs');
  };

  const addLeg = () => {
    setLegs([
      ...legs,
      {
        id: generateId(),
        matchName: '',
        league: '',
        date: new Date().toISOString().split('T')[0],
        type: BetType.MATCH_WINNER,
        selection: 'Home',
        status: LegStatus.PENDING,
      }
    ]);
  };

  const removeLeg = (id: string) => {
    if (legs.length > 1) {
      setLegs(legs.filter(l => l.id !== id));
    }
  };

  const updateLeg = (id: string, field: keyof Leg, value: any) => {
    setLegs(legs.map(l => {
      if (l.id === id) {
        const updated = { ...l, [field]: value };
        if (field === 'type') {
           if (value === BetType.MATCH_WINNER) updated.selection = 'Home';
           if (value === BetType.BTTS) updated.selection = 'Yes';
           if (value === BetType.OVER_UNDER) updated.selection = 'Over 2.5';
           if (value === BetType.DOUBLE_CHANCE) updated.selection = '1X';
           if (value === BetType.DRAW_NO_BET) updated.selection = 'Home';
           if (value === BetType.WIN_EITHER_HALF) updated.selection = 'Home';
           if (value === BetType.HANDICAP) updated.selection = 'Home (+0.5)';
        }
        return updated;
      }
      return l;
    }));
  };

  const parseTeams = (matchName: string) => {
    const parts = matchName.split(/\s+v\s+|\s+vs\.?\s+|\s+-\s+/i);
    return {
      home: parts[0]?.trim() || 'Home',
      away: parts[1]?.trim() || 'Away'
    };
  };

  const handleNumericChange = (value: string, setter: (v: string) => void) => {
    if (value === '' || /^\d*\.?\d*$/.test(value)) {
      setter(value);
    }
  };

  const handleImport = () => {
    if (!importText.trim()) return;

    try {
      const lines = importText.split('\n').map(l => l.trim()).filter(l => l.length > 0);

      const newLegs: Leg[] = [];
      let calculatedOdds = 1;

      let i = 0;
      while (i < lines.length) {
        const selectionRaw = lines[i];
        const oddsRaw = lines[i+1];
        const marketRaw = lines[i+2];
        const matchRaw = lines[i+3];

        if (!selectionRaw || !oddsRaw || !marketRaw || !matchRaw) {
          i++;
          continue;
        }

        const oddsVal = parseFloat(oddsRaw.replace(/[^0-9.]/g, ''));
        if (isNaN(oddsVal)) {
           i++;
           continue;
        }

        let dateRaw = new Date().toISOString().split('T')[0];
        let consumedLines = 4;

        if (i + 4 < lines.length) {
          const potentialDate = lines[i+4];
          if (potentialDate.match(/\d{2}[/.-]\d{2}/) || potentialDate.toLowerCase().includes('today') || potentialDate.toLowerCase().includes('tomorrow')) {
             if (potentialDate.toLowerCase().includes('tomorrow')) {
               const d = new Date(); d.setDate(d.getDate() + 1);
               dateRaw = d.toISOString().split('T')[0];
             }
             consumedLines = 5;
          }
        }

        calculatedOdds *= oddsVal;

        let type = BetType.MATCH_WINNER;
        let selection = 'Home';
        const mUpper = marketRaw.toUpperCase();
        const sUpper = selectionRaw.toUpperCase();
        const { home, away } = parseTeams(matchRaw);

        if (mUpper.includes('BOTH') || mUpper.includes('BTTS')) {
          type = BetType.BTTS;
          selection = sUpper.includes('YES') || sUpper === 'GG' ? 'Yes' : 'No';
        } else if (mUpper.includes('OVER') || mUpper.includes('UNDER') || mUpper.includes('TOTAL')) {
          type = BetType.OVER_UNDER;
          const match = selectionRaw.match(/(\d+\.?\d*)/);
          const val = match ? match[1] : '2.5';
          selection = `${sUpper.includes('UNDER') ? 'Under' : 'Over'} ${val}`;
        } else if (mUpper.includes('DOUBLE') || mUpper.includes('DC')) {
          type = BetType.DOUBLE_CHANCE;
          if (sUpper.includes('1X') || (sUpper.includes('HOME') && sUpper.includes('DRAW'))) selection = '1X';
          else if (sUpper.includes('X2') || (sUpper.includes('AWAY') && sUpper.includes('DRAW'))) selection = 'X2';
          else selection = '12';
        } else if (mUpper.includes('1X2') || mUpper.includes('WINNER') || mUpper.includes('RESULT')) {
          type = BetType.MATCH_WINNER;
          if (sUpper.includes(away.toUpperCase()) || sUpper === '2') selection = 'Away';
          else if (sUpper.includes('DRAW') || sUpper === 'X') selection = 'Draw';
          else selection = 'Home';
        }

        newLegs.push({
          id: generateId(),
          matchName: matchRaw,
          league: '',
          date: dateRaw,
          type,
          selection,
          status: LegStatus.PENDING
        });

        i += consumedLines;
      }

      if (newLegs.length > 0) {
        setLegs(newLegs);
        setTotalOdds(calculatedOdds.toFixed(2));
        setShowImport(false);
        setImportText('');
      } else {
        alert("Couldn't find valid bet selections. Ensure the format is Selection, Odds, Market, then Match name on separate lines.");
      }
    } catch (e) {
      alert("Error parsing bet slip.");
    }
  };

  const handleSave = () => {
    if (legs.some(l => !l.matchName)) {
      alert("Please enter a match name for all selections.");
      return;
    }
    const numStake = parseFloat(stake) || 0;
    const numOdds = parseFloat(totalOdds) || 1;
    const newSlip: Slip = {
      id: initialData ? initialData.id : generateId(),
      createdAt: initialData ? initialData.createdAt : Date.now(),
      legs,
      stake: numStake,
      odds: numOdds,
      potentialReturn: numStake * numOdds,
      status: initialData ? initialData.status : SlipStatus.PENDING,
      folder: folder.trim() || undefined
    };
    onSave(newSlip);
    clearDraft();
  };

  return (
    <div className="bg-surface rounded-xl shadow-xl border border-borderBase overflow-hidden relative transition-colors">
      <div className="p-6 border-b border-borderBase flex justify-between items-center bg-inputBg">
        <h2 className="text-xl font-bold text-textMain flex items-center gap-2">
          {isEditing ? <Edit3 className="text-primary" /> : <Plus className="text-primary" />} 
          {isEditing ? 'Edit Bet Slip' : 'Create New Bet Slip'}
        </h2>
        <div className="flex gap-2">
          {!isEditing && (
            <span className="text-[10px] uppercase tracking-wider font-bold text-success/80 border border-success/20 px-2 py-1 rounded-full flex items-center bg-success/5">
              Auto-Saved
            </span>
          )}
          <button 
            onClick={() => setShowImport(true)}
            className="text-xs flex items-center gap-1 bg-surface border border-borderBase hover:bg-background text-textMain px-3 py-1.5 rounded transition-colors"
          >
            <ClipboardPaste size={14} /> Import
          </button>
        </div>
      </div>

      <div className="p-6 space-y-6">
        <div className="bg-inputBg/50 p-4 rounded-lg border border-borderBase">
            <label className="text-sm font-medium text-textMain mb-2 flex items-center gap-2">
                <Folder size={16} className="text-primary" /> Betting Folder
            </label>
            <div className="relative">
                <input
                    type="text"
                    list="folders-list"
                    value={folder}
                    onChange={(e) => setFolder(e.target.value)}
                    placeholder="e.g. Accumulator, High Stakes..."
                    className="w-full bg-surface border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                />
                <datalist id="folders-list">
                    {availableFolders.map(f => <option key={f} value={f} />)}
                </datalist>
            </div>
        </div>

        <div className="space-y-4">
          <label className="text-sm font-medium text-textMuted uppercase tracking-wider">Match Selections</label>
          {legs.map((leg, index) => (
            <div key={leg.id} className="p-4 bg-background rounded-lg border border-borderBase hover:border-textMuted transition-colors space-y-4">
              <div className="grid grid-cols-1 md:grid-cols-12 gap-4">
                <div className="md:col-span-8 space-y-1">
                  <label className="text-xs text-textMuted font-bold uppercase">Match Name</label>
                  <input
                    type="text"
                    value={leg.matchName}
                    onChange={(e) => updateLeg(leg.id, 'matchName', e.target.value)}
                    placeholder="e.g. Man City vs Arsenal"
                    className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                  />
                </div>
                <div className="md:col-span-3 space-y-1">
                  <label className="text-xs text-textMuted font-bold uppercase">Date</label>
                  <input
                    type="date"
                    value={leg.date}
                    onChange={(e) => updateLeg(leg.id, 'date', e.target.value)}
                    className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                  />
                </div>
                <div className="md:col-span-1 flex items-end justify-center pb-1">
                  <button 
                    onClick={() => removeLeg(leg.id)}
                    disabled={legs.length === 1}
                    className="p-2 rounded hover:bg-danger/20 text-danger/80 transition-colors disabled:opacity-30"
                  >
                    <Trash2 size={18} />
                  </button>
                </div>
              </div>

              {/* League Selection */}
              <div className="space-y-3 bg-inputBg/30 p-3 rounded-lg border border-borderBase/50">
                <div className="flex flex-col md:flex-row md:items-center gap-4">
                  <div className="flex-1 space-y-1">
                    <label className="text-xs text-textMuted font-bold uppercase flex items-center gap-1">
                      <Globe size={12} className="text-primary" /> League
                    </label>
                    <select
                      value={availableLeagues.includes(leg.league || '') ? (leg.league || '') : 'other'}
                      onChange={(e) => {
                        const val = e.target.value;
                        if (val !== 'other') updateLeg(leg.id, 'league', val);
                      }}
                      className="w-full bg-surface border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                    >
                      <option value="">Select League...</option>
                      {availableLeagues.map(l => <option key={l} value={l}>{l}</option>)}
                      <option value="other">Manual Entry...</option>
                    </select>
                  </div>

                  {(!availableLeagues.includes(leg.league || '') || leg.league === '') && (
                    <div className="flex-1 space-y-1">
                      <label className="text-xs text-textMuted font-bold uppercase">Manual League Name</label>
                      <input
                        type="text"
                        placeholder="Type league name..."
                        value={leg.league || ''}
                        onChange={(e) => updateLeg(leg.id, 'league', e.target.value)}
                        className="w-full bg-surface border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                      />
                    </div>
                  )}
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-xs text-textMuted font-bold uppercase">Market</label>
                  <select
                    value={leg.type}
                    onChange={(e) => updateLeg(leg.id, 'type', e.target.value)}
                    className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                  >
                    <optgroup label="Popular">
                      <option value={BetType.MATCH_WINNER}>1X2 (Full Time)</option>
                      <option value={BetType.BTTS}>BTTS</option>
                      <option value={BetType.OVER_UNDER}>Over/Under Goals</option>
                      <option value={BetType.DOUBLE_CHANCE}>Double Chance</option>
                    </optgroup>
                    <optgroup label="Other Markets">
                      <option value={BetType.DRAW_NO_BET}>Draw No Bet</option>
                      <option value={BetType.HANDICAP}>Handicap (2-Way)</option>
                      <option value={BetType.WIN_EITHER_HALF}>Win Either Half</option>
                      <option value={BetType.TOTAL_CORNERS}>Total Corners</option>
                    </optgroup>
                  </select>
                </div>
                <div className="space-y-1">
                  <label className="text-xs text-textMuted font-bold uppercase">Selection</label>
                  <select
                    value={leg.selection}
                    onChange={(e) => updateLeg(leg.id, 'selection', e.target.value)}
                    className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                  >
                    {leg.type === BetType.MATCH_WINNER && (
                      <>
                        <option value="Home">Home Win (1)</option>
                        <option value="Draw">Draw (X)</option>
                        <option value="Away">Away Win (2)</option>
                      </>
                    )}
                    {leg.type === BetType.BTTS && (
                      <>
                        <option value="Yes">Yes</option>
                        <option value="No">No</option>
                      </>
                    )}
                    {leg.type === BetType.DOUBLE_CHANCE && (
                      <>
                        <option value="1X">1X (Home or Draw)</option>
                        <option value="X2">X2 (Away or Draw)</option>
                        <option value="12">12 (Home or Away)</option>
                      </>
                    )}
                    {leg.type === BetType.OVER_UNDER && (
                      <>
                        <optgroup label="Overs">
                          <option value="Over 0.5">Over 0.5</option>
                          <option value="Over 1.5">Over 1.5</option>
                          <option value="Over 2.5">Over 2.5</option>
                          <option value="Over 3.5">Over 3.5</option>
                          <option value="Over 4.5">Over 4.5</option>
                        </optgroup>
                        <optgroup label="Unders">
                          <option value="Under 0.5">Under 0.5</option>
                          <option value="Under 1.5">Under 1.5</option>
                          <option value="Under 2.5">Under 2.5</option>
                          <option value="Under 3.5">Under 3.5</option>
                          <option value="Under 4.5">Under 4.5</option>
                        </optgroup>
                      </>
                    )}
                    {leg.type === BetType.WIN_EITHER_HALF && (
                      <>
                        <option value="Home">Home (1)</option>
                        <option value="Away">Away (2)</option>
                      </>
                    )}
                    {leg.type === BetType.HANDICAP && (
                      <>
                        <optgroup label="0.5 Handicap">
                          <option value="Home (+0.5)">Home (0.5 : 0)</option>
                          <option value="Away (-0.5)">Away (0 : 0.5)</option>
                        </optgroup>
                        <optgroup label="1.5 Handicap">
                          <option value="Home (+1.5)">Home (1.5 : 0)</option>
                          <option value="Away (-1.5)">Away (0 : 1.5)</option>
                        </optgroup>
                        <optgroup label="2.5 Handicap">
                          <option value="Home (+2.5)">Home (2.5 : 0)</option>
                          <option value="Away (-2.5)">Away (0 : 2.5)</option>
                        </optgroup>
                      </>
                    )}
                    {!([BetType.MATCH_WINNER, BetType.BTTS, BetType.DOUBLE_CHANCE, BetType.OVER_UNDER, BetType.WIN_EITHER_HALF, BetType.HANDICAP].includes(leg.type as BetType)) && (
                      <option value={leg.selection}>{leg.selection}</option>
                    )}
                  </select>
                </div>
              </div>
            </div>
          ))}

          <button 
            onClick={addLeg}
            className="w-full py-3 border border-dashed border-borderBase rounded-lg text-textMuted hover:text-textMain hover:bg-inputBg transition-all flex items-center justify-center gap-2"
          >
            <Plus size={18} /> Add Match
          </button>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 pt-6 border-t border-borderBase">
           <div className="space-y-1">
              <label className="text-xs font-bold text-textMuted uppercase">Stake ({symbol})</label>
              <input 
                type="text" 
                inputMode="decimal"
                value={stake}
                onChange={(e) => handleNumericChange(e.target.value, setStake)}
                className="w-full bg-inputBg border border-borderBase rounded px-4 py-3 text-textMain font-bold focus:outline-none focus:border-primary"
              />
           </div>
           <div className="space-y-1">
              <label className="text-xs font-bold text-textMuted uppercase">Total Odds</label>
              <input 
                type="text" 
                inputMode="decimal"
                value={totalOdds}
                onChange={(e) => handleNumericChange(e.target.value, setTotalOdds)}
                className="w-full bg-inputBg border border-borderBase rounded px-4 py-3 text-textMain font-bold focus:outline-none focus:border-primary"
              />
           </div>
        </div>

        <div className="bg-primary/10 rounded-lg p-4 flex justify-between items-center border border-primary/20">
          <span className="text-primary font-medium">Potential Return</span>
          <span className="text-2xl font-bold text-primary">
            {symbol}{((parseFloat(stake) || 0) * (parseFloat(totalOdds) || 0)).toFixed(2)}
          </span>
        </div>

        <div className="flex gap-4 justify-end pt-4">
          <button onClick={onCancel} className="px-6 py-3 text-textMuted hover:text-textMain">Cancel</button>
          <button 
            onClick={handleSave}
            className="px-8 py-3 rounded-lg font-bold bg-primary hover:bg-blue-600 text-white shadow-lg transition-all flex items-center gap-2"
          >
            <Save size={18} /> {isEditing ? 'Update Slip' : 'Save Bet Slip'}
          </button>
        </div>
      </div>

      {showImport && (
        <div className="fixed inset-0 z-[60] bg-background/95 flex items-center justify-center p-6 animate-fade-in">
           <div className="w-full max-w-lg bg-surface border border-borderBase rounded-xl p-6 shadow-2xl">
              <div className="flex justify-between items-center mb-4">
                 <h3 className="text-textMain font-bold flex items-center gap-2">
                   <ClipboardPaste size={18} className="text-primary" /> Import Selections
                 </h3>
                 <button onClick={() => setShowImport(false)} className="text-textMuted hover:text-textMain"><X size={20} /></button>
              </div>
              <p className="text-xs text-textMuted mb-4 italic">
                Format: Selection, Odds, Market, Match on separate lines.
              </p>
              <textarea
                value={importText}
                onChange={(e) => setImportText(e.target.value)}
                placeholder="Arsenal&#10;1.85&#10;Match Result&#10;Arsenal vs Liverpool&#10;---&#10;Over 2.5&#10;2.10&#10;Total Goals&#10;Chelsea vs Spurs"
                className="w-full h-64 bg-inputBg border border-borderBase rounded-lg p-4 text-xs font-mono text-textMain focus:outline-none focus:border-primary resize-none"
              />
              <div className="mt-4 flex justify-end gap-3">
                 <button onClick={() => setShowImport(false)} className="px-4 py-2 text-textMuted font-medium">Cancel</button>
                 <button 
                   onClick={handleImport} 
                   className="px-6 py-2 bg-primary text-white rounded-lg font-bold hover:bg-blue-600 transition-colors shadow-lg shadow-blue-500/20"
                 >
                   Process & Import
                 </button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Plus, Trash2, Save, ClipboardPaste, X, Edit3, Folder, Globe } from 'lucide-react';
import { BetType, Leg, LegStatus, Slip, SlipStatus, Currency, CURRENCY_SYMBOLS } from '../types';

interface NewSlipFormProps {
  initialData?: Slip;
  onSave: (slip: Slip) => void;
  onCancel: () => void;
  currency: Currency;
  availableFolders: string[];
  availableLeagues: string[];
}

// Robust ID generator
const generateId = () => {
  return Date.now().toString(36) + Math.random().toString(36).substring(2, 9);
};

export const NewSlipForm: React.FC<NewSlipFormProps> = ({ initialData, onSave, onCancel, currency, availableFolders, availableLeagues }) => {
  const [stake, setStake] = useState<string>(() => {
    if (initialData) return initialData.stake.toString();
    const saved = localStorage.getItem('smartbet_draft_stake');
    return saved || '10';
  });

  const [totalOdds, setTotalOdds] = useState<string>(() => {
    if (initialData) return initialData.odds.toString();
    const saved = localStorage.getItem('smartbet_draft_odds');
    return saved || '1.00';
  });

  const [folder, setFolder] = useState<string>(() => {
    if (initialData) return initialData.folder || '';
    return '';
  });

  const [legs, setLegs] = useState<Leg[]>(() => {
    if (initialData) return initialData.legs;
    const saved = localStorage.getItem('smartbet_draft_legs');
    if (saved) return JSON.parse(saved);
    return [{
      id: generateId(),
      matchName: '',
      league: '',
      date: new Date().toISOString().split('T')[0],
      type: BetType.MATCH_WINNER,
      selection: 'Home',
      status: LegStatus.PENDING,
    }];
  });

  const [showImport, setShowImport] = useState(false);
  const [importText, setImportText] = useState('');

  const symbol = CURRENCY_SYMBOLS[currency];
  const isEditing = !!initialData;

  useEffect(() => {
    if (!isEditing) {
      localStorage.setItem('smartbet_draft_stake', stake);
      localStorage.setItem('smartbet_draft_odds', totalOdds);
      localStorage.setItem('smartbet_draft_legs', JSON.stringify(legs));
    }
  }, [stake, totalOdds, legs, isEditing]);

  const clearDraft = () => {
    localStorage.removeItem('smartbet_draft_stake');
    localStorage.removeItem('smartbet_draft_odds');
    localStorage.removeItem('smartbet_draft_legs');
  };

  const addLeg = () => {
    setLegs([
      ...legs,
      {
        id: generateId(),
        matchName: '',
        league: '',
        date: new Date().toISOString().split('T')[0],
        type: BetType.MATCH_WINNER,
        selection: 'Home',
        status: LegStatus.PENDING,
      }
    ]);
  };

  const removeLeg = (id: string) => {
    if (legs.length > 1) {
      setLegs(legs.filter(l => l.id !== id));
    }
  };

  const updateLeg = (id: string, field: keyof Leg, value: any) => {
    setLegs(legs.map(l => {
      if (l.id === id) {
        const updated = { ...l, [field]: value };
        if (field === 'type') {
           if (value === BetType.MATCH_WINNER) updated.selection = 'Home';
           if (value === BetType.BTTS) updated.selection = 'Yes';
           if (value === BetType.OVER_UNDER) updated.selection = 'Over 2.5';
           if (value === BetType.DOUBLE_CHANCE) updated.selection = '1X';
           if (value === BetType.DRAW_NO_BET) updated.selection = 'Home';
           if (value === BetType.WIN_EITHER_HALF) updated.selection = 'Home';
           if (value === BetType.HANDICAP) updated.selection = 'Home (+0.5)';
        }
        return updated;
      }
      return l;
    }));
  };

  const parseTeams = (matchName: string) => {
    const parts = matchName.split(/\s+v\s+|\s+vs\.?\s+|\s+-\s+/i);
    return {
      home: parts[0]?.trim() || 'Home',
      away: parts[1]?.trim() || 'Away'
    };
  };

  const handleNumericChange = (value: string, setter: (v: string) => void) => {
    if (value === '' || /^\d*\.?\d*$/.test(value)) {
      setter(value);
    }
  };

  const handleImport = () => {
    if (!importText.trim()) return;

    try {
      const lines = importText.split('\n').map(l => l.trim()).filter(l => l.length > 0);

      const newLegs: Leg[] = [];
      let calculatedOdds = 1;

      let i = 0;
      while (i < lines.length) {
        const selectionRaw = lines[i];
        const oddsRaw = lines[i+1];
        const marketRaw = lines[i+2];
        const matchRaw = lines[i+3];

        if (!selectionRaw || !oddsRaw || !marketRaw || !matchRaw) {
          i++;
          continue;
        }

        const oddsVal = parseFloat(oddsRaw.replace(/[^0-9.]/g, ''));
        if (isNaN(oddsVal)) {
           i++;
           continue;
        }

        let dateRaw = new Date().toISOString().split('T')[0];
        let consumedLines = 4;

        if (i + 4 < lines.length) {
          const potentialDate = lines[i+4];
          if (potentialDate.match(/\d{2}[/.-]\d{2}/) || potentialDate.toLowerCase().includes('today') || potentialDate.toLowerCase().includes('tomorrow')) {
             if (potentialDate.toLowerCase().includes('tomorrow')) {
               const d = new Date(); d.setDate(d.getDate() + 1);
               dateRaw = d.toISOString().split('T')[0];
             }
             consumedLines = 5;
          }
        }

        calculatedOdds *= oddsVal;

        let type = BetType.MATCH_WINNER;
        let selection = 'Home';
        const mUpper = marketRaw.toUpperCase();
        const sUpper = selectionRaw.toUpperCase();
        const { home, away } = parseTeams(matchRaw);

        if (mUpper.includes('BOTH') || mUpper.includes('BTTS')) {
          type = BetType.BTTS;
          selection = sUpper.includes('YES') || sUpper === 'GG' ? 'Yes' : 'No';
        } else if (mUpper.includes('OVER') || mUpper.includes('UNDER') || mUpper.includes('TOTAL')) {
          type = BetType.OVER_UNDER;
          const match = selectionRaw.match(/(\d+\.?\d*)/);
          const val = match ? match[1] : '2.5';
          selection = `${sUpper.includes('UNDER') ? 'Under' : 'Over'} ${val}`;
        } else if (mUpper.includes('DOUBLE') || mUpper.includes('DC')) {
          type = BetType.DOUBLE_CHANCE;
          if (sUpper.includes('1X') || (sUpper.includes('HOME') && sUpper.includes('DRAW'))) selection = '1X';
          else if (sUpper.includes('X2') || (sUpper.includes('AWAY') && sUpper.includes('DRAW'))) selection = 'X2';
          else selection = '12';
        } else if (mUpper.includes('1X2') || mUpper.includes('WINNER') || mUpper.includes('RESULT')) {
          type = BetType.MATCH_WINNER;
          if (sUpper.includes(away.toUpperCase()) || sUpper === '2') selection = 'Away';
          else if (sUpper.includes('DRAW') || sUpper === 'X') selection = 'Draw';
          else selection = 'Home';
        }

        newLegs.push({
          id: generateId(),
          matchName: matchRaw,
          league: '',
          date: dateRaw,
          type,
          selection,
          status: LegStatus.PENDING
        });

        i += consumedLines;
      }

      if (newLegs.length > 0) {
        setLegs(newLegs);
        setTotalOdds(calculatedOdds.toFixed(2));
        setShowImport(false);
        setImportText('');
      } else {
        alert("Couldn't find valid bet selections. Ensure the format is Selection, Odds, Market, then Match name on separate lines.");
      }
    } catch (e) {
      alert("Error parsing bet slip.");
    }
  };

  const handleSave = () => {
    if (legs.some(l => !l.matchName)) {
      alert("Please enter a match name for all selections.");
      return;
    }
    const numStake = parseFloat(stake) || 0;
    const numOdds = parseFloat(totalOdds) || 1;
    const newSlip: Slip = {
      id: initialData ? initialData.id : generateId(),
      createdAt: initialData ? initialData.createdAt : Date.now(),
      legs,
      stake: numStake,
      odds: numOdds,
      potentialReturn: numStake * numOdds,
      status: initialData ? initialData.status : SlipStatus.PENDING,
      folder: folder.trim() || undefined
    };
    onSave(newSlip);
    clearDraft();
  };

  return (
    <div className="bg-surface rounded-xl shadow-xl border border-borderBase overflow-hidden relative transition-colors">
      <div className="p-6 border-b border-borderBase flex justify-between items-center bg-inputBg">
        <h2 className="text-xl font-bold text-textMain flex items-center gap-2">
          {isEditing ? <Edit3 className="text-primary" /> : <Plus className="text-primary" />} 
          {isEditing ? 'Edit Bet Slip' : 'Create New Bet Slip'}
        </h2>
        <div className="flex gap-2">
          {!isEditing && (
            <span className="text-[10px] uppercase tracking-wider font-bold text-success/80 border border-success/20 px-2 py-1 rounded-full flex items-center bg-success/5">
              Auto-Saved
            </span>
          )}
          <button 
            onClick={() => setShowImport(true)}
            className="text-xs flex items-center gap-1 bg-surface border border-borderBase hover:bg-background text-textMain px-3 py-1.5 rounded transition-colors"
          >
            <ClipboardPaste size={14} /> Import
          </button>
        </div>
      </div>

      <div className="p-6 space-y-6">
        <div className="bg-inputBg/50 p-4 rounded-lg border border-borderBase">
            <label className="text-sm font-medium text-textMain mb-2 flex items-center gap-2">
                <Folder size={16} className="text-primary" /> Betting Folder
            </label>
            <div className="relative">
                <input
                    type="text"
                    list="folders-list"
                    value={folder}
                    onChange={(e) => setFolder(e.target.value)}
                    placeholder="e.g. Accumulator, High Stakes..."
                    className="w-full bg-surface border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                />
                <datalist id="folders-list">
                    {availableFolders.map(f => <option key={f} value={f} />)}
                </datalist>
            </div>
        </div>

        <div className="space-y-4">
          <label className="text-sm font-medium text-textMuted uppercase tracking-wider">Match Selections</label>
          {legs.map((leg, index) => (
            <div key={leg.id} className="p-4 bg-background rounded-lg border border-borderBase hover:border-textMuted transition-colors space-y-4">
              <div className="grid grid-cols-1 md:grid-cols-12 gap-4">
                <div className="md:col-span-8 space-y-1">
                  <label className="text-xs text-textMuted font-bold uppercase">Match Name</label>
                  <input
                    type="text"
                    value={leg.matchName}
                    onChange={(e) => updateLeg(leg.id, 'matchName', e.target.value)}
                    placeholder="e.g. Man City vs Arsenal"
                    className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                  />
                </div>
                <div className="md:col-span-3 space-y-1">
                  <label className="text-xs text-textMuted font-bold uppercase">Date</label>
                  <input
                    type="date"
                    value={leg.date}
                    onChange={(e) => updateLeg(leg.id, 'date', e.target.value)}
                    className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                  />
                </div>
                <div className="md:col-span-1 flex items-end justify-center pb-1">
                  <button 
                    onClick={() => removeLeg(leg.id)}
                    disabled={legs.length === 1}
                    className="p-2 rounded hover:bg-danger/20 text-danger/80 transition-colors disabled:opacity-30"
                  >
                    <Trash2 size={18} />
                  </button>
                </div>
              </div>

              {/* League Selection */}
              <div className="space-y-3 bg-inputBg/30 p-3 rounded-lg border border-borderBase/50">
                <div className="flex flex-col md:flex-row md:items-center gap-4">
                  <div className="flex-1 space-y-1">
                    <label className="text-xs text-textMuted font-bold uppercase flex items-center gap-1">
                      <Globe size={12} className="text-primary" /> League
                    </label>
                    <select
                      value={availableLeagues.includes(leg.league || '') ? (leg.league || '') : 'other'}
                      onChange={(e) => {
                        const val = e.target.value;
                        if (val !== 'other') updateLeg(leg.id, 'league', val);
                      }}
                      className="w-full bg-surface border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                    >
                      <option value="">Select League...</option>
                      {availableLeagues.map(l => <option key={l} value={l}>{l}</option>)}
                      <option value="other">Manual Entry...</option>
                    </select>
                  </div>

                  {(!availableLeagues.includes(leg.league || '') || leg.league === '') && (
                    <div className="flex-1 space-y-1">
                      <label className="text-xs text-textMuted font-bold uppercase">Manual League Name</label>
                      <input
                        type="text"
                        placeholder="Type league name..."
                        value={leg.league || ''}
                        onChange={(e) => updateLeg(leg.id, 'league', e.target.value)}
                        className="w-full bg-surface border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                      />
                    </div>
                  )}
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-xs text-textMuted font-bold uppercase">Market</label>
                  <select
                    value={leg.type}
                    onChange={(e) => updateLeg(leg.id, 'type', e.target.value)}
                    className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                  >
                    <optgroup label="Popular">
                      <option value={BetType.MATCH_WINNER}>1X2 (Full Time)</option>
                      <option value={BetType.BTTS}>BTTS</option>
                      <option value={BetType.OVER_UNDER}>Over/Under Goals</option>
                      <option value={BetType.DOUBLE_CHANCE}>Double Chance</option>
                    </optgroup>
                    <optgroup label="Other Markets">
                      <option value={BetType.DRAW_NO_BET}>Draw No Bet</option>
                      <option value={BetType.HANDICAP}>Handicap (2-Way)</option>
                      <option value={BetType.WIN_EITHER_HALF}>Win Either Half</option>
                      <option value={BetType.TOTAL_CORNERS}>Total Corners</option>
                    </optgroup>
                  </select>
                </div>
                <div className="space-y-1">
                  <label className="text-xs text-textMuted font-bold uppercase">Selection</label>
                  <select
                    value={leg.selection}
                    onChange={(e) => updateLeg(leg.id, 'selection', e.target.value)}
                    className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                  >
                    {leg.type === BetType.MATCH_WINNER && (
                      <>
                        <option value="Home">Home Win (1)</option>
                        <option value="Draw">Draw (X)</option>
                        <option value="Away">Away Win (2)</option>
                      </>
                    )}
                    {leg.type === BetType.BTTS && (
                      <>
                        <option value="Yes">Yes</option>
                        <option value="No">No</option>
                      </>
                    )}
                    {leg.type === BetType.DOUBLE_CHANCE && (
                      <>
                        <option value="1X">1X (Home or Draw)</option>
                        <option value="X2">X2 (Away or Draw)</option>
                        <option value="12">12 (Home or Away)</option>
                      </>
                    )}
                    {leg.type === BetType.OVER_UNDER && (
                      <>
                        <optgroup label="Overs">
                          <option value="Over 0.5">Over 0.5</option>
                          <option value="Over 1.5">Over 1.5</option>
                          <option value="Over 2.5">Over 2.5</option>
                          <option value="Over 3.5">Over 3.5</option>
                          <option value="Over 4.5">Over 4.5</option>
                        </optgroup>
                        <optgroup label="Unders">
                          <option value="Under 0.5">Under 0.5</option>
                          <option value="Under 1.5">Under 1.5</option>
                          <option value="Under 2.5">Under 2.5</option>
                          <option value="Under 3.5">Under 3.5</option>
                          <option value="Under 4.5">Under 4.5</option>
                        </optgroup>
                      </>
                    )}
                    {leg.type === BetType.WIN_EITHER_HALF && (
                      <>
                        <option value="Home">Home (1)</option>
                        <option value="Away">Away (2)</option>
                      </>
                    )}
                    {leg.type === BetType.DRAW_NO_BET && (
                      <>
                        <option value="Home">Home (1)</option>
                        <option value="Away">Away (2)</option>
                      </>
                    )}
                    {leg.type === BetType.HANDICAP && (
                      <>
                        <optgroup label="0.5 Handicap">
                          <option value="Home (+0.5)">Home (0.5 : 0)</option>
                          <option value="Away (-0.5)">Away (0 : 0.5)</option>
                        </optgroup>
                        <optgroup label="1.5 Handicap">
                          <option value="Home (+1.5)">Home (1.5 : 0)</option>
                          <option value="Away (-1.5)">Away (0 : 1.5)</option>
                        </optgroup>
                        <optgroup label="2.5 Handicap">
                          <option value="Home (+2.5)">Home (2.5 : 0)</option>
                          <option value="Away (-2.5)">Away (0 : 2.5)</option>
                        </optgroup>
                      </>
                    )}
                    {!([BetType.MATCH_WINNER, BetType.BTTS, BetType.DOUBLE_CHANCE, BetType.OVER_UNDER, BetType.WIN_EITHER_HALF, BetType.HANDICAP, BetType.DRAW_NO_BET].includes(leg.type as BetType)) && (
                      <option value={leg.selection}>{leg.selection}</option>
                    )}
                  </select>
                </div>
              </div>
            </div>
          ))}

          <button 
            onClick={addLeg}
            className="w-full py-3 border border-dashed border-borderBase rounded-lg text-textMuted hover:text-textMain hover:bg-inputBg transition-all flex items-center justify-center gap-2"
          >
            <Plus size={18} /> Add Match
          </button>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 pt-6 border-t border-borderBase">
           <div className="space-y-1">
              <label className="text-xs font-bold text-textMuted uppercase">Stake ({symbol})</label>
              <input 
                type="text" 
                inputMode="decimal"
                value={stake}
                onChange={(e) => handleNumericChange(e.target.value, setStake)}
                className="w-full bg-inputBg border border-borderBase rounded px-4 py-3 text-textMain font-bold focus:outline-none focus:border-primary"
              />
           </div>
           <div className="space-y-1">
              <label className="text-xs font-bold text-textMuted uppercase">Total Odds</label>
              <input 
                type="text" 
                inputMode="decimal"
                value={totalOdds}
                onChange={(e) => handleNumericChange(e.target.value, setTotalOdds)}
                className="w-full bg-inputBg border border-borderBase rounded px-4 py-3 text-textMain font-bold focus:outline-none focus:border-primary"
              />
           </div>
        </div>

        <div className="bg-primary/10 rounded-lg p-4 flex justify-between items-center border border-primary/20">
          <span className="text-primary font-medium">Potential Return</span>
          <span className="text-2xl font-bold text-primary">
            {symbol}{((parseFloat(stake) || 0) * (parseFloat(totalOdds) || 0)).toFixed(2)}
          </span>
        </div>

        <div className="flex gap-4 justify-end pt-4">
          <button onClick={onCancel} className="px-6 py-3 text-textMuted hover:text-textMain">Cancel</button>
          <button 
            onClick={handleSave}
            className="px-8 py-3 rounded-lg font-bold bg-primary hover:bg-blue-600 text-white shadow-lg transition-all flex items-center gap-2"
          >
            <Save size={18} /> {isEditing ? 'Update Slip' : 'Save Bet Slip'}
          </button>
        </div>
      </div>

      {showImport && (
        <div className="fixed inset-0 z-[60] bg-background/95 flex items-center justify-center p-6 animate-fade-in">
           <div className="w-full max-w-lg bg-surface border border-borderBase rounded-xl p-6 shadow-2xl">
              <div className="flex justify-between items-center mb-4">
                 <h3 className="text-textMain font-bold flex items-center gap-2">
                   <ClipboardPaste size={18} className="text-primary" /> Import Selections
                 </h3>
                 <button onClick={() => setShowImport(false)} className="text-textMuted hover:text-textMain"><X size={20} /></button>
              </div>
              <p className="text-xs text-textMuted mb-4 italic">
                Format: Selection, Odds, Market, Match on separate lines.
              </p>
              <textarea
                value={importText}
                onChange={(e) => setImportText(e.target.value)}
                placeholder="Arsenal&#10;1.85&#10;Match Result&#10;Arsenal vs Liverpool&#10;---&#10;Over 2.5&#10;2.10&#10;Total Goals&#10;Chelsea vs Spurs"
                className="w-full h-64 bg-inputBg border border-borderBase rounded-lg p-4 text-xs font-mono text-textMain focus:outline-none focus:border-primary resize-none"
              />
              <div className="mt-4 flex justify-end gap-3">
                 <button onClick={() => setShowImport(false)} className="px-4 py-2 text-textMuted font-medium">Cancel</button>
                 <button 
                   onClick={handleImport} 
                   className="px-6 py-2 bg-primary text-white rounded-lg font-bold hover:bg-blue-600 transition-colors shadow-lg shadow-blue-500/20"
                 >
                   Process & Import
                 </button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Plus, Trash2, Save, ClipboardPaste, X, Edit3, Folder, Globe } from 'lucide-react';
import { BetType, Leg, LegStatus, Slip, SlipStatus, Currency, CURRENCY_SYMBOLS } from '../types';

interface NewSlipFormProps {
  initialData?: Slip;
  onSave: (slip: Slip) => void;
  onCancel: () => void;
  currency: Currency;
  availableFolders: string[];
  availableLeagues: string[];
}

// Robust ID generator
const generateId = () => {
  return Date.now().toString(36) + Math.random().toString(36).substring(2, 9);
};

export const NewSlipForm: React.FC<NewSlipFormProps> = ({ initialData, onSave, onCancel, currency, availableFolders, availableLeagues }) => {
  const [stake, setStake] = useState<string>(() => {
    if (initialData) return initialData.stake.toString();
    const saved = localStorage.getItem('smartbet_draft_stake');
    return saved || '10';
  });

  const [totalOdds, setTotalOdds] = useState<string>(() => {
    if (initialData) return initialData.odds.toString();
    const saved = localStorage.getItem('smartbet_draft_odds');
    return saved || '1.00';
  });

  const [folder, setFolder] = useState<string>(() => {
    if (initialData) return initialData.folder || '';
    return '';
  });

  const [legs, setLegs] = useState<Leg[]>(() => {
    if (initialData) return initialData.legs;
    const saved = localStorage.getItem('smartbet_draft_legs');
    if (saved) return JSON.parse(saved);
    return [{
      id: generateId(),
      matchName: '',
      league: '',
      date: new Date().toISOString().split('T')[0],
      type: BetType.MATCH_WINNER,
      selection: 'Home',
      status: LegStatus.PENDING,
    }];
  });

  const [showImport, setShowImport] = useState(false);
  const [importText, setImportText] = useState('');

  const symbol = CURRENCY_SYMBOLS[currency];
  const isEditing = !!initialData;

  useEffect(() => {
    if (!isEditing) {
      localStorage.setItem('smartbet_draft_stake', stake);
      localStorage.setItem('smartbet_draft_odds', totalOdds);
      localStorage.setItem('smartbet_draft_legs', JSON.stringify(legs));
    }
  }, [stake, totalOdds, legs, isEditing]);

  const clearDraft = () => {
    localStorage.removeItem('smartbet_draft_stake');
    localStorage.removeItem('smartbet_draft_odds');
    localStorage.removeItem('smartbet_draft_legs');
  };

  const addLeg = () => {
    setLegs([
      ...legs,
      {
        id: generateId(),
        matchName: '',
        league: '',
        date: new Date().toISOString().split('T')[0],
        type: BetType.MATCH_WINNER,
        selection: 'Home',
        status: LegStatus.PENDING,
      }
    ]);
  };

  const removeLeg = (id: string) => {
    if (legs.length > 1) {
      setLegs(legs.filter(l => l.id !== id));
    }
  };

  const updateLeg = (id: string, field: keyof Leg, value: any) => {
    setLegs(legs.map(l => {
      if (l.id === id) {
        const updated = { ...l, [field]: value };
        if (field === 'type') {
           if (value === BetType.MATCH_WINNER) updated.selection = 'Home';
           if (value === BetType.BTTS) updated.selection = 'Yes';
           if (value === BetType.OVER_UNDER) updated.selection = 'Over 2.5';
           if (value === BetType.DOUBLE_CHANCE) updated.selection = '1X';
           if (value === BetType.DRAW_NO_BET) updated.selection = 'Home';
           if (value === BetType.WIN_EITHER_HALF) updated.selection = 'Home';
           if (value === BetType.HANDICAP) updated.selection = 'Home (+0.5)';
           if (value === BetType.TOTAL_CORNERS) updated.selection = 'Over 9.5';
        }
        return updated;
      }
      return l;
    }));
  };

  const parseTeams = (matchName: string) => {
    const parts = matchName.split(/\s+v\s+|\s+vs\.?\s+|\s+-\s+/i);
    return {
      home: parts[0]?.trim() || 'Home',
      away: parts[1]?.trim() || 'Away'
    };
  };

  const handleNumericChange = (value: string, setter: (v: string) => void) => {
    if (value === '' || /^\d*\.?\d*$/.test(value)) {
      setter(value);
    }
  };

  const handleImport = () => {
    if (!importText.trim()) return;

    try {
      const lines = importText.split('\n').map(l => l.trim()).filter(l => l.length > 0);

      const newLegs: Leg[] = [];
      let calculatedOdds = 1;

      let i = 0;
      while (i < lines.length) {
        const selectionRaw = lines[i];
        const oddsRaw = lines[i+1];
        const marketRaw = lines[i+2];
        const matchRaw = lines[i+3];

        if (!selectionRaw || !oddsRaw || !marketRaw || !matchRaw) {
          i++;
          continue;
        }

        const oddsVal = parseFloat(oddsRaw.replace(/[^0-9.]/g, ''));
        if (isNaN(oddsVal)) {
           i++;
           continue;
        }

        let dateRaw = new Date().toISOString().split('T')[0];
        let consumedLines = 4;

        if (i + 4 < lines.length) {
          const potentialDate = lines[i+4];
          if (potentialDate.match(/\d{2}[/.-]\d{2}/) || potentialDate.toLowerCase().includes('today') || potentialDate.toLowerCase().includes('tomorrow')) {
             if (potentialDate.toLowerCase().includes('tomorrow')) {
               const d = new Date(); d.setDate(d.getDate() + 1);
               dateRaw = d.toISOString().split('T')[0];
             }
             consumedLines = 5;
          }
        }

        calculatedOdds *= oddsVal;

        let type = BetType.MATCH_WINNER;
        let selection = 'Home';
        const mUpper = marketRaw.toUpperCase();
        const sUpper = selectionRaw.toUpperCase();
        const { home, away } = parseTeams(matchRaw);

        if (mUpper.includes('BOTH') || mUpper.includes('BTTS')) {
          type = BetType.BTTS;
          selection = sUpper.includes('YES') || sUpper === 'GG' ? 'Yes' : 'No';
        } else if (mUpper.includes('OVER') || mUpper.includes('UNDER') || mUpper.includes('TOTAL')) {
          type = BetType.OVER_UNDER;
          const match = selectionRaw.match(/(\d+\.?\d*)/);
          const val = match ? match[1] : '2.5';
          selection = `${sUpper.includes('UNDER') ? 'Under' : 'Over'} ${val}`;
        } else if (mUpper.includes('DOUBLE') || mUpper.includes('DC')) {
          type = BetType.DOUBLE_CHANCE;
          if (sUpper.includes('1X') || (sUpper.includes('HOME') && sUpper.includes('DRAW'))) selection = '1X';
          else if (sUpper.includes('X2') || (sUpper.includes('AWAY') && sUpper.includes('DRAW'))) selection = 'X2';
          else selection = '12';
        } else if (mUpper.includes('1X2') || mUpper.includes('WINNER') || mUpper.includes('RESULT')) {
          type = BetType.MATCH_WINNER;
          if (sUpper.includes(away.toUpperCase()) || sUpper === '2') selection = 'Away';
          else if (sUpper.includes('DRAW') || sUpper === 'X') selection = 'Draw';
          else selection = 'Home';
        }

        newLegs.push({
          id: generateId(),
          matchName: matchRaw,
          league: '',
          date: dateRaw,
          type,
          selection,
          status: LegStatus.PENDING
        });

        i += consumedLines;
      }

      if (newLegs.length > 0) {
        setLegs(newLegs);
        setTotalOdds(calculatedOdds.toFixed(2));
        setShowImport(false);
        setImportText('');
      } else {
        alert("Couldn't find valid bet selections. Ensure the format is Selection, Odds, Market, then Match name on separate lines.");
      }
    } catch (e) {
      alert("Error parsing bet slip.");
    }
  };

  const handleSave = () => {
    if (legs.some(l => !l.matchName)) {
      alert("Please enter a match name for all selections.");
      return;
    }
    const numStake = parseFloat(stake) || 0;
    const numOdds = parseFloat(totalOdds) || 1;
    const newSlip: Slip = {
      id: initialData ? initialData.id : generateId(),
      createdAt: initialData ? initialData.createdAt : Date.now(),
      legs,
      stake: numStake,
      odds: numOdds,
      potentialReturn: numStake * numOdds,
      status: initialData ? initialData.status : SlipStatus.PENDING,
      folder: folder.trim() || undefined
    };
    onSave(newSlip);
    clearDraft();
  };

  return (
    <div className="bg-surface rounded-xl shadow-xl border border-borderBase overflow-hidden relative transition-colors">
      <div className="p-6 border-b border-borderBase flex justify-between items-center bg-inputBg">
        <h2 className="text-xl font-bold text-textMain flex items-center gap-2">
          {isEditing ? <Edit3 className="text-primary" /> : <Plus className="text-primary" />} 
          {isEditing ? 'Edit Bet Slip' : 'Create New Bet Slip'}
        </h2>
        <div className="flex gap-2">
          {!isEditing && (
            <span className="text-[10px] uppercase tracking-wider font-bold text-success/80 border border-success/20 px-2 py-1 rounded-full flex items-center bg-success/5">
              Auto-Saved
            </span>
          )}
          <button 
            onClick={() => setShowImport(true)}
            className="text-xs flex items-center gap-1 bg-surface border border-borderBase hover:bg-background text-textMain px-3 py-1.5 rounded transition-colors"
          >
            <ClipboardPaste size={14} /> Import
          </button>
        </div>
      </div>

      <div className="p-6 space-y-6">
        <div className="bg-inputBg/50 p-4 rounded-lg border border-borderBase">
            <label className="text-sm font-medium text-textMain mb-2 flex items-center gap-2">
                <Folder size={16} className="text-primary" /> Betting Folder
            </label>
            <div className="relative">
                <input
                    type="text"
                    list="folders-list"
                    value={folder}
                    onChange={(e) => setFolder(e.target.value)}
                    placeholder="e.g. Accumulator, High Stakes..."
                    className="w-full bg-surface border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                />
                <datalist id="folders-list">
                    {availableFolders.map(f => <option key={f} value={f} />)}
                </datalist>
            </div>
        </div>

        <div className="space-y-4">
          <label className="text-sm font-medium text-textMuted uppercase tracking-wider">Match Selections</label>
          {legs.map((leg, index) => (
            <div key={leg.id} className="p-4 bg-background rounded-lg border border-borderBase hover:border-textMuted transition-colors space-y-4">
              <div className="grid grid-cols-1 md:grid-cols-12 gap-4">
                <div className="md:col-span-8 space-y-1">
                  <label className="text-xs text-textMuted font-bold uppercase">Match Name</label>
                  <input
                    type="text"
                    value={leg.matchName}
                    onChange={(e) => updateLeg(leg.id, 'matchName', e.target.value)}
                    placeholder="e.g. Man City vs Arsenal"
                    className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                  />
                </div>
                <div className="md:col-span-3 space-y-1">
                  <label className="text-xs text-textMuted font-bold uppercase">Date</label>
                  <input
                    type="date"
                    value={leg.date}
                    onChange={(e) => updateLeg(leg.id, 'date', e.target.value)}
                    className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                  />
                </div>
                <div className="md:col-span-1 flex items-end justify-center pb-1">
                  <button 
                    onClick={() => removeLeg(leg.id)}
                    disabled={legs.length === 1}
                    className="p-2 rounded hover:bg-danger/20 text-danger/80 transition-colors disabled:opacity-30"
                  >
                    <Trash2 size={18} />
                  </button>
                </div>
              </div>

              {/* League Selection */}
              <div className="space-y-3 bg-inputBg/30 p-3 rounded-lg border border-borderBase/50">
                <div className="flex flex-col md:flex-row md:items-center gap-4">
                  <div className="flex-1 space-y-1">
                    <label className="text-xs text-textMuted font-bold uppercase flex items-center gap-1">
                      <Globe size={12} className="text-primary" /> League
                    </label>
                    <select
                      value={availableLeagues.includes(leg.league || '') ? (leg.league || '') : 'other'}
                      onChange={(e) => {
                        const val = e.target.value;
                        if (val !== 'other') updateLeg(leg.id, 'league', val);
                      }}
                      className="w-full bg-surface border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                    >
                      <option value="">Select League...</option>
                      {availableLeagues.map(l => <option key={l} value={l}>{l}</option>)}
                      <option value="other">Manual Entry...</option>
                    </select>
                  </div>

                  {(!availableLeagues.includes(leg.league || '') || leg.league === '') && (
                    <div className="flex-1 space-y-1">
                      <label className="text-xs text-textMuted font-bold uppercase">Manual League Name</label>
                      <input
                        type="text"
                        placeholder="Type league name..."
                        value={leg.league || ''}
                        onChange={(e) => updateLeg(leg.id, 'league', e.target.value)}
                        className="w-full bg-surface border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                      />
                    </div>
                  )}
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-xs text-textMuted font-bold uppercase">Market</label>
                  <select
                    value={leg.type}
                    onChange={(e) => updateLeg(leg.id, 'type', e.target.value)}
                    className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                  >
                    <optgroup label="Popular">
                      <option value={BetType.MATCH_WINNER}>1X2 (Full Time)</option>
                      <option value={BetType.BTTS}>BTTS</option>
                      <option value={BetType.OVER_UNDER}>Over/Under Goals</option>
                      <option value={BetType.DOUBLE_CHANCE}>Double Chance</option>
                    </optgroup>
                    <optgroup label="Other Markets">
                      <option value={BetType.DRAW_NO_BET}>Draw No Bet</option>
                      <option value={BetType.HANDICAP}>Handicap (2-Way)</option>
                      <option value={BetType.WIN_EITHER_HALF}>Win Either Half</option>
                      <option value={BetType.TOTAL_CORNERS}>Total Corners</option>
                    </optgroup>
                  </select>
                </div>
                <div className="space-y-1">
                  <label className="text-xs text-textMuted font-bold uppercase">Selection</label>
                  <select
                    value={leg.selection}
                    onChange={(e) => updateLeg(leg.id, 'selection', e.target.value)}
                    className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                  >
                    {leg.type === BetType.MATCH_WINNER && (
                      <>
                        <option value="Home">Home Win (1)</option>
                        <option value="Draw">Draw (X)</option>
                        <option value="Away">Away Win (2)</option>
                      </>
                    )}
                    {leg.type === BetType.BTTS && (
                      <>
                        <option value="Yes">Yes</option>
                        <option value="No">No</option>
                      </>
                    )}
                    {leg.type === BetType.DOUBLE_CHANCE && (
                      <>
                        <option value="1X">1X (Home or Draw)</option>
                        <option value="X2">X2 (Away or Draw)</option>
                        <option value="12">12 (Home or Away)</option>
                      </>
                    )}
                    {leg.type === BetType.OVER_UNDER && (
                      <>
                        <optgroup label="Overs">
                          <option value="Over 0.5">Over 0.5</option>
                          <option value="Over 1.5">Over 1.5</option>
                          <option value="Over 2.5">Over 2.5</option>
                          <option value="Over 3.5">Over 3.5</option>
                          <option value="Over 4.5">Over 4.5</option>
                        </optgroup>
                        <optgroup label="Unders">
                          <option value="Under 0.5">Under 0.5</option>
                          <option value="Under 1.5">Under 1.5</option>
                          <option value="Under 2.5">Under 2.5</option>
                          <option value="Under 3.5">Under 3.5</option>
                          <option value="Under 4.5">Under 4.5</option>
                        </optgroup>
                      </>
                    )}
                    {leg.type === BetType.WIN_EITHER_HALF && (
                      <>
                        <option value="Home">Home (1)</option>
                        <option value="Away">Away (2)</option>
                      </>
                    )}
                    {leg.type === BetType.DRAW_NO_BET && (
                      <>
                        <option value="Home">Home (1)</option>
                        <option value="Away">Away (2)</option>
                      </>
                    )}
                    {leg.type === BetType.TOTAL_CORNERS && (
                      <>
                        <optgroup label="Overs">
                          <option value="Over 7.5">Over 7.5</option>
                          <option value="Over 8.5">Over 8.5</option>
                          <option value="Over 9.5">Over 9.5</option>
                          <option value="Over 10.5">Over 10.5</option>
                          <option value="Over 11.5">Over 11.5</option>
                          <option value="Over 12.5">Over 12.5</option>
                        </optgroup>
                        <optgroup label="Unders">
                          <option value="Under 7.5">Under 7.5</option>
                          <option value="Under 8.5">Under 8.5</option>
                          <option value="Under 9.5">Under 9.5</option>
                          <option value="Under 10.5">Under 10.5</option>
                          <option value="Under 11.5">Under 11.5</option>
                          <option value="Under 12.5">Under 12.5</option>
                        </optgroup>
                      </>
                    )}
                    {leg.type === BetType.HANDICAP && (
                      <>
                        <optgroup label="0.5 Handicap">
                          <option value="Home (+0.5)">Home (0.5 : 0)</option>
                          <option value="Away (-0.5)">Away (0 : 0.5)</option>
                        </optgroup>
                        <optgroup label="1.5 Handicap">
                          <option value="Home (+1.5)">Home (1.5 : 0)</option>
                          <option value="Away (-1.5)">Away (0 : 1.5)</option>
                        </optgroup>
                        <optgroup label="2.5 Handicap">
                          <option value="Home (+2.5)">Home (2.5 : 0)</option>
                          <option value="Away (-2.5)">Away (0 : 2.5)</option>
                        </optgroup>
                      </>
                    )}
                    {!([BetType.MATCH_WINNER, BetType.BTTS, BetType.DOUBLE_CHANCE, BetType.OVER_UNDER, BetType.WIN_EITHER_HALF, BetType.HANDICAP, BetType.DRAW_NO_BET, BetType.TOTAL_CORNERS].includes(leg.type as BetType)) && (
                      <option value={leg.selection}>{leg.selection}</option>
                    )}
                  </select>
                </div>
              </div>
            </div>
          ))}

          <button 
            onClick={addLeg}
            className="w-full py-3 border border-dashed border-borderBase rounded-lg text-textMuted hover:text-textMain hover:bg-inputBg transition-all flex items-center justify-center gap-2"
          >
            <Plus size={18} /> Add Match
          </button>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 pt-6 border-t border-borderBase">
           <div className="space-y-1">
              <label className="text-xs font-bold text-textMuted uppercase">Stake ({symbol})</label>
              <input 
                type="text" 
                inputMode="decimal"
                value={stake}
                onChange={(e) => handleNumericChange(e.target.value, setStake)}
                className="w-full bg-inputBg border border-borderBase rounded px-4 py-3 text-textMain font-bold focus:outline-none focus:border-primary"
              />
           </div>
           <div className="space-y-1">
              <label className="text-xs font-bold text-textMuted uppercase">Total Odds</label>
              <input 
                type="text" 
                inputMode="decimal"
                value={totalOdds}
                onChange={(e) => handleNumericChange(e.target.value, setTotalOdds)}
                className="w-full bg-inputBg border border-borderBase rounded px-4 py-3 text-textMain font-bold focus:outline-none focus:border-primary"
              />
           </div>
        </div>

        <div className="bg-primary/10 rounded-lg p-4 flex justify-between items-center border border-primary/20">
          <span className="text-primary font-medium">Potential Return</span>
          <span className="text-2xl font-bold text-primary">
            {symbol}{((parseFloat(stake) || 0) * (parseFloat(totalOdds) || 0)).toFixed(2)}
          </span>
        </div>

        <div className="flex gap-4 justify-end pt-4">
          <button onClick={onCancel} className="px-6 py-3 text-textMuted hover:text-textMain">Cancel</button>
          <button 
            onClick={handleSave}
            className="px-8 py-3 rounded-lg font-bold bg-primary hover:bg-blue-600 text-white shadow-lg transition-all flex items-center gap-2"
          >
            <Save size={18} /> {isEditing ? 'Update Slip' : 'Save Bet Slip'}
          </button>
        </div>
      </div>

      {showImport && (
        <div className="fixed inset-0 z-[60] bg-background/95 flex items-center justify-center p-6 animate-fade-in">
           <div className="w-full max-w-lg bg-surface border border-borderBase rounded-xl p-6 shadow-2xl">
              <div className="flex justify-between items-center mb-4">
                 <h3 className="text-textMain font-bold flex items-center gap-2">
                   <ClipboardPaste size={18} className="text-primary" /> Import Selections
                 </h3>
                 <button onClick={() => setShowImport(false)} className="text-textMuted hover:text-textMain"><X size={20} /></button>
              </div>
              <p className="text-xs text-textMuted mb-4 italic">
                Format: Selection, Odds, Market, Match on separate lines.
              </p>
              <textarea
                value={importText}
                onChange={(e) => setImportText(e.target.value)}
                placeholder="Arsenal&#10;1.85&#10;Match Result&#10;Arsenal vs Liverpool&#10;---&#10;Over 2.5&#10;2.10&#10;Total Goals&#10;Chelsea vs Spurs"
                className="w-full h-64 bg-inputBg border border-borderBase rounded-lg p-4 text-xs font-mono text-textMain focus:outline-none focus:border-primary resize-none"
              />
              <div className="mt-4 flex justify-end gap-3">
                 <button onClick={() => setShowImport(false)} className="px-4 py-2 text-textMuted font-medium">Cancel</button>
                 <button 
                   onClick={handleImport} 
                   className="px-6 py-2 bg-primary text-white rounded-lg font-bold hover:bg-blue-600 transition-colors shadow-lg shadow-blue-500/20"
                 >
                   Process & Import
                 </button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Plus, Trash2, Save, ClipboardPaste, X, Edit3, Folder, Globe } from 'lucide-react';
import { BetType, Leg, LegStatus, Slip, SlipStatus, Currency, CURRENCY_SYMBOLS } from '../types';

interface NewSlipFormProps {
  initialData?: Slip;
  onSave: (slip: Slip) => void;
  onCancel: () => void;
  currency: Currency;
  availableFolders: string[];
  availableLeagues: string[];
}

// Robust ID generator
const generateId = () => {
  return Date.now().toString(36) + Math.random().toString(36).substring(2, 9);
};

export const NewSlipForm: React.FC<NewSlipFormProps> = ({ initialData, onSave, onCancel, currency, availableFolders, availableLeagues }) => {
  const [stake, setStake] = useState<string>(() => {
    if (initialData) return initialData.stake.toString();
    const saved = localStorage.getItem('smartbet_draft_stake');
    return saved || '10';
  });

  const [totalOdds, setTotalOdds] = useState<string>(() => {
    if (initialData) return initialData.odds.toString();
    const saved = localStorage.getItem('smartbet_draft_odds');
    return saved || '1.00';
  });

  const [folder, setFolder] = useState<string>(() => {
    if (initialData) return initialData.folder || '';
    return '';
  });

  const [legs, setLegs] = useState<Leg[]>(() => {
    if (initialData) return initialData.legs;
    const saved = localStorage.getItem('smartbet_draft_legs');
    if (saved) return JSON.parse(saved);
    return [{
      id: generateId(),
      matchName: '',
      league: '',
      date: new Date().toISOString().split('T')[0],
      type: BetType.MATCH_WINNER,
      selection: 'Home',
      status: LegStatus.PENDING,
    }];
  });

  const [showImport, setShowImport] = useState(false);
  const [importText, setImportText] = useState('');

  const symbol = CURRENCY_SYMBOLS[currency];
  const isEditing = !!initialData;

  useEffect(() => {
    if (!isEditing) {
      localStorage.setItem('smartbet_draft_stake', stake);
      localStorage.setItem('smartbet_draft_odds', totalOdds);
      localStorage.setItem('smartbet_draft_legs', JSON.stringify(legs));
    }
  }, [stake, totalOdds, legs, isEditing]);

  const clearDraft = () => {
    localStorage.removeItem('smartbet_draft_stake');
    localStorage.removeItem('smartbet_draft_odds');
    localStorage.removeItem('smartbet_draft_legs');
  };

  const addLeg = () => {
    setLegs([
      ...legs,
      {
        id: generateId(),
        matchName: '',
        league: '',
        date: new Date().toISOString().split('T')[0],
        type: BetType.MATCH_WINNER,
        selection: 'Home',
        status: LegStatus.PENDING,
      }
    ]);
  };

  const removeLeg = (id: string) => {
    if (legs.length > 1) {
      setLegs(legs.filter(l => l.id !== id));
    }
  };

  const updateLeg = (id: string, field: keyof Leg, value: any) => {
    setLegs(legs.map(l => {
      if (l.id === id) {
        const updated = { ...l, [field]: value };
        if (field === 'type') {
           if (value === BetType.MATCH_WINNER) updated.selection = 'Home';
           if (value === BetType.BTTS) updated.selection = 'Yes';
           if (value === BetType.OVER_UNDER) updated.selection = 'Over 2.5';
           if (value === BetType.DOUBLE_CHANCE) updated.selection = '1X';
           if (value === BetType.DRAW_NO_BET) updated.selection = 'Home';
           if (value === BetType.WIN_EITHER_HALF) updated.selection = 'Home';
           if (value === BetType.HANDICAP) updated.selection = 'Home (+0.5)';
           if (value === BetType.TOTAL_CORNERS) updated.selection = 'Over 9.5';
           if (value === BetType.WINNING_MARGIN) updated.selection = 'Home By 1';
        }
        return updated;
      }
      return l;
    }));
  };

  const parseTeams = (matchName: string) => {
    const parts = matchName.split(/\s+v\s+|\s+vs\.?\s+|\s+-\s+/i);
    return {
      home: parts[0]?.trim() || 'Home',
      away: parts[1]?.trim() || 'Away'
    };
  };

  const handleNumericChange = (value: string, setter: (v: string) => void) => {
    if (value === '' || /^\d*\.?\d*$/.test(value)) {
      setter(value);
    }
  };

  const handleImport = () => {
    if (!importText.trim()) return;

    try {
      const lines = importText.split('\n').map(l => l.trim()).filter(l => l.length > 0);

      const newLegs: Leg[] = [];
      let calculatedOdds = 1;

      let i = 0;
      while (i < lines.length) {
        const selectionRaw = lines[i];
        const oddsRaw = lines[i+1];
        const marketRaw = lines[i+2];
        const matchRaw = lines[i+3];

        if (!selectionRaw || !oddsRaw || !marketRaw || !matchRaw) {
          i++;
          continue;
        }

        const oddsVal = parseFloat(oddsRaw.replace(/[^0-9.]/g, ''));
        if (isNaN(oddsVal)) {
           i++;
           continue;
        }

        let dateRaw = new Date().toISOString().split('T')[0];
        let consumedLines = 4;

        if (i + 4 < lines.length) {
          const potentialDate = lines[i+4];
          if (potentialDate.match(/\d{2}[/.-]\d{2}/) || potentialDate.toLowerCase().includes('today') || potentialDate.toLowerCase().includes('tomorrow')) {
             if (potentialDate.toLowerCase().includes('tomorrow')) {
               const d = new Date(); d.setDate(d.getDate() + 1);
               dateRaw = d.toISOString().split('T')[0];
             }
             consumedLines = 5;
          }
        }

        calculatedOdds *= oddsVal;

        let type = BetType.MATCH_WINNER;
        let selection = 'Home';
        const mUpper = marketRaw.toUpperCase();
        const sUpper = selectionRaw.toUpperCase();
        const { home, away } = parseTeams(matchRaw);

        if (mUpper.includes('BOTH') || mUpper.includes('BTTS')) {
          type = BetType.BTTS;
          selection = sUpper.includes('YES') || sUpper === 'GG' ? 'Yes' : 'No';
        } else if (mUpper.includes('OVER') || mUpper.includes('UNDER') || mUpper.includes('TOTAL')) {
          type = BetType.OVER_UNDER;
          const match = selectionRaw.match(/(\d+\.?\d*)/);
          const val = match ? match[1] : '2.5';
          selection = `${sUpper.includes('UNDER') ? 'Under' : 'Over'} ${val}`;
        } else if (mUpper.includes('DOUBLE') || mUpper.includes('DC')) {
          type = BetType.DOUBLE_CHANCE;
          if (sUpper.includes('1X') || (sUpper.includes('HOME') && sUpper.includes('DRAW'))) selection = '1X';
          else if (sUpper.includes('X2') || (sUpper.includes('AWAY') && sUpper.includes('DRAW'))) selection = 'X2';
          else selection = '12';
        } else if (mUpper.includes('1X2') || mUpper.includes('WINNER') || mUpper.includes('RESULT')) {
          type = BetType.MATCH_WINNER;
          if (sUpper.includes(away.toUpperCase()) || sUpper === '2') selection = 'Away';
          else if (sUpper.includes('DRAW') || sUpper === 'X') selection = 'Draw';
          else selection = 'Home';
        }

        newLegs.push({
          id: generateId(),
          matchName: matchRaw,
          league: '',
          date: dateRaw,
          type,
          selection,
          status: LegStatus.PENDING
        });

        i += consumedLines;
      }

      if (newLegs.length > 0) {
        setLegs(newLegs);
        setTotalOdds(calculatedOdds.toFixed(2));
        setShowImport(false);
        setImportText('');
      } else {
        alert("Couldn't find valid bet selections. Ensure the format is Selection, Odds, Market, then Match name on separate lines.");
      }
    } catch (e) {
      alert("Error parsing bet slip.");
    }
  };

  const handleSave = () => {
    if (legs.some(l => !l.matchName)) {
      alert("Please enter a match name for all selections.");
      return;
    }
    const numStake = parseFloat(stake) || 0;
    const numOdds = parseFloat(totalOdds) || 1;
    const newSlip: Slip = {
      id: initialData ? initialData.id : generateId(),
      createdAt: initialData ? initialData.createdAt : Date.now(),
      legs,
      stake: numStake,
      odds: numOdds,
      potentialReturn: numStake * numOdds,
      status: initialData ? initialData.status : SlipStatus.PENDING,
      folder: folder.trim() || undefined
    };
    onSave(newSlip);
    clearDraft();
  };

  return (
    <div className="bg-surface rounded-xl shadow-xl border border-borderBase overflow-hidden relative transition-colors">
      <div className="p-6 border-b border-borderBase flex justify-between items-center bg-inputBg">
        <h2 className="text-xl font-bold text-textMain flex items-center gap-2">
          {isEditing ? <Edit3 className="text-primary" /> : <Plus className="text-primary" />} 
          {isEditing ? 'Edit Bet Slip' : 'Create New Bet Slip'}
        </h2>
        <div className="flex gap-2">
          {!isEditing && (
            <span className="text-[10px] uppercase tracking-wider font-bold text-success/80 border border-success/20 px-2 py-1 rounded-full flex items-center bg-success/5">
              Auto-Saved
            </span>
          )}
          <button 
            onClick={() => setShowImport(true)}
            className="text-xs flex items-center gap-1 bg-surface border border-borderBase hover:bg-background text-textMain px-3 py-1.5 rounded transition-colors"
          >
            <ClipboardPaste size={14} /> Import
          </button>
        </div>
      </div>

      <div className="p-6 space-y-6">
        <div className="bg-inputBg/50 p-4 rounded-lg border border-borderBase">
            <label className="text-sm font-medium text-textMain mb-2 flex items-center gap-2">
                <Folder size={16} className="text-primary" /> Betting Folder
            </label>
            <div className="relative">
                <input
                    type="text"
                    list="folders-list"
                    value={folder}
                    onChange={(e) => setFolder(e.target.value)}
                    placeholder="e.g. Accumulator, High Stakes..."
                    className="w-full bg-surface border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary"
                />
                <datalist id="folders-list">
                    {availableFolders.map(f => <option key={f} value={f} />)}
                </datalist>
            </div>
        </div>

        <div className="space-y-4">
          <label className="text-sm font-medium text-textMuted uppercase tracking-wider">Match Selections</label>
          {legs.map((leg, index) => {
            const { home, away } = parseTeams(leg.matchName);
            return (
