import { GoogleGenAI } from "@google/genai";
import { Slip, Leg, LegStatus, ValidationResult } from "../types";

// Initialize Gemini Client
const apiKey = process.env.API_KEY || '';
const ai = new GoogleGenAI({ apiKey });

export interface ValidationResponse {
  results: ValidationResult[];
  sources: string[];
}

/**
 * Validates bet slip legs using Gemini 3 Flash.
 * Enforces strict settlement only for finished matches.
 */
export const validateSlipWithGemini = async (slip: Slip): Promise<ValidationResponse> => {
  if (!apiKey) {
    throw new Error("API Key is missing.");
  }

  const legsDescription = slip.legs.map(leg => {
    const parts = leg.matchName.split(/\s+v\s+|\s+vs\.?\s+|\s+-\s+/i);
    const home = parts[0]?.trim() || 'Home';
    const away = parts[1]?.trim() || 'Away';

    return `ID:${leg.id}|Match:${home} vs ${away}|Date:${leg.date}|Market:${leg.type}|Selection:${leg.selection}`;
  }).join('\n');

  const prompt = `
    Find current scores and match statuses for these sports matches.

    CRITICAL SETTLEMENT RULES:
    1. ONLY return status "WON" or "LOST" if the match is officially FINISHED (FT / Full Time).
    2. If the match is LIVE (e.g. 75th minute), HT (Half Time), or NOT STARTED, the status MUST be "PENDING".
    3. If the match is POSTPONED or CANCELLED, status is "VOID".
    4. Market Verification Logic:
       - 1X2: Result at FT.
       - BTTS: Both scored at FT?
       - OVER_UNDER: Total goals at FT.
       - TEAM_TOTAL: Total goals scored by the specific team (Home or Away) at FT.
       - HANDICAP: Settle based on FT score plus/minus the handicap value for the chosen team.
       - TEN_MINS_1X2: Settle based on the score at exactly the 10-minute mark (10:00). If no goals are scored in the first 10 minutes, the selection "Draw (1-10')" is WON.
       - 1X2_BTTS: Combined market. WON if BOTH the match outcome (1, X, or 2) and the BTTS status (Yes/No) match the selection (e.g. "Home & Yes").
       - WIN_EITHER_HALF: The selection format is "Team - 1stHalfAnswer/2ndHalfAnswer" (e.g. "Home - Yes/No"). 
         "Yes" means the team won that half (treat as starting 0-0). 
         Settle as WON only if both half results match the selection.
       - WINNING_MARGIN: Calculate goal difference at FT.
       - HALVES_BTTS: Both scored in both halves.

    INPUTS:
    ${legsDescription}

    OUTPUT ONLY JSON ARRAY:
    \`\`\`json
    [
      { 
        "legId": "...", 
        "status": "WON|LOST|VOID|PENDING", 
        "score": "X-Y (Status e.g. FT, HT, 65', PPD)", 
        "reason": "Brief detail on why settled or why pending" 
      }
    ]
    \`\`\`
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        temperature: 0,
      },
    });

    const text = response.text || '';

    const sources: string[] = [];
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
    chunks.forEach(chunk => {
      if (chunk.web?.uri) {
        sources.push(chunk.web.uri);
      }
    });

    const jsonMatch = text.match(/```json\s*([\s\S]*?)\s*```/) || text.match(/\[\s*\{[\s\S]*\}\s*\]/);

    if (!jsonMatch) {
      throw new Error("No structured results found.");
    }

    const jsonString = jsonMatch[1] || jsonMatch[0];
    const results = JSON.parse(jsonString) as ValidationResult[];

    return { results, sources };

  } catch (error) {
    console.error("Gemini Validation Error:", error);
    throw error;
  }
};

import React, { useState, useEffect } from 'react';
import { Plus, Trash2, Save, ClipboardPaste, X, Edit3, Folder, Globe } from 'lucide-react';
import { BetType, Leg, LegStatus, Slip, SlipStatus, Currency, CURRENCY_SYMBOLS } from '../types';

interface NewSlipFormProps {
  initialData?: Slip;
  onSave: (slip: Slip) => void;
  onCancel: () => void;
  currency: Currency;
  availableFolders: string[];
  availableLeagues: string[];
}

// Robust ID generator
const generateId = () => {
  return Date.now().toString(36) + Math.random().toString(36).substring(2, 9);
};

export const NewSlipForm: React.FC<NewSlipFormProps> = ({ initialData, onSave, onCancel, currency, availableFolders, availableLeagues }) => {
  const [stake, setStake] = useState<string>(() => {
    if (initialData) return initialData.stake.toString();
    const saved = localStorage.getItem('smartbet_draft_stake');
    return saved || '10';
  });

  const [totalOdds, setTotalOdds] = useState<string>(() => {
    if (initialData) return initialData.odds.toString();
    const saved = localStorage.getItem('smartbet_draft_odds');
    return saved || '1.00';
  });

  const [folder, setFolder] = useState<string>(() => {
    if (initialData) return initialData.folder || '';
    return '';
  });

  const [legs, setLegs] = useState<Leg[]>(() => {
    if (initialData) return initialData.legs;
    const saved = localStorage.getItem('smartbet_draft_legs');
    if (saved) return JSON.parse(saved);
    return [{
      id: generateId(),
      matchName: '',
      league: '',
      date: new Date().toISOString().split('T')[0],
      type: BetType.MATCH_WINNER,
      selection: 'Home',
      status: LegStatus.PENDING,
    }];
  });

  const [showImport, setShowImport] = useState(false);
  const [importText, setImportText] = useState('');

  const symbol = CURRENCY_SYMBOLS[currency];
  const isEditing = !!initialData;

  useEffect(() => {
    if (!isEditing) {
      localStorage.setItem('smartbet_draft_stake', stake);
      localStorage.setItem('smartbet_draft_odds', totalOdds);
      localStorage.setItem('smartbet_draft_legs', JSON.stringify(legs));
    }
  }, [stake, totalOdds, legs, isEditing]);

  const clearDraft = () => {
    localStorage.removeItem('smartbet_draft_stake');
    localStorage.removeItem('smartbet_draft_odds');
    localStorage.removeItem('smartbet_draft_legs');
  };

  const addLeg = () => {
    setLegs([
      ...legs,
      {
        id: generateId(),
        matchName: '',
        league: '',
        date: new Date().toISOString().split('T')[0],
        type: BetType.MATCH_WINNER,
        selection: 'Home',
        status: LegStatus.PENDING,
      }
    ]);
  };

  const removeLeg = (id: string) => {
    if (legs.length > 1) {
      setLegs(legs.filter(l => l.id !== id));
    }
  };

  const updateLeg = (id: string, field: keyof Leg, value: any) => {
    setLegs(legs.map(l => {
      if (l.id === id) {
        const updated = { ...l, [field]: value };
        if (field === 'type') {
           if (value === BetType.MATCH_WINNER) updated.selection = 'Home';
           if (value === BetType.BTTS) updated.selection = 'Yes';
           if (value === BetType.OVER_UNDER) updated.selection = 'Over 2.5';
           if (value === BetType.DOUBLE_CHANCE) updated.selection = '1X';
           if (value === BetType.DRAW_NO_BET) updated.selection = 'Home';
           if (value === BetType.WIN_EITHER_HALF) updated.selection = 'Home - Yes/No';
           if (value === BetType.HANDICAP) updated.selection = 'Home (-0.5)';
           if (value === BetType.TOTAL_CORNERS) updated.selection = 'Over 9.5';
           if (value === BetType.WINNING_MARGIN) updated.selection = 'Home By 1';
           if (value === BetType.HALVES_BTTS) updated.selection = 'No/No';
           if (value === BetType.TEAM_TOTAL) updated.selection = 'Home Over 0.5';
           if (value === BetType.TEN_MINS_1X2) updated.selection = 'Home (1-10\')';
           if (value === BetType.MATCH_RESULT_AND_BTTS) updated.selection = 'Home & Yes';
           if (value === BetType.ODD_EVEN) updated.selection = 'Odd';
        }
        return updated;
      }
      return l;
    }));
  };

  const parseTeams = (matchName: string) => {
    const parts = matchName.split(/\s+v\s+|\s+vs\.?\s+|\s+-\s+/i);
    return {
      home: parts[0]?.trim() || 'Home',
      away: parts[1]?.trim() || 'Away'
    };
  };

  const handleNumericChange = (value: string, setter: (v: string) => void) => {
    if (value === '' || /^\d*\.?\d*$/.test(value)) {
      setter(value);
    }
  };

  const handleImport = () => {
    if (!importText.trim()) return;

    try {
      const lines = importText.split('\n').map(l => l.trim());
      const newLegs: Leg[] = [];
      let calculatedOdds = 1;
      let i = 0;

      while (i < lines.length) {
        if (!lines[i]) { i++; continue; }

        const selectionRaw = lines[i];
        const oddsRaw = lines[i+1];
        const marketRaw = lines[i+2];
        const matchRaw = lines[i+3];

        if (!selectionRaw || !oddsRaw || !marketRaw || !matchRaw) { i++; continue; }

        const oddsVal = parseFloat(oddsRaw.replace(/[^0-9.]/g, ''));
        if (isNaN(oddsVal) || !oddsRaw.match(/^\d*\.?\d*$/)) { i++; continue; }

        let dateRaw = new Date().toISOString().split('T')[0];
        let metadataIndex = i + 4;
        while (metadataIndex < lines.length && lines[metadataIndex]) {
          const meta = lines[metadataIndex].toLowerCase();
          if (meta.includes('today')) dateRaw = new Date().toISOString().split('T')[0];
          else if (meta.includes('tomorrow')) {
            const d = new Date(); d.setDate(d.getDate() + 1);
            dateRaw = d.toISOString().split('T')[0];
          }
          metadataIndex++;
        }

        calculatedOdds *= oddsVal;
        let type = BetType.MATCH_WINNER;
        let selection = selectionRaw;
        const mUpper = marketRaw.toUpperCase();
        const sUpper = selectionRaw.toUpperCase();
        const { home, away } = parseTeams(matchRaw);

        if (mUpper.includes('BOTH TEAMS TO SCORE') || mUpper.includes('BTTS') || mUpper.includes('GG/NG')) {
          type = BetType.BTTS;
          if (sUpper === 'NO' || sUpper === 'NG') selection = 'No';
          else if (sUpper === 'YES' || sUpper === 'GG') selection = 'Yes';
        } else if (mUpper.includes('WIN EITHER HALF')) {
          type = BetType.WIN_EITHER_HALF;
        } else if (mUpper.includes('TEAM TOTAL') || mUpper.includes('TOTAL') && (mUpper.includes(home.toUpperCase()) || mUpper.includes(away.toUpperCase()))) {
          type = BetType.TEAM_TOTAL;
        } else if (mUpper.includes('OVER') || mUpper.includes('UNDER') || mUpper.includes('TOTAL GOALS')) {
          type = BetType.OVER_UNDER;
        } else if (mUpper.includes('DOUBLE CHANCE')) {
          type = BetType.DOUBLE_CHANCE;
        } else if (mUpper.includes('1X2') || mUpper.includes('MATCH RESULT')) {
          type = BetType.MATCH_WINNER;
        }

        newLegs.push({ id: generateId(), matchName: matchRaw, date: dateRaw, type, selection, status: LegStatus.PENDING });
        i = metadataIndex;
      }

      if (newLegs.length > 0) {
        setLegs(newLegs);
        setTotalOdds(calculatedOdds.toFixed(2));
        setShowImport(false);
        setImportText('');
      } else {
        alert("Couldn't find valid bet selections.");
      }
    } catch (e) {
      alert("Error parsing bet slip.");
    }
  };

  const handleSave = () => {
