              <div className="mt-4 flex justify-end gap-3">
                 <button onClick={() => setShowImport(false)} className="px-4 py-2 text-textMuted font-medium">Cancel</button>
                 <button onClick={handleImport} className="px-6 py-2 bg-primary text-white rounded-lg font-bold hover:bg-blue-600 transition-colors shadow-lg">Import</button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

import { GoogleGenAI } from "@google/genai";
import { Slip, Leg, LegStatus, ValidationResult } from "../types";

// Initialize Gemini Client
const apiKey = process.env.API_KEY || '';
const ai = new GoogleGenAI({ apiKey });

export interface ValidationResponse {
  results: ValidationResult[];
  sources: string[];
}

/**
 * Validates bet slip legs using Gemini 3 Flash.
 * Enforces strict settlement only for finished matches.
 */
export const validateSlipWithGemini = async (slip: Slip): Promise<ValidationResponse> => {
  if (!apiKey) {
    throw new Error("API Key is missing.");
  }

  const legsDescription = slip.legs.map(leg => {
    const parts = leg.matchName.split(/\s+v\s+|\s+vs\.?\s+|\s+-\s+/i);
    const home = parts[0]?.trim() || 'Home';
    const away = parts[1]?.trim() || 'Away';

    return `ID:${leg.id}|Match:${home} vs ${away}|Date:${leg.date}|Market:${leg.type}|Selection:${leg.selection}`;
  }).join('\n');

  const prompt = `
    Find current scores and match statuses for these sports matches.

    CRITICAL SETTLEMENT RULES:
    1. ONLY return status "WON" or "LOST" if the match is officially FINISHED (FT / Full Time).
    2. If the match is LIVE (e.g. 75th minute), HT (Half Time), or NOT STARTED, the status MUST be "PENDING".
    3. If the match is POSTPONED or CANCELLED, status is "VOID".
    4. Market Verification Logic:
       - 1X2: Result at FT.
       - BTTS: Both scored at FT?
       - OVER_UNDER: Total goals at FT.
       - TEAM_TOTAL: Total goals scored by the specific team (Home or Away) at FT.
       - HANDICAP: Settle based on FT score plus/minus the handicap value for the chosen team.
       - ODD_EVEN: WON if total match goals (Home + Away) is Odd or Even as selected. Note: 0 goals is settled as Even.
       - BOOKINGS: Settle based on the total number of cards (Yellow=1, Red=1) shown to active players. A second yellow leading to a red counts as 2 cards in total for that player.
       - TEN_MINS_1X2: Settle based on the score at exactly the 10-minute mark (10:00). If no goals are scored in the first 10 minutes, the selection "Draw (1-10')" is WON.
       - 1X2_BTTS: Combined market. WON if BOTH the match outcome (1, X, or 2) and the BTTS status (Yes/No) match the selection (e.g. "Home & Yes").
       - WIN_EITHER_HALF: The selection format is "Team - 1stHalfAnswer/2ndHalfAnswer" (e.g. "Home - Yes/No"). 
         "Yes" means the team won that half (treat as starting 0-0). 
         Settle as WON only if both half results match the selection.
       - WINNING_MARGIN: Calculate goal difference at FT.
       - HALVES_BTTS: Both scored in both halves.

    INPUTS:
    ${legsDescription}

    OUTPUT ONLY JSON ARRAY:
    \`\`\`json
    [
      { 
        "legId": "...", 
        "status": "WON|LOST|VOID|PENDING", 
        "score": "X-Y (Status e.g. FT, HT, 65', PPD)", 
        "reason": "Brief detail on why settled or why pending" 
      }
    ]
    \`\`\`
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        temperature: 0,
      },
    });

    const text = response.text || '';

    const sources: string[] = [];
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
    chunks.forEach(chunk => {
      if (chunk.web?.uri) {
        sources.push(chunk.web.uri);
      }
    });

    const jsonMatch = text.match(/```json\s*([\s\S]*?)\s*```/) || text.match(/\[\s*\{[\s\S]*\}\s*\]/);

    if (!jsonMatch) {
      throw new Error("No structured results found.");
    }

    const jsonString = jsonMatch[1] || jsonMatch[0];
    const results = JSON.parse(jsonString) as ValidationResult[];

    return { results, sources };

  } catch (error) {
    console.error("Gemini Validation Error:", error);
    throw error;
  }
};

export enum BetType {
  MATCH_WINNER = '1X2',
  BTTS = 'BTTS',
  OVER_UNDER = 'OVER_UNDER',
  DOUBLE_CHANCE = 'DOUBLE_CHANCE',
  DRAW_NO_BET = 'DRAW_NO_BET',
  TOTAL_CORNERS = 'TOTAL_CORNERS',
  HANDICAP = 'HANDICAP',
  BOOKINGS = 'BOOKINGS',
  BOOKINGS_1X2 = 'BOOKINGS_1X2',
  SENDING_OFF = 'SENDING_OFF',
  EXACT_GOALS = 'EXACT_GOALS',
  ODD_EVEN = 'ODD_EVEN',
  WINNING_MARGIN = 'WINNING_MARGIN',
  TEAM_TOTAL = 'TEAM_TOTAL',

  // Halves Markets
  HALF_TIME_WINNER = '1ST_HALF_1X2',
  HALF_TIME_DOUBLE_CHANCE = '1ST_HALF_DC',
  HALF_TIME_BTTS = '1ST_HALF_BTTS',
  HALVES_BTTS = '1ST_2ND_HALF_BTTS', // e.g. Yes/Yes
  HALF_TIME_1ST_GOAL = '1ST_HALF_1ST_GOAL',
  HALF_TIME_1ST_CORNER = '1ST_HALF_1ST_CORNER',
  HALF_TIME_WINNER_AND_BTTS = '1ST_HALF_1X2_BTTS',
  WIN_EITHER_HALF = 'WIN_EITHER_HALF',

  // Time-based Markets
  TEN_MINS_1X2 = '10_MIN_1X2',

  // Combined Markets
  MATCH_RESULT_AND_BTTS = '1X2_BTTS',
}

export enum LegStatus {
  PENDING = 'PENDING',
  WON = 'WON',
  LOST = 'LOST',
  VOID = 'VOID'
}

export enum SlipStatus {
  PENDING = 'PENDING',
  WON = 'WON',
  LOST = 'LOST',
  VOID = 'VOID'
}

export type Currency = 'USD' | 'GBP' | 'ZAR';

export const CURRENCY_SYMBOLS: Record<Currency, string> = {
  USD: '$',
  GBP: '£',
  ZAR: 'R'
};

export interface Leg {
  id: string;
  matchName: string; // e.g., "Arsenal vs Liverpool"
