import { GoogleGenAI } from "@google/genai";
import { Slip, Leg, LegStatus, ValidationResult } from "../types";

// Initialize Gemini Client
const apiKey = process.env.API_KEY || '';
const ai = new GoogleGenAI({ apiKey });

export interface ValidationResponse {
  results: ValidationResult[];
  sources: string[];
}

/**
 * Validates bet slip legs using Gemini 3 Flash.
 * Enforces strict settlement only for finished matches.
 */
export const validateSlipWithGemini = async (slip: Slip): Promise<ValidationResponse> => {
  if (!apiKey) {
    throw new Error("API Key is missing.");
  }

  const legsDescription = slip.legs.map(leg => {
    const parts = leg.matchName.split(/\s+v\s+|\s+vs\.?\s+|\s+-\s+/i);
    const home = parts[0]?.trim() || 'Home';
    const away = parts[1]?.trim() || 'Away';

    return `ID:${leg.id}|Match:${home} vs ${away}|Date:${leg.date}|Market:${leg.type}|Selection:${leg.selection}`;
  }).join('\n');

  const prompt = `
    Find current scores and match statuses for these sports matches.

    CRITICAL SETTLEMENT RULES:
    1. ONLY return status "WON" or "LOST" if the match is officially FINISHED (FT / Full Time).
    2. If the match is LIVE (e.g. 75th minute), HT (Half Time), or NOT STARTED, the status MUST be "PENDING".
    3. If the match is POSTPONED or CANCELLED, status is "VOID".
    4. Market Verification Logic:
       - 1X2: Result at FT.
       - BTTS: Both scored at FT?
       - SENDING_OFF: WON if at least one player was shown a Red Card (direct or second yellow). "Yes" selection wins if card shown, "No" selection wins if no card shown.
       - OVER_UNDER: Total goals at FT.
       - TEAM_TOTAL: Total goals scored by the specific team (Home or Away) at FT.
       - HANDICAP: Settle based on FT score plus/minus the handicap value for the chosen team.
       - ODD_EVEN: WON if total match goals (Home + Away) is Odd or Even as selected. Note: 0 goals is settled as Even.
       - BOOKINGS: Settle based on the total number of cards (Yellow=1, Red=1) shown to active players. A second yellow leading to a red counts as 2 cards in total for that player.
       - BOOKINGS_1X2: Settle based on which team received more cards at FT. "Home" means Home team had more cards, "Away" means Away team had more cards, "Draw" means both had the same count.
       - CORNER_1X2: Settle based on which team had more corner kicks awarded at FT. "Home" means Home team had more corners, "Away" means Away team had more corners, "Draw" means both had the same count.
       - TOTAL_CORNERS: Settle based on total number of corners in the match at FT (Home + Away).
       - TEN_MINS_1X2: Settle based on the score at exactly the 10-minute mark (10:00). If no goals are scored in the first 10 minutes, the selection "Draw (1-10')" is WON.
       - 1X2_BTTS: Combined market. WON if BOTH the match outcome (1, X, or 2) and the BTTS status (Yes/No) match the selection (e.g. "Home & Yes").
       - WIN_EITHER_HALF: The selection format is "Team - 1stHalfAnswer/2ndHalfAnswer" (e.g. "Home - Yes/No"). 
         "Yes" means the team won that half (treat as starting 0-0). 
         Settle as WON only if both half results match the selection.
       - WINNING_MARGIN: Calculate goal difference at FT.
       - HALVES_BTTS: Both scored in both halves.

    INPUTS:
    ${legsDescription}

    OUTPUT ONLY JSON ARRAY:
    \`\`\`json
    [
      { 
        "legId": "...", 
        "status": "WON|LOST|VOID|PENDING", 
        "score": "X-Y (Status e.g. FT, HT, 65', PPD)", 
        "reason": "Brief detail on why settled or why pending" 
      }
    ]
    \`\`\`
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        temperature: 0,
      },
    });

    const text = response.text || '';

    const sources: string[] = [];
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
    chunks.forEach(chunk => {
      if (chunk.web?.uri) {
        sources.push(chunk.web.uri);
      }
    });

    const jsonMatch = text.match(/```json\s*([\s\S]*?)\s*```/) || text.match(/\[\s*\{[\s\S]*\}\s*\]/);

    if (!jsonMatch) {
      throw new Error("No structured results found.");
    }

    const jsonString = jsonMatch[1] || jsonMatch[0];
    const results = JSON.parse(jsonString) as ValidationResult[];

    return { results, sources };

  } catch (error) {
    console.error("Gemini Validation Error:", error);
    throw error;
  }
};

import React, { useState, useEffect } from 'react';
import { Plus, Trash2, Save, ClipboardPaste, X, Edit3, Folder, Globe } from 'lucide-react';
import { BetType, Leg, LegStatus, Slip, SlipStatus, Currency, CURRENCY_SYMBOLS } from '../types';

interface NewSlipFormProps {
  initialData?: Slip;
  onSave: (slip: Slip) => void;
  onCancel: () => void;
  currency: Currency;
  availableFolders: string[];
  availableLeagues: string[];
}

// Robust ID generator
const generateId = () => {
  return Date.now().toString(36) + Math.random().toString(36).substring(2, 9);
};

export const NewSlipForm: React.FC<NewSlipFormProps> = ({ initialData, onSave, onCancel, currency, availableFolders, availableLeagues }) => {
  const [stake, setStake] = useState<string>(() => {
    if (initialData) return initialData.stake.toString();
    const saved = localStorage.getItem('smartbet_draft_stake');
    return saved || '10';
  });

  const [totalOdds, setTotalOdds] = useState<string>(() => {
    if (initialData) return initialData.odds.toString();
    const saved = localStorage.getItem('smartbet_draft_odds');
    return saved || '1.00';
  });

  const [folder, setFolder] = useState<string>(() => {
    if (initialData) return initialData.folder || '';
    return '';
  });

  const [legs, setLegs] = useState<Leg[]>(() => {
    if (initialData) return initialData.legs;
    const saved = localStorage.getItem('smartbet_draft_legs');
    if (saved) return JSON.parse(saved);
    return [{
      id: generateId(),
      matchName: '',
      league: '',
      date: new Date().toISOString().split('T')[0],
      type: BetType.MATCH_WINNER,
      selection: 'Home',
      status: LegStatus.PENDING,
    }];
  });

  const [showImport, setShowImport] = useState(false);
  const [importText, setImportText] = useState('');

  const symbol = CURRENCY_SYMBOLS[currency];
  const isEditing = !!initialData;

  useEffect(() => {
    if (!isEditing) {
      localStorage.setItem('smartbet_draft_stake', stake);
      localStorage.setItem('smartbet_draft_odds', totalOdds);
      localStorage.setItem('smartbet_draft_legs', JSON.stringify(legs));
    }
  }, [stake, totalOdds, legs, isEditing]);

  const clearDraft = () => {
    localStorage.removeItem('smartbet_draft_stake');
    localStorage.removeItem('smartbet_draft_odds');
    localStorage.removeItem('smartbet_draft_legs');
  };

  const addLeg = () => {
    setLegs([
      ...legs,
      {
        id: generateId(),
        matchName: '',
        league: '',
        date: new Date().toISOString().split('T')[0],
        type: BetType.MATCH_WINNER,
        selection: 'Home',
        status: LegStatus.PENDING,
      }
    ]);
  };

  const removeLeg = (id: string) => {
    if (legs.length > 1) {
      setLegs(legs.filter(l => l.id !== id));
    }
  };

  const updateLeg = (id: string, field: keyof Leg, value: any) => {
    setLegs(legs.map(l => {
      if (l.id === id) {
        const updated = { ...l, [field]: value };
        if (field === 'type') {
           if (value === BetType.MATCH_WINNER) updated.selection = 'Home';
           if (value === BetType.BTTS) updated.selection = 'Yes';
           if (value === BetType.SENDING_OFF) updated.selection = 'Yes';
           if (value === BetType.OVER_UNDER) updated.selection = 'Over 2.5';
           if (value === BetType.DOUBLE_CHANCE) updated.selection = '1X';
           if (value === BetType.DRAW_NO_BET) updated.selection = 'Home';
           if (value === BetType.WIN_EITHER_HALF) updated.selection = 'Home - Yes/No';
           if (value === BetType.HANDICAP) updated.selection = 'Home (-0.5)';
           if (value === BetType.TOTAL_CORNERS) updated.selection = 'Over 9.5';
           if (value === BetType.CORNER_1X2) updated.selection = 'Home';
           if (value === BetType.WINNING_MARGIN) updated.selection = 'Home By 1';
           if (value === BetType.HALVES_BTTS) updated.selection = 'No/No';
           if (value === BetType.TEAM_TOTAL) updated.selection = 'Home Over 0.5';
           if (value === BetType.TEN_MINS_1X2) updated.selection = 'Home (1-10\')';
           if (value === BetType.MATCH_RESULT_AND_BTTS) updated.selection = 'Home & Yes';
           if (value === BetType.ODD_EVEN) updated.selection = 'Odd';
           if (value === BetType.BOOKINGS) updated.selection = 'Over 3.5';
           if (value === BetType.BOOKINGS_1X2) updated.selection = 'Home';
        }
        return updated;
      }
      return l;
    }));
  };

  const parseTeams = (matchName: string) => {
    const parts = matchName.split(/\s+v\s+|\s+vs\.?\s+|\s+-\s+/i);
    return {
      home: parts[0]?.trim() || 'Home',
      away: parts[1]?.trim() || 'Away'
    };
  };

  const handleNumericChange = (value: string, setter: (v: string) => void) => {
    if (value === '' || /^\d*\.?\d*$/.test(value)) {
      setter(value);
    }
  };

  const handleImport = () => {
    if (!importText.trim()) return;

    try {
      const lines = importText.split('\n').map(l => l.trim());
      const newLegs: Leg[] = [];
      let calculatedOdds = 1;
      let i = 0;

      while (i < lines.length) {
        if (!lines[i]) { i++; continue; }

        const selectionRaw = lines[i];
        const oddsRaw = lines[i+1];
        const marketRaw = lines[i+2];
        const matchRaw = lines[i+3];

        if (!selectionRaw || !oddsRaw || !marketRaw || !matchRaw) { i++; continue; }

        const oddsVal = parseFloat(oddsRaw.replace(/[^0-9.]/g, ''));
        if (isNaN(oddsVal) || !oddsRaw.match(/^\d*\.?\d*$/)) { i++; continue; }

        let dateRaw = new Date().toISOString().split('T')[0];
        let metadataIndex = i + 4;
        while (metadataIndex < lines.length && lines[metadataIndex]) {
          const meta = lines[metadataIndex].toLowerCase();
          if (meta.includes('today')) dateRaw = new Date().toISOString().split('T')[0];
          else if (meta.includes('tomorrow')) {
            const d = new Date(); d.setDate(d.getDate() + 1);
            dateRaw = d.toISOString().split('T')[0];
          }
          metadataIndex++;
        }

        calculatedOdds *= oddsVal;
        let type = BetType.MATCH_WINNER;
        let selection = selectionRaw;
        const mUpper = marketRaw.toUpperCase();
        const sUpper = selectionRaw.toUpperCase();
        const { home, away } = parseTeams(matchRaw);

        if (mUpper.includes('BOTH TEAMS TO SCORE') || mUpper.includes('BTTS') || mUpper.includes('GG/NG')) {
          type = BetType.BTTS;
          if (sUpper === 'NO' || sUpper === 'NG') selection = 'No';
          else if (sUpper === 'YES' || sUpper === 'GG') selection = 'Yes';
        } else if (mUpper.includes('WIN EITHER HALF')) {
          type = BetType.WIN_EITHER_HALF;
        } else if (mUpper.includes('TEAM TOTAL') || mUpper.includes('TOTAL') && (mUpper.includes(home.toUpperCase()) || mUpper.includes(away.toUpperCase()))) {
          type = BetType.TEAM_TOTAL;
        } else if (mUpper.includes('CORNER')) {
          if (mUpper.includes('1X2') || mUpper.includes('MATCH RESULT')) type = BetType.CORNER_1X2;
          else type = BetType.TOTAL_CORNERS;
        } else if (mUpper.includes('OVER') || mUpper.includes('UNDER') || mUpper.includes('TOTAL GOALS')) {
          type = BetType.OVER_UNDER;
        } else if (mUpper.includes('DOUBLE CHANCE')) {
          type = BetType.DOUBLE_CHANCE;
        } else if (mUpper.includes('1X2') || mUpper.includes('MATCH RESULT')) {
          type = BetType.MATCH_WINNER;
        } else if (mUpper.includes('RED CARD') || mUpper.includes('SENDING OFF')) {
          type = BetType.SENDING_OFF;
        }

        newLegs.push({ id: generateId(), matchName: matchRaw, date: dateRaw, type, selection, status: LegStatus.PENDING });
        i = metadataIndex;
      }

      if (newLegs.length > 0) {
        setLegs(newLegs);
        setTotalOdds(calculatedOdds.toFixed(2));
        setShowImport(false);
        setImportText('');
      } else {
        alert("Couldn't find valid bet selections.");
      }
    } catch (e) {
      alert("Error parsing bet slip.");
    }
  };

  const handleSave = () => {
    if (legs.some(l => !l.matchName)) {
      alert("Please enter a match name for all selections.");
      return;
    }
    const numStake = parseFloat(stake) || 0;
    const numOdds = parseFloat(totalOdds) || 1;
    onSave({
      id: initialData ? initialData.id : generateId(),
      createdAt: initialData ? initialData.createdAt : Date.now(),
      legs,
      stake: numStake,
      odds: numOdds,
      potentialReturn: numStake * numOdds,
      status: initialData ? initialData.status : SlipStatus.PENDING,
      folder: folder.trim() || undefined
    });
    clearDraft();
  };

  return (
    <div className="bg-surface rounded-xl shadow-xl border border-borderBase overflow-hidden relative transition-colors">
      <div className="p-6 border-b border-borderBase flex justify-between items-center bg-inputBg">
        <h2 className="text-xl font-bold text-textMain flex items-center gap-2">
          {isEditing ? <Edit3 className="text-primary" /> : <Plus className="text-primary" />} 
          {isEditing ? 'Edit Bet Slip' : 'Create New Bet Slip'}
        </h2>
        <button onClick={() => setShowImport(true)} className="text-xs flex items-center gap-1 bg-surface border border-borderBase hover:bg-background text-textMain px-3 py-1.5 rounded transition-colors">
          <ClipboardPaste size={14} /> Import
        </button>
      </div>

      <div className="p-6 space-y-6">
        <div className="bg-inputBg/50 p-4 rounded-lg border border-borderBase">
            <label className="text-sm font-medium text-textMain mb-2 flex items-center gap-2"><Folder size={16} className="text-primary" /> Betting Folder</label>
            <input type="text" list="folders-list" value={folder} onChange={(e) => setFolder(e.target.value)} placeholder="e.g. Accumulator..." className="w-full bg-surface border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary" />
            <datalist id="folders-list">{availableFolders.map(f => <option key={f} value={f} />)}</datalist>
        </div>

        <div className="space-y-4">
          <label className="text-sm font-medium text-textMuted uppercase tracking-wider">Match Selections</label>
          {legs.map((leg) => {
            const { home, away } = parseTeams(leg.matchName);
            return (
              <div key={leg.id} className="p-4 bg-background rounded-lg border border-borderBase hover:border-textMuted transition-colors space-y-4">
                <div className="grid grid-cols-1 md:grid-cols-12 gap-4">
                  <div className="md:col-span-8 space-y-1">
                    <label className="text-xs text-textMuted font-bold uppercase">Match Name</label>
                    <input type="text" value={leg.matchName} onChange={(e) => updateLeg(leg.id, 'matchName', e.target.value)} placeholder="e.g. Man City vs Arsenal" className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary" />
                  </div>
                  <div className="md:col-span-3 space-y-1">
                    <label className="text-xs text-textMuted font-bold uppercase">Date</label>
                    <input type="date" value={leg.date} onChange={(e) => updateLeg(leg.id, 'date', e.target.value)} className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary" />
                  </div>
                  <div className="md:col-span-1 flex items-end justify-center pb-1">
                    <button onClick={() => removeLeg(leg.id)} disabled={legs.length === 1} className="p-2 rounded hover:bg-danger/20 text-danger/80 transition-colors disabled:opacity-30"><Trash2 size={18} /></button>
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-xs text-textMuted font-bold uppercase">Market</label>
                    <select value={leg.type} onChange={(e) => updateLeg(leg.id, 'type', e.target.value)} className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary">
                      <optgroup label="Popular">
                        <option value={BetType.MATCH_WINNER}>1X2 (Full Time)</option>
                        <option value={BetType.BTTS}>BTTS</option>
                        <option value={BetType.OVER_UNDER}>Over/Under Goals</option>
                        <option value={BetType.TEAM_TOTAL}>Team Totals</option>
                      </optgroup>
                      <optgroup label="Corners">
                        <option value={BetType.CORNER_1X2}>Corner 1X2</option>
                        <option value={BetType.TOTAL_CORNERS}>Total Corners (O/U)</option>
                      </optgroup>
                      <optgroup label="Cards & Events">
                        <option value={BetType.SENDING_OFF}>Sending Off (Red Card)</option>
                        <option value={BetType.BOOKINGS_1X2}>Bookings 1X2</option>
                        <option value={BetType.BOOKINGS}>Total Bookings (O/U)</option>
                      </optgroup>
                      <optgroup label="Others">
                        <option value={BetType.ODD_EVEN}>Total Goals - Odd/Even</option>
                        <option value={BetType.MATCH_RESULT_AND_BTTS}>1X2 & Both Teams To Score</option>
                        <option value={BetType.TEN_MINS_1X2}>10 Minutes - 1X2 (1-10')</option>
                        <option value={BetType.HANDICAP}>Handicap (2-Way)</option>
                        <option value={BetType.WIN_EITHER_HALF}>Win Either Half</option>
                        <option value={BetType.DOUBLE_CHANCE}>Double Chance</option>
                        <option value={BetType.DRAW_NO_BET}>Draw No Bet</option>
                        <option value={BetType.WINNING_MARGIN}>Winning Margin</option>
                      </optgroup>
                    </select>
                  </div>
                  <div className="space-y-1">
                    <label className="text-xs text-textMuted font-bold uppercase">Selection</label>
                    <select value={leg.selection} onChange={(e) => updateLeg(leg.id, 'selection', e.target.value)} className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary">
                      {leg.type === BetType.MATCH_WINNER && (
                        <>
                          <option value="Home">Home Win (1)</option>
                          <option value="Draw">Draw (X)</option>
                          <option value="Away">Away Win (2)</option>
                        </>
                      )}
                      {leg.type === BetType.BTTS && (
                        <>
                          <option value="Yes">Yes</option>
                          <option value="No">No</option>
                        </>
                      )}
                      {leg.type === BetType.SENDING_OFF && (
                        <>
                          <option value="Yes">Yes (Red Card Shown)</option>
                          <option value="No">No (No Red Card)</option>
                        </>
                      )}
                      {leg.type === BetType.ODD_EVEN && (
                        <>
                          <option value="Odd">Odd</option>
                          <option value="Even">Even</option>
                        </>
                      )}
                      {leg.type === BetType.CORNER_1X2 && (
                        <>
                          <option value="Home">{home} (Most Corners)</option>
                          <option value="Draw">Draw (Same Corners)</option>
                          <option value="Away">{away} (Most Corners)</option>
                        </>
                      )}
                      {leg.type === BetType.BOOKINGS_1X2 && (
                        <>
                          <option value="Home">{home} (Most Cards)</option>
                          <option value="Draw">Draw (Same Cards)</option>
                          <option value="Away">{away} (Most Cards)</option>
                        </>
                      )}
                      {leg.type === BetType.BOOKINGS && (
                        <>
                          <optgroup label="Over Thresholds">
                            <option value="Over 1.5">Over 1.5</option>
                            <option value="Over 2.5">Over 2.5</option>
                            <option value="Over 3.5">Over 3.5</option>
                            <option value="Over 4.5">Over 4.5</option>
                            <option value="Over 5.5">Over 5.5</option>
                          </optgroup>
                          <optgroup label="Under Thresholds">
                            <option value="Under 1.5">Under 1.5</option>
                            <option value="Under 2.5">Under 2.5</option>
                            <option value="Under 3.5">Under 3.5</option>
                            <option value="Under 4.5">Under 4.5</option>
                            <option value="Under 5.5">Under 5.5</option>
                          </optgroup>
                        </>
                      )}
                      {leg.type === BetType.TOTAL_CORNERS && (
                        <>
                          <optgroup label="Over Thresholds">
                            <option value="Over 7.5">Over 7.5</option>
                            <option value="Over 8.5">Over 8.5</option>
                            <option value="Over 9.5">Over 9.5</option>
                            <option value="Over 10.5">Over 10.5</option>
                            <option value="Over 11.5">Over 11.5</option>
                          </optgroup>
                          <optgroup label="Under Thresholds">
                            <option value="Under 7.5">Under 7.5</option>
                            <option value="Under 8.5">Under 8.5</option>
                            <option value="Under 9.5">Under 9.5</option>
                            <option value="Under 10.5">Under 10.5</option>
                            <option value="Under 11.5">Under 11.5</option>
                          </optgroup>
                        </>
                      )}
                      {leg.type === BetType.MATCH_RESULT_AND_BTTS && (
                        <>
                          <optgroup label={home}>
                            <option value="Home & Yes">Home & Yes</option>
                            <option value="Home & No">Home & No</option>
                          </optgroup>
                          <optgroup label="Draw">
                            <option value="Draw & Yes">Draw & Yes</option>
                            <option value="Draw & No">Draw & No</option>
                          </optgroup>
                          <optgroup label={away}>
                            <option value="Away & Yes">Away & Yes</option>
                            <option value="Away & No">Away & No</option>
                          </optgroup>
                        </>
                      )}
                      {leg.type === BetType.TEN_MINS_1X2 && (
                        <>
                          <option value={`Home (1-10')`}>{home} (1-10')</option>
                          <option value={`Draw (1-10')`}>Draw (1-10')</option>
                          <option value={`Away (1-10')`}>{away} (1-10')</option>
                        </>
                      )}
                      {leg.type === BetType.HANDICAP && (
                        <>
                          <optgroup label={home}>
                            <option value="Home (-3.5)">Home (-3.5)</option>
                            <option value="Home (-2.5)">Home (-2.5)</option>
                            <option value="Home (-1.5)">Home (-1.5)</option>
                            <option value="Home (-0.5)">Home (-0.5)</option>
                            <option value="Home (+0.5)">Home (+0.5)</option>
                            <option value="Home (+1.5)">Home (+1.5)</option>
                            <option value="Home (+2.5)">Home (+2.5)</option>
                            <option value="Home (+3.5)">Home (+3.5)</option>
                          </optgroup>
                          <optgroup label={away}>
                            <option value="Away (-3.5)">Away (-3.5)</option>
                            <option value="Away (-2.5)">Away (-2.5)</option>
                            <option value="Away (-1.5)">Away (-1.5)</option>
                            <option value="Away (-0.5)">Away (-0.5)</option>
                            <option value="Away (+0.5)">Away (+0.5)</option>
                            <option value="Away (+1.5)">Away (+1.5)</option>
                            <option value="Away (+2.5)">Away (+2.5)</option>
                            <option value="Away (+3.5)">Away (+3.5)</option>
                          </optgroup>
                        </>
                      )}
                      {leg.type === BetType.WIN_EITHER_HALF && (
                        <>
                          <optgroup label={home}>
                            <option value="Home - Yes/Yes">Yes/Yes (Win Both)</option>
                            <option value="Home - Yes/No">Yes/No (1st Only)</option>
                            <option value="Home - No/Yes">No/Yes (2nd Only)</option>
                            <option value="Home - No/No">No/No (Win Neither)</option>
                          </optgroup>
                          <optgroup label={away}>
                            <option value="Away - Yes/Yes">Yes/Yes (Win Both)</option>
                            <option value="Away - Yes/No">Yes/No (1st Only)</option>
                            <option value="Away - No/Yes">No/Yes (2nd Only)</option>
                            <option value="Away - No/No">No/No (Win Neither)</option>
                          </optgroup>
                        </>
                      )}
                      {leg.type === BetType.TEAM_TOTAL && (
                        <>
                          <optgroup label={home}>
                            <option value="Home Over 0.5">Over 0.5</option>
                            <option value="Home Under 0.5">Under 0.5</option>
                            <option value="Home Over 1.5">Over 1.5</option>
                            <option value="Home Under 1.5">Under 1.5</option>
                            <option value="Home Over 2.5">Over 2.5</option>
                            <option value="Home Under 2.5">Under 2.5</option>
                            <option value="Home Over 3.5">Over 3.5</option>
                            <option value="Home Under 3.5">Under 3.5</option>
                            <option value="Home Over 4.5">Over 4.5</option>
                            <option value="Home Under 4.5">Under 4.5</option>
                            <option value="Home Over 5.5">Over 5.5</option>
                            <option value="Home Under 5.5">Under 5.5</option>
                          </optgroup>
                          <optgroup label={away}>
                            <option value="Away Over 0.5">Over 0.5</option>
                            <option value="Away Under 0.5">Under 0.5</option>
                            <option value="Away Over 1.5">Over 1.5</option>
                            <option value="Away Under 1.5">Under 1.5</option>
                            <option value="Away Over 2.5">Over 2.5</option>
                            <option value="Away Under 2.5">Under 2.5</option>
                            <option value="Away Over 3.5">Over 3.5</option>
                            <option value="Away Under 3.5">Under 3.5</option>
                            <option value="Away Over 4.5">Over 4.5</option>
                            <option value="Away Under 4.5">Under 4.5</option>
                            <option value="Away Over 5.5">Over 5.5</option>
                            <option value="Away Under 5.5">Under 5.5</option>
                          </optgroup>
                        </>
                      )}
                      {leg.type === BetType.OVER_UNDER && (
                        <>
                          <optgroup label="Over Thresholds">
                            <option value="Over 0.5">Over 0.5</option>
                            <option value="Over 1.5">Over 1.5</option>
                            <option value="Over 2.5">Over 2.5</option>
                            <option value="Over 3.5">Over 3.5</option>
                            <option value="Over 4.5">Over 4.5</option>
                            <option value="Over 5.5">Over 5.5</option>
                          </optgroup>
                          <optgroup label="Under Thresholds">
                            <option value="Under 0.5">Under 0.5</option>
                            <option value="Under 1.5">Under 1.5</option>
                            <option value="Under 2.5">Under 2.5</option>
                            <option value="Under 3.5">Under 3.5</option>
                            <option value="Under 4.5">Under 4.5</option>
                            <option value="Under 5.5">Under 5.5</option>
                          </optgroup>
                        </>
                      )}
                      {!([BetType.MATCH_WINNER, BetType.BTTS, BetType.SENDING_OFF, BetType.TEAM_TOTAL, BetType.OVER_UNDER, BetType.WIN_EITHER_HALF, BetType.HANDICAP, BetType.TEN_MINS_1X2, BetType.MATCH_RESULT_AND_BTTS, BetType.ODD_EVEN, BetType.BOOKINGS, BetType.BOOKINGS_1X2, BetType.CORNER_1X2, BetType.TOTAL_CORNERS].includes(leg.type as BetType)) && (
                        <option value={leg.selection}>{leg.selection}</option>
                      )}
                    </select>
                  </div>
                </div>
              </div>
            );
          })}
          <button onClick={addLeg} className="w-full py-3 border border-dashed border-borderBase rounded-lg text-textMuted hover:text-textMain hover:bg-inputBg transition-all flex items-center justify-center gap-2"><Plus size={18} /> Add Match</button>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 pt-6 border-t border-borderBase">
           <div className="space-y-1">
              <label className="text-xs font-bold text-textMuted uppercase">Stake ({symbol})</label>
              <input type="text" inputMode="decimal" value={stake} onChange={(e) => handleNumericChange(e.target.value, setStake)} className="w-full bg-inputBg border border-borderBase rounded px-4 py-3 text-textMain font-bold focus:outline-none focus:border-primary" />
           </div>
           <div className="space-y-1">
              <label className="text-xs font-bold text-textMuted uppercase">Total Odds</label>
              <input type="text" inputMode="decimal" value={totalOdds} onChange={(e) => handleNumericChange(e.target.value, setTotalOdds)} className="w-full bg-inputBg border border-borderBase rounded px-4 py-3 text-textMain font-bold focus:outline-none focus:border-primary" />
           </div>
        </div>

        <div className="bg-primary/10 rounded-lg p-4 flex justify-between items-center border border-primary/20">
          <span className="text-primary font-medium">Potential Return</span>
          <span className="text-2xl font-bold text-primary">{symbol}{((parseFloat(stake) || 0) * (parseFloat(totalOdds) || 0)).toFixed(2)}</span>
        </div>

        <div className="flex gap-4 justify-end pt-4">
          <button onClick={onCancel} className="px-6 py-3 text-textMuted hover:text-textMain">Cancel</button>
          <button onClick={handleSave} className="px-8 py-3 rounded-lg font-bold bg-primary hover:bg-blue-600 text-white shadow-lg transition-all flex items-center gap-2"><Save size={18} /> Save Bet Slip</button>
        </div>
      </div>

      {showImport && (
        <div className="fixed inset-0 z-[60] bg-background/95 flex items-center justify-center p-6 animate-fade-in">
           <div className="w-full max-w-lg bg-surface border border-borderBase rounded-xl p-6 shadow-2xl">
              <div className="flex justify-between items-center mb-4">
                 <h3 className="text-textMain font-bold flex items-center gap-2"><ClipboardPaste size={18} className="text-primary" /> Import Selections</h3>
                 <button onClick={() => setShowImport(false)} className="text-textMuted hover:text-textMain"><X size={20} /></button>
              </div>
              <textarea value={importText} onChange={(e) => setImportText(e.target.value)} placeholder="Selection\nOdds\nMarket\nMatch" className="w-full h-64 bg-inputBg border border-borderBase rounded-lg p-4 text-xs font-mono text-textMain focus:outline-none focus:border-primary resize-none" />
              <div className="mt-4 flex justify-end gap-3">
                 <button onClick={() => setShowImport(false)} className="px-4 py-2 text-textMuted font-medium">Cancel</button>
                 <button onClick={handleImport} className="px-6 py-2 bg-primary text-white rounded-lg font-bold hover:bg-blue-600 transition-colors shadow-lg">Import</button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

import { GoogleGenAI } from "@google/genai";
import { Slip, Leg, LegStatus, ValidationResult } from "../types";

// Initialize Gemini Client
const apiKey = process.env.API_KEY || '';
const ai = new GoogleGenAI({ apiKey });

export interface ValidationResponse {
  results: ValidationResult[];
  sources: string[];
}

/**
 * Validates bet slip legs using Gemini 3 Flash.
 * Enforces strict settlement only for finished matches.
 */
export const validateSlipWithGemini = async (slip: Slip): Promise<ValidationResponse> => {
  if (!apiKey) {
    throw new Error("API Key is missing.");
  }

  const legsDescription = slip.legs.map(leg => {
    const parts = leg.matchName.split(/\s+v\s+|\s+vs\.?\s+|\s+-\s+/i);
    const home = parts[0]?.trim() || 'Home';
    const away = parts[1]?.trim() || 'Away';

    return `ID:${leg.id}|Match:${home} vs ${away}|Date:${leg.date}|Market:${leg.type}|Selection:${leg.selection}`;
  }).join('\n');

  const prompt = `
    Find current scores and match statuses for these sports matches.

    CRITICAL SETTLEMENT RULES:
    1. ONLY return status "WON" or "LOST" if the match is officially FINISHED (FT / Full Time).
    2. If the match is LIVE (e.g. 75th minute), HT (Half Time), or NOT STARTED, the status MUST be "PENDING".
    3. If the match is POSTPONED or CANCELLED, status is "VOID".
    4. Market Verification Logic:
       - 1X2: Result at FT.
       - BTTS: Both scored at FT?
       - SENDING_OFF: WON if at least one player was shown a Red Card (direct or second yellow). "Yes" selection wins if card shown, "No" selection wins if no card shown.
       - OVER_UNDER: Total goals at FT.
       - TEAM_TOTAL: Total goals scored by the specific team (Home or Away) at FT.
       - HANDICAP: Settle based on FT score plus/minus the handicap value for the chosen team.
       - ODD_EVEN: WON if total match goals (Home + Away) is Odd or Even as selected. Note: 0 goals is settled as Even.
       - BOOKINGS: Settle based on the total number of cards (Yellow=1, Red=1) shown to active players. A second yellow leading to a red counts as 2 cards in total for that player.
       - BOOKINGS_1X2: Settle based on which team received more cards at FT. "Home" means Home team had more cards, "Away" means Away team had more cards, "Draw" means both had the same count.
       - CORNER_1X2: Settle based on which team had more corner kicks awarded at FT. "Home" means Home team had more corners, "Away" means Away team had more corners, "Draw" means both had the same count.
       - TOTAL_CORNERS: Settle based on total number of corners in the match at FT (Home + Away). For "Over X.5", win if total > X. For "Under X.5", win if total < X.
       - TEN_MINS_1X2: Settle based on the score at exactly the 10-minute mark (10:00). If no goals are scored in the first 10 minutes, the selection "Draw (1-10')" is WON.
       - 1X2_BTTS: Combined market. WON if BOTH the match outcome (1, X, or 2) and the BTTS status (Yes/No) match the selection (e.g. "Home & Yes").
       - WIN_EITHER_HALF: The selection format is "Team - 1stHalfAnswer/2ndHalfAnswer" (e.g. "Home - Yes/No"). 
         "Yes" means the team won that half (treat as starting 0-0). 
         Settle as WON only if both half results match the selection.
       - WINNING_MARGIN: Calculate goal difference at FT.
       - HALVES_BTTS: Both scored in both halves.

    INPUTS:
    ${legsDescription}

    OUTPUT ONLY JSON ARRAY:
    \`\`\`json
    [
      { 
        "legId": "...", 
        "status": "WON|LOST|VOID|PENDING", 
        "score": "X-Y (Status e.g. FT, HT, 65', PPD)", 
        "reason": "Brief detail on why settled or why pending" 
      }
    ]
    \`\`\`
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        temperature: 0,
      },
    });

    const text = response.text || '';

    const sources: string[] = [];
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
    chunks.forEach(chunk => {
      if (chunk.web?.uri) {
        sources.push(chunk.web.uri);
      }
    });

    const jsonMatch = text.match(/```json\s*([\s\S]*?)\s*```/) || text.match(/\[\s*\{[\s\S]*\}\s*\]/);

    if (!jsonMatch) {
      throw new Error("No structured results found.");
    }

    const jsonString = jsonMatch[1] || jsonMatch[0];
    const results = JSON.parse(jsonString) as ValidationResult[];

    return { results, sources };

  } catch (error) {
    console.error("Gemini Validation Error:", error);
    throw error;
  }
};

import React, { useState, useEffect } from 'react';
import { Plus, Trash2, Save, ClipboardPaste, X, Edit3, Folder, Globe } from 'lucide-react';
import { BetType, Leg, LegStatus, Slip, SlipStatus, Currency, CURRENCY_SYMBOLS } from '../types';

interface NewSlipFormProps {
  initialData?: Slip;
  onSave: (slip: Slip) => void;
  onCancel: () => void;
  currency: Currency;
  availableFolders: string[];
  availableLeagues: string[];
}

// Robust ID generator
const generateId = () => {
  return Date.now().toString(36) + Math.random().toString(36).substring(2, 9);
};

export const NewSlipForm: React.FC<NewSlipFormProps> = ({ initialData, onSave, onCancel, currency, availableFolders, availableLeagues }) => {
  const [stake, setStake] = useState<string>(() => {
    if (initialData) return initialData.stake.toString();
    const saved = localStorage.getItem('smartbet_draft_stake');
    return saved || '10';
  });

  const [totalOdds, setTotalOdds] = useState<string>(() => {
    if (initialData) return initialData.odds.toString();
    const saved = localStorage.getItem('smartbet_draft_odds');
    return saved || '1.00';
  });

  const [folder, setFolder] = useState<string>(() => {
    if (initialData) return initialData.folder || '';
    return '';
  });

  const [legs, setLegs] = useState<Leg[]>(() => {
    if (initialData) return initialData.legs;
    const saved = localStorage.getItem('smartbet_draft_legs');
    if (saved) return JSON.parse(saved);
    return [{
      id: generateId(),
      matchName: '',
      league: '',
      date: new Date().toISOString().split('T')[0],
      type: BetType.MATCH_WINNER,
      selection: 'Home',
      status: LegStatus.PENDING,
    }];
  });

  const [showImport, setShowImport] = useState(false);
  const [importText, setImportText] = useState('');

  const symbol = CURRENCY_SYMBOLS[currency];
  const isEditing = !!initialData;

  useEffect(() => {
    if (!isEditing) {
      localStorage.setItem('smartbet_draft_stake', stake);
      localStorage.setItem('smartbet_draft_odds', totalOdds);
      localStorage.setItem('smartbet_draft_legs', JSON.stringify(legs));
    }
  }, [stake, totalOdds, legs, isEditing]);

  const clearDraft = () => {
    localStorage.removeItem('smartbet_draft_stake');
    localStorage.removeItem('smartbet_draft_odds');
    localStorage.removeItem('smartbet_draft_legs');
  };

  const addLeg = () => {
    setLegs([
      ...legs,
      {
        id: generateId(),
        matchName: '',
        league: '',
        date: new Date().toISOString().split('T')[0],
        type: BetType.MATCH_WINNER,
        selection: 'Home',
        status: LegStatus.PENDING,
      }
    ]);
  };

  const removeLeg = (id: string) => {
    if (legs.length > 1) {
      setLegs(legs.filter(l => l.id !== id));
    }
  };

  const updateLeg = (id: string, field: keyof Leg, value: any) => {
    setLegs(legs.map(l => {
      if (l.id === id) {
        const updated = { ...l, [field]: value };
        if (field === 'type') {
           if (value === BetType.MATCH_WINNER) updated.selection = 'Home';
           if (value === BetType.BTTS) updated.selection = 'Yes';
           if (value === BetType.SENDING_OFF) updated.selection = 'Yes';
           if (value === BetType.OVER_UNDER) updated.selection = 'Over 2.5';
           if (value === BetType.DOUBLE_CHANCE) updated.selection = '1X';
           if (value === BetType.DRAW_NO_BET) updated.selection = 'Home';
           if (value === BetType.WIN_EITHER_HALF) updated.selection = 'Home - Yes/No';
           if (value === BetType.HANDICAP) updated.selection = 'Home (-0.5)';
           if (value === BetType.TOTAL_CORNERS) updated.selection = 'Over 9.5';
           if (value === BetType.CORNER_1X2) updated.selection = 'Home';
           if (value === BetType.WINNING_MARGIN) updated.selection = 'Home By 1';
           if (value === BetType.HALVES_BTTS) updated.selection = 'No/No';
           if (value === BetType.TEAM_TOTAL) updated.selection = 'Home Over 0.5';
           if (value === BetType.TEN_MINS_1X2) updated.selection = 'Home (1-10\')';
           if (value === BetType.MATCH_RESULT_AND_BTTS) updated.selection = 'Home & Yes';
           if (value === BetType.ODD_EVEN) updated.selection = 'Odd';
           if (value === BetType.BOOKINGS) updated.selection = 'Over 3.5';
           if (value === BetType.BOOKINGS_1X2) updated.selection = 'Home';
        }
        return updated;
      }
      return l;
    }));
  };

  const parseTeams = (matchName: string) => {
    const parts = matchName.split(/\s+v\s+|\s+vs\.?\s+|\s+-\s+|\s+–\s+/i);
    return {
      home: parts[0]?.trim() || 'Home',
      away: parts[1]?.trim() || 'Away'
    };
  };

  const handleNumericChange = (value: string, setter: (v: string) => void) => {
    if (value === '' || /^\d*\.?\d*$/.test(value)) {
      setter(value);
    }
  };

  const handleImport = () => {
    if (!importText.trim()) return;

    try {
      const lines = importText.split('\n').map(l => l.trim()).filter(l => l !== '');
      const newLegs: Leg[] = [];
      let calculatedOdds = 1;
      let i = 0;

      // The new format is roughly 5 lines per leg:
      // 1. Selection (Over (1.5))
      // 2. Odds (1.34)
      // 3. Market (Total (1.5))
      // 4. Match (Derby - Boro)
      // 5. Date/Time (Today 17:00)

      while (i < lines.length) {
        const selectionRaw = lines[i];
        const oddsRaw = lines[i+1];
        const marketRaw = lines[i+2];
        const matchRaw = lines[i+3];
        const dateTimeRaw = lines[i+4];

        if (!selectionRaw || !oddsRaw || !marketRaw || !matchRaw) {
          i++; 
          continue;
        }

        // Validate odds line
        const oddsVal = parseFloat(oddsRaw.replace(/[^0-9.]/g, ''));
        if (isNaN(oddsVal)) {
          i++;
          continue;
        }

        // Date detection from Line 5
        let dateRaw = new Date().toISOString().split('T')[0];
        if (dateTimeRaw) {
          const lowerDT = dateTimeRaw.toLowerCase();
          if (lowerDT.includes('today')) {
            dateRaw = new Date().toISOString().split('T')[0];
          } else if (lowerDT.includes('tomorrow')) {
            const d = new Date();
            d.setDate(d.getDate() + 1);
            dateRaw = d.toISOString().split('T')[0];
          } else {
            // Check for specific date patterns like "24 Dec"
            const match = dateTimeRaw.match(/(\d{1,2})\s+(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)/i);
            if (match) {
              const d = new Date(`${match[1]} ${match[2]} ${new Date().getFullYear()}`);
              if (!isNaN(d.getTime())) dateRaw = d.toISOString().split('T')[0];
            }
          }
        }

        calculatedOdds *= oddsVal;

        // Normalize selection: "Over (1.5)" -> "Over 1.5"
        let selection = selectionRaw.replace(/\((.*?)\)/g, '$1').trim();

        const mUpper = marketRaw.toUpperCase();
        const { home, away } = parseTeams(matchRaw);

        let type = BetType.MATCH_WINNER;

        // Market logic
        if (mUpper.includes('BOTH TEAMS TO SCORE') || mUpper.includes('BTTS') || mUpper.includes('GG/NG')) {
          type = BetType.BTTS;
        } else if (mUpper.includes('TOTAL') || mUpper.includes('OVER/UNDER') || mUpper.includes('GOALS')) {
          // Check if it's a team total
          if (mUpper.includes(home.toUpperCase()) || mUpper.includes(away.toUpperCase())) {
            type = BetType.TEAM_TOTAL;
            const chosenTeam = mUpper.includes(home.toUpperCase()) ? 'Home' : 'Away';
            selection = `${chosenTeam} ${selection}`;
          } else {
            type = BetType.OVER_UNDER;
          }
        } else if (mUpper.includes('CORNER')) {
          if (mUpper.includes('1X2') || mUpper.includes('MATCH RESULT')) type = BetType.CORNER_1X2;
          else type = BetType.TOTAL_CORNERS;
        } else if (mUpper.includes('DOUBLE CHANCE')) {
          type = BetType.DOUBLE_CHANCE;
        } else if (mUpper.includes('DRAW NO BET') || mUpper.includes('DNB')) {
          type = BetType.DRAW_NO_BET;
        } else if (mUpper.includes('RED CARD') || mUpper.includes('SENDING OFF')) {
          type = BetType.SENDING_OFF;
        } else if (mUpper.includes('1X2') || mUpper.includes('MATCH RESULT')) {
          type = BetType.MATCH_WINNER;
        }

        newLegs.push({
          id: generateId(),
          matchName: matchRaw,
          date: dateRaw,
          type,
          selection,
          status: LegStatus.PENDING
        });

        // Advance index: we expect 5 lines but sometimes it might be 4 if date is missing
        i += (dateTimeRaw && (dateTimeRaw.toLowerCase().includes('today') || dateTimeRaw.toLowerCase().includes('tomorrow') || dateTimeRaw.match(/\d{1,2}:\d{2}/))) ? 5 : 4;
      }

      if (newLegs.length > 0) {
        setLegs(newLegs);
        setTotalOdds(calculatedOdds.toFixed(2));
        setShowImport(false);
        setImportText('');
      } else {
        alert("Couldn't find valid bet selections. Please check the format.");
      }
    } catch (e) {
      console.error(e);
      alert("Error parsing bet slip.");
    }
  };

  const handleSave = () => {
    if (legs.some(l => !l.matchName)) {
      alert("Please enter a match name for all selections.");
      return;
    }
    const numStake = parseFloat(stake) || 0;
    const numOdds = parseFloat(totalOdds) || 1;
    onSave({
      id: initialData ? initialData.id : generateId(),
      createdAt: initialData ? initialData.createdAt : Date.now(),
      legs,
      stake: numStake,
      odds: numOdds,
      potentialReturn: numStake * numOdds,
      status: initialData ? initialData.status : SlipStatus.PENDING,
      folder: folder.trim() || undefined
    });
    clearDraft();
  };

  return (
    <div className="bg-surface rounded-xl shadow-xl border border-borderBase overflow-hidden relative transition-colors">
      <div className="p-6 border-b border-borderBase flex justify-between items-center bg-inputBg">
        <h2 className="text-xl font-bold text-textMain flex items-center gap-2">
          {isEditing ? <Edit3 className="text-primary" /> : <Plus className="text-primary" />} 
          {isEditing ? 'Edit Bet Slip' : 'Create New Bet Slip'}
        </h2>
        <button onClick={() => setShowImport(true)} className="text-xs flex items-center gap-1 bg-surface border border-borderBase hover:bg-background text-textMain px-3 py-1.5 rounded transition-colors">
          <ClipboardPaste size={14} /> Import
        </button>
      </div>

      <div className="p-6 space-y-6">
        <div className="bg-inputBg/50 p-4 rounded-lg border border-borderBase">
            <label className="text-sm font-medium text-textMain mb-2 flex items-center gap-2"><Folder size={16} className="text-primary" /> Betting Folder</label>
            <input type="text" list="folders-list" value={folder} onChange={(e) => setFolder(e.target.value)} placeholder="e.g. Accumulator..." className="w-full bg-surface border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary" />
            <datalist id="folders-list">{availableFolders.map(f => <option key={f} value={f} />)}</datalist>
        </div>

        <div className="space-y-4">
          <label className="text-sm font-medium text-textMuted uppercase tracking-wider">Match Selections</label>
          {legs.map((leg) => {
            const { home, away } = parseTeams(leg.matchName);
            return (
              <div key={leg.id} className="p-4 bg-background rounded-lg border border-borderBase hover:border-textMuted transition-colors space-y-4">
                <div className="grid grid-cols-1 md:grid-cols-12 gap-4">
                  <div className="md:col-span-8 space-y-1">
                    <label className="text-xs text-textMuted font-bold uppercase">Match Name</label>
                    <input type="text" value={leg.matchName} onChange={(e) => updateLeg(leg.id, 'matchName', e.target.value)} placeholder="e.g. Man City vs Arsenal" className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary" />
                  </div>
                  <div className="md:col-span-3 space-y-1">
                    <label className="text-xs text-textMuted font-bold uppercase">Date</label>
                    <input type="date" value={leg.date} onChange={(e) => updateLeg(leg.id, 'date', e.target.value)} className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary" />
                  </div>
                  <div className="md:col-span-1 flex items-end justify-center pb-1">
                    <button onClick={() => removeLeg(leg.id)} disabled={legs.length === 1} className="p-2 rounded hover:bg-danger/20 text-danger/80 transition-colors disabled:opacity-30"><Trash2 size={18} /></button>
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-xs text-textMuted font-bold uppercase">Market</label>
                    <select value={leg.type} onChange={(e) => updateLeg(leg.id, 'type', e.target.value)} className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary">
                      <optgroup label="Popular">
                        <option value={BetType.MATCH_WINNER}>1X2 (Full Time)</option>
                        <option value={BetType.BTTS}>BTTS</option>
                        <option value={BetType.OVER_UNDER}>Over/Under Goals</option>
                        <option value={BetType.TEAM_TOTAL}>Team Totals</option>
                      </optgroup>
                      <optgroup label="Corners">
                        <option value={BetType.CORNER_1X2}>Corner 1X2</option>
                        <option value={BetType.TOTAL_CORNERS}>Total Corners (O/U)</option>
                      </optgroup>
                      <optgroup label="Cards & Events">
                        <option value={BetType.SENDING_OFF}>Sending Off (Red Card)</option>
                        <option value={BetType.BOOKINGS_1X2}>Bookings 1X2</option>
                        <option value={BetType.BOOKINGS}>Total Bookings (O/U)</option>
                      </optgroup>
                      <optgroup label="Others">
                        <option value={BetType.ODD_EVEN}>Total Goals - Odd/Even</option>
                        <option value={BetType.MATCH_RESULT_AND_BTTS}>1X2 & Both Teams To Score</option>
                        <option value={BetType.TEN_MINS_1X2}>10 Minutes - 1X2 (1-10')</option>
                        <option value={BetType.HANDICAP}>Handicap (2-Way)</option>
                        <option value={BetType.WIN_EITHER_HALF}>Win Either Half</option>
                        <option value={BetType.DOUBLE_CHANCE}>Double Chance</option>
                        <option value={BetType.DRAW_NO_BET}>Draw No Bet</option>
                        <option value={BetType.WINNING_MARGIN}>Winning Margin</option>
                      </optgroup>
                    </select>
                  </div>
                  <div className="space-y-1">
                    <label className="text-xs text-textMuted font-bold uppercase">Selection</label>
                    <select value={leg.selection} onChange={(e) => updateLeg(leg.id, 'selection', e.target.value)} className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary">
                      {leg.type === BetType.MATCH_WINNER && (
                        <>
                          <option value="Home">Home Win (1)</option>
                          <option value="Draw">Draw (X)</option>
                          <option value="Away">Away Win (2)</option>
                        </>
                      )}
                      {leg.type === BetType.BTTS && (
                        <>
                          <option value="Yes">Yes</option>
                          <option value="No">No</option>
                        </>
                      )}
                      {leg.type === BetType.SENDING_OFF && (
                        <>
                          <option value="Yes">Yes (Red Card Shown)</option>
                          <option value="No">No (No Red Card)</option>
                        </>
                      )}
                      {leg.type === BetType.ODD_EVEN && (
                        <>
                          <option value="Odd">Odd</option>
                          <option value="Even">Even</option>
                        </>
                      )}
                      {leg.type === BetType.CORNER_1X2 && (
                        <>
                          <option value="Home">{home} (Most Corners)</option>
                          <option value="Draw">Draw (Same Corners)</option>
                          <option value="Away">{away} (Most Corners)</option>
                        </>
                      )}
                      {leg.type === BetType.BOOKINGS_1X2 && (
                        <>
                          <option value="Home">{home} (Most Cards)</option>
                          <option value="Draw">Draw (Same Cards)</option>
                          <option value="Away">{away} (Most Cards)</option>
                        </>
                      )}
                      {leg.type === BetType.BOOKINGS && (
                        <>
                          <optgroup label="Over Thresholds">
                            <option value="Over 1.5">Over 1.5</option>
                            <option value="Over 2.5">Over 2.5</option>
                            <option value="Over 3.5">Over 3.5</option>
                            <option value="Over 4.5">Over 4.5</option>
                            <option value="Over 5.5">Over 5.5</option>
                          </optgroup>
                          <optgroup label="Under Thresholds">
                            <option value="Under 1.5">Under 1.5</option>
                            <option value="Under 2.5">Under 2.5</option>
                            <option value="Under 3.5">Under 3.5</option>
                            <option value="Under 4.5">Under 4.5</option>
                            <option value="Under 5.5">Under 5.5</option>
                          </optgroup>
                        </>
                      )}
                      {leg.type === BetType.TOTAL_CORNERS && (
                        <>
                          <optgroup label="Over Thresholds">
                            <option value="Over 7.5">Over 7.5</option>
                            <option value="Over 8.5">Over 8.5</option>
                            <option value="Over 9.5">Over 9.5</option>
                            <option value="Over 10.5">Over 10.5</option>
                            <option value="Over 11.5">Over 11.5</option>
                          </optgroup>
                          <optgroup label="Under Thresholds">
                            <option value="Under 7.5">Under 7.5</option>
                            <option value="Under 8.5">Under 8.5</option>
                            <option value="Under 9.5">Under 9.5</option>
                            <option value="Under 10.5">Under 10.5</option>
                            <option value="Under 11.5">Under 11.5</option>
                          </optgroup>
                        </>
                      )}
                      {leg.type === BetType.MATCH_RESULT_AND_BTTS && (
                        <>
                          <optgroup label={home}>
                            <option value="Home & Yes">Home & Yes</option>
                            <option value="Home & No">Home & No</option>
                          </optgroup>
                          <optgroup label="Draw">
                            <option value="Draw & Yes">Draw & Yes</option>
                            <option value="Draw & No">Draw & No</option>
                          </optgroup>
                          <optgroup label={away}>
                            <option value="Away & Yes">Away & Yes</option>
                            <option value="Away & No">Away & No</option>
                          </optgroup>
                        </>
                      )}
                      {leg.type === BetType.TEN_MINS_1X2 && (
                        <>
                          <option value={`Home (1-10')`}>{home} (1-10')</option>
                          <option value={`Draw (1-10')`}>Draw (1-10')</option>
                          <option value={`Away (1-10')`}>{away} (1-10')</option>
                        </>
                      )}
                      {leg.type === BetType.HANDICAP && (
                        <>
                          <optgroup label={home}>
                            <option value="Home (-3.5)">Home (-3.5)</option>
                            <option value="Home (-2.5)">Home (-2.5)</option>
                            <option value="Home (-1.5)">Home (-1.5)</option>
                            <option value="Home (-0.5)">Home (-0.5)</option>
                            <option value="Home (+0.5)">Home (+0.5)</option>
                            <option value="Home (+1.5)">Home (+1.5)</option>
                            <option value="Home (+2.5)">Home (+2.5)</option>
                            <option value="Home (+3.5)">Home (+3.5)</option>
                          </optgroup>
                          <optgroup label={away}>
                            <option value="Away (-3.5)">Away (-3.5)</option>
                            <option value="Away (-2.5)">Away (-2.5)</option>
                            <option value="Away (-1.5)">Away (-1.5)</option>
                            <option value="Away (-0.5)">Away (-0.5)</option>
                            <option value="Away (+0.5)">Away (+0.5)</option>
                            <option value="Away (+1.5)">Away (+1.5)</option>
                            <option value="Away (+2.5)">Away (+2.5)</option>
                            <option value="Away (+3.5)">Away (+3.5)</option>
                          </optgroup>
                        </>
                      )}
                      {leg.type === BetType.WIN_EITHER_HALF && (
                        <>
                          <optgroup label={home}>
                            <option value="Home - Yes/Yes">Yes/Yes (Win Both)</option>
                            <option value="Home - Yes/No">Yes/No (1st Only)</option>
                            <option value="Home - No/Yes">No/Yes (2nd Only)</option>
                            <option value="Home - No/No">No/No (Win Neither)</option>
                          </optgroup>
                          <optgroup label={away}>
                            <option value="Away - Yes/Yes">Yes/Yes (Win Both)</option>
                            <option value="Away - Yes/No">Yes/No (1st Only)</option>
                            <option value="Away - No/Yes">No/Yes (2nd Only)</option>
                            <option value="Away - No/No">No/No (Win Neither)</option>
                          </optgroup>
                        </>
                      )}
                      {leg.type === BetType.TEAM_TOTAL && (
                        <>
                          <optgroup label={home}>
                            <option value="Home Over 0.5">Over 0.5</option>
                            <option value="Home Under 0.5">Under 0.5</option>
                            <option value="Home Over 1.5">Over 1.5</option>
                            <option value="Home Under 1.5">Under 1.5</option>
                            <option value="Home Over 2.5">Over 2.5</option>
                            <option value="Home Under 2.5">Under 2.5</option>
                            <option value="Home Over 3.5">Over 3.5</option>
                            <option value="Home Under 3.5">Under 3.5</option>
                            <option value="Home Over 4.5">Over 4.5</option>
                            <option value="Home Under 4.5">Under 4.5</option>
                            <option value="Home Over 5.5">Over 5.5</option>
                            <option value="Home Under 5.5">Under 5.5</option>
                          </optgroup>
                          <optgroup label={away}>
                            <option value="Away Over 0.5">Over 0.5</option>
                            <option value="Away Under 0.5">Under 0.5</option>
                            <option value="Away Over 1.5">Over 1.5</option>
                            <option value="Away Under 1.5">Under 1.5</option>
                            <option value="Away Over 2.5">Over 2.5</option>
                            <option value="Away Under 2.5">Under 2.5</option>
                            <option value="Away Over 3.5">Over 3.5</option>
                            <option value="Away Under 3.5">Under 3.5</option>
                            <option value="Away Over 4.5">Over 4.5</option>
                            <option value="Away Under 4.5">Under 4.5</option>
                            <option value="Away Over 5.5">Over 5.5</option>
                            <option value="Away Under 5.5">Under 5.5</option>
                          </optgroup>
                        </>
                      )}
                      {leg.type === BetType.OVER_UNDER && (
                        <>
                          <optgroup label="Over Thresholds">
                            <option value="Over 0.5">Over 0.5</option>
                            <option value="Over 1.5">Over 1.5</option>
                            <option value="Over 2.5">Over 2.5</option>
                            <option value="Over 3.5">Over 3.5</option>
                            <option value="Over 4.5">Over 4.5</option>
                            <option value="Over 5.5">Over 5.5</option>
                          </optgroup>
                          <optgroup label="Under Thresholds">
                            <option value="Under 0.5">Under 0.5</option>
                            <option value="Under 1.5">Under 1.5</option>
                            <option value="Under 2.5">Under 2.5</option>
                            <option value="Under 3.5">Under 3.5</option>
                            <option value="Under 4.5">Under 4.5</option>
                            <option value="Under 5.5">Under 5.5</option>
                          </optgroup>
                        </>
                      )}
                      {!([BetType.MATCH_WINNER, BetType.BTTS, BetType.SENDING_OFF, BetType.TEAM_TOTAL, BetType.OVER_UNDER, BetType.WIN_EITHER_HALF, BetType.HANDICAP, BetType.TEN_MINS_1X2, BetType.MATCH_RESULT_AND_BTTS, BetType.ODD_EVEN, BetType.BOOKINGS, BetType.BOOKINGS_1X2, BetType.CORNER_1X2, BetType.TOTAL_CORNERS].includes(leg.type as BetType)) && (
                        <option value={leg.selection}>{leg.selection}</option>
                      )}
                    </select>
                  </div>
                </div>
              </div>
            );
          })}
          <button onClick={addLeg} className="w-full py-3 border border-dashed border-borderBase rounded-lg text-textMuted hover:text-textMain hover:bg-inputBg transition-all flex items-center justify-center gap-2"><Plus size={18} /> Add Match</button>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 pt-6 border-t border-borderBase">
           <div className="space-y-1">
              <label className="text-xs font-bold text-textMuted uppercase">Stake ({symbol})</label>
              <input type="text" inputMode="decimal" value={stake} onChange={(e) => handleNumericChange(e.target.value, setStake)} className="w-full bg-inputBg border border-borderBase rounded px-4 py-3 text-textMain font-bold focus:outline-none focus:border-primary" />
           </div>
           <div className="space-y-1">
              <label className="text-xs font-bold text-textMuted uppercase">Total Odds</label>
              <input type="text" inputMode="decimal" value={totalOdds} onChange={(e) => handleNumericChange(e.target.value, setTotalOdds)} className="w-full bg-inputBg border border-borderBase rounded px-4 py-3 text-textMain font-bold focus:outline-none focus:border-primary" />
           </div>
        </div>

        <div className="bg-primary/10 rounded-lg p-4 flex justify-between items-center border border-primary/20">
          <span className="text-primary font-medium">Potential Return</span>
          <span className="text-2xl font-bold text-primary">{symbol}{((parseFloat(stake) || 0) * (parseFloat(totalOdds) || 0)).toFixed(2)}</span>
        </div>

        <div className="flex gap-4 justify-end pt-4">
          <button onClick={onCancel} className="px-6 py-3 text-textMuted hover:text-textMain">Cancel</button>
          <button onClick={handleSave} className="px-8 py-3 rounded-lg font-bold bg-primary hover:bg-blue-600 text-white shadow-lg transition-all flex items-center gap-2"><Save size={18} /> Save Bet Slip</button>
        </div>
      </div>

      {showImport && (
        <div className="fixed inset-0 z-[60] bg-background/95 flex items-center justify-center p-6 animate-fade-in">
           <div className="w-full max-w-lg bg-surface border border-borderBase rounded-xl p-6 shadow-2xl">
              <div className="flex justify-between items-center mb-4">
                 <h3 className="text-textMain font-bold flex items-center gap-2"><ClipboardPaste size={18} className="text-primary" /> Import Selections</h3>
                 <button onClick={() => setShowImport(false)} className="text-textMuted hover:text-textMain"><X size={20} /></button>
              </div>
              <textarea 
                value={importText} 
                onChange={(e) => setImportText(e.target.value)} 
                placeholder={`Selection (e.g. Over (1.5))\nOdds (e.g. 1.34)\nMarket (e.g. Total (1.5))\nMatch (e.g. Team A - Team B)\nDate (e.g. Today 17:00)`} 
                className="w-full h-64 bg-inputBg border border-borderBase rounded-lg p-4 text-xs font-mono text-textMain focus:outline-none focus:border-primary resize-none" 
              />
              <div className="mt-4 flex justify-end gap-3">
                 <button onClick={() => { setShowImport(false); setImportText(''); }} className="px-4 py-2 text-textMuted font-medium">Cancel</button>
                 <button onClick={handleImport} className="px-6 py-2 bg-primary text-white rounded-lg font-bold hover:bg-blue-600 transition-colors shadow-lg">Import</button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { LayoutDashboard, PlusCircle, History, Wallet, TrendingUp, Trophy, Settings as SettingsIcon, Sun, Moon, Trash2, X, BarChart3, FolderOpen, Edit2, Check, Plus, Coins, ArrowUpCircle } from 'lucide-react';
import { Slip, SlipStatus, Stats, Currency, CURRENCY_SYMBOLS } from './types';
import { StatsCard } from './components/StatsCard';
import { SlipList } from './components/SlipList';
import { NewSlipForm } from './components/NewSlipForm';
import { StatisticsPanel } from './components/StatisticsPanel';

const DEFAULT_LEAGUES = [
  'EPL', 'La Liga', 'Bundesliga', 'Serie A', 'Ligue 1', 
  'UCL', 'UEL', 'MLS', 'Eredivisie', 'Championship'
];

const STARTING_BALANCE = 1000;

const App: React.FC = () => {
  // State Initialization with LocalStorage
  const [activeTab, setActiveTab] = useState<'dashboard' | 'active' | 'settled' | 'create' | 'stats'>('dashboard');

  const [slips, setSlips] = useState<Slip[]>(() => {
    const saved = localStorage.getItem('smartbet_slips');
    return saved ? JSON.parse(saved) : [];
  });

  const [theme, setTheme] = useState<'light' | 'dark'>(() => {
    return (localStorage.getItem('smartbet_theme') as 'light' | 'dark') || 'dark';
  });

  const [currency, setCurrency] = useState<Currency>(() => {
    return (localStorage.getItem('smartbet_currency') as Currency) || 'ZAR';
  });

  const [bankroll, setBankroll] = useState<number>(() => {
    const saved = localStorage.getItem('smartbet_bankroll');
    return saved !== null ? parseFloat(saved) : STARTING_BALANCE;
  });

  const [customLeagues, setCustomLeagues] = useState<string[]>(() => {
    const saved = localStorage.getItem('smartbet_custom_leagues');
    return saved ? JSON.parse(saved) : DEFAULT_LEAGUES;
  });

  // Folder state
  const [selectedFolder, setSelectedFolder] = useState<string>('All');

  const [showSettings, setShowSettings] = useState(false);
  const [editingSlip, setEditingSlip] = useState<Slip | null>(null);
  const [newLeagueInput, setNewLeagueInput] = useState('');

  const [stats, setStats] = useState<Stats>({
    totalSlips: 0,
    wins: 0,
    losses: 0,
    winRate: 0,
    totalStaked: 0,
    totalReturned: 0,
    profit: 0,
    roi: 0
  });

  // Derived state for unique folders
  const uniqueFolders = React.useMemo(() => {
    const folders = new Set<string>();
    slips.forEach(s => {
      if (s.folder) folders.add(s.folder);
    });
    return Array.from(folders).sort();
  }, [slips]);

  // Persist State
  useEffect(() => {
    localStorage.setItem('smartbet_slips', JSON.stringify(slips));
  }, [slips]);

  useEffect(() => {
    localStorage.setItem('smartbet_bankroll', bankroll.toString());
  }, [bankroll]);

  useEffect(() => {
    localStorage.setItem('smartbet_theme', theme);
    const root = window.document.documentElement;
    if (theme === 'dark') {
      root.classList.add('dark');
    } else {
      root.classList.remove('dark');
    }
  }, [theme]);

  useEffect(() => {
    localStorage.setItem('smartbet_currency', currency);
  }, [currency]);

  useEffect(() => {
    localStorage.setItem('smartbet_custom_leagues', JSON.stringify(customLeagues));
  }, [customLeagues]);


  // Calculate Stats
  useEffect(() => {
    const settledSlips = slips.filter(s => s.status === SlipStatus.WON || s.status === SlipStatus.LOST);
    const totalSlips = settledSlips.length;
    const wins = settledSlips.filter(s => s.status === SlipStatus.WON).length;
    const losses = settledSlips.filter(s => s.status === SlipStatus.LOST).length;
    const winRate = totalSlips > 0 ? (wins / totalSlips) * 100 : 0;

    const totalStaked = slips.reduce((acc, s) => acc + s.stake, 0);
    const totalReturned = settledSlips
      .filter(s => s.status === SlipStatus.WON)
      .reduce((acc, s) => acc + s.potentialReturn, 0);

    const settledStaked = settledSlips.reduce((acc, s) => acc + s.stake, 0);
    const profit = totalReturned - settledStaked;
    const roi = settledStaked > 0 ? (profit / settledStaked) * 100 : 0;

    setStats({
      totalSlips,
      wins,
      losses,
      winRate,
      totalStaked,
      totalReturned,
      profit,
      roi
    });
  }, [slips]);

  const handleSaveSlip = (savedSlip: Slip) => {
    const exists = slips.find(s => s.id === savedSlip.id);

    if (exists) {
      // If we are editing, we don't handle balance here as it's complex 
      // but if the status changes from Pending to Won, we handle it in handleUpdate
      setSlips(slips.map(s => s.id === savedSlip.id ? savedSlip : s));
    } else {
      // New bet - deduct from bankroll
      setBankroll(prev => prev - savedSlip.stake);
      setSlips([savedSlip, ...slips]);
    }
    setEditingSlip(null);
    setActiveTab('active');
  };

  const handleUpdateSlip = (updatedSlip: Slip) => {
    const oldSlip = slips.find(s => s.id === updatedSlip.id);
    if (oldSlip) {
      // Logic for adding winnings to bankroll
      // If it moves from NOT WON to WON, add potential return
      if (oldSlip.status !== SlipStatus.WON && updatedSlip.status === SlipStatus.WON) {
        setBankroll(prev => prev + updatedSlip.potentialReturn);
      }
      // If it moves from WON to something else (correction), deduct return
      else if (oldSlip.status === SlipStatus.WON && updatedSlip.status !== SlipStatus.WON) {
        setBankroll(prev => prev - updatedSlip.potentialReturn);
      }
    }
    setSlips(slips.map(s => s.id === updatedSlip.id ? updatedSlip : s));
  };

  const handleEditSlip = (slip: Slip) => {
    setEditingSlip(slip);
    setActiveTab('create');
  };

  const handleResetStats = () => {
    if (confirm("Are you sure you want to delete all betting history? This cannot be undone.")) {
      setSlips([]);
      setBankroll(STARTING_BALANCE);
      setShowSettings(false);
    }
  };

  const handleTopUp = (amount: number) => {
    setBankroll(prev => prev + amount);
  };

  const handleAddLeague = () => {
    const trimmed = newLeagueInput.trim();
    if (trimmed && !customLeagues.includes(trimmed)) {
      setCustomLeagues([...customLeagues, trimmed]);
      setNewLeagueInput('');
    }
  };

  const handleRemoveLeague = (league: string) => {
    setCustomLeagues(customLeagues.filter(l => l !== league));
  };

  const handleRenameFolder = (oldName: string, newName: string) => {
    const trimmed = newName.trim();
    if (!trimmed || trimmed === oldName) return;

    if (uniqueFolders.includes(trimmed)) {
      if (!confirm(`Folder "${trimmed}" already exists. Do you want to merge "${oldName}" into it?`)) {
        return;
      }
    }

    setSlips(slips.map(s => s.folder === oldName ? { ...s, folder: trimmed } : s));
    if (selectedFolder === oldName) setSelectedFolder(trimmed);
  };

  const handleDeleteFolder = (folderName: string) => {
    if (confirm(`Are you sure you want to delete folder "${folderName}"? The bets will remain but will be ungrouped.`)) {
      setSlips(slips.map(s => s.folder === folderName ? { ...s, folder: undefined } : s));
      if (selectedFolder === folderName) setSelectedFolder('All');
    }
  };

  // Filter Slips based on status AND selected folder
  const activeSlips = slips.filter(s => 
    s.status === SlipStatus.PENDING && 
    (selectedFolder === 'All' || s.folder === selectedFolder)
  );

  const settledSlips = slips.filter(s => 
    s.status !== SlipStatus.PENDING && 
    (selectedFolder === 'All' || s.folder === selectedFolder)
  );

  const filteredSlipsForOverview = slips.filter(s => 
    selectedFolder === 'All' || s.folder === selectedFolder
  );

  return (
    <div className="min-h-screen bg-background pb-20 md:pb-0 transition-colors duration-300">
      {/* Top Navigation / Header */}
      <header className="bg-surface border-b border-borderBase sticky top-0 z-50 transition-colors">
        <div className="max-w-5xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
             <div className="bg-primary p-1.5 rounded-lg">
               <TrendingUp className="text-white" size={20} />
             </div>
             <h1 className="text-xl font-bold text-textMain tracking-tight">SmartBet<span className="text-primary">Tracker</span></h1>
          </div>
          <div className="hidden md:flex items-center gap-1 bg-inputBg p-1 rounded-lg border border-borderBase">
             <NavButton active={activeTab === 'dashboard'} onClick={() => setActiveTab('dashboard')} icon={LayoutDashboard} label="Overview" />
             <NavButton active={activeTab === 'active'} onClick={() => setActiveTab('active')} icon={Wallet} label="Active" badge={slips.filter(s => s.status === SlipStatus.PENDING).length} />
             <NavButton active={activeTab === 'stats'} onClick={() => setActiveTab('stats')} icon={BarChart3} label="Analytics" />
             <NavButton active={activeTab === 'settled'} onClick={() => setActiveTab('settled')} icon={History} label="History" />
          </div>

          <div className="flex items-center gap-4">
            {/* Virtual Wallet Display */}
            <div className="hidden sm:flex items-center gap-2 bg-inputBg border border-borderBase px-3 py-1.5 rounded-lg">
              <div className="bg-success/20 text-success p-1 rounded">
                <Coins size={14} />
              </div>
              <div className="flex flex-col leading-none">
                <span className="text-[10px] text-textMuted font-bold uppercase">Demo Balance</span>
                <span className="text-sm font-bold text-textMain">{CURRENCY_SYMBOLS[currency]}{bankroll.toFixed(2)}</span>
              </div>
            </div>

            <div className="flex gap-2">
              <button 
                onClick={() => setShowSettings(true)}
                className="p-2 rounded-lg text-textMuted hover:text-textMain hover:bg-inputBg transition-colors"
              >
                <SettingsIcon size={20} />
              </button>
              <button 
                onClick={() => { setEditingSlip(null); setActiveTab('create'); }}
                className="bg-primary hover:bg-blue-600 text-white px-4 py-2 rounded-lg text-sm font-bold flex items-center gap-2 transition-colors shadow-lg shadow-blue-500/20"
              >
                <PlusCircle size={18} /> <span className="hidden sm:inline">New Bet</span>
              </button>
            </div>
          </div>
        </div>
      </header>

      {/* Settings Modal */}
      {showSettings && (
        <div className="fixed inset-0 z-[100] bg-background/80 backdrop-blur-sm flex items-center justify-center p-4 animate-fade-in">
          <div className="bg-surface border border-borderBase rounded-xl shadow-2xl w-full max-w-md overflow-hidden max-h-[90vh] flex flex-col">
            <div className="p-4 border-b border-borderBase flex justify-between items-center bg-inputBg">
               <h3 className="font-bold text-textMain flex items-center gap-2">
                 <SettingsIcon size={18} className="text-primary" /> Settings
               </h3>
               <button onClick={() => setShowSettings(false)} className="text-textMuted hover:text-textMain">
                 <X size={20} />
               </button>
            </div>
            <div className="p-6 space-y-6 overflow-y-auto">
               {/* Bankroll Management */}
               <div className="space-y-3">
                 <span className="text-textMain font-medium flex items-center gap-2">
                   <Wallet size={16} className="text-primary" /> Demo Account Balance
                 </span>
                 <div className="flex items-center justify-between bg-inputBg p-3 rounded-lg border border-borderBase">
                    <span className="text-lg font-bold text-textMain">{CURRENCY_SYMBOLS[currency]}{bankroll.toFixed(2)}</span>
                    <button 
                      onClick={() => handleTopUp(1000)}
                      className="bg-success hover:bg-emerald-600 text-white px-3 py-1.5 rounded-lg text-xs font-bold flex items-center gap-1 transition-colors"
                    >
                      <Plus size={14} /> Top Up 1k
                    </button>
                 </div>
               </div>

               {/* Theme Toggle */}
               <div className="flex items-center justify-between">
                 <span className="text-textMain font-medium">Appearance</span>
                 <div className="flex bg-inputBg rounded-lg p-1 border border-borderBase">
                    <button 
                      onClick={() => setTheme('light')}
                      className={`p-2 rounded flex items-center gap-2 text-xs font-bold transition-all ${theme === 'light' ? 'bg-surface shadow text-primary' : 'text-textMuted'}`}
                    >
                      <Sun size={14} /> Light
                    </button>
                    <button 
                      onClick={() => setTheme('dark')}
                      className={`p-2 rounded flex items-center gap-2 text-xs font-bold transition-all ${theme === 'dark' ? 'bg-surface shadow text-primary' : 'text-textMuted'}`}
                    >
                      <Moon size={14} /> Dark
                    </button>
                 </div>
               </div>

               {/* Currency Select */}
               <div className="flex items-center justify-between">
                 <span className="text-textMain font-medium">Currency</span>
                 <select 
                   value={currency}
                   onChange={(e) => setCurrency(e.target.value as Currency)}
                   className="bg-inputBg border border-borderBase rounded-lg px-3 py-1.5 text-textMain text-sm focus:outline-none focus:border-primary"
                 >
                   <option value="ZAR">ZAR (R)</option>
                   <option value="USD">USD ($)</option>
                   <option value="GBP">GBP (£)</option>
                 </select>
               </div>

               {/* League Management */}
               <div className="space-y-3 pt-4 border-t border-borderBase">
                  <span className="text-textMain font-medium flex items-center gap-2">
                    <Trophy size={16} className="text-primary" /> Manage Leagues
                  </span>
                  <div className="flex gap-2">
                    <input 
                      type="text"
                      placeholder="e.g. Champions League"
                      value={newLeagueInput}
                      onChange={(e) => setNewLeagueInput(e.target.value)}
                      onKeyDown={(e) => e.key === 'Enter' && handleAddLeague()}
                      className="flex-1 bg-inputBg border border-borderBase rounded-lg px-3 py-2 text-sm text-textMain focus:outline-none focus:border-primary"
                    />
                    <button 
                      onClick={handleAddLeague}
                      className="bg-primary text-white p-2 rounded-lg hover:bg-blue-600 transition-colors"
                    >
                      <Plus size={20} />
                    </button>
                  </div>
                  <div className="flex flex-wrap gap-2">
                    {customLeagues.map(league => (
                      <div key={league} className="flex items-center gap-1 bg-inputBg border border-borderBase px-3 py-1 rounded-full text-xs text-textMain group">
                        {league}
                        <button 
                          onClick={() => handleRemoveLeague(league)}
                          className="text-textMuted hover:text-danger ml-1"
                        >
                          <X size={12} />
                        </button>
                      </div>
                    ))}
                  </div>
               </div>

               {/* Folder Management */}
               <div className="space-y-3 pt-4 border-t border-borderBase">
                  <span className="text-textMain font-medium flex items-center gap-2">
                    <FolderOpen size={16} /> Manage Folders
                  </span>
                  <div className="bg-background/50 rounded-lg border border-borderBase p-2 max-h-48 overflow-y-auto space-y-2">
                    {uniqueFolders.length === 0 ? (
                      <p className="text-xs text-textMuted italic text-center py-2">No folders created yet.</p>
                    ) : (
                      uniqueFolders.map(folder => (
                        <FolderRow 
                          key={folder} 
                          name={folder} 
                          onRename={handleRenameFolder} 
                          onDelete={handleDeleteFolder} 
                        />
                      ))
                    )}
                  </div>
               </div>

               <div className="border-t border-borderBase pt-6">
                 <button 
                   onClick={handleResetStats}
                   className="w-full py-3 rounded-lg border border-danger/30 text-danger hover:bg-danger hover:text-white transition-all font-bold flex items-center justify-center gap-2"
                 >
                   <Trash2 size={18} /> Reset All Stats & Data
                 </button>
               </div>
            </div>
          </div>
        </div>
      )}

      {/* Mobile Bottom Nav */}
      <div className="md:hidden fixed bottom-0 left-0 right-0 bg-surface border-t border-borderBase z-40 px-6 py-3 flex justify-between items-center">
        <MobileNavButton active={activeTab === 'dashboard'} onClick={() => setActiveTab('dashboard')} icon={LayoutDashboard} label="Overview" />
        <MobileNavButton active={activeTab === 'active'} onClick={() => setActiveTab('active')} icon={Wallet} label="Active" badge={activeSlips.length} />
        <MobileNavButton active={activeTab === 'stats'} onClick={() => setActiveTab('stats')} icon={BarChart3} label="Analytics" />
        <MobileNavButton active={activeTab === 'create'} onClick={() => { setEditingSlip(null); setActiveTab('create'); }} icon={PlusCircle} label="New" />
      </div>

      {/* Main Content */}
      <main className="max-w-5xl mx-auto px-4 py-8">

        {/* Betting Folders Filter (Main Panel) */}
        {uniqueFolders.length > 0 && activeTab !== 'create' && (
          <div className="mb-6 overflow-x-auto pb-2 scrollbar-hide">
             <div className="flex gap-2">
               <button
                 onClick={() => setSelectedFolder('All')}
                 className={`px-4 py-2 rounded-full text-xs font-bold whitespace-nowrap border transition-all ${
                   selectedFolder === 'All' 
                     ? 'bg-primary text-white border-primary' 
                     : 'bg-surface text-textMuted border-borderBase hover:bg-inputBg'
                 }`}
               >
                 All Bets
               </button>
               {uniqueFolders.map(folder => (
                 <button
                   key={folder}
                   onClick={() => setSelectedFolder(folder)}
                   className={`px-4 py-2 rounded-full text-xs font-bold whitespace-nowrap border flex items-center gap-2 transition-all ${
                     selectedFolder === folder 
                       ? 'bg-primary text-white border-primary' 
                       : 'bg-surface text-textMuted border-borderBase hover:bg-inputBg'
                   }`}
                 >
                   <FolderOpen size={14} /> {folder}
                 </button>
               ))}
             </div>
          </div>
        )}

        {activeTab === 'dashboard' && (
          <div className="space-y-8 animate-fade-in">
            {/* Quick Stats + Demo Top Up Widget */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
               <StatsCard title="Virtual Balance" value={bankroll.toFixed(2)} isMoney currency={currency} icon={Coins} color="text-success" />
               <StatsCard title="Net Profit" value={stats.profit.toFixed(2)} isMoney currency={currency} icon={Wallet} color={stats.profit >= 0 ? 'text-success' : 'text-danger'} />
               <StatsCard title="Win Rate" value={`${stats.winRate.toFixed(1)}%`} icon={Trophy} color="text-warning" />
               <StatsCard title="ROI" value={`${stats.roi.toFixed(1)}%`} icon={TrendingUp} color={stats.roi >= 0 ? 'text-success' : 'text-danger'} />
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
              <div className="lg:col-span-2 space-y-4">
                <div className="flex items-center justify-between">
                  <h2 className="text-xl font-bold text-textMain flex items-center gap-2">
                    <History className="text-textMuted" size={20} /> Recent Activity {selectedFolder !== 'All' && `(${selectedFolder})`}
                  </h2>
                </div>
                <SlipList slips={filteredSlipsForOverview.slice(0, 5)} onUpdateSlip={handleUpdateSlip} onEditSlip={handleEditSlip} currency={currency} />
              </div>

              <div className="space-y-6">
                 {/* Top Up Promo Widget */}
                 <div className="bg-gradient-to-br from-primary to-blue-600 p-6 rounded-xl border border-primary/20 shadow-xl shadow-primary/10 relative overflow-hidden group">
                    <div className="relative z-10">
                      <h3 className="text-white font-bold text-lg mb-1">Low on Demo Cash?</h3>
                      <p className="text-white/80 text-xs mb-4">Refill your virtual bankroll instantly to keep practicing your strategies.</p>
                      <button 
                        onClick={() => handleTopUp(2500)}
                        className="w-full bg-white text-primary py-2.5 rounded-lg font-bold text-sm flex items-center justify-center gap-2 hover:bg-white/90 transition-all active:scale-[0.98]"
                      >
                        <ArrowUpCircle size={18} /> Top Up {CURRENCY_SYMBOLS[currency]}2,500
                      </button>
                    </div>
                    {/* Background decoration */}
                    <Coins className="absolute -bottom-4 -right-4 text-white/10 rotate-12 transition-transform group-hover:scale-125" size={120} />
                 </div>

                 <div className="bg-surface p-6 rounded-xl border border-borderBase">
                    <h3 className="text-textMain font-bold mb-4">Settlement Accuracy</h3>
                    <div className="space-y-4">
                       <div className="flex justify-between text-sm">
                          <span className="text-textMuted">Wins</span>
                          <span className="text-success font-bold">{stats.wins}</span>
                       </div>
                       <div className="w-full bg-inputBg rounded-full h-2">
                          <div className="bg-success h-2 rounded-full" style={{ width: `${stats.totalSlips ? (stats.wins/stats.totalSlips)*100 : 0}%` }}></div>
                       </div>
                       <div className="flex justify-between text-sm">
                          <span className="text-textMuted">Losses</span>
                          <span className="text-danger font-bold">{stats.losses}</span>
                       </div>
                        <div className="w-full bg-inputBg rounded-full h-2">
                          <div className="bg-danger h-2 rounded-full" style={{ width: `${stats.totalSlips ? (stats.losses/stats.totalSlips)*100 : 0}%` }}></div>
                       </div>
                    </div>
                 </div>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'create' && (
          <div className="max-w-3xl mx-auto animate-fade-in">
             {bankroll < 5 && (
               <div className="mb-6 p-4 bg-warning/10 border border-warning/30 rounded-lg flex items-center justify-between">
                 <p className="text-warning text-sm font-medium">Your demo balance is very low ({CURRENCY_SYMBOLS[currency]}{bankroll.toFixed(2)}).</p>
                 <button onClick={() => handleTopUp(1000)} className="text-xs font-bold bg-warning text-white px-3 py-1 rounded">Top Up 1k</button>
               </div>
             )}
             <NewSlipForm 
               initialData={editingSlip || undefined}
               onSave={handleSaveSlip} 
               onCancel={() => { setEditingSlip(null); setActiveTab('dashboard'); }} 
               currency={currency}
               availableFolders={uniqueFolders}
               availableLeagues={customLeagues}
             />
          </div>
        )}

        {activeTab === 'stats' && (
           <StatisticsPanel slips={filteredSlipsForOverview} currency={currency} />
        )}

        {activeTab === 'active' && (
          <div className="space-y-4 animate-fade-in">
             <h2 className="text-xl font-bold text-textMain mb-6">Active Slips {selectedFolder !== 'All' && `(${selectedFolder})`}</h2>
             <SlipList slips={activeSlips} onUpdateSlip={handleUpdateSlip} onEditSlip={handleEditSlip} currency={currency} />
          </div>
        )}

        {activeTab === 'settled' && (
          <div className="space-y-4 animate-fade-in">
             <h2 className="text-xl font-bold text-textMain mb-6">Betting History {selectedFolder !== 'All' && `(${selectedFolder})`}</h2>
             <SlipList slips={settledSlips} onUpdateSlip={handleUpdateSlip} onEditSlip={handleEditSlip} currency={currency} />
          </div>
        )}

      </main>
    </div>
  );
};

// Internal component for folder row
interface FolderRowProps {
  name: string;
  onRename: (oldName: string, newName: string) => void;
  onDelete: (folderName: string) => void;
}

const FolderRow: React.FC<FolderRowProps> = ({ name, onRename, onDelete }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [val, setVal] = useState(name);

  const handleSave = () => {
    if (val.trim() && val.trim() !== name) {
      onRename(name, val);
    }
    setIsEditing(false);
  };

  if (isEditing) {
    return (
      <div className="flex gap-2 items-center bg-inputBg p-2 rounded border border-primary">
        <input 
          className="flex-1 bg-transparent border-none outline-none text-sm text-textMain"
          value={val}
          onChange={e => setVal(e.target.value)}
          autoFocus
          onKeyDown={(e) => {
            if (e.key === 'Enter') handleSave();
            if (e.key === 'Escape') { setIsEditing(false); setVal(name); }
          }}
        />
        <button onClick={handleSave} className="text-success hover:bg-success/10 p-1 rounded"><Check size={14}/></button>
        <button onClick={() => { setIsEditing(false); setVal(name); }} className="text-danger hover:bg-danger/10 p-1 rounded"><X size={14}/></button>
      </div>
    )
  }
  return (
    <div className="flex justify-between items-center bg-inputBg p-2 rounded border border-borderBase hover:border-textMuted transition-colors group">
      <span className="text-sm text-textMain">{name}</span>
      <div className="flex gap-2 opacity-60 group-hover:opacity-100 transition-opacity">
         <button onClick={() => setIsEditing(true)} className="text-textMuted hover:text-primary p-1" title="Rename"><Edit2 size={14}/></button>
         <button onClick={() => onDelete(name)} className="text-textMuted hover:text-danger p-1" title="Ungroup bets"><Trash2 size={14}/></button>
      </div>
    </div>
  )
}

// Helper Components for Nav
const NavButton = ({ active, onClick, icon: Icon, label, badge }: any) => (
  <button 
    onClick={onClick}
    className={`px-4 py-2 rounded-md text-sm font-medium flex items-center gap-2 transition-all ${active ? 'bg-inputBg text-textMain shadow-sm border border-borderBase' : 'text-textMuted hover:text-textMain hover:bg-inputBg'}`}
  >
    <Icon size={16} /> {label}
    {badge > 0 && <span className="bg-primary text-white text-[10px] px-1.5 py-0.5 rounded-full">{badge}</span>}
  </button>
);

const MobileNavButton = ({ active, onClick, icon: Icon, label, badge }: any) => (
  <button 
    onClick={onClick}
    className={`flex flex-col items-center gap-1 ${active ? 'text-primary' : 'text-textMuted'}`}
  >
    <div className="relative">
      <Icon size={24} />
      {badge > 0 && <span className="absolute -top-1 -right-1 bg-red-500 text-white text-[10px] w-4 h-4 flex items-center justify-center rounded-full border border-surface">{badge}</span>}
    </div>
    <span className="text-[10px] font-medium">{label}</span>
  </button>
);

export default App;

import React, { useState, useEffect } from 'react';
import { LayoutDashboard, PlusCircle, History, Wallet, TrendingUp, Trophy, Settings as SettingsIcon, Sun, Moon, Trash2, X, BarChart3, FolderOpen, Edit2, Check, Plus, Coins, ArrowUpCircle, Save } from 'lucide-react';
import { Slip, SlipStatus, Stats, Currency, CURRENCY_SYMBOLS } from './types';
import { StatsCard } from './components/StatsCard';
import { SlipList } from './components/SlipList';
import { NewSlipForm } from './components/NewSlipForm';
import { StatisticsPanel } from './components/StatisticsPanel';

const DEFAULT_LEAGUES = [
  'EPL', 'La Liga', 'Bundesliga', 'Serie A', 'Ligue 1', 
  'UCL', 'UEL', 'MLS', 'Eredivisie', 'Championship'
];

const STARTING_BALANCE = 1000;

const App: React.FC = () => {
  // State Initialization with LocalStorage
  const [activeTab, setActiveTab] = useState<'dashboard' | 'active' | 'settled' | 'create' | 'stats'>('dashboard');

  const [slips, setSlips] = useState<Slip[]>(() => {
    const saved = localStorage.getItem('smartbet_slips');
    return saved ? JSON.parse(saved) : [];
  });

  const [theme, setTheme] = useState<'light' | 'dark'>(() => {
    return (localStorage.getItem('smartbet_theme') as 'light' | 'dark') || 'dark';
  });

  const [currency, setCurrency] = useState<Currency>(() => {
    return (localStorage.getItem('smartbet_currency') as Currency) || 'ZAR';
  });

  const [bankroll, setBankroll] = useState<number>(() => {
    const saved = localStorage.getItem('smartbet_bankroll');
    return saved !== null ? parseFloat(saved) : STARTING_BALANCE;
  });

  const [customLeagues, setCustomLeagues] = useState<string[]>(() => {
    const saved = localStorage.getItem('smartbet_custom_leagues');
    return saved ? JSON.parse(saved) : DEFAULT_LEAGUES;
  });

  // Folder state
  const [selectedFolder, setSelectedFolder] = useState<string>('All');

  const [showSettings, setShowSettings] = useState(false);
  const [editingSlip, setEditingSlip] = useState<Slip | null>(null);
  const [newLeagueInput, setNewLeagueInput] = useState('');

  // Balance editing state
  const [isEditingBalance, setIsEditingBalance] = useState(false);
  const [balanceInput, setBalanceInput] = useState(bankroll.toString());

  const [stats, setStats] = useState<Stats>({
    totalSlips: 0,
    wins: 0,
    losses: 0,
    winRate: 0,
    totalStaked: 0,
    totalReturned: 0,
    profit: 0,
    roi: 0
  });

  // Derived state for unique folders
  const uniqueFolders = React.useMemo(() => {
    const folders = new Set<string>();
    slips.forEach(s => {
      if (s.folder) folders.add(s.folder);
    });
    return Array.from(folders).sort();
  }, [slips]);

  // Persist State
  useEffect(() => {
    localStorage.setItem('smartbet_slips', JSON.stringify(slips));
  }, [slips]);

  useEffect(() => {
    localStorage.setItem('smartbet_bankroll', bankroll.toString());
    if (!isEditingBalance) {
      setBalanceInput(bankroll.toString());
    }
  }, [bankroll]);

  useEffect(() => {
    localStorage.setItem('smartbet_theme', theme);
    const root = window.document.documentElement;
    if (theme === 'dark') {
      root.classList.add('dark');
    } else {
      root.classList.remove('dark');
    }
  }, [theme]);

  useEffect(() => {
    localStorage.setItem('smartbet_currency', currency);
  }, [currency]);

  useEffect(() => {
    localStorage.setItem('smartbet_custom_leagues', JSON.stringify(customLeagues));
  }, [customLeagues]);


  // Calculate Stats
  useEffect(() => {
    const settledSlips = slips.filter(s => s.status === SlipStatus.WON || s.status === SlipStatus.LOST);
    const totalSlips = settledSlips.length;
    const wins = settledSlips.filter(s => s.status === SlipStatus.WON).length;
    const losses = settledSlips.filter(s => s.status === SlipStatus.LOST).length;
    const winRate = totalSlips > 0 ? (wins / totalSlips) * 100 : 0;

    const totalStaked = slips.reduce((acc, s) => acc + s.stake, 0);
    const totalReturned = settledSlips
      .filter(s => s.status === SlipStatus.WON)
      .reduce((acc, s) => acc + s.potentialReturn, 0);

    const settledStaked = settledSlips.reduce((acc, s) => acc + s.stake, 0);
    const profit = totalReturned - settledStaked;
    const roi = settledStaked > 0 ? (profit / settledStaked) * 100 : 0;

    setStats({
      totalSlips,
      wins,
      losses,
      winRate,
      totalStaked,
      totalReturned,
      profit,
      roi
    });
  }, [slips]);

  const handleSaveSlip = (savedSlip: Slip) => {
    const exists = slips.find(s => s.id === savedSlip.id);

    if (exists) {
      setSlips(slips.map(s => s.id === savedSlip.id ? savedSlip : s));
    } else {
      setBankroll(prev => prev - savedSlip.stake);
      setSlips([savedSlip, ...slips]);
    }
    setEditingSlip(null);
    setActiveTab('active');
  };

  const handleUpdateSlip = (updatedSlip: Slip) => {
    const oldSlip = slips.find(s => s.id === updatedSlip.id);
    if (oldSlip) {
      if (oldSlip.status !== SlipStatus.WON && updatedSlip.status === SlipStatus.WON) {
        setBankroll(prev => prev + updatedSlip.potentialReturn);
      }
      else if (oldSlip.status === SlipStatus.WON && updatedSlip.status !== SlipStatus.WON) {
        setBankroll(prev => prev - updatedSlip.potentialReturn);
      }
    }
    setSlips(slips.map(s => s.id === updatedSlip.id ? updatedSlip : s));
  };

  const handleEditSlip = (slip: Slip) => {
    setEditingSlip(slip);
    setActiveTab('create');
  };

  const handleResetStats = () => {
    if (confirm("Are you sure you want to delete all betting history? This cannot be undone.")) {
      setSlips([]);
      setBankroll(STARTING_BALANCE);
      setShowSettings(false);
    }
  };

  const handleTopUp = (amount: number) => {
    setBankroll(prev => prev + amount);
  };

  const handleSetBalance = () => {
    const val = parseFloat(balanceInput);
    if (!isNaN(val)) {
      setBankroll(val);
      setIsEditingBalance(false);
    }
  };

  const handleAddLeague = () => {
    const trimmed = newLeagueInput.trim();
    if (trimmed && !customLeagues.includes(trimmed)) {
      setCustomLeagues([...customLeagues, trimmed]);
      setNewLeagueInput('');
    }
  };

  const handleRemoveLeague = (league: string) => {
    setCustomLeagues(customLeagues.filter(l => l !== league));
  };

  const handleRenameFolder = (oldName: string, newName: string) => {
    const trimmed = newName.trim();
    if (!trimmed || trimmed === oldName) return;

    if (uniqueFolders.includes(trimmed)) {
      if (!confirm(`Folder "${trimmed}" already exists. Do you want to merge "${oldName}" into it?`)) {
        return;
      }
    }

    setSlips(slips.map(s => s.folder === oldName ? { ...s, folder: trimmed } : s));
    if (selectedFolder === oldName) setSelectedFolder(trimmed);
  };

  const handleDeleteFolder = (folderName: string) => {
    if (confirm(`Are you sure you want to delete folder "${folderName}"? The bets will remain but will be ungrouped.`)) {
      setSlips(slips.map(s => s.folder === folderName ? { ...s, folder: undefined } : s));
      if (selectedFolder === folderName) setSelectedFolder('All');
    }
  };

  // Filter Slips based on status AND selected folder
  const activeSlips = slips.filter(s => 
    s.status === SlipStatus.PENDING && 
    (selectedFolder === 'All' || s.folder === selectedFolder)
  );

  const settledSlips = slips.filter(s => 
    s.status !== SlipStatus.PENDING && 
    (selectedFolder === 'All' || s.folder === selectedFolder)
  );

  const filteredSlipsForOverview = slips.filter(s => 
    selectedFolder === 'All' || s.folder === selectedFolder
  );

  return (
    <div className="min-h-screen bg-background pb-20 md:pb-0 transition-colors duration-300">
      <header className="bg-surface border-b border-borderBase sticky top-0 z-50 transition-colors">
        <div className="max-w-5xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
             <div className="bg-primary p-1.5 rounded-lg">
               <TrendingUp className="text-white" size={20} />
             </div>
             <h1 className="text-xl font-bold text-textMain tracking-tight">SmartBet<span className="text-primary">Tracker</span></h1>
          </div>
          <div className="hidden md:flex items-center gap-1 bg-inputBg p-1 rounded-lg border border-borderBase">
             <NavButton active={activeTab === 'dashboard'} onClick={() => setActiveTab('dashboard')} icon={LayoutDashboard} label="Overview" />
             <NavButton active={activeTab === 'active'} onClick={() => setActiveTab('active')} icon={Wallet} label="Active" badge={slips.filter(s => s.status === SlipStatus.PENDING).length} />
             <NavButton active={activeTab === 'stats'} onClick={() => setActiveTab('stats')} icon={BarChart3} label="Analytics" />
             <NavButton active={activeTab === 'settled'} onClick={() => setActiveTab('settled')} icon={History} label="History" />
          </div>

          <div className="flex items-center gap-4">
            <div className="hidden sm:flex items-center gap-2 bg-inputBg border border-borderBase px-3 py-1.5 rounded-lg">
              <div className="bg-success/20 text-success p-1 rounded">
                <Coins size={14} />
              </div>
              <div className="flex flex-col leading-none">
                <span className="text-[10px] text-textMuted font-bold uppercase">Demo Balance</span>
                <span className="text-sm font-bold text-textMain">{CURRENCY_SYMBOLS[currency]}{bankroll.toFixed(2)}</span>
              </div>
            </div>

            <div className="flex gap-2">
              <button 
                onClick={() => setShowSettings(true)}
                className="p-2 rounded-lg text-textMuted hover:text-textMain hover:bg-inputBg transition-colors"
              >
                <SettingsIcon size={20} />
              </button>
              <button 
                onClick={() => { setEditingSlip(null); setActiveTab('create'); }}
                className="bg-primary hover:bg-blue-600 text-white px-4 py-2 rounded-lg text-sm font-bold flex items-center gap-2 transition-colors shadow-lg shadow-blue-500/20"
              >
                <PlusCircle size={18} /> <span className="hidden sm:inline">New Bet</span>
              </button>
            </div>
          </div>
        </div>
      </header>

      {showSettings && (
        <div className="fixed inset-0 z-[100] bg-background/80 backdrop-blur-sm flex items-center justify-center p-4 animate-fade-in">
          <div className="bg-surface border border-borderBase rounded-xl shadow-2xl w-full max-w-md overflow-hidden max-h-[90vh] flex flex-col">
            <div className="p-4 border-b border-borderBase flex justify-between items-center bg-inputBg">
               <h3 className="font-bold text-textMain flex items-center gap-2">
                 <SettingsIcon size={18} className="text-primary" /> Settings
               </h3>
               <button onClick={() => setShowSettings(false)} className="text-textMuted hover:text-textMain">
                 <X size={20} />
               </button>
            </div>
            <div className="p-6 space-y-6 overflow-y-auto">
               <div className="space-y-3">
                 <div className="flex justify-between items-center">
                   <span className="text-textMain font-medium flex items-center gap-2">
                     <Wallet size={16} className="text-primary" /> Demo Account Balance
                   </span>
                   {!isEditingBalance && (
                     <button onClick={() => setIsEditingBalance(true)} className="text-[10px] font-bold text-primary hover:underline uppercase tracking-wider">
                       Edit Manually
                     </button>
                   )}
                 </div>

                 {isEditingBalance ? (
                   <div className="flex gap-2 animate-fade-in">
                     <div className="relative flex-1">
                        <span className="absolute left-3 top-1/2 -translate-y-1/2 text-textMuted font-bold">{CURRENCY_SYMBOLS[currency]}</span>
                        <input 
                          type="number" 
                          value={balanceInput}
                          onChange={(e) => setBalanceInput(e.target.value)}
                          className="w-full bg-inputBg border border-primary rounded-lg pl-8 pr-3 py-2 text-textMain font-bold focus:outline-none"
                          autoFocus
                        />
                     </div>
                     <button onClick={handleSetBalance} className="bg-primary text-white p-2 rounded-lg hover:bg-blue-600 transition-colors"><Check size={20} /></button>
                     <button onClick={() => setIsEditingBalance(false)} className="bg-inputBg border border-borderBase text-textMuted p-2 rounded-lg hover:text-textMain transition-colors"><X size={20} /></button>
                   </div>
                 ) : (
                   <div className="flex items-center justify-between bg-inputBg p-3 rounded-lg border border-borderBase">
                      <span className="text-lg font-bold text-textMain">{CURRENCY_SYMBOLS[currency]}{bankroll.toFixed(2)}</span>
                      <div className="flex gap-2">
                        <button 
                          onClick={() => handleTopUp(1000)}
                          className="bg-success hover:bg-emerald-600 text-white px-3 py-1.5 rounded-lg text-xs font-bold flex items-center gap-1 transition-colors"
                        >
                          <Plus size={14} /> Top Up 1k
                        </button>
                      </div>
                   </div>
                 )}
               </div>

               <div className="flex items-center justify-between">
                 <span className="text-textMain font-medium">Appearance</span>
                 <div className="flex bg-inputBg rounded-lg p-1 border border-borderBase">
                    <button 
                      onClick={() => setTheme('light')}
                      className={`p-2 rounded flex items-center gap-2 text-xs font-bold transition-all ${theme === 'light' ? 'bg-surface shadow text-primary' : 'text-textMuted'}`}
                    >
                      <Sun size={14} /> Light
                    </button>
                    <button 
                      onClick={() => setTheme('dark')}
                      className={`p-2 rounded flex items-center gap-2 text-xs font-bold transition-all ${theme === 'dark' ? 'bg-surface shadow text-primary' : 'text-textMuted'}`}
                    >
                      <Moon size={14} /> Dark
                    </button>
                 </div>
               </div>

               <div className="flex items-center justify-between">
                 <span className="text-textMain font-medium">Currency</span>
                 <select 
                   value={currency}
                   onChange={(e) => setCurrency(e.target.value as Currency)}
                   className="bg-inputBg border border-borderBase rounded-lg px-3 py-1.5 text-textMain text-sm focus:outline-none focus:border-primary"
                 >
                   <option value="ZAR">ZAR (R)</option>
                   <option value="USD">USD ($)</option>
                   <option value="GBP">GBP (£)</option>
                 </select>
               </div>

               <div className="space-y-3 pt-4 border-t border-borderBase">
                  <span className="text-textMain font-medium flex items-center gap-2">
                    <Trophy size={16} className="text-primary" /> Manage Leagues
                  </span>
                  <div className="flex gap-2">
                    <input 
                      type="text"
                      placeholder="e.g. Champions League"
                      value={newLeagueInput}
                      onChange={(e) => setNewLeagueInput(e.target.value)}
                      onKeyDown={(e) => e.key === 'Enter' && handleAddLeague()}
                      className="flex-1 bg-inputBg border border-borderBase rounded-lg px-3 py-2 text-sm text-textMain focus:outline-none focus:border-primary"
                    />
                    <button 
                      onClick={handleAddLeague}
                      className="bg-primary text-white p-2 rounded-lg hover:bg-blue-600 transition-colors"
                    >
                      <Plus size={20} />
                    </button>
                  </div>
                  <div className="flex flex-wrap gap-2">
                    {customLeagues.map(league => (
                      <div key={league} className="flex items-center gap-1 bg-inputBg border border-borderBase px-3 py-1 rounded-full text-xs text-textMain group">
                        {league}
                        <button 
                          onClick={() => handleRemoveLeague(league)}
                          className="text-textMuted hover:text-danger ml-1"
                        >
                          <X size={12} />
                        </button>
                      </div>
                    ))}
                  </div>
               </div>

               <div className="space-y-3 pt-4 border-t border-borderBase">
                  <span className="text-textMain font-medium flex items-center gap-2">
                    <FolderOpen size={16} /> Manage Folders
                  </span>
                  <div className="bg-background/50 rounded-lg border border-borderBase p-2 max-h-48 overflow-y-auto space-y-2">
                    {uniqueFolders.length === 0 ? (
                      <p className="text-xs text-textMuted italic text-center py-2">No folders created yet.</p>
                    ) : (
                      uniqueFolders.map(folder => (
                        <FolderRow 
                          key={folder} 
                          name={folder} 
                          onRename={handleRenameFolder} 
                          onDelete={handleDeleteFolder} 
                        />
                      ))
                    )}
                  </div>
               </div>

               <div className="border-t border-borderBase pt-6">
                 <button 
                   onClick={handleResetStats}
                   className="w-full py-3 rounded-lg border border-danger/30 text-danger hover:bg-danger hover:text-white transition-all font-bold flex items-center justify-center gap-2"
                 >
                   <Trash2 size={18} /> Reset All Stats & Data
                 </button>
               </div>
            </div>
          </div>
        </div>
      )}

      <div className="md:hidden fixed bottom-0 left-0 right-0 bg-surface border-t border-borderBase z-40 px-6 py-3 flex justify-between items-center">
        <MobileNavButton active={activeTab === 'dashboard'} onClick={() => setActiveTab('dashboard')} icon={LayoutDashboard} label="Overview" />
        <MobileNavButton active={activeTab === 'active'} onClick={() => setActiveTab('active')} icon={Wallet} label="Active" badge={activeSlips.filter(s => s.status === SlipStatus.PENDING).length} />
        <MobileNavButton active={activeTab === 'stats'} onClick={() => setActiveTab('stats')} icon={BarChart3} label="Analytics" />
        <MobileNavButton active={activeTab === 'create'} onClick={() => { setEditingSlip(null); setActiveTab('create'); }} icon={PlusCircle} label="New" />
      </div>

      <main className="max-w-5xl mx-auto px-4 py-8">

        {uniqueFolders.length > 0 && activeTab !== 'create' && (
          <div className="mb-6 overflow-x-auto pb-2 scrollbar-hide">
             <div className="flex gap-2">
               <button
                 onClick={() => setSelectedFolder('All')}
                 className={`px-4 py-2 rounded-full text-xs font-bold whitespace-nowrap border transition-all ${
                   selectedFolder === 'All' 
                     ? 'bg-primary text-white border-primary' 
                     : 'bg-surface text-textMuted border-borderBase hover:bg-inputBg'
                 }`}
               >
                 All Bets
               </button>
               {uniqueFolders.map(folder => (
                 <button
                   key={folder}
                   onClick={() => setSelectedFolder(folder)}
                   className={`px-4 py-2 rounded-full text-xs font-bold whitespace-nowrap border flex items-center gap-2 transition-all ${
                     selectedFolder === folder 
                       ? 'bg-primary text-white border-primary' 
                       : 'bg-surface text-textMuted border-borderBase hover:bg-inputBg'
                   }`}
                 >
                   <FolderOpen size={14} /> {folder}
                 </button>
               ))}
             </div>
          </div>
        )}

        {activeTab === 'dashboard' && (
          <div className="space-y-8 animate-fade-in">
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
               <StatsCard title="Virtual Balance" value={bankroll.toFixed(2)} isMoney currency={currency} icon={Coins} color="text-success" />
               <StatsCard title="Net Profit" value={stats.profit.toFixed(2)} isMoney currency={currency} icon={Wallet} color={stats.profit >= 0 ? 'text-success' : 'text-danger'} />
               <StatsCard title="Win Rate" value={`${stats.winRate.toFixed(1)}%`} icon={Trophy} color="text-warning" />
               <StatsCard title="ROI" value={`${stats.roi.toFixed(1)}%`} icon={TrendingUp} color={stats.roi >= 0 ? 'text-success' : 'text-danger'} />
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
              <div className="lg:col-span-2 space-y-4">
                <div className="flex items-center justify-between">
                  <h2 className="text-xl font-bold text-textMain flex items-center gap-2">
                    <History className="text-textMuted" size={20} /> Recent Activity {selectedFolder !== 'All' && `(${selectedFolder})`}
                  </h2>
                </div>
                <SlipList slips={filteredSlipsForOverview.slice(0, 5)} onUpdateSlip={handleUpdateSlip} onEditSlip={handleEditSlip} currency={currency} />
              </div>

              <div className="space-y-6">
                 <div className="bg-gradient-to-br from-primary to-blue-600 p-6 rounded-xl border border-primary/20 shadow-xl shadow-primary/10 relative overflow-hidden group">
                    <div className="relative z-10">
                      <h3 className="text-white font-bold text-lg mb-1">Low on Demo Cash?</h3>
                      <p className="text-white/80 text-xs mb-4">Refill your virtual bankroll instantly to keep practicing your strategies.</p>
                      <button 
                        onClick={() => handleTopUp(2500)}
                        className="w-full bg-white text-primary py-2.5 rounded-lg font-bold text-sm flex items-center justify-center gap-2 hover:bg-white/90 transition-all active:scale-[0.98]"
                      >
                        <ArrowUpCircle size={18} /> Top Up {CURRENCY_SYMBOLS[currency]}2,500
                      </button>
                    </div>
                    <Coins className="absolute -bottom-4 -right-4 text-white/10 rotate-12 transition-transform group-hover:scale-125" size={120} />
                 </div>

                 <div className="bg-surface p-6 rounded-xl border border-borderBase">
                    <h3 className="text-textMain font-bold mb-4">Settlement Accuracy</h3>
                    <div className="space-y-4">
                       <div className="flex justify-between text-sm">
                          <span className="text-textMuted">Wins</span>
                          <span className="text-success font-bold">{stats.wins}</span>
                       </div>
                       <div className="w-full bg-inputBg rounded-full h-2">
                          <div className="bg-success h-2 rounded-full" style={{ width: `${stats.totalSlips ? (stats.wins/stats.totalSlips)*100 : 0}%` }}></div>
                       </div>
                       <div className="flex justify-between text-sm">
                          <span className="text-textMuted">Losses</span>
                          <span className="text-danger font-bold">{stats.losses}</span>
                       </div>
                        <div className="w-full bg-inputBg rounded-full h-2">
                          <div className="bg-danger h-2 rounded-full" style={{ width: `${stats.totalSlips ? (stats.losses/stats.totalSlips)*100 : 0}%` }}></div>
                       </div>
                    </div>
                 </div>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'create' && (
          <div className="max-w-3xl mx-auto animate-fade-in">
             {bankroll < 5 && (
               <div className="mb-6 p-4 bg-warning/10 border border-warning/30 rounded-lg flex items-center justify-between">
                 <p className="text-warning text-sm font-medium">Your demo balance is very low ({CURRENCY_SYMBOLS[currency]}{bankroll.toFixed(2)}).</p>
                 <button onClick={() => handleTopUp(1000)} className="text-xs font-bold bg-warning text-white px-3 py-1 rounded">Top Up 1k</button>
               </div>
             )}
             <NewSlipForm 
               initialData={editingSlip || undefined}
               onSave={handleSaveSlip} 
               onCancel={() => { setEditingSlip(null); setActiveTab('dashboard'); }} 
               currency={currency}
               availableFolders={uniqueFolders}
               availableLeagues={customLeagues}
             />
          </div>
        )}

        {activeTab === 'stats' && (
           <StatisticsPanel slips={filteredSlipsForOverview} currency={currency} />
        )}

        {activeTab === 'active' && (
          <div className="space-y-4 animate-fade-in">
             <h2 className="text-xl font-bold text-textMain mb-6">Active Slips {selectedFolder !== 'All' && `(${selectedFolder})`}</h2>
             <SlipList slips={slips.filter(s => s.status === SlipStatus.PENDING && (selectedFolder === 'All' || s.folder === selectedFolder))} onUpdateSlip={handleUpdateSlip} onEditSlip={handleEditSlip} currency={currency} />
          </div>
        )}

        {activeTab === 'settled' && (
          <div className="space-y-4 animate-fade-in">
             <h2 className="text-xl font-bold text-textMain mb-6">Betting History {selectedFolder !== 'All' && `(${selectedFolder})`}</h2>
             <SlipList slips={slips.filter(s => s.status !== SlipStatus.PENDING && (selectedFolder === 'All' || s.folder === selectedFolder))} onUpdateSlip={handleUpdateSlip} onEditSlip={handleEditSlip} currency={currency} />
          </div>
        )}

      </main>
    </div>
  );
};

// Internal component for folder row
interface FolderRowProps {
  name: string;
  onRename: (oldName: string, newName: string) => void;
  onDelete: (folderName: string) => void;
}

const FolderRow: React.FC<FolderRowProps> = ({ name, onRename, onDelete }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [val, setVal] = useState(name);

  const handleSave = () => {
    if (val.trim() && val.trim() !== name) {
      onRename(name, val);
    }
    setIsEditing(false);
  };

  if (isEditing) {
    return (
      <div className="flex gap-2 items-center bg-inputBg p-2 rounded border border-primary">
        <input 
          className="flex-1 bg-transparent border-none outline-none text-sm text-textMain"
          value={val}
          onChange={e => setVal(e.target.value)}
          autoFocus
          onKeyDown={(e) => {
            if (e.key === 'Enter') handleSave();
            if (e.key === 'Escape') { setIsEditing(false); setVal(name); }
          }}
        />
        <button onClick={handleSave} className="text-success hover:bg-success/10 p-1 rounded"><Check size={14}/></button>
        <button onClick={() => { setIsEditing(false); setVal(name); }} className="text-danger hover:bg-danger/10 p-1 rounded"><X size={14}/></button>
      </div>
    )
  }
  return (
    <div className="flex justify-between items-center bg-inputBg p-2 rounded border border-borderBase hover:border-textMuted transition-colors group">
      <span className="text-sm text-textMain">{name}</span>
      <div className="flex gap-2 opacity-60 group-hover:opacity-100 transition-opacity">
         <button onClick={() => setIsEditing(true)} className="text-textMuted hover:text-primary p-1" title="Rename"><Edit2 size={14}/></button>
         <button onClick={() => onDelete(name)} className="text-textMuted hover:text-danger p-1" title="Ungroup bets"><Trash2 size={14}/></button>
      </div>
    </div>
  )
}

const NavButton = ({ active, onClick, icon: Icon, label, badge }: any) => (
  <button 
    onClick={onClick}
    className={`px-4 py-2 rounded-md text-sm font-medium flex items-center gap-2 transition-all ${active ? 'bg-inputBg text-textMain shadow-sm border border-borderBase' : 'text-textMuted hover:text-textMain hover:bg-inputBg'}`}
  >
    <Icon size={16} /> {label}
    {badge > 0 && <span className="bg-primary text-white text-[10px] px-1.5 py-0.5 rounded-full">{badge}</span>}
  </button>
);

const MobileNavButton = ({ active, onClick, icon: Icon, label, badge }: any) => (
  <button 
    onClick={onClick}
    className={`flex flex-col items-center gap-1 ${active ? 'text-primary' : 'text-textMuted'}`}
  >
    <div className="relative">
      <Icon size={24} />
      {badge > 0 && <span className="absolute -top-1 -right-1 bg-red-500 text-white text-[10px] w-4 h-4 flex items-center justify-center rounded-full border border-surface">{badge}</span>}
    </div>
    <span className="text-[10px] font-medium">{label}</span>
  </button>
);

export default App;

import React, { useState, useEffect } from 'react';
import { LayoutDashboard, PlusCircle, History, Wallet, TrendingUp, Trophy, Settings as SettingsIcon, Sun, Moon, Trash2, X, BarChart3, FolderOpen, Edit2, Check, Plus, Coins, ArrowUpCircle, Save } from 'lucide-react';
import { Slip, SlipStatus, Stats, Currency, CURRENCY_SYMBOLS } from './types';
import { StatsCard } from './components/StatsCard';
import { SlipList } from './components/SlipList';
import { NewSlipForm } from './components/NewSlipForm';
import { StatisticsPanel } from './components/StatisticsPanel';

const DEFAULT_LEAGUES = [
  'EPL', 'La Liga', 'Bundesliga', 'Serie A', 'Ligue 1', 
  'UCL', 'UEL', 'MLS', 'Eredivisie', 'Championship'
];

const STARTING_BALANCE = 1000;

const App: React.FC = () => {
  // State Initialization with LocalStorage
  const [activeTab, setActiveTab] = useState<'dashboard' | 'active' | 'settled' | 'create' | 'stats'>('dashboard');

  const [slips, setSlips] = useState<Slip[]>(() => {
    const saved = localStorage.getItem('smartbet_slips');
    return saved ? JSON.parse(saved) : [];
  });

  const [theme, setTheme] = useState<'light' | 'dark'>(() => {
    return (localStorage.getItem('smartbet_theme') as 'light' | 'dark') || 'dark';
  });

  const [currency, setCurrency] = useState<Currency>(() => {
    return (localStorage.getItem('smartbet_currency') as Currency) || 'ZAR';
  });

  const [bankroll, setBankroll] = useState<number>(() => {
    const saved = localStorage.getItem('smartbet_bankroll');
    return saved !== null ? parseFloat(saved) : STARTING_BALANCE;
  });

  const [customLeagues, setCustomLeagues] = useState<string[]>(() => {
    const saved = localStorage.getItem('smartbet_custom_leagues');
    return saved ? JSON.parse(saved) : DEFAULT_LEAGUES;
  });

  // Folder state
  const [selectedFolder, setSelectedFolder] = useState<string>('All');

  const [showSettings, setShowSettings] = useState(false);
  const [editingSlip, setEditingSlip] = useState<Slip | null>(null);
  const [newLeagueInput, setNewLeagueInput] = useState('');

  // Balance editing state
  const [isEditingBalance, setIsEditingBalance] = useState(false);
  const [balanceInput, setBalanceInput] = useState(bankroll.toString());

  const [stats, setStats] = useState<Stats>({
    totalSlips: 0,
    wins: 0,
    losses: 0,
    winRate: 0,
    totalStaked: 0,
    totalReturned: 0,
    profit: 0,
    roi: 0
  });

  // Derived state for unique folders
  const uniqueFolders = React.useMemo(() => {
    const folders = new Set<string>();
    slips.forEach(s => {
      if (s.folder) folders.add(s.folder);
    });
    return Array.from(folders).sort();
  }, [slips]);

  // Persist State
  useEffect(() => {
    localStorage.setItem('smartbet_slips', JSON.stringify(slips));
  }, [slips]);

  useEffect(() => {
    localStorage.setItem('smartbet_bankroll', bankroll.toString());
    if (!isEditingBalance) {
      setBalanceInput(bankroll.toString());
    }
  }, [bankroll]);

  useEffect(() => {
    localStorage.setItem('smartbet_theme', theme);
    const root = window.document.documentElement;
    if (theme === 'dark') {
      root.classList.add('dark');
    } else {
      root.classList.remove('dark');
    }
  }, [theme]);

  useEffect(() => {
    localStorage.setItem('smartbet_currency', currency);
  }, [currency]);

  useEffect(() => {
    localStorage.setItem('smartbet_custom_leagues', JSON.stringify(customLeagues));
  }, [customLeagues]);


  // Calculate Stats
  useEffect(() => {
    const settledSlips = slips.filter(s => s.status === SlipStatus.WON || s.status === SlipStatus.LOST);
    const totalSlips = settledSlips.length;
    const wins = settledSlips.filter(s => s.status === SlipStatus.WON).length;
    const losses = settledSlips.filter(s => s.status === SlipStatus.LOST).length;
    const winRate = totalSlips > 0 ? (wins / totalSlips) * 100 : 0;

    const totalStaked = slips.reduce((acc, s) => acc + s.stake, 0);
    const totalReturned = settledSlips
      .filter(s => s.status === SlipStatus.WON)
      .reduce((acc, s) => acc + s.potentialReturn, 0);

    const settledStaked = settledSlips.reduce((acc, s) => acc + s.stake, 0);
    const profit = totalReturned - settledStaked;
    const roi = settledStaked > 0 ? (profit / settledStaked) * 100 : 0;

    setStats({
      totalSlips,
      wins,
      losses,
      winRate,
      totalStaked,
      totalReturned,
      profit,
      roi
    });
  }, [slips]);

  const handleSaveSlip = (savedSlip: Slip) => {
    const exists = slips.find(s => s.id === savedSlip.id);

    if (exists) {
      setSlips(slips.map(s => s.id === savedSlip.id ? savedSlip : s));
    } else {
      setBankroll(prev => prev - savedSlip.stake);
      setSlips([savedSlip, ...slips]);
    }
    setEditingSlip(null);
    setActiveTab('active');
  };

  const handleUpdateSlip = (updatedSlip: Slip) => {
    const oldSlip = slips.find(s => s.id === updatedSlip.id);
    if (oldSlip) {
      if (oldSlip.status !== SlipStatus.WON && updatedSlip.status === SlipStatus.WON) {
        setBankroll(prev => prev + updatedSlip.potentialReturn);
      }
      else if (oldSlip.status === SlipStatus.WON && updatedSlip.status !== SlipStatus.WON) {
        setBankroll(prev => prev - updatedSlip.potentialReturn);
      }
    }
    setSlips(slips.map(s => s.id === updatedSlip.id ? updatedSlip : s));
  };

  const handleEditSlip = (slip: Slip) => {
    setEditingSlip(slip);
    setActiveTab('create');
  };

  const handleResetStats = () => {
    if (confirm("Are you sure you want to delete all betting history? This cannot be undone.")) {
      setSlips([]);
      setBankroll(STARTING_BALANCE);
      setShowSettings(false);
    }
  };

  const handleSetBalance = () => {
    const val = parseFloat(balanceInput);
    if (!isNaN(val)) {
      setBankroll(val);
      setIsEditingBalance(false);
    }
  };

  const handleAddLeague = () => {
    const trimmed = newLeagueInput.trim();
    if (trimmed && !customLeagues.includes(trimmed)) {
      setCustomLeagues([...customLeagues, trimmed]);
      setNewLeagueInput('');
    }
  };

  const handleRemoveLeague = (league: string) => {
    setCustomLeagues(customLeagues.filter(l => l !== league));
  };

  const handleRenameFolder = (oldName: string, newName: string) => {
    const trimmed = newName.trim();
    if (!trimmed || trimmed === oldName) return;

    if (uniqueFolders.includes(trimmed)) {
      if (!confirm(`Folder "${trimmed}" already exists. Do you want to merge "${oldName}" into it?`)) {
        return;
      }
    }

    setSlips(slips.map(s => s.folder === oldName ? { ...s, folder: trimmed } : s));
    if (selectedFolder === oldName) setSelectedFolder(trimmed);
  };

  const handleDeleteFolder = (folderName: string) => {
    if (confirm(`Are you sure you want to delete folder "${folderName}"? The bets will remain but will be ungrouped.`)) {
      setSlips(slips.map(s => s.folder === folderName ? { ...s, folder: undefined } : s));
      if (selectedFolder === folderName) setSelectedFolder('All');
    }
  };

  // Filter Slips based on status AND selected folder
  const activeSlips = slips.filter(s => 
    s.status === SlipStatus.PENDING && 
    (selectedFolder === 'All' || s.folder === selectedFolder)
  );

  const settledSlips = slips.filter(s => 
    s.status !== SlipStatus.PENDING && 
    (selectedFolder === 'All' || s.folder === selectedFolder)
  );

  const filteredSlipsForOverview = slips.filter(s => 
    selectedFolder === 'All' || s.folder === selectedFolder
  );

  return (
    <div className="min-h-screen bg-background pb-20 md:pb-0 transition-colors duration-300">
      <header className="bg-surface border-b border-borderBase sticky top-0 z-50 transition-colors">
        <div className="max-w-5xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
             <div className="bg-primary p-1.5 rounded-lg">
               <TrendingUp className="text-white" size={20} />
             </div>
             <h1 className="text-xl font-bold text-textMain tracking-tight">SmartBet<span className="text-primary">Tracker</span></h1>
          </div>
          <div className="hidden md:flex items-center gap-1 bg-inputBg p-1 rounded-lg border border-borderBase">
             <NavButton active={activeTab === 'dashboard'} onClick={() => setActiveTab('dashboard')} icon={LayoutDashboard} label="Overview" />
             <NavButton active={activeTab === 'active'} onClick={() => setActiveTab('active')} icon={Wallet} label="Active" badge={slips.filter(s => s.status === SlipStatus.PENDING).length} />
             <NavButton active={activeTab === 'stats'} onClick={() => setActiveTab('stats')} icon={BarChart3} label="Analytics" />
             <NavButton active={activeTab === 'settled'} onClick={() => setActiveTab('settled')} icon={History} label="History" />
          </div>

          <div className="flex items-center gap-4">
            <div className="hidden sm:flex items-center gap-2 bg-inputBg border border-borderBase px-3 py-1.5 rounded-lg">
              <div className="bg-success/20 text-success p-1 rounded">
                <Coins size={14} />
              </div>
              <div className="flex flex-col leading-none">
                <span className="text-[10px] text-textMuted font-bold uppercase">Demo Balance</span>
                <span className="text-sm font-bold text-textMain">{CURRENCY_SYMBOLS[currency]}{bankroll.toFixed(2)}</span>
              </div>
            </div>

            <div className="flex gap-2">
              <button 
                onClick={() => setShowSettings(true)}
                className="p-2 rounded-lg text-textMuted hover:text-textMain hover:bg-inputBg transition-colors"
              >
                <SettingsIcon size={20} />
              </button>
              <button 
                onClick={() => { setEditingSlip(null); setActiveTab('create'); }}
                className="bg-primary hover:bg-blue-600 text-white px-4 py-2 rounded-lg text-sm font-bold flex items-center gap-2 transition-colors shadow-lg shadow-blue-500/20"
              >
                <PlusCircle size={18} /> <span className="hidden sm:inline">New Bet</span>
              </button>
            </div>
          </div>
        </div>
      </header>

      {showSettings && (
        <div className="fixed inset-0 z-[100] bg-background/80 backdrop-blur-sm flex items-center justify-center p-4 animate-fade-in">
          <div className="bg-surface border border-borderBase rounded-xl shadow-2xl w-full max-w-md overflow-hidden max-h-[90vh] flex flex-col">
            <div className="p-4 border-b border-borderBase flex justify-between items-center bg-inputBg">
               <h3 className="font-bold text-textMain flex items-center gap-2">
                 <SettingsIcon size={18} className="text-primary" /> Settings
               </h3>
               <button onClick={() => setShowSettings(false)} className="text-textMuted hover:text-textMain">
                 <X size={20} />
               </button>
            </div>
            <div className="p-6 space-y-6 overflow-y-auto">
               <div className="space-y-3">
                 <div className="flex justify-between items-center">
                   <span className="text-textMain font-medium flex items-center gap-2">
                     <Wallet size={16} className="text-primary" /> Demo Account Balance
                   </span>
                   {!isEditingBalance && (
                     <button onClick={() => setIsEditingBalance(true)} className="text-[10px] font-bold text-primary hover:underline uppercase tracking-wider">
                       Edit Manually
                     </button>
                   )}
                 </div>

                 {isEditingBalance ? (
                   <div className="flex gap-2 animate-fade-in">
                     <div className="relative flex-1">
                        <span className="absolute left-3 top-1/2 -translate-y-1/2 text-textMuted font-bold">{CURRENCY_SYMBOLS[currency]}</span>
                        <input 
                          type="number" 
                          value={balanceInput}
                          onChange={(e) => setBalanceInput(e.target.value)}
                          className="w-full bg-inputBg border border-primary rounded-lg pl-8 pr-3 py-2 text-textMain font-bold focus:outline-none"
                          autoFocus
                        />
                     </div>
                     <button onClick={handleSetBalance} className="bg-primary text-white p-2 rounded-lg hover:bg-blue-600 transition-colors"><Check size={20} /></button>
                     <button onClick={() => setIsEditingBalance(false)} className="bg-inputBg border border-borderBase text-textMuted p-2 rounded-lg hover:text-textMain transition-colors"><X size={20} /></button>
                   </div>
                 ) : (
                   <div className="flex items-center justify-between bg-inputBg p-3 rounded-lg border border-borderBase">
                      <span className="text-lg font-bold text-textMain">{CURRENCY_SYMBOLS[currency]}{bankroll.toFixed(2)}</span>
                   </div>
                 )}
               </div>

               <div className="flex items-center justify-between">
                 <span className="text-textMain font-medium">Appearance</span>
                 <div className="flex bg-inputBg rounded-lg p-1 border border-borderBase">
                    <button 
                      onClick={() => setTheme('light')}
                      className={`p-2 rounded flex items-center gap-2 text-xs font-bold transition-all ${theme === 'light' ? 'bg-surface shadow text-primary' : 'text-textMuted'}`}
                    >
                      <Sun size={14} /> Light
                    </button>
                    <button 
                      onClick={() => setTheme('dark')}
                      className={`p-2 rounded flex items-center gap-2 text-xs font-bold transition-all ${theme === 'dark' ? 'bg-surface shadow text-primary' : 'text-textMuted'}`}
                    >
                      <Moon size={14} /> Dark
                    </button>
                 </div>
               </div>

               <div className="flex items-center justify-between">
                 <span className="text-textMain font-medium">Currency</span>
                 <select 
                   value={currency}
                   onChange={(e) => setCurrency(e.target.value as Currency)}
                   className="bg-inputBg border border-borderBase rounded-lg px-3 py-1.5 text-textMain text-sm focus:outline-none focus:border-primary"
                 >
                   <option value="ZAR">ZAR (R)</option>
                   <option value="USD">USD ($)</option>
                   <option value="GBP">GBP (£)</option>
                 </select>
               </div>

               <div className="space-y-3 pt-4 border-t border-borderBase">
                  <span className="text-textMain font-medium flex items-center gap-2">
                    <Trophy size={16} className="text-primary" /> Manage Leagues
                  </span>
                  <div className="flex gap-2">
                    <input 
                      type="text"
                      placeholder="e.g. Champions League"
                      value={newLeagueInput}
                      onChange={(e) => setNewLeagueInput(e.target.value)}
                      onKeyDown={(e) => e.key === 'Enter' && handleAddLeague()}
                      className="flex-1 bg-inputBg border border-borderBase rounded-lg px-3 py-2 text-sm text-textMain focus:outline-none focus:border-primary"
                    />
                    <button 
                      onClick={handleAddLeague}
                      className="bg-primary text-white p-2 rounded-lg hover:bg-blue-600 transition-colors"
                    >
                      <Plus size={20} />
                    </button>
                  </div>
                  <div className="flex flex-wrap gap-2">
                    {customLeagues.map(league => (
                      <div key={league} className="flex items-center gap-1 bg-inputBg border border-borderBase px-3 py-1 rounded-full text-xs text-textMain group">
                        {league}
                        <button 
                          onClick={() => handleRemoveLeague(league)}
                          className="text-textMuted hover:text-danger ml-1"
                        >
                          <X size={12} />
                        </button>
                      </div>
                    ))}
                  </div>
               </div>

               <div className="space-y-3 pt-4 border-t border-borderBase">
                  <span className="text-textMain font-medium flex items-center gap-2">
                    <FolderOpen size={16} /> Manage Folders
                  </span>
                  <div className="bg-background/50 rounded-lg border border-borderBase p-2 max-h-48 overflow-y-auto space-y-2">
                    {uniqueFolders.length === 0 ? (
                      <p className="text-xs text-textMuted italic text-center py-2">No folders created yet.</p>
                    ) : (
                      uniqueFolders.map(folder => (
                        <FolderRow 
                          key={folder} 
                          name={folder} 
                          onRename={handleRenameFolder} 
                          onDelete={handleDeleteFolder} 
                        />
                      ))
                    )}
                  </div>
               </div>

               <div className="border-t border-borderBase pt-6">
                 <button 
                   onClick={handleResetStats}
                   className="w-full py-3 rounded-lg border border-danger/30 text-danger hover:bg-danger hover:text-white transition-all font-bold flex items-center justify-center gap-2"
                 >
                   <Trash2 size={18} /> Reset All Stats & Data
                 </button>
               </div>
            </div>
          </div>
        </div>
      )}

      <div className="md:hidden fixed bottom-0 left-0 right-0 bg-surface border-t border-borderBase z-40 px-6 py-3 flex justify-between items-center">
        <MobileNavButton active={activeTab === 'dashboard'} onClick={() => setActiveTab('dashboard')} icon={LayoutDashboard} label="Overview" />
        <MobileNavButton active={activeTab === 'active'} onClick={() => setActiveTab('active')} icon={Wallet} label="Active" badge={activeSlips.filter(s => s.status === SlipStatus.PENDING).length} />
        <MobileNavButton active={activeTab === 'stats'} onClick={() => setActiveTab('stats'} icon={BarChart3} label="Analytics" />
        <MobileNavButton active={activeTab === 'create'} onClick={() => { setEditingSlip(null); setActiveTab('create'); }} icon={PlusCircle} label="New" />
      </div>

      <main className="max-w-5xl mx-auto px-4 py-8">

        {uniqueFolders.length > 0 && activeTab !== 'create' && (
          <div className="mb-6 overflow-x-auto pb-2 scrollbar-hide">
             <div className="flex gap-2">
               <button
                 onClick={() => setSelectedFolder('All')}
                 className={`px-4 py-2 rounded-full text-xs font-bold whitespace-nowrap border transition-all ${
                   selectedFolder === 'All' 
                     ? 'bg-primary text-white border-primary' 
                     : 'bg-surface text-textMuted border-borderBase hover:bg-inputBg'
                 }`}
               >
                 All Bets
               </button>
               {uniqueFolders.map(folder => (
                 <button
                   key={folder}
                   onClick={() => setSelectedFolder(folder)}
                   className={`px-4 py-2 rounded-full text-xs font-bold whitespace-nowrap border flex items-center gap-2 transition-all ${
                     selectedFolder === folder 
                       ? 'bg-primary text-white border-primary' 
                       : 'bg-surface text-textMuted border-borderBase hover:bg-inputBg'
                   }`}
                 >
                   <FolderOpen size={14} /> {folder}
                 </button>
               ))}
             </div>
          </div>
        )}

        {activeTab === 'dashboard' && (
          <div className="space-y-8 animate-fade-in">
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
               <StatsCard title="Virtual Balance" value={bankroll.toFixed(2)} isMoney currency={currency} icon={Coins} color="text-success" />
               <StatsCard title="Net Profit" value={stats.profit.toFixed(2)} isMoney currency={currency} icon={Wallet} color={stats.profit >= 0 ? 'text-success' : 'text-danger'} />
               <StatsCard title="Win Rate" value={`${stats.winRate.toFixed(1)}%`} icon={Trophy} color="text-warning" />
               <StatsCard title="ROI" value={`${stats.roi.toFixed(1)}%`} icon={TrendingUp} color={stats.roi >= 0 ? 'text-success' : 'text-danger'} />
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
              <div className="lg:col-span-2 space-y-4">
                <div className="flex items-center justify-between">
                  <h2 className="text-xl font-bold text-textMain flex items-center gap-2">
                    <History className="text-textMuted" size={20} /> Recent Activity {selectedFolder !== 'All' && `(${selectedFolder})`}
                  </h2>
                </div>
                <SlipList slips={filteredSlipsForOverview.slice(0, 5)} onUpdateSlip={handleUpdateSlip} onEditSlip={handleEditSlip} currency={currency} />
              </div>

              <div className="space-y-6">
                 <div className="bg-surface p-6 rounded-xl border border-borderBase">
                    <h3 className="text-textMain font-bold mb-4">Settlement Accuracy</h3>
                    <div className="space-y-4">
                       <div className="flex justify-between text-sm">
                          <span className="text-textMuted">Wins</span>
                          <span className="text-success font-bold">{stats.wins}</span>
                       </div>
                       <div className="w-full bg-inputBg rounded-full h-2">
                          <div className="bg-success h-2 rounded-full" style={{ width: `${stats.totalSlips ? (stats.wins/stats.totalSlips)*100 : 0}%` }}></div>
                       </div>
                       <div className="flex justify-between text-sm">
                          <span className="text-textMuted">Losses</span>
                          <span className="text-danger font-bold">{stats.losses}</span>
                       </div>
                        <div className="w-full bg-inputBg rounded-full h-2">
                          <div className="bg-danger h-2 rounded-full" style={{ width: `${stats.totalSlips ? (stats.losses/stats.totalSlips)*100 : 0}%` }}></div>
                       </div>
                    </div>
                 </div>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'create' && (
          <div className="max-w-3xl mx-auto animate-fade-in">
             <NewSlipForm 
               initialData={editingSlip || undefined}
               onSave={handleSaveSlip} 
               onCancel={() => { setEditingSlip(null); setActiveTab('dashboard'); }} 
               currency={currency}
               availableFolders={uniqueFolders}
               availableLeagues={customLeagues}
             />
          </div>
        )}

        {activeTab === 'stats' && (
           <StatisticsPanel slips={filteredSlipsForOverview} currency={currency} />
        )}

        {activeTab === 'active' && (
          <div className="space-y-4 animate-fade-in">
             <h2 className="text-xl font-bold text-textMain mb-6">Active Slips {selectedFolder !== 'All' && `(${selectedFolder})`}</h2>
             <SlipList slips={slips.filter(s => s.status === SlipStatus.PENDING && (selectedFolder === 'All' || s.folder === selectedFolder))} onUpdateSlip={handleUpdateSlip} onEditSlip={handleEditSlip} currency={currency} />
          </div>
        )}

        {activeTab === 'settled' && (
          <div className="space-y-4 animate-fade-in">
             <h2 className="text-xl font-bold text-textMain mb-6">Betting History {selectedFolder !== 'All' && `(${selectedFolder})`}</h2>
             <SlipList slips={slips.filter(s => s.status !== SlipStatus.PENDING && (selectedFolder === 'All' || s.folder === selectedFolder))} onUpdateSlip={handleUpdateSlip} onEditSlip={handleEditSlip} currency={currency} />
          </div>
        )}

      </main>
    </div>
  );
};

// Internal component for folder row
interface FolderRowProps {
  name: string;
  onRename: (oldName: string, newName: string) => void;
  onDelete: (folderName: string) => void;
}

const FolderRow: React.FC<FolderRowProps> = ({ name, onRename, onDelete }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [val, setVal] = useState(name);

  const handleSave = () => {
    if (val.trim() && val.trim() !== name) {
      onRename(name, val);
    }
    setIsEditing(false);
  };

  if (isEditing) {
    return (
      <div className="flex gap-2 items-center bg-inputBg p-2 rounded border border-primary">
        <input 
          className="flex-1 bg-transparent border-none outline-none text-sm text-textMain"
          value={val}
          onChange={e => setVal(e.target.value)}
          autoFocus
          onKeyDown={(e) => {
            if (e.key === 'Enter') handleSave();
            if (e.key === 'Escape') { setIsEditing(false); setVal(name); }
          }}
        />
        <button onClick={handleSave} className="text-success hover:bg-success/10 p-1 rounded"><Check size={14}/></button>
        <button onClick={() => { setIsEditing(false); setVal(name); }} className="text-danger hover:bg-danger/10 p-1 rounded"><X size={14}/></button>
      </div>
    )
  }
  return (
    <div className="flex justify-between items-center bg-inputBg p-2 rounded border border-borderBase hover:border-textMuted transition-colors group">
      <span className="text-sm text-textMain">{name}</span>
      <div className="flex gap-2 opacity-60 group-hover:opacity-100 transition-opacity">
         <button onClick={() => setIsEditing(true)} className="text-textMuted hover:text-primary p-1" title="Rename"><Edit2 size={14}/></button>
         <button onClick={() => onDelete(name)} className="text-textMuted hover:text-danger p-1" title="Ungroup bets"><Trash2 size={14}/></button>
      </div>
    </div>
  )
}

const NavButton = ({ active, onClick, icon: Icon, label, badge }: any) => (
  <button 
    onClick={onClick}
    className={`px-4 py-2 rounded-md text-sm font-medium flex items-center gap-2 transition-all ${active ? 'bg-inputBg text-textMain shadow-sm border border-borderBase' : 'text-textMuted hover:text-textMain hover:bg-inputBg'}`}
  >
    <Icon size={16} /> {label}
    {badge > 0 && <span className="bg-primary text-white text-[10px] px-1.5 py-0.5 rounded-full">{badge}</span>}
  </button>
);

const MobileNavButton = ({ active, onClick, icon: Icon, label, badge }: any) => (
  <button 
    onClick={onClick}
    className={`flex flex-col items-center gap-1 ${active ? 'text-primary' : 'text-textMuted'}`}
  >
    <div className="relative">
      <Icon size={24} />
      {badge > 0 && <span className="absolute -top-1 -right-1 bg-red-500 text-white text-[10px] w-4 h-4 flex items-center justify-center rounded-full border border-surface">{badge}</span>}
    </div>
    <span className="text-[10px] font-medium">{label}</span>
  </button>
);

export default App;

import React, { useState, useEffect } from 'react';
import { LayoutDashboard, PlusCircle, History, Wallet, TrendingUp, Trophy, Settings as SettingsIcon, Sun, Moon, Trash2, X, BarChart3, FolderOpen, Edit2, Check, Plus, Coins, ArrowUpCircle, Save } from 'lucide-react';
import { Slip, SlipStatus, Stats, Currency, CURRENCY_SYMBOLS } from './types';
import { StatsCard } from './components/StatsCard';
import { SlipList } from './components/SlipList';
import { NewSlipForm } from './components/NewSlipForm';
import { StatisticsPanel } from './components/StatisticsPanel';

const DEFAULT_LEAGUES = [
  'EPL', 'La Liga', 'Bundesliga', 'Serie A', 'Ligue 1', 
  'UCL', 'UEL', 'MLS', 'Eredivisie', 'Championship'
];

const STARTING_BALANCE = 1000;

const App: React.FC = () => {
  // State Initialization with LocalStorage
  const [activeTab, setActiveTab] = useState<'dashboard' | 'active' | 'settled' | 'create' | 'stats'>('dashboard');

  const [slips, setSlips] = useState<Slip[]>(() => {
    const saved = localStorage.getItem('smartbet_slips');
    return saved ? JSON.parse(saved) : [];
  });

  const [theme, setTheme] = useState<'light' | 'dark'>(() => {
    return (localStorage.getItem('smartbet_theme') as 'light' | 'dark') || 'dark';
  });

  const [currency, setCurrency] = useState<Currency>(() => {
    return (localStorage.getItem('smartbet_currency') as Currency) || 'ZAR';
  });

  const [bankroll, setBankroll] = useState<number>(() => {
    const saved = localStorage.getItem('smartbet_bankroll');
    return saved !== null ? parseFloat(saved) : STARTING_BALANCE;
  });

  const [customLeagues, setCustomLeagues] = useState<string[]>(() => {
    const saved = localStorage.getItem('smartbet_custom_leagues');
    return saved ? JSON.parse(saved) : DEFAULT_LEAGUES;
  });

  // Folder state
  const [selectedFolder, setSelectedFolder] = useState<string>('All');

  const [showSettings, setShowSettings] = useState(false);
  const [editingSlip, setEditingSlip] = useState<Slip | null>(null);
  const [newLeagueInput, setNewLeagueInput] = useState('');

  // Balance editing state
  const [isEditingBalance, setIsEditingBalance] = useState(false);
  const [balanceInput, setBalanceInput] = useState(bankroll.toString());

  const [stats, setStats] = useState<Stats>({
    totalSlips: 0,
    wins: 0,
    losses: 0,
    winRate: 0,
    totalStaked: 0,
    totalReturned: 0,
    profit: 0,
    roi: 0
  });

  // Derived state for unique folders
  const uniqueFolders = React.useMemo(() => {
    const folders = new Set<string>();
    slips.forEach(s => {
      if (s.folder) folders.add(s.folder);
    });
    return Array.from(folders).sort();
  }, [slips]);

  // Persist State
  useEffect(() => {
    localStorage.setItem('smartbet_slips', JSON.stringify(slips));
  }, [slips]);

  useEffect(() => {
    localStorage.setItem('smartbet_bankroll', bankroll.toString());
    if (!isEditingBalance) {
      setBalanceInput(bankroll.toString());
    }
  }, [bankroll]);

  useEffect(() => {
    localStorage.setItem('smartbet_theme', theme);
    const root = window.document.documentElement;
    if (theme === 'dark') {
      root.classList.add('dark');
    } else {
      root.classList.remove('dark');
    }
  }, [theme]);

  useEffect(() => {
    localStorage.setItem('smartbet_currency', currency);
  }, [currency]);

  useEffect(() => {
    localStorage.setItem('smartbet_custom_leagues', JSON.stringify(customLeagues));
  }, [customLeagues]);


  // Calculate Stats
  useEffect(() => {
    const settledSlips = slips.filter(s => s.status === SlipStatus.WON || s.status === SlipStatus.LOST);
    const totalSlips = settledSlips.length;
    const wins = settledSlips.filter(s => s.status === SlipStatus.WON).length;
    const losses = settledSlips.filter(s => s.status === SlipStatus.LOST).length;
    const winRate = totalSlips > 0 ? (wins / totalSlips) * 100 : 0;

    const totalStaked = slips.reduce((acc, s) => acc + s.stake, 0);
    const totalReturned = settledSlips
      .filter(s => s.status === SlipStatus.WON)
      .reduce((acc, s) => acc + s.potentialReturn, 0);

    const settledStaked = settledSlips.reduce((acc, s) => acc + s.stake, 0);
    const profit = totalReturned - settledStaked;
    const roi = settledStaked > 0 ? (profit / settledStaked) * 100 : 0;

    setStats({
      totalSlips,
      wins,
      losses,
      winRate,
      totalStaked,
      totalReturned,
      profit,
      roi
    });
  }, [slips]);

  const handleSaveSlip = (savedSlip: Slip) => {
    const exists = slips.find(s => s.id === savedSlip.id);

    if (exists) {
      setSlips(slips.map(s => s.id === savedSlip.id ? savedSlip : s));
    } else {
      setBankroll(prev => prev - savedSlip.stake);
      setSlips([savedSlip, ...slips]);
    }
    setEditingSlip(null);
    setActiveTab('active');
  };

  const handleUpdateSlip = (updatedSlip: Slip) => {
    const oldSlip = slips.find(s => s.id === updatedSlip.id);
    if (oldSlip) {
      if (oldSlip.status !== SlipStatus.WON && updatedSlip.status === SlipStatus.WON) {
        setBankroll(prev => prev + updatedSlip.potentialReturn);
      }
      else if (oldSlip.status === SlipStatus.WON && updatedSlip.status !== SlipStatus.WON) {
        setBankroll(prev => prev - updatedSlip.potentialReturn);
      }
    }
    setSlips(slips.map(s => s.id === updatedSlip.id ? updatedSlip : s));
  };

  const handleEditSlip = (slip: Slip) => {
    setEditingSlip(slip);
    setActiveTab('create');
  };

  const handleResetStats = () => {
    if (confirm("Are you sure you want to delete all betting history? This cannot be undone.")) {
      setSlips([]);
      setBankroll(STARTING_BALANCE);
      setShowSettings(false);
    }
  };

  const handleSetBalance = () => {
    const val = parseFloat(balanceInput);
    if (!isNaN(val)) {
      setBankroll(val);
      setIsEditingBalance(false);
    }
  };

  const handleAddLeague = () => {
    const trimmed = newLeagueInput.trim();
    if (trimmed && !customLeagues.includes(trimmed)) {
      setCustomLeagues([...customLeagues, trimmed]);
      setNewLeagueInput('');
    }
  };

  const handleRemoveLeague = (league: string) => {
    setCustomLeagues(customLeagues.filter(l => l !== league));
  };

  const handleRenameFolder = (oldName: string, newName: string) => {
    const trimmed = newName.trim();
    if (!trimmed || trimmed === oldName) return;

    if (uniqueFolders.includes(trimmed)) {
      if (!confirm(`Folder "${trimmed}" already exists. Do you want to merge "${oldName}" into it?`)) {
        return;
      }
    }

    setSlips(slips.map(s => s.folder === oldName ? { ...s, folder: trimmed } : s));
    if (selectedFolder === oldName) setSelectedFolder(trimmed);
  };

  const handleDeleteFolder = (folderName: string) => {
    if (confirm(`Are you sure you want to delete folder "${folderName}"? The bets will remain but will be ungrouped.`)) {
      setSlips(slips.map(s => s.folder === folderName ? { ...s, folder: undefined } : s));
      if (selectedFolder === folderName) setSelectedFolder('All');
    }
  };

  return (
    <div className="min-h-screen bg-background pb-20 md:pb-0 transition-colors duration-300">
      <header className="bg-surface border-b border-borderBase sticky top-0 z-50 transition-colors">
        <div className="max-w-5xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
             <div className="bg-primary p-1.5 rounded-lg">
               <TrendingUp className="text-white" size={20} />
             </div>
             <h1 className="text-xl font-bold text-textMain tracking-tight">SmartBet<span className="text-primary">Tracker</span></h1>
          </div>
          <div className="hidden md:flex items-center gap-1 bg-inputBg p-1 rounded-lg border border-borderBase">
             <NavButton active={activeTab === 'dashboard'} onClick={() => setActiveTab('dashboard')} icon={LayoutDashboard} label="Overview" />
             <NavButton active={activeTab === 'active'} onClick={() => setActiveTab('active')} icon={Wallet} label="Active" badge={slips.filter(s => s.status === SlipStatus.PENDING).length} />
             <NavButton active={activeTab === 'stats'} onClick={() => setActiveTab('stats')} icon={BarChart3} label="Analytics" />
             <NavButton active={activeTab === 'settled'} onClick={() => setActiveTab('settled')} icon={History} label="History" />
          </div>

          <div className="flex items-center gap-4">
            <div className="hidden sm:flex items-center gap-2 bg-inputBg border border-borderBase px-3 py-1.5 rounded-lg">
              <div className="bg-success/20 text-success p-1 rounded">
                <Coins size={14} />
              </div>
              <div className="flex flex-col leading-none">
                <span className="text-[10px] text-textMuted font-bold uppercase">Demo Balance</span>
                <span className="text-sm font-bold text-textMain">{CURRENCY_SYMBOLS[currency]}{bankroll.toFixed(2)}</span>
              </div>
            </div>

            <div className="flex gap-2">
              <button 
                onClick={() => setShowSettings(true)}
                className="p-2 rounded-lg text-textMuted hover:text-textMain hover:bg-inputBg transition-colors"
              >
                <SettingsIcon size={20} />
              </button>
              <button 
                onClick={() => { setEditingSlip(null); setActiveTab('create'); }}
                className="bg-primary hover:bg-blue-600 text-white px-4 py-2 rounded-lg text-sm font-bold flex items-center gap-2 transition-colors shadow-lg shadow-blue-500/20"
              >
                <PlusCircle size={18} /> <span className="hidden sm:inline">New Bet</span>
              </button>
            </div>
          </div>
        </div>
      </header>

      {showSettings && (
        <div className="fixed inset-0 z-[100] bg-background/80 backdrop-blur-sm flex items-center justify-center p-4 animate-fade-in">
          <div className="bg-surface border border-borderBase rounded-xl shadow-2xl w-full max-w-md overflow-hidden max-h-[90vh] flex flex-col">
            <div className="p-4 border-b border-borderBase flex justify-between items-center bg-inputBg">
               <h3 className="font-bold text-textMain flex items-center gap-2">
                 <SettingsIcon size={18} className="text-primary" /> Settings
               </h3>
               <button onClick={() => setShowSettings(false)} className="text-textMuted hover:text-textMain">
                 <X size={20} />
               </button>
            </div>
            <div className="p-6 space-y-6 overflow-y-auto">
               <div className="space-y-3">
                 <div className="flex justify-between items-center">
                   <span className="text-textMain font-medium flex items-center gap-2">
                     <Wallet size={16} className="text-primary" /> Demo Account Balance
                   </span>
                   {!isEditingBalance && (
                     <button onClick={() => setIsEditingBalance(true)} className="text-[10px] font-bold text-primary hover:underline uppercase tracking-wider">
                       Edit Manually
                     </button>
                   )}
                 </div>

                 {isEditingBalance ? (
                   <div className="flex gap-2 animate-fade-in">
                     <div className="relative flex-1">
                        <span className="absolute left-3 top-1/2 -translate-y-1/2 text-textMuted font-bold">{CURRENCY_SYMBOLS[currency]}</span>
                        <input 
                          type="number" 
                          value={balanceInput}
                          onChange={(e) => setBalanceInput(e.target.value)}
                          className="w-full bg-inputBg border border-primary rounded-lg pl-8 pr-3 py-2 text-textMain font-bold focus:outline-none"
                          autoFocus
                        />
                     </div>
                     <button onClick={handleSetBalance} className="bg-primary text-white p-2 rounded-lg hover:bg-blue-600 transition-colors"><Check size={20} /></button>
                     <button onClick={() => setIsEditingBalance(false)} className="bg-inputBg border border-borderBase text-textMuted p-2 rounded-lg hover:text-textMain transition-colors"><X size={20} /></button>
                   </div>
                 ) : (
                   <div className="flex items-center justify-between bg-inputBg p-3 rounded-lg border border-borderBase">
                      <span className="text-lg font-bold text-textMain">{CURRENCY_SYMBOLS[currency]}{bankroll.toFixed(2)}</span>
                   </div>
                 )}
               </div>

               <div className="flex items-center justify-between">
                 <span className="text-textMain font-medium">Appearance</span>
                 <div className="flex bg-inputBg rounded-lg p-1 border border-borderBase">
                    <button onClick={() => setTheme('light')} className={`p-2 rounded flex items-center gap-2 text-xs font-bold transition-all ${theme === 'light' ? 'bg-surface shadow text-primary' : 'text-textMuted'}`}><Sun size={14} /> Light</button>
                    <button onClick={() => setTheme('dark')} className={`p-2 rounded flex items-center gap-2 text-xs font-bold transition-all ${theme === 'dark' ? 'bg-surface shadow text-primary' : 'text-textMuted'}`}><Moon size={14} /> Dark</button>
                 </div>
               </div>

               <div className="flex items-center justify-between">
                 <span className="text-textMain font-medium">Currency</span>
                 <select value={currency} onChange={(e) => setCurrency(e.target.value as Currency)} className="bg-inputBg border border-borderBase rounded-lg px-3 py-1.5 text-textMain text-sm focus:outline-none focus:border-primary">
                   <option value="ZAR">ZAR (R)</option>
                   <option value="USD">USD ($)</option>
                   <option value="GBP">GBP (£)</option>
                 </select>
               </div>

               <div className="space-y-3 pt-4 border-t border-borderBase">
                  <span className="text-textMain font-medium flex items-center gap-2"><Trophy size={16} className="text-primary" /> Manage Leagues</span>
                  <div className="flex gap-2">
                    <input type="text" placeholder="e.g. Champions League" value={newLeagueInput} onChange={(e) => setNewLeagueInput(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleAddLeague()} className="flex-1 bg-inputBg border border-borderBase rounded-lg px-3 py-2 text-sm text-textMain focus:outline-none focus:border-primary" />
                    <button onClick={handleAddLeague} className="bg-primary text-white p-2 rounded-lg hover:bg-blue-600 transition-colors"><Plus size={20} /></button>
                  </div>
                  <div className="flex flex-wrap gap-2">
                    {customLeagues.map(league => (
                      <div key={league} className="flex items-center gap-1 bg-inputBg border border-borderBase px-3 py-1 rounded-full text-xs text-textMain group">
                        {league}
                        <button onClick={() => handleRemoveLeague(league)} className="text-textMuted hover:text-danger ml-1"><X size={12} /></button>
                      </div>
                    ))}
                  </div>
               </div>

               <div className="space-y-3 pt-4 border-t border-borderBase">
                  <span className="text-textMain font-medium flex items-center gap-2"><FolderOpen size={16} /> Manage Folders</span>
                  <div className="bg-background/50 rounded-lg border border-borderBase p-2 max-h-48 overflow-y-auto space-y-2">
                    {uniqueFolders.length === 0 ? <p className="text-xs text-textMuted italic text-center py-2">No folders created yet.</p> : uniqueFolders.map(folder => <FolderRow key={folder} name={folder} onRename={handleRenameFolder} onDelete={handleDeleteFolder} />)}
                  </div>
               </div>

               <div className="border-t border-borderBase pt-6">
                 <button onClick={handleResetStats} className="w-full py-3 rounded-lg border border-danger/30 text-danger hover:bg-danger hover:text-white transition-all font-bold flex items-center justify-center gap-2"><Trash2 size={18} /> Reset All Stats & Data</button>
               </div>
            </div>
          </div>
        </div>
      )}

      <div className="md:hidden fixed bottom-0 left-0 right-0 bg-surface border-t border-borderBase z-40 px-6 py-3 flex justify-between items-center">
        <MobileNavButton active={activeTab === 'dashboard'} onClick={() => setActiveTab('dashboard')} icon={LayoutDashboard} label="Overview" />
        <MobileNavButton active={activeTab === 'active'} onClick={() => setActiveTab('active')} icon={Wallet} label="Active" badge={slips.filter(s => s.status === SlipStatus.PENDING).length} />
        <MobileNavButton active={activeTab === 'stats'} onClick={() => setActiveTab('stats')} icon={BarChart3} label="Analytics" />
        <MobileNavButton active={activeTab === 'create'} onClick={() => { setEditingSlip(null); setActiveTab('create'); }} icon={PlusCircle} label="New" />
      </div>

      <main className="max-w-5xl mx-auto px-4 py-8">
        {uniqueFolders.length > 0 && activeTab !== 'create' && (
          <div className="mb-6 overflow-x-auto pb-2 scrollbar-hide">
             <div className="flex gap-2">
               <button onClick={() => setSelectedFolder('All')} className={`px-4 py-2 rounded-full text-xs font-bold whitespace-nowrap border transition-all ${selectedFolder === 'All' ? 'bg-primary text-white border-primary' : 'bg-surface text-textMuted border-borderBase hover:bg-inputBg'}`}>All Bets</button>
               {uniqueFolders.map(folder => (
                 <button key={folder} onClick={() => setSelectedFolder(folder)} className={`px-4 py-2 rounded-full text-xs font-bold whitespace-nowrap border flex items-center gap-2 transition-all ${selectedFolder === folder ? 'bg-primary text-white border-primary' : 'bg-surface text-textMuted border-borderBase hover:bg-inputBg'}`}><FolderOpen size={14} /> {folder}</button>
               ))}
             </div>
          </div>
        )}

        {activeTab === 'dashboard' && (
          <div className="space-y-8 animate-fade-in">
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
               <StatsCard title="Virtual Balance" value={bankroll.toFixed(2)} isMoney currency={currency} icon={Coins} color="text-success" />
               <StatsCard title="Net Profit" value={stats.profit.toFixed(2)} isMoney currency={currency} icon={Wallet} color={stats.profit >= 0 ? 'text-success' : 'text-danger'} />
               <StatsCard title="Win Rate" value={`${stats.winRate.toFixed(1)}%`} icon={Trophy} color="text-warning" />
               <StatsCard title="ROI" value={`${stats.roi.toFixed(1)}%`} icon={TrendingUp} color={stats.roi >= 0 ? 'text-success' : 'text-danger'} />
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
              <div className="lg:col-span-2 space-y-4">
                <div className="flex items-center justify-between"><h2 className="text-xl font-bold text-textMain flex items-center gap-2"><History className="text-textMuted" size={20} /> Recent Activity {selectedFolder !== 'All' && `(${selectedFolder})`}</h2></div>
                <SlipList slips={slips.filter(s => selectedFolder === 'All' || s.folder === selectedFolder).slice(0, 5)} onUpdateSlip={handleUpdateSlip} onEditSlip={handleEditSlip} currency={currency} />
              </div>
              <div className="space-y-6">
                 <div className="bg-surface p-6 rounded-xl border border-borderBase">
                    <h3 className="text-textMain font-bold mb-4">Settlement Accuracy</h3>
                    <div className="space-y-4">
                       <div className="flex justify-between text-sm"><span className="text-textMuted">Wins</span><span className="text-success font-bold">{stats.wins}</span></div>
                       <div className="w-full bg-inputBg rounded-full h-2"><div className="bg-success h-2 rounded-full" style={{ width: `${stats.totalSlips ? (stats.wins/stats.totalSlips)*100 : 0}%` }}></div></div>
                       <div className="flex justify-between text-sm"><span className="text-textMuted">Losses</span><span className="text-danger font-bold">{stats.losses}</span></div>
                        <div className="w-full bg-inputBg rounded-full h-2"><div className="bg-danger h-2 rounded-full" style={{ width: `${stats.totalSlips ? (stats.losses/stats.totalSlips)*100 : 0}%` }}></div></div>
                    </div>
                 </div>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'create' && (
          <div className="max-w-3xl mx-auto animate-fade-in">
             <NewSlipForm initialData={editingSlip || undefined} onSave={handleSaveSlip} onCancel={() => { setEditingSlip(null); setActiveTab('dashboard'); }} currency={currency} availableFolders={uniqueFolders} availableLeagues={customLeagues} />
          </div>
        )}

        {activeTab === 'stats' && <StatisticsPanel slips={slips.filter(s => selectedFolder === 'All' || s.folder === selectedFolder)} currency={currency} />}
        {activeTab === 'active' && <div className="space-y-4 animate-fade-in"><h2 className="text-xl font-bold text-textMain mb-6">Active Slips {selectedFolder !== 'All' && `(${selectedFolder})`}</h2><SlipList slips={slips.filter(s => s.status === SlipStatus.PENDING && (selectedFolder === 'All' || s.folder === selectedFolder))} onUpdateSlip={handleUpdateSlip} onEditSlip={handleEditSlip} currency={currency} /></div>}
        {activeTab === 'settled' && <div className="space-y-4 animate-fade-in"><h2 className="text-xl font-bold text-textMain mb-6">Betting History {selectedFolder !== 'All' && `(${selectedFolder})`}</h2><SlipList slips={slips.filter(s => s.status !== SlipStatus.PENDING && (selectedFolder === 'All' || s.folder === selectedFolder))} onUpdateSlip={handleUpdateSlip} onEditSlip={handleEditSlip} currency={currency} /></div>}
      </main>
    </div>
  );
};

const FolderRow = ({ name, onRename, onDelete }: any) => {
  const [isEditing, setIsEditing] = useState(false);
  const [val, setVal] = useState(name);
  const handleSave = () => { if (val.trim() && val.trim() !== name) onRename(name, val); setIsEditing(false); };
  if (isEditing) return <div className="flex gap-2 items-center bg-inputBg p-2 rounded border border-primary"><input className="flex-1 bg-transparent border-none outline-none text-sm text-textMain" value={val} onChange={e => setVal(e.target.value)} autoFocus onKeyDown={(e) => { if (e.key === 'Enter') handleSave(); if (e.key === 'Escape') { setIsEditing(false); setVal(name); }}} /><button onClick={handleSave} className="text-success hover:bg-success/10 p-1 rounded"><Check size={14}/></button><button onClick={() => { setIsEditing(false); setVal(name); }} className="text-danger hover:bg-danger/10 p-1 rounded"><X size={14}/></button></div>;
  return <div className="flex justify-between items-center bg-inputBg p-2 rounded border border-borderBase hover:border-textMuted transition-colors group"><span className="text-sm text-textMain">{name}</span><div className="flex gap-2 opacity-60 group-hover:opacity-100 transition-opacity"><button onClick={() => setIsEditing(true)} className="text-textMuted hover:text-primary p-1"><Edit2 size={14}/></button><button onClick={() => onDelete(name)} className="text-textMuted hover:text-danger p-1"><Trash2 size={14}/></button></div></div>;
};

const NavButton = ({ active, onClick, icon: Icon, label, badge }: any) => <button onClick={onClick} className={`px-4 py-2 rounded-md text-sm font-medium flex items-center gap-2 transition-all ${active ? 'bg-inputBg text-textMain shadow-sm border border-borderBase' : 'text-textMuted hover:text-textMain hover:bg-inputBg'}`}><Icon size={16} /> {label}{badge > 0 && <span className="bg-primary text-white text-[10px] px-1.5 py-0.5 rounded-full">{badge}</span>}</button>;
const MobileNavButton = ({ active, onClick, icon: Icon, label, badge }: any) => <button onClick={onClick} className={`flex flex-col items-center gap-1 ${active ? 'text-primary' : 'text-textMuted'}`}><div className="relative"><Icon size={24} />{badge > 0 && <span className="absolute -top-1 -right-1 bg-red-500 text-white text-[10px] w-4 h-4 flex items-center justify-center rounded-full border border-surface">{badge}</span>}</div><span className="text-[10px] font-medium">{label}</span></button>;

export default App;

import React, { useState, useEffect } from 'react';
import { Plus, Trash2, Save, ClipboardPaste, X, Edit3, Folder, Globe } from 'lucide-react';
import { BetType, Leg, LegStatus, Slip, SlipStatus, Currency, CURRENCY_SYMBOLS } from '../types';

interface NewSlipFormProps {
  initialData?: Slip;
  onSave: (slip: Slip) => void;
  onCancel: () => void;
  currency: Currency;
  availableFolders: string[];
  availableLeagues: string[];
}

const generateId = () => {
  return Date.now().toString(36) + Math.random().toString(36).substring(2, 9);
};

export const NewSlipForm: React.FC<NewSlipFormProps> = ({ initialData, onSave, onCancel, currency, availableFolders, availableLeagues }) => {
  const [stake, setStake] = useState<string>(() => {
    if (initialData) return initialData.stake.toString();
    const saved = localStorage.getItem('smartbet_draft_stake');
    return saved || '10';
  });

  const [totalOdds, setTotalOdds] = useState<string>(() => {
    if (initialData) return initialData.odds.toString();
    const saved = localStorage.getItem('smartbet_draft_odds');
    return saved || '1.00';
  });

  const [folder, setFolder] = useState<string>(() => {
    if (initialData) return initialData.folder || '';
    return '';
  });

  const [legs, setLegs] = useState<Leg[]>(() => {
    if (initialData) return initialData.legs;
    const saved = localStorage.getItem('smartbet_draft_legs');
    if (saved) return JSON.parse(saved);
    return [{
      id: generateId(),
      matchName: '',
      league: '',
      date: new Date().toISOString().split('T')[0],
      type: BetType.MATCH_WINNER,
      selection: 'Home',
      status: LegStatus.PENDING,
    }];
  });

  const [showImport, setShowImport] = useState(false);
  const [importText, setImportText] = useState('');

  const symbol = CURRENCY_SYMBOLS[currency];
  const isEditing = !!initialData;

  useEffect(() => {
    if (!isEditing) {
      localStorage.setItem('smartbet_draft_stake', stake);
      localStorage.setItem('smartbet_draft_odds', totalOdds);
      localStorage.setItem('smartbet_draft_legs', JSON.stringify(legs));
    }
  }, [stake, totalOdds, legs, isEditing]);

  const clearDraft = () => {
    localStorage.removeItem('smartbet_draft_stake');
    localStorage.removeItem('smartbet_draft_odds');
    localStorage.removeItem('smartbet_draft_legs');
  };

  const addLeg = () => {
    setLegs([
      ...legs,
      {
        id: generateId(),
        matchName: '',
        league: '',
        date: new Date().toISOString().split('T')[0],
        type: BetType.MATCH_WINNER,
        selection: 'Home',
        status: LegStatus.PENDING,
      }
    ]);
  };

  const removeLeg = (id: string) => {
    if (legs.length > 1) {
      setLegs(legs.filter(l => l.id !== id));
    }
  };

  const updateLeg = (id: string, field: keyof Leg, value: any) => {
    setLegs(legs.map(l => {
      if (l.id === id) {
        const updated = { ...l, [field]: value };
        if (field === 'type') {
           if (value === BetType.MATCH_WINNER) updated.selection = 'Home';
           if (value === BetType.BTTS) updated.selection = 'Yes';
           if (value === BetType.SENDING_OFF) updated.selection = 'Yes';
           if (value === BetType.OVER_UNDER) updated.selection = 'Over 2.5';
           if (value === BetType.DOUBLE_CHANCE) updated.selection = '1X';
           if (value === BetType.DRAW_NO_BET) updated.selection = 'Home';
           if (value === BetType.WIN_EITHER_HALF) updated.selection = 'Home - Yes/No';
           if (value === BetType.HANDICAP) updated.selection = 'Home (-0.5)';
           if (value === BetType.TOTAL_CORNERS) updated.selection = 'Over 9.5';
           if (value === BetType.CORNER_1X2) updated.selection = 'Home';
           if (value === BetType.WINNING_MARGIN) updated.selection = 'Home By 1';
           if (value === BetType.HALVES_BTTS) updated.selection = 'No/No';
           if (value === BetType.TEAM_TOTAL) updated.selection = 'Home Over 0.5';
           if (value === BetType.TEN_MINS_1X2) updated.selection = 'Home (1-10\')';
           if (value === BetType.MATCH_RESULT_AND_BTTS) updated.selection = 'Home & Yes';
           if (value === BetType.ODD_EVEN) updated.selection = 'Odd';
           if (value === BetType.BOOKINGS) updated.selection = 'Over 3.5';
           if (value === BetType.BOOKINGS_1X2) updated.selection = 'Home';
        }
        return updated;
      }
      return l;
    }));
  };

  const parseTeams = (matchName: string) => {
    const parts = matchName.split(/\s+v\s+|\s+vs\.?\s+|\s+-\s+|\s+–\s+/i);
    return {
      home: parts[0]?.trim() || 'Home',
      away: parts[1]?.trim() || 'Away'
    };
  };

  const handleNumericChange = (value: string, setter: (v: string) => void) => {
    if (value === '' || /^\d*\.?\d*$/.test(value)) {
      setter(value);
    }
  };

  const handleImport = () => {
    if (!importText.trim()) return;

    try {
      const lines = importText.split('\n').map(l => l.trim()).filter(l => l !== '');
      const newLegs: Leg[] = [];
      let calculatedOdds = 1;
      let i = 0;

      while (i < lines.length) {
        const selectionRaw = lines[i];
        const oddsRaw = lines[i+1];
        const marketRaw = lines[i+2];
        const matchRaw = lines[i+3];
        const dateTimeRaw = lines[i+4];

        if (!selectionRaw || !oddsRaw || !marketRaw || !matchRaw) {
          i++; 
          continue;
        }

        const oddsVal = parseFloat(oddsRaw.replace(/[^0-9.]/g, ''));
        if (isNaN(oddsVal)) { i++; continue; }

        let dateRaw = new Date().toISOString().split('T')[0];
        if (dateTimeRaw) {
          const lowerDT = dateTimeRaw.toLowerCase();
          if (lowerDT.includes('today')) dateRaw = new Date().toISOString().split('T')[0];
          else if (lowerDT.includes('tomorrow')) {
            const d = new Date(); d.setDate(d.getDate() + 1); dateRaw = d.toISOString().split('T')[0];
          } else {
            const match = dateTimeRaw.match(/(\d{1,2})\s+(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)/i);
            if (match) {
              const d = new Date(`${match[1]} ${match[2]} ${new Date().getFullYear()}`);
              if (!isNaN(d.getTime())) dateRaw = d.toISOString().split('T')[0];
            }
          }
        }

        calculatedOdds *= oddsVal;

        let selection = selectionRaw.replace(/^\(|\)$/g, '').trim();
        const mUpper = marketRaw.toUpperCase();
        const { home, away } = parseTeams(matchRaw);
        let type = BetType.MATCH_WINNER;

        if (mUpper.includes('BOTH TEAMS TO SCORE') || mUpper.includes('BTTS') || mUpper.includes('GG/NG')) {
          type = BetType.BTTS;
        } else if (mUpper.includes('TOTAL') || mUpper.includes('OVER/UNDER') || mUpper.includes('GOALS')) {
          if (mUpper.includes('BOOKING') || mUpper.includes('CARD')) type = BetType.BOOKINGS;
          else if (mUpper.includes('CORNER')) type = BetType.TOTAL_CORNERS;
          else if (mUpper.includes(home.toUpperCase()) || mUpper.includes(away.toUpperCase())) {
            type = BetType.TEAM_TOTAL;
            const chosenTeam = mUpper.includes(home.toUpperCase()) ? 'Home' : 'Away';
            selection = `${chosenTeam} ${selection.replace(/\((.*?)\)/g, '$1')}`;
          } else {
            type = BetType.OVER_UNDER;
            selection = selection.replace(/\((.*?)\)/g, '$1');
          }
        } else if (mUpper.includes('BOOKING') || mUpper.includes('CARD')) {
          if (mUpper.includes('1X2') || mUpper.includes('RESULT')) type = BetType.BOOKINGS_1X2;
          else type = BetType.BOOKINGS;
        } else if (mUpper.includes('CORNER')) {
          if (mUpper.includes('1X2') || mUpper.includes('RESULT')) type = BetType.CORNER_1X2;
          else type = BetType.TOTAL_CORNERS;
        } else if (mUpper.includes('DOUBLE CHANCE')) type = BetType.DOUBLE_CHANCE;
        else if (mUpper.includes('DRAW NO BET') || mUpper.includes('DNB')) type = BetType.DRAW_NO_BET;
        else if (mUpper.includes('RED CARD') || mUpper.includes('SENDING OFF')) type = BetType.SENDING_OFF;

        // Selection Matching for Team Names
        if ([BetType.MATCH_WINNER, BetType.DRAW_NO_BET, BetType.CORNER_1X2, BetType.BOOKINGS_1X2].includes(type)) {
          const cleanSel = selection.toLowerCase().trim();
          const cleanHome = home.toLowerCase().trim();
          const cleanAway = away.toLowerCase().trim();
          if (cleanSel === cleanHome || (cleanSel.length > 3 && cleanHome.includes(cleanSel))) selection = 'Home';
          else if (cleanSel === cleanAway || (cleanSel.length > 3 && cleanAway.includes(cleanSel))) selection = 'Away';
          else if (cleanSel.includes('draw') || cleanSel === 'x') selection = 'Draw';
        }

        newLegs.push({ id: generateId(), matchName: matchRaw, date: dateRaw, type, selection, status: LegStatus.PENDING });
        i += (dateTimeRaw && (dateTimeRaw.toLowerCase().includes('today') || dateTimeRaw.toLowerCase().includes('tomorrow') || dateTimeRaw.match(/\d{1,2}:\d{2}/))) ? 5 : 4;
      }

      if (newLegs.length > 0) {
        setLegs(newLegs);
        setTotalOdds(calculatedOdds.toFixed(2));
        setShowImport(false);
        setImportText('');
      } else {
        alert("Couldn't find valid bet selections.");
      }
    } catch (e) {
      alert("Error parsing bet slip.");
    }
  };

  const handleSave = () => {
    if (legs.some(l => !l.matchName)) {
      alert("Please enter a match name for all selections.");
      return;
    }
    const numStake = parseFloat(stake) || 0;
    const numOdds = parseFloat(totalOdds) || 1;
    onSave({
      id: initialData ? initialData.id : generateId(),
      createdAt: initialData ? initialData.createdAt : Date.now(),
      legs,
      stake: numStake,
      odds: numOdds,
      potentialReturn: numStake * numOdds,
      status: initialData ? initialData.status : SlipStatus.PENDING,
      folder: folder.trim() || undefined
    });
    clearDraft();
  };

  return (
    <div className="bg-surface rounded-xl shadow-xl border border-borderBase overflow-hidden relative transition-colors">
      <div className="p-6 border-b border-borderBase flex justify-between items-center bg-inputBg">
        <h2 className="text-xl font-bold text-textMain flex items-center gap-2">
          {isEditing ? <Edit3 className="text-primary" /> : <Plus className="text-primary" />} 
          {isEditing ? 'Edit Bet Slip' : 'Create New Bet Slip'}
        </h2>
        <button onClick={() => setShowImport(true)} className="text-xs flex items-center gap-1 bg-surface border border-borderBase hover:bg-background text-textMain px-3 py-1.5 rounded transition-colors">
          <ClipboardPaste size={14} /> Import
        </button>
      </div>

      <div className="p-6 space-y-6">
        <div className="bg-inputBg/50 p-4 rounded-lg border border-borderBase">
            <label className="text-sm font-medium text-textMain mb-2 flex items-center gap-2"><Folder size={16} className="text-primary" /> Betting Folder</label>
            <input type="text" list="folders-list" value={folder} onChange={(e) => setFolder(e.target.value)} placeholder="e.g. Accumulator..." className="w-full bg-surface border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary" />
            <datalist id="folders-list">{availableFolders.map(f => <option key={f} value={f} />)}</datalist>
        </div>

        <div className="space-y-4">
          <label className="text-sm font-medium text-textMuted uppercase tracking-wider">Match Selections</label>
          {legs.map((leg) => {
            const { home, away } = parseTeams(leg.matchName);
            return (
              <div key={leg.id} className="p-4 bg-background rounded-lg border border-borderBase hover:border-textMuted transition-colors space-y-4">
                <div className="grid grid-cols-1 md:grid-cols-12 gap-4">
