const MobileNavButton = ({ active, onClick, icon: Icon, label, badge }: any) => <button onClick={onClick} className={`flex flex-col items-center gap-1 ${active ? 'text-primary' : 'text-textMuted'}`}><div className="relative"><Icon size={24} />{badge > 0 && <span className="absolute -top-1 -right-1 bg-red-500 text-white text-[10px] w-4 h-4 flex items-center justify-center rounded-full border border-surface">{badge}</span>}</div><span className="text-[10px] font-medium">{label}</span></button>;

export default App;

import React, { useState, useEffect } from 'react';
import { ChevronDown, ChevronUp, RefreshCw, Trophy, XCircle, Clock, Check, Pencil, Gavel, Save, X, Ban, Folder, Info, Activity, Trash2 } from 'lucide-react';
import { Slip, SlipStatus, Leg, LegStatus, Currency, CURRENCY_SYMBOLS } from '../types';
import { validateSlipWithGemini } from '../services/geminiService';

interface SlipListProps {
  slips: Slip[];
  onUpdateSlip: (updatedSlip: Slip) => void;
  onEditSlip?: (slip: Slip) => void;
  onDeleteSlip?: (slipId: string) => void;
  currency: Currency;
}

export const SlipList: React.FC<SlipListProps> = ({ slips, onUpdateSlip, onEditSlip, onDeleteSlip, currency }) => {
  const symbol = CURRENCY_SYMBOLS[currency];

  if (slips.length === 0) {
    return (
      <div className="text-center py-20 bg-surface rounded-xl border border-borderBase">
        <div className="inline-block p-4 rounded-full bg-inputBg mb-4"><Trophy className="text-textMuted" size={32} /></div>
        <h3 className="text-lg font-medium text-textMain">No bets found</h3>
        <p className="text-textMuted">Create a new bet slip to get started.</p>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {slips.map(slip => (
        <SlipCard key={slip.id} slip={slip} onUpdate={onUpdateSlip} onEdit={onEditSlip} onDelete={onDeleteSlip} symbol={symbol} />
      ))}
    </div>
  );
};

interface SlipCardProps {
  slip: Slip;
  onUpdate: (slip: Slip) => void;
  onEdit?: (slip: Slip) => void;
  onDelete?: (slipId: string) => void;
  symbol: string;
}

const SlipCard: React.FC<SlipCardProps> = ({ slip, onUpdate, onEdit, onDelete, symbol }) => {
  const [expanded, setExpanded] = useState(false);
  const [checking, setChecking] = useState(false);
  const [checkingLegs, setCheckingLegs] = useState<Set<string>>(new Set());
  const [isSettling, setIsSettling] = useState(false);
  const [editedLegs, setEditedLegs] = useState<Leg[]>([]);

  const getStatusColor = (status: SlipStatus | LegStatus) => {
    switch (status) {
      case 'WON': return 'text-success bg-success/10 border-success/20';
      case 'LOST': return 'text-danger bg-danger/10 border-danger/20';
      case 'VOID': return 'text-warning bg-warning/10 border-warning/20';
      default: return 'text-textMuted bg-inputBg border-borderBase';
    }
  };

  const getStatusIcon = (status: SlipStatus | LegStatus) => {
    switch (status) {
      case 'WON': return <Check size={16} />;
      case 'LOST': return <XCircle size={16} />;
      case 'PENDING': return <Clock size={16} />;
      case 'VOID': return <Ban size={16} />;
      default: return null;
    }
  };

  const calculateSlipStatus = (legs: Leg[]): SlipStatus => {
    if (legs.some(l => l.status === LegStatus.LOST)) return SlipStatus.LOST;
    if (legs.some(l => l.status === LegStatus.PENDING)) return SlipStatus.PENDING;
    if (legs.every(l => l.status === LegStatus.VOID)) return SlipStatus.VOID;
    return SlipStatus.WON;
  };

  const handleAICheck = async (e: React.MouseEvent) => {
    e.stopPropagation();
    if (checking || slip.legs.length === 0) return;
    setChecking(true);
    try {
      const response = await validateSlipWithGemini(slip);
      const updatedLegs = slip.legs.map(leg => {
        const update = response.results.find(r => r.legId === leg.id);
        if (update) return { ...leg, status: update.status, resultScore: update.score, notes: (update as any).reason || leg.notes };
        return leg;
      });
      const newStatus = calculateSlipStatus(updatedLegs);
      onUpdate({ ...slip, legs: updatedLegs, status: newStatus, groundingUrls: Array.from(new Set([...(slip.groundingUrls || []), ...response.sources])) });
    } catch (error) { alert("Verification failed."); } finally { setChecking(false); }
  };

  const handleLegAICheck = async (legId: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (checkingLegs.has(legId)) return;
    setCheckingLegs(prev => new Set(prev).add(legId));
    try {
      const legToCheck = slip.legs.find(l => l.id === legId);
      if (!legToCheck) return;
      const response = await validateSlipWithGemini({ ...slip, legs: [legToCheck] });
      const update = response.results.find(r => r.legId === legId);
      if (update) {
        const updatedLegs = slip.legs.map(l => l.id === legId ? { ...l, status: update.status, resultScore: update.score, notes: (update as any).reason || l.notes } : l);
        onUpdate({ ...slip, legs: updatedLegs, status: calculateSlipStatus(updatedLegs), groundingUrls: Array.from(new Set([...(slip.groundingUrls || []), ...response.sources])) });
      }
    } catch (error) { alert("Failed to fetch score."); } finally { setCheckingLegs(prev => { const next = new Set(prev); next.delete(legId); return next; }); }
  };

  const startSettling = (e: React.MouseEvent) => { e.stopPropagation(); setEditedLegs([...slip.legs]); setIsSettling(true); setExpanded(true); };
  const cancelSettling = (e: React.MouseEvent) => { e.stopPropagation(); setIsSettling(false); };
  const saveSettlement = (e: React.MouseEvent) => { e.stopPropagation(); const newStatus = calculateSlipStatus(editedLegs); onUpdate({ ...slip, legs: editedLegs, status: newStatus }); setIsSettling(false); };

  const updateLegStatus = (legId: string, status: LegStatus) => setEditedLegs(prev => prev.map(l => l.id === legId ? { ...l, status } : l));
  const updateLegScore = (legId: string, score: string) => setEditedLegs(prev => prev.map(l => l.id === legId ? { ...l, resultScore: score } : l));

  return (
    <div className={`bg-surface rounded-xl border transition-all overflow-hidden ${slip.status === SlipStatus.WON ? 'border-success/30 shadow-success/5' : slip.status === SlipStatus.LOST ? 'border-danger/30' : 'border-borderBase'}`}>
      <div className="p-5 flex items-center justify-between cursor-pointer hover:bg-inputBg transition-colors" onClick={() => !isSettling && setExpanded(!expanded)}>
        <div className="flex items-center gap-4">
          <div className={`w-10 h-10 rounded-full flex items-center justify-center border ${getStatusColor(slip.status)}`}>{getStatusIcon(slip.status)}</div>
          <div>
             <div className="flex items-center gap-2 flex-wrap">
               <h4 className="font-bold text-textMain text-lg">{slip.legs.length} Match Accumulator</h4>
               {slip.folder && <span className="flex items-center gap-1 text-[10px] font-bold text-textMuted uppercase tracking-wide bg-inputBg border border-borderBase px-2 py-0.5 rounded-full"><Folder size={10} /> {slip.folder}</span>}
               <span className="text-xs text-textMuted font-mono">{new Date(slip.createdAt).toLocaleDateString()}</span>
             </div>
             <p className="text-textMuted text-sm">Stake: <span className="text-textMain font-medium">{symbol}{slip.stake}</span> • Odds: <span className="text-textMain font-medium">{slip.odds}</span> • Return: <span className={`font-bold ${slip.status === 'WON' ? 'text-success' : 'text-primary'}`}>{symbol}{slip.potentialReturn.toFixed(2)}</span></p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          {isSettling ? (
            <div className="flex gap-2">
               <button onClick={cancelSettling} className="p-2 rounded-lg bg-surface border border-borderBase text-textMuted hover:text-textMain transition-colors"><X size={18} /></button>
               <button onClick={saveSettlement} className="px-4 py-2 rounded-lg bg-primary text-white font-bold flex items-center gap-2 hover:bg-blue-600 transition-colors shadow-lg"><Save size={18} /> Save</button>
            </div>
          ) : (
            <div className="flex items-center gap-2">
              <button onClick={startSettling} className="p-2 rounded-lg text-textMuted hover:text-primary hover:bg-primary/10 transition-colors"><Gavel size={16} /></button>
              {(slip.status === SlipStatus.PENDING || slip.legs.some(l => l.status === LegStatus.PENDING)) && (
                <button onClick={handleAICheck} disabled={checking} className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs font-bold uppercase tracking-wide transition-all ${checking ? 'bg-inputBg text-textMuted' : 'bg-primary/20 text-primary hover:bg-primary/30'}`}><RefreshCw size={14} className={checking ? "animate-spin" : ""} />{checking ? 'Checking...' : 'Check All'}</button>
              )}
              {onEdit && <button onClick={(e) => { e.stopPropagation(); onEdit(slip); }} className="p-2 rounded-lg text-textMuted hover:text-textMain transition-all"><Pencil size={14} /></button>}
              {onDelete && <button onClick={(e) => { e.stopPropagation(); onDelete(slip.id); }} className="p-2 rounded-lg text-textMuted hover:text-danger transition-all"><Trash2 size={14} /></button>}
              <div className="pl-2 border-l border-borderBase ml-2">{expanded ? <ChevronUp className="text-textMuted" size={20} /> : <ChevronDown className="text-textMuted" size={20} />}</div>
            </div>
          )}
        </div>
      </div>
      {expanded && (
        <div className="border-t border-borderBase bg-background/30 p-4">
          <div className="space-y-2">
             {(isSettling ? editedLegs : slip.legs).map((leg) => {
                const isLive = leg.resultScore && !leg.resultScore.includes('FT') && !leg.resultScore.includes('PPD');
                return (
                  <div key={leg.id} className={`flex flex-col md:flex-row md:items-center justify-between p-3 rounded-lg border ${isSettling ? 'bg-surface border-primary/30 shadow-sm' : 'bg-inputBg border-borderBase'}`}>
                    <div className="flex-1 mb-3 md:mb-0">
                        <div className="flex justify-between items-start"><h5 className="text-textMain font-medium">{leg.matchName}</h5>{!isSettling && <span className="text-xs text-textMuted">{leg.date}</span>}</div>
                        <div className="flex items-center gap-2 mt-1"><span className="text-xs font-bold px-2 py-0.5 rounded bg-surface border border-borderBase text-textMuted">{leg.type}</span><span className="text-sm text-primary font-medium">Bet: {leg.selection}</span></div>
                        {isSettling ? (
                          <div className="mt-3"><label className="text-[10px] uppercase text-textMuted font-bold mb-1 block">Manual Result</label><input type="text" value={leg.resultScore || ''} onChange={(e) => updateLegScore(leg.id, e.target.value)} className="w-full md:w-48 bg-inputBg border border-borderBase rounded px-2 py-1 text-sm text-textMain" /></div>
                        ) : (
                          <div className="flex flex-col gap-1 mt-2">
                            {leg.resultScore && <div className="flex items-center gap-2"><span className={`text-xs font-mono font-bold px-2 py-0.5 rounded ${isLive ? 'bg-warning/20 text-warning animate-pulse' : 'bg-inputBg text-textMain'}`}>{isLive && <Activity size={10} className="inline mr-1" />}{leg.resultScore}</span></div>}
                            {leg.notes && <div className="text-[10px] text-textMuted italic flex items-center gap-1"><Info size={10} className="text-primary" /> {leg.notes}</div>}
                          </div>
                        )}
                    </div>
                    <div className="ml-0 md:ml-4 flex items-center gap-3">
                        {!isSettling && <button onClick={(e) => handleLegAICheck(leg.id, e)} disabled={checkingLegs.has(leg.id)} className={`p-1.5 rounded-lg border transition-all ${checkingLegs.has(leg.id) ? 'bg-inputBg text-textMuted' : 'bg-surface hover:text-primary'}`}><RefreshCw size={12} className={checkingLegs.has(leg.id) ? "animate-spin" : ""} /></button>}
                        {isSettling ? (
                          <div className="flex gap-1 bg-inputBg p-1 rounded-lg border border-borderBase">
                            <button onClick={() => updateLegStatus(leg.id, LegStatus.WON)} className={`p-1.5 rounded ${leg.status === LegStatus.WON ? 'bg-success text-white' : 'text-textMuted'}`}><Check size={14} /></button>
                            <button onClick={() => updateLegStatus(leg.id, LegStatus.LOST)} className={`p-1.5 rounded ${leg.status === LegStatus.LOST ? 'bg-danger text-white' : 'text-textMuted'}`}><XCircle size={14} /></button>
                            <button onClick={() => updateLegStatus(leg.id, LegStatus.VOID)} className={`p-1.5 rounded ${leg.status === LegStatus.VOID ? 'bg-warning text-white' : 'text-textMuted'}`}><Ban size={14} /></button>
                            <button onClick={() => updateLegStatus(leg.id, LegStatus.PENDING)} className={`p-1.5 rounded ${leg.status === LegStatus.PENDING ? 'bg-surface text-textMain' : 'text-textMuted'}`}><Clock size={14} /></button>
                          </div>
                        ) : <span className={`text-xs font-bold px-2 py-1 rounded border min-w-[70px] text-center ${getStatusColor(leg.status)}`}>{leg.status}</span>}
                    </div>
                  </div>
                );
             })}
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Plus, Trash2, Save, ClipboardPaste, X, Edit3, Folder, Globe } from 'lucide-react';
import { BetType, Leg, LegStatus, Slip, SlipStatus, Currency, CURRENCY_SYMBOLS } from '../types';

interface NewSlipFormProps {
  initialData?: Slip;
  onSave: (slip: Slip) => void;
  onCancel: () => void;
  currency: Currency;
  availableFolders: string[];
  availableLeagues: string[];
}

const generateId = () => {
  return Date.now().toString(36) + Math.random().toString(36).substring(2, 9);
};

export const NewSlipForm: React.FC<NewSlipFormProps> = ({ initialData, onSave, onCancel, currency, availableFolders, availableLeagues }) => {
  const [stake, setStake] = useState<string>(() => {
    if (initialData) return initialData.stake.toString();
    const saved = localStorage.getItem('smartbet_draft_stake');
    return saved || '10';
  });

  const [totalOdds, setTotalOdds] = useState<string>(() => {
    if (initialData) return initialData.odds.toString();
    const saved = localStorage.getItem('smartbet_draft_odds');
    return saved || '1.00';
  });

  const [folder, setFolder] = useState<string>(() => {
    if (initialData) return initialData.folder || '';
    return '';
  });

  const [legs, setLegs] = useState<Leg[]>(() => {
    if (initialData) return initialData.legs;
    const saved = localStorage.getItem('smartbet_draft_legs');
    if (saved) return JSON.parse(saved);
    return [{
      id: generateId(),
      matchName: '',
      league: '',
      date: new Date().toISOString().split('T')[0],
      type: BetType.MATCH_WINNER,
      selection: 'Home',
      status: LegStatus.PENDING,
    }];
  });

  const [showImport, setShowImport] = useState(false);
  const [importText, setImportText] = useState('');

  const symbol = CURRENCY_SYMBOLS[currency];
  const isEditing = !!initialData;

  useEffect(() => {
    if (!isEditing) {
      localStorage.setItem('smartbet_draft_stake', stake);
      localStorage.setItem('smartbet_draft_odds', totalOdds);
      localStorage.setItem('smartbet_draft_legs', JSON.stringify(legs));
    }
  }, [stake, totalOdds, legs, isEditing]);

  const clearDraft = () => {
    localStorage.removeItem('smartbet_draft_stake');
    localStorage.removeItem('smartbet_draft_odds');
    localStorage.removeItem('smartbet_draft_legs');
  };

  const addLeg = () => {
    setLegs([
      ...legs,
      {
        id: generateId(),
        matchName: '',
        league: '',
        date: new Date().toISOString().split('T')[0],
        type: BetType.MATCH_WINNER,
        selection: 'Home',
        status: LegStatus.PENDING,
      }
    ]);
  };

  const removeLeg = (id: string) => {
    if (legs.length > 1) {
      setLegs(legs.filter(l => l.id !== id));
    }
  };

  const updateLeg = (id: string, field: keyof Leg, value: any) => {
    setLegs(legs.map(l => {
      if (l.id === id) {
        const updated = { ...l, [field]: value };
        if (field === 'type') {
           if (value === BetType.MATCH_WINNER) updated.selection = 'Home';
           if (value === BetType.BTTS) updated.selection = 'Yes';
           if (value === BetType.SENDING_OFF) updated.selection = 'Yes';
           if (value === BetType.OVER_UNDER) updated.selection = 'Over 2.5';
           if (value === BetType.DOUBLE_CHANCE) updated.selection = '1X';
           if (value === BetType.DRAW_NO_BET) updated.selection = 'Home';
           if (value === BetType.WIN_EITHER_HALF) updated.selection = 'Home - Yes/No';
           if (value === BetType.HANDICAP) updated.selection = 'Home (-0.5)';
           if (value === BetType.TOTAL_CORNERS) updated.selection = 'Over 9.5';
           if (value === BetType.CORNER_1X2) updated.selection = 'Home';
           if (value === BetType.WINNING_MARGIN) updated.selection = 'Home By 1';
           if (value === BetType.HALVES_BTTS) updated.selection = 'No/No';
           if (value === BetType.TEAM_TOTAL) updated.selection = 'Home Over 0.5';
           if (value === BetType.TEN_MINS_1X2) updated.selection = 'Home (1-10\')';
           if (value === BetType.MATCH_RESULT_AND_BTTS) updated.selection = 'Home & Yes';
           if (value === BetType.ODD_EVEN) updated.selection = 'Odd';
           if (value === BetType.BOOKINGS) updated.selection = 'Over 3.5';
           if (value === BetType.BOOKINGS_1X2) updated.selection = 'Home';
        }
        return updated;
      }
      return l;
    }));
  };

  const parseTeams = (matchName: string) => {
    const parts = matchName.split(/\s+v\s+|\s+vs\.?\s+|\s+-\s+|\s+–\s+/i);
    return {
      home: parts[0]?.trim() || 'Home',
      away: parts[1]?.trim() || 'Away'
    };
  };

  const handleNumericChange = (value: string, setter: (v: string) => void) => {
    if (value === '' || /^\d*\.?\d*$/.test(value)) {
      setter(value);
    }
  };

  const handleImport = () => {
    if (!importText.trim()) return;

    try {
      const lines = importText.split('\n').map(l => l.trim()).filter(l => l !== '');
      const newLegs: Leg[] = [];
      let calculatedOdds = 1;
      let i = 0;

      while (i < lines.length) {
        const selectionRaw = lines[i];
        const oddsRaw = lines[i+1];
        const marketRaw = lines[i+2];
        const matchRaw = lines[i+3];
        const dateTimeRaw = lines[i+4];

        if (!selectionRaw || !oddsRaw || !marketRaw || !matchRaw) {
          i++; 
          continue;
        }

        const oddsVal = parseFloat(oddsRaw.replace(/[^0-9.]/g, ''));
        if (isNaN(oddsVal)) { i++; continue; }

        let dateRaw = new Date().toISOString().split('T')[0];
        if (dateTimeRaw) {
          const lowerDT = dateTimeRaw.toLowerCase();
          if (lowerDT.includes('today')) dateRaw = new Date().toISOString().split('T')[0];
          else if (lowerDT.includes('tomorrow')) {
            const d = new Date(); d.setDate(d.getDate() + 1); dateRaw = d.toISOString().split('T')[0];
          } else {
            const match = dateTimeRaw.match(/(\d{1,2})\s+(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)/i);
            if (match) {
              const d = new Date(`${match[1]} ${match[2]} ${new Date().getFullYear()}`);
              if (!isNaN(d.getTime())) dateRaw = d.toISOString().split('T')[0];
            }
          }
        }

        calculatedOdds *= oddsVal;

        // Smart Selection Cleaning
        let selection = selectionRaw.trim();
        const overUnderMatch = selection.match(/(Over|Under)\s*\(?(\d+\.?\d*)\)?/i);
        if (overUnderMatch) {
          selection = `${overUnderMatch[1].charAt(0).toUpperCase() + overUnderMatch[1].slice(1).toLowerCase()} ${overUnderMatch[2]}`;
        } else {
          selection = selection.split(' (')[0].trim(); // Remove suffix comments
        }

        const mUpper = marketRaw.toUpperCase();
        const { home, away } = parseTeams(matchRaw);
        let type = BetType.MATCH_WINNER;

        if (mUpper.includes('BOTH TEAMS TO SCORE') || mUpper.includes('BTTS') || mUpper.includes('GG/NG')) {
          type = BetType.BTTS;
        } else if (mUpper.includes('TOTAL') || mUpper.includes('OVER/UNDER') || mUpper.includes('GOALS')) {
          if (mUpper.includes('BOOKING') || mUpper.includes('CARD')) type = BetType.BOOKINGS;
          else if (mUpper.includes('CORNER')) type = BetType.TOTAL_CORNERS;
          else if (mUpper.includes(home.toUpperCase()) || mUpper.includes(away.toUpperCase())) {
            type = BetType.TEAM_TOTAL;
            const chosenTeam = mUpper.includes(home.toUpperCase()) ? 'Home' : 'Away';
            const cleanSel = selection.replace(/^(Over|Under)\s+/i, '');
            selection = `${chosenTeam} ${cleanSel.includes('Over') || cleanSel.includes('Under') ? cleanSel : 'Over ' + cleanSel}`;
          } else {
            type = BetType.OVER_UNDER;
          }
        } else if (mUpper.includes('BOOKING') || mUpper.includes('CARD')) {
          if (mUpper.includes('1X2') || mUpper.includes('RESULT')) type = BetType.BOOKINGS_1X2;
          else type = BetType.BOOKINGS;
        } else if (mUpper.includes('CORNER')) {
          if (mUpper.includes('1X2') || mUpper.includes('RESULT')) type = BetType.CORNER_1X2;
          else type = BetType.TOTAL_CORNERS;
        } else if (mUpper.includes('DOUBLE CHANCE')) type = BetType.DOUBLE_CHANCE;
        else if (mUpper.includes('DRAW NO BET') || mUpper.includes('DNB')) type = BetType.DRAW_NO_BET;
        else if (mUpper.includes('RED CARD') || mUpper.includes('SENDING OFF')) type = BetType.SENDING_OFF;

        // Selection Matching for Team Names
        if ([BetType.MATCH_WINNER, BetType.DRAW_NO_BET, BetType.CORNER_1X2, BetType.BOOKINGS_1X2].includes(type)) {
          const cleanSel = selection.toLowerCase().trim();
          const cleanHome = home.toLowerCase().trim();
          const cleanAway = away.toLowerCase().trim();

          if (cleanSel === cleanHome || cleanSel.includes(cleanHome) || cleanHome.includes(cleanSel)) selection = 'Home';
          else if (cleanSel === cleanAway || cleanSel.includes(cleanAway) || cleanAway.includes(cleanSel)) selection = 'Away';
          else if (cleanSel.includes('draw') || cleanSel === 'x') selection = 'Draw';
        }

        newLegs.push({ id: generateId(), matchName: matchRaw, date: dateRaw, type, selection, status: LegStatus.PENDING });
        i += (dateTimeRaw && (dateTimeRaw.toLowerCase().includes('today') || dateTimeRaw.toLowerCase().includes('tomorrow') || dateTimeRaw.match(/\d{1,2}:\d{2}/))) ? 5 : 4;
      }

      if (newLegs.length > 0) {
        setLegs(newLegs);
        setTotalOdds(calculatedOdds.toFixed(2));
        setShowImport(false);
        setImportText('');
      } else {
        alert("Couldn't find valid bet selections.");
      }
    } catch (e) {
      alert("Error parsing bet slip.");
    }
  };

  const handleSave = () => {
    if (legs.some(l => !l.matchName)) {
      alert("Please enter a match name for all selections.");
      return;
    }
    const numStake = parseFloat(stake) || 0;
    const numOdds = parseFloat(totalOdds) || 1;
    onSave({
      id: initialData ? initialData.id : generateId(),
      createdAt: initialData ? initialData.createdAt : Date.now(),
      legs,
      stake: numStake,
      odds: numOdds,
      potentialReturn: numStake * numOdds,
      status: initialData ? initialData.status : SlipStatus.PENDING,
      folder: folder.trim() || undefined
    });
    clearDraft();
  };

  return (
    <div className="bg-surface rounded-xl shadow-xl border border-borderBase overflow-hidden relative transition-colors">
      <div className="p-6 border-b border-borderBase flex justify-between items-center bg-inputBg">
        <h2 className="text-xl font-bold text-textMain flex items-center gap-2">
          {isEditing ? <Edit3 className="text-primary" /> : <Plus className="text-primary" />} 
          {isEditing ? 'Edit Bet Slip' : 'Create New Bet Slip'}
        </h2>
        <button onClick={() => setShowImport(true)} className="text-xs flex items-center gap-1 bg-surface border border-borderBase hover:bg-background text-textMain px-3 py-1.5 rounded transition-colors">
          <ClipboardPaste size={14} /> Import
        </button>
      </div>

      <div className="p-6 space-y-6">
        <div className="bg-inputBg/50 p-4 rounded-lg border border-borderBase">
            <label className="text-sm font-medium text-textMain mb-2 flex items-center gap-2"><Folder size={16} className="text-primary" /> Betting Folder</label>
            <input type="text" list="folders-list" value={folder} onChange={(e) => setFolder(e.target.value)} placeholder="e.g. Accumulator..." className="w-full bg-surface border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary" />
            <datalist id="folders-list">{availableFolders.map(f => <option key={f} value={f} />)}</datalist>
        </div>

        <div className="space-y-4">
          <label className="text-sm font-medium text-textMuted uppercase tracking-wider">Match Selections</label>
          {legs.map((leg) => {
            const { home, away } = parseTeams(leg.matchName);
            return (
              <div key={leg.id} className="p-4 bg-background rounded-lg border border-borderBase hover:border-textMuted transition-colors space-y-4">
                <div className="grid grid-cols-1 md:grid-cols-12 gap-4">
                  <div className="md:col-span-8 space-y-1">
                    <label className="text-xs text-textMuted font-bold uppercase">Match Name</label>
                    <input type="text" value={leg.matchName} onChange={(e) => updateLeg(leg.id, 'matchName', e.target.value)} placeholder="e.g. Man City vs Arsenal" className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary" />
                  </div>
                  <div className="md:col-span-3 space-y-1">
                    <label className="text-xs text-textMuted font-bold uppercase">Date</label>
                    <input type="date" value={leg.date} onChange={(e) => updateLeg(leg.id, 'date', e.target.value)} className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary" />
                  </div>
                  <div className="md:col-span-1 flex items-end justify-center pb-1">
                    <button onClick={() => removeLeg(leg.id)} disabled={legs.length === 1} className="p-2 rounded hover:bg-danger/20 text-danger/80 transition-colors disabled:opacity-30"><Trash2 size={18} /></button>
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-xs text-textMuted font-bold uppercase">Market</label>
                    <select value={leg.type} onChange={(e) => updateLeg(leg.id, 'type', e.target.value)} className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary">
                      <optgroup label="Popular">
                        <option value={BetType.MATCH_WINNER}>1X2 (Full Time)</option>
                        <option value={BetType.BTTS}>BTTS</option>
                        <option value={BetType.OVER_UNDER}>Over/Under Goals</option>
                        <option value={BetType.TEAM_TOTAL}>Team Totals</option>
                      </optgroup>
                      <optgroup label="Corners">
                        <option value={BetType.CORNER_1X2}>Corner 1X2</option>
                        <option value={BetType.TOTAL_CORNERS}>Total Corners (O/U)</option>
                      </optgroup>
                      <optgroup label="Cards & Events">
                        <option value={BetType.SENDING_OFF}>Sending Off (Red Card)</option>
                        <option value={BetType.BOOKINGS_1X2}>Bookings 1X2</option>
                        <option value={BetType.BOOKINGS}>Total Bookings (O/U)</option>
                      </optgroup>
                      <optgroup label="Others">
                        <option value={BetType.ODD_EVEN}>Total Goals - Odd/Even</option>
                        <option value={BetType.MATCH_RESULT_AND_BTTS}>1X2 & Both Teams To Score</option>
                        <option value={BetType.TEN_MINS_1X2}>10 Minutes - 1X2 (1-10')</option>
                        <option value={BetType.HANDICAP}>Handicap (2-Way)</option>
                        <option value={BetType.WIN_EITHER_HALF}>Win Either Half</option>
                        <option value={BetType.DOUBLE_CHANCE}>Double Chance</option>
                        <option value={BetType.DRAW_NO_BET}>Draw No Bet</option>
                        <option value={BetType.WINNING_MARGIN}>Winning Margin</option>
                      </optgroup>
                    </select>
                  </div>
                  <div className="space-y-1">
                    <label className="text-xs text-textMuted font-bold uppercase">Selection</label>
                    <select value={leg.selection} onChange={(e) => updateLeg(leg.id, 'selection', e.target.value)} className="w-full bg-inputBg border border-borderBase rounded px-3 py-2 text-textMain text-sm focus:outline-none focus:border-primary">
                      {leg.type === BetType.MATCH_WINNER && (
                        <>
                          <option value="Home">Home Win (1)</option>
                          <option value="Draw">Draw (X)</option>
                          <option value="Away">Away Win (2)</option>
                        </>
                      )}
                      {leg.type === BetType.BTTS && (
                        <>
                          <option value="Yes">Yes</option>
                          <option value="No">No</option>
                        </>
                      )}
                      {leg.type === BetType.SENDING_OFF && (
                        <>
                          <option value="Yes">Yes (Red Card Shown)</option>
                          <option value="No">No (No Red Card)</option>
                        </>
                      )}
                      {leg.type === BetType.ODD_EVEN && (
                        <>
                          <option value="Odd">Odd</option>
                          <option value="Even">Even</option>
                        </>
                      )}
                      {leg.type === BetType.CORNER_1X2 && (
                        <>
                          <option value="Home">{home} (Most Corners)</option>
                          <option value="Draw">Draw (Same Corners)</option>
                          <option value="Away">{away} (Most Corners)</option>
                        </>
                      )}
                      {leg.type === BetType.BOOKINGS_1X2 && (
                        <>
                          <option value="Home">{home} (Most Cards)</option>
                          <option value="Draw">Draw (Same Cards)</option>
                          <option value="Away">{away} (Most Cards)</option>
                        </>
                      )}
                      {leg.type === BetType.BOOKINGS && (
                        <>
                          <optgroup label="Over Thresholds">
                            <option value="Over 1.5">Over 1.5</option>
                            <option value="Over 2.5">Over 2.5</option>
                            <option value="Over 3.5">Over 3.5</option>
                            <option value="Over 4.5">Over 4.5</option>
                            <option value="Over 5.5">Over 5.5</option>
                          </optgroup>
                          <optgroup label="Under Thresholds">
                            <option value="Under 1.5">Under 1.5</option>
                            <option value="Under 2.5">Under 2.5</option>
                            <option value="Under 3.5">Under 3.5</option>
                            <option value="Under 4.5">Under 4.5</option>
                            <option value="Under 5.5">Under 5.5</option>
                          </optgroup>
                        </>
                      )}
                      {leg.type === BetType.TOTAL_CORNERS && (
                        <>
                          <optgroup label="Over Thresholds">
                            <option value="Over 7.5">Over 7.5</option>
                            <option value="Over 8.5">Over 8.5</option>
                            <option value="Over 9.5">Over 9.5</option>
                            <option value="Over 10.5">Over 10.5</option>
                            <option value="Over 11.5">Over 11.5</option>
                          </optgroup>
                          <optgroup label="Under Thresholds">
                            <option value="Under 7.5">Under 7.5</option>
                            <option value="Under 8.5">Under 8.5</option>
                            <option value="Under 9.5">Under 9.5</option>
                            <option value="Under 10.5">Under 10.5</option>
                            <option value="Under 11.5">Under 11.5</option>
                          </optgroup>
                        </>
                      )}
                      {leg.type === BetType.MATCH_RESULT_AND_BTTS && (
                        <>
                          <optgroup label={home}>
                            <option value="Home & Yes">Home & Yes</option>
                            <option value="Home & No">Home & No</option>
                          </optgroup>
                          <optgroup label="Draw">
                            <option value="Draw & Yes">Draw & Yes</option>
                            <option value="Draw & No">Draw & No</option>
                          </optgroup>
                          <optgroup label={away}>
                            <option value="Away & Yes">Away & Yes</option>
                            <option value="Away & No">Away & No</option>
                          </optgroup>
                        </>
                      )}
                      {leg.type === BetType.TEN_MINS_1X2 && (
                        <>
                          <option value={`Home (1-10')`}>{home} (1-10')</option>
                          <option value={`Draw (1-10')`}>Draw (1-10')</option>
                          <option value={`Away (1-10')`}>{away} (1-10')</option>
                        </>
                      )}
                      {leg.type === BetType.HANDICAP && (
                        <>
                          <optgroup label={home}>
                            <option value="Home (-3.5)">Home (-3.5)</option>
                            <option value="Home (-2.5)">Home (-2.5)</option>
                            <option value="Home (-1.5)">Home (-1.5)</option>
                            <option value="Home (-0.5)">Home (-0.5)</option>
                            <option value="Home (+0.5)">Home (+0.5)</option>
                            <option value="Home (+1.5)">Home (+1.5)</option>
                            <option value="Home (+2.5)">Home (+2.5)</option>
                            <option value="Home (+3.5)">Home (+3.5)</option>
                          </optgroup>
                          <optgroup label={away}>
                            <option value="Away (-3.5)">Away (-3.5)</option>
                            <option value="Away (-2.5)">Away (-2.5)</option>
                            <option value="Away (-1.5)">Away (-1.5)</option>
                            <option value="Away (-0.5)">Away (-0.5)</option>
                            <option value="Away (+0.5)">Away (+0.5)</option>
                            <option value="Away (+1.5)">Away (+1.5)</option>
                            <option value="Away (+2.5)">Away (+2.5)</option>
                            <option value="Away (+3.5)">Away (+3.5)</option>
                          </optgroup>
                        </>
                      )}
                      {leg.type === BetType.WIN_EITHER_HALF && (
                        <>
                          <optgroup label={home}>
                            <option value="Home - Yes/Yes">Yes/Yes (Win Both)</option>
                            <option value="Home - Yes/No">Yes/No (1st Only)</option>
                            <option value="Home - No/Yes">No/Yes (2nd Only)</option>
                            <option value="Home - No/No">No/No (Win Neither)</option>
                          </optgroup>
                          <optgroup label={away}>
                            <option value="Away - Yes/Yes">Yes/Yes (Win Both)</option>
                            <option value="Away - Yes/No">Yes/No (1st Only)</option>
                            <option value="Away - No/Yes">No/Yes (2nd Only)</option>
                            <option value="Away - No/No">No/No (Win Neither)</option>
                          </optgroup>
                        </>
                      )}
                      {leg.type === BetType.TEAM_TOTAL && (
                        <>
                          <optgroup label={home}>
                            <option value="Home Over 0.5">Over 0.5</option>
                            <option value="Home Under 0.5">Under 0.5</option>
                            <option value="Home Over 1.5">Over 1.5</option>
                            <option value="Home Under 1.5">Under 1.5</option>
                            <option value="Home Over 2.5">Over 2.5</option>
                            <option value="Home Under 2.5">Under 2.5</option>
                          </optgroup>
                          <optgroup label={away}>
                            <option value="Away Over 0.5">Over 0.5</option>
                            <option value="Away Under 0.5">Under 0.5</option>
                            <option value="Away Over 1.5">Over 1.5</option>
                            <option value="Away Under 1.5">Under 1.5</option>
                            <option value="Away Over 2.5">Over 2.5</option>
                            <option value="Away Under 2.5">Under 2.5</option>
                          </optgroup>
                        </>
                      )}
                      {leg.type === BetType.OVER_UNDER && (
                        <>
                          <optgroup label="Over Thresholds">
                            <option value="Over 0.5">Over 0.5</option>
                            <option value="Over 1.5">Over 1.5</option>
                            <option value="Over 2.5">Over 2.5</option>
                            <option value="Over 3.5">Over 3.5</option>
                          </optgroup>
                          <optgroup label="Under Thresholds">
                            <option value="Under 0.5">Under 0.5</option>
                            <option value="Under 1.5">Under 1.5</option>
                            <option value="Under 2.5">Under 2.5</option>
                            <option value="Under 3.5">Under 3.5</option>
                          </optgroup>
                        </>
                      )}
                      {!([BetType.MATCH_WINNER, BetType.BTTS, BetType.SENDING_OFF, BetType.TEAM_TOTAL, BetType.OVER_UNDER, BetType.WIN_EITHER_HALF, BetType.HANDICAP, BetType.TEN_MINS_1X2, BetType.MATCH_RESULT_AND_BTTS, BetType.ODD_EVEN, BetType.BOOKINGS, BetType.BOOKINGS_1X2, BetType.CORNER_1X2, BetType.TOTAL_CORNERS].includes(leg.type as BetType)) && (
                        <option value={leg.selection}>{leg.selection}</option>
                      )}
                    </select>
                  </div>
                </div>
              </div>
            );
          })}
          <button onClick={addLeg} className="w-full py-3 border border-dashed border-borderBase rounded-lg text-textMuted hover:text-textMain hover:bg-inputBg transition-all flex items-center justify-center gap-2"><Plus size={18} /> Add Match</button>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 pt-6 border-t border-borderBase">
           <div className="space-y-1">
              <label className="text-xs font-bold text-textMuted uppercase">Stake ({symbol})</label>
              <input type="text" inputMode="decimal" value={stake} onChange={(e) => handleNumericChange(e.target.value, setStake)} className="w-full bg-inputBg border border-borderBase rounded px-4 py-3 text-textMain font-bold focus:outline-none focus:border-primary" />
           </div>
           <div className="space-y-1">
              <label className="text-xs font-bold text-textMuted uppercase">Total Odds</label>
              <input type="text" inputMode="decimal" value={totalOdds} onChange={(e) => handleNumericChange(e.target.value, setTotalOdds)} className="w-full bg-inputBg border border-borderBase rounded px-4 py-3 text-textMain font-bold focus:outline-none focus:border-primary" />
           </div>
        </div>

        <div className="bg-primary/10 rounded-lg p-4 flex justify-between items-center border border-primary/20">
          <span className="text-primary font-medium">Potential Return</span>
          <span className="text-2xl font-bold text-primary">{symbol}{((parseFloat(stake) || 0) * (parseFloat(totalOdds) || 0)).toFixed(2)}</span>
        </div>

        <div className="flex gap-4 justify-end pt-4">
          <button onClick={onCancel} className="px-6 py-3 text-textMuted hover:text-textMain">Cancel</button>
          <button onClick={handleSave} className="px-8 py-3 rounded-lg font-bold bg-primary hover:bg-blue-600 text-white shadow-lg transition-all flex items-center gap-2"><Save size={18} /> Save Bet Slip</button>
        </div>
      </div>

      {showImport && (
        <div className="fixed inset-0 z-[60] bg-background/95 flex items-center justify-center p-6 animate-fade-in">
           <div className="w-full max-w-lg bg-surface border border-borderBase rounded-xl p-6 shadow-2xl">
              <div className="flex justify-between items-center mb-4">
                 <h3 className="text-textMain font-bold flex items-center gap-2"><ClipboardPaste size={18} className="text-primary" /> Import Selections</h3>
                 <button onClick={() => setShowImport(false)} className="text-textMuted hover:text-textMain"><X size={20} /></button>
              </div>
              <textarea 
                value={importText} 
                onChange={(e) => setImportText(e.target.value)} 
                placeholder={`Selection (e.g. Over (2.5))\nOdds (e.g. 1.34)\nMarket (e.g. Total (1.5))\nMatch (e.g. Team A - Team B)\nDate (e.g. Today 17:00)`} 
                className="w-full h-64 bg-inputBg border border-borderBase rounded-lg p-4 text-xs font-mono text-textMain focus:outline-none focus:border-primary resize-none" 
              />
              <div className="mt-4 flex justify-end gap-3">
                 <button onClick={() => { setShowImport(false); setImportText(''); }} className="px-4 py-2 text-textMuted font-medium">Cancel</button>
                 <button onClick={handleImport} className="px-6 py-2 bg-primary text-white rounded-lg font-bold hover:bg-blue-600 transition-colors shadow-lg">Import Selections</button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { LayoutDashboard, PlusCircle, History, Wallet, TrendingUp, Trophy, Settings as SettingsIcon, Sun, Moon, Trash2, X, BarChart3, FolderOpen, Edit2, Check, Plus, Coins, ArrowUpCircle, Save } from 'lucide-react';
import { Slip, SlipStatus, Stats, Currency, CURRENCY_SYMBOLS } from './types';
import { StatsCard } from './components/StatsCard';
import { SlipList } from './components/SlipList';
import { NewSlipForm } from './components/NewSlipForm';
import { StatisticsPanel } from './components/StatisticsPanel';

const DEFAULT_LEAGUES = [
  'EPL', 'La Liga', 'Bundesliga', 'Serie A', 'Ligue 1', 
  'UCL', 'UEL', 'MLS', 'Eredivisie', 'Championship'
];

const STARTING_BALANCE = 1000;

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'active' | 'settled' | 'create' | 'stats'>('dashboard');

  const [slips, setSlips] = useState<Slip[]>(() => {
    const saved = localStorage.getItem('smartbet_slips');
    return saved ? JSON.parse(saved) : [];
  });

  const [theme, setTheme] = useState<'light' | 'dark'>(() => {
    return (localStorage.getItem('smartbet_theme') as 'light' | 'dark') || 'dark';
  });

  const [currency, setCurrency] = useState<Currency>(() => {
    return (localStorage.getItem('smartbet_currency') as Currency) || 'ZAR';
  });

  const [bankroll, setBankroll] = useState<number>(() => {
    const saved = localStorage.getItem('smartbet_bankroll');
    return saved !== null ? parseFloat(saved) : STARTING_BALANCE;
  });

  const [customLeagues, setCustomLeagues] = useState<string[]>(() => {
    const saved = localStorage.getItem('smartbet_custom_leagues');
    return saved ? JSON.parse(saved) : DEFAULT_LEAGUES;
  });

  const [selectedFolder, setSelectedFolder] = useState<string>('All');
  const [showSettings, setShowSettings] = useState(false);
  const [editingSlip, setEditingSlip] = useState<Slip | null>(null);
  const [newLeagueInput, setNewLeagueInput] = useState('');
  const [isEditingBalance, setIsEditingBalance] = useState(false);
  const [balanceInput, setBalanceInput] = useState(bankroll.toString());

  const [stats, setStats] = useState<Stats>({
    totalSlips: 0, wins: 0, losses: 0, winRate: 0,
    totalStaked: 0, totalReturned: 0, profit: 0, roi: 0
  });

  const uniqueFolders = React.useMemo(() => {
    const folders = new Set<string>();
    slips.forEach(s => { if (s.folder) folders.add(s.folder); });
    return Array.from(folders).sort();
  }, [slips]);

  useEffect(() => { localStorage.setItem('smartbet_slips', JSON.stringify(slips)); }, [slips]);
  useEffect(() => {
    localStorage.setItem('smartbet_bankroll', bankroll.toString());
    if (!isEditingBalance) setBalanceInput(bankroll.toString());
  }, [bankroll, isEditingBalance]);

  useEffect(() => {
    localStorage.setItem('smartbet_theme', theme);
    document.documentElement.classList.toggle('dark', theme === 'dark');
  }, [theme]);

  useEffect(() => { localStorage.setItem('smartbet_currency', currency); }, [currency]);
  useEffect(() => { localStorage.setItem('smartbet_custom_leagues', JSON.stringify(customLeagues)); }, [customLeagues]);

  useEffect(() => {
    const settledSlips = slips.filter(s => s.status === SlipStatus.WON || s.status === SlipStatus.LOST || s.status === SlipStatus.VOID);
    const totalSlips = settledSlips.filter(s => s.status !== SlipStatus.VOID).length;
    const wins = settledSlips.filter(s => s.status === SlipStatus.WON).length;
    const losses = settledSlips.filter(s => s.status === SlipStatus.LOST).length;
    const winRate = totalSlips > 0 ? (wins / totalSlips) * 100 : 0;

    const totalStaked = slips.reduce((acc, s) => acc + s.stake, 0);
    const totalReturned = settledSlips.filter(s => s.status === SlipStatus.WON).reduce((acc, s) => acc + s.potentialReturn, 0);
    const voidReturned = settledSlips.filter(s => s.status === SlipStatus.VOID).reduce((acc, s) => acc + s.stake, 0);

    const settledStaked = settledSlips.reduce((acc, s) => acc + s.stake, 0);
    const profit = (totalReturned + voidReturned) - settledStaked;
    const roi = (settledStaked - voidReturned) > 0 ? (profit / (settledStaked - voidReturned)) * 100 : 0;

    setStats({ totalSlips, wins, losses, winRate, totalStaked, totalReturned, profit, roi });
  }, [slips]);

  const handleSaveSlip = (savedSlip: Slip) => {
    const existing = slips.find(s => s.id === savedSlip.id);
    if (existing) {
      if (existing.status === SlipStatus.PENDING) {
        const diff = savedSlip.stake - existing.stake;
        setBankroll(prev => prev - diff);
      }
      setSlips(slips.map(s => s.id === savedSlip.id ? savedSlip : s));
    } else {
      setBankroll(prev => prev - savedSlip.stake);
      setSlips([savedSlip, ...slips]);
    }
    setEditingSlip(null);
    setActiveTab('active');
  };

  const handleUpdateSlip = (updatedSlip: Slip) => {
    const oldSlip = slips.find(s => s.id === updatedSlip.id);
    if (oldSlip) {
      if (oldSlip.status !== SlipStatus.WON && updatedSlip.status === SlipStatus.WON) {
        const correction = oldSlip.status === SlipStatus.VOID ? -oldSlip.stake : 0;
        setBankroll(prev => prev + updatedSlip.potentialReturn + correction);
      }
      else if (oldSlip.status === SlipStatus.WON && updatedSlip.status !== SlipStatus.WON) {
        const refund = updatedSlip.status === SlipStatus.VOID ? updatedSlip.stake : 0;
        setBankroll(prev => prev - oldSlip.potentialReturn + refund);
      }
      else if (oldSlip.status !== SlipStatus.VOID && updatedSlip.status === SlipStatus.VOID) {
        setBankroll(prev => prev + updatedSlip.stake);
      }
      else if (oldSlip.status === SlipStatus.VOID && updatedSlip.status !== SlipStatus.VOID) {
        setBankroll(prev => prev - oldSlip.stake);
      }
    }
    setSlips(slips.map(s => s.id === updatedSlip.id ? updatedSlip : s));
  };

  const handleDeleteSlip = (slipId: string) => {
    const slipToDelete = slips.find(s => s.id === slipId);
    if (!slipToDelete) return;

    if (confirm("Delete this bet slip?")) {
      if (slipToDelete.status === SlipStatus.PENDING || slipToDelete.status === SlipStatus.LOST) {
        setBankroll(prev => prev + slipToDelete.stake);
      } else if (slipToDelete.status === SlipStatus.WON) {
        setBankroll(prev => prev - slipToDelete.potentialReturn + slipToDelete.stake);
      } else if (slipToDelete.status === SlipStatus.VOID) {
        // Stake was already refunded when status became VOID
      }
      setSlips(slips.filter(s => s.id !== slipId));
    }
  };

  const handleEditSlip = (slip: Slip) => {
    setEditingSlip(slip);
    setActiveTab('create');
  };

  const handleResetStats = () => {
    if (confirm("Reset everything?")) {
      setSlips([]);
      setBankroll(STARTING_BALANCE);
      setShowSettings(false);
    }
  };

  const handleSetBalance = () => {
    const val = parseFloat(balanceInput);
    if (!isNaN(val)) {
      setBankroll(val);
      setIsEditingBalance(false);
    }
  };

  const handleAddLeague = () => {
    const trimmed = newLeagueInput.trim();
    if (trimmed && !customLeagues.includes(trimmed)) {
      setCustomLeagues([...customLeagues, trimmed]);
      setNewLeagueInput('');
    }
  };

  const handleRemoveLeague = (league: string) => setCustomLeagues(customLeagues.filter(l => l !== league));

  const handleRenameFolder = (oldName: string, newName: string) => {
    const trimmed = newName.trim();
    if (!trimmed || trimmed === oldName) return;
    if (uniqueFolders.includes(trimmed)) {
      if (!confirm(`Merge "${oldName}" into "${trimmed}"?`)) return;
    }
    setSlips(slips.map(s => s.folder === oldName ? { ...s, folder: trimmed } : s));
    if (selectedFolder === oldName) setSelectedFolder(trimmed);
  };

  const handleDeleteFolder = (folderName: string) => {
    if (confirm(`Ungroup all bets in "${folderName}"?`)) {
      setSlips(slips.map(s => s.folder === folderName ? { ...s, folder: undefined } : s));
      if (selectedFolder === folderName) setSelectedFolder('All');
    }
  };

  return (
    <div className="min-h-screen bg-background pb-20 md:pb-0 transition-colors duration-300">
      <header className="bg-surface border-b border-borderBase sticky top-0 z-50 transition-colors">
        <div className="max-w-5xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
             <div className="bg-primary p-1.5 rounded-lg"><TrendingUp className="text-white" size={20} /></div>
             <h1 className="text-xl font-bold text-textMain tracking-tight">SmartBet<span className="text-primary">Tracker</span></h1>
          </div>
          <div className="hidden md:flex items-center gap-1 bg-inputBg p-1 rounded-lg border border-borderBase">
             <NavButton active={activeTab === 'dashboard'} onClick={() => setActiveTab('dashboard')} icon={LayoutDashboard} label="Overview" />
             <NavButton active={activeTab === 'active'} onClick={() => setActiveTab('active')} icon={Wallet} label="Active" badge={slips.filter(s => s.status === SlipStatus.PENDING).length} />
             <NavButton active={activeTab === 'stats'} onClick={() => setActiveTab('stats')} icon={BarChart3} label="Analytics" />
             <NavButton active={activeTab === 'settled'} onClick={() => setActiveTab('settled')} icon={History} label="History" />
          </div>
          <div className="flex items-center gap-4">
            <div className="hidden sm:flex items-center gap-2 bg-inputBg border border-borderBase px-3 py-1.5 rounded-lg">
              <div className="bg-success/20 text-success p-1 rounded"><Coins size={14} /></div>
              <div className="flex flex-col leading-none">
                <span className="text-[10px] text-textMuted font-bold uppercase">Demo Balance</span>
                <span className="text-sm font-bold text-textMain">{CURRENCY_SYMBOLS[currency]}{bankroll.toFixed(2)}</span>
              </div>
            </div>
            <div className="flex gap-2">
              <button onClick={() => setShowSettings(true)} className="p-2 rounded-lg text-textMuted hover:text-textMain hover:bg-inputBg transition-colors"><SettingsIcon size={20} /></button>
              <button onClick={() => { setEditingSlip(null); setActiveTab('create'); }} className="bg-primary hover:bg-blue-600 text-white px-4 py-2 rounded-lg text-sm font-bold flex items-center gap-2 transition-colors shadow-lg shadow-blue-500/20"><PlusCircle size={18} /> <span className="hidden sm:inline">New Bet</span></button>
            </div>
          </div>
        </div>
      </header>

      {showSettings && (
        <div className="fixed inset-0 z-[100] bg-background/80 backdrop-blur-sm flex items-center justify-center p-4 animate-fade-in">
          <div className="bg-surface border border-borderBase rounded-xl shadow-2xl w-full max-w-md overflow-hidden max-h-[90vh] flex flex-col">
            <div className="p-4 border-b border-borderBase flex justify-between items-center bg-inputBg">
               <h3 className="font-bold text-textMain flex items-center gap-2"><SettingsIcon size={18} className="text-primary" /> Settings</h3>
               <button onClick={() => setShowSettings(false)} className="text-textMuted hover:text-textMain"><X size={20} /></button>
            </div>
            <div className="p-6 space-y-6 overflow-y-auto">
               <div className="space-y-3">
                 <div className="flex justify-between items-center">
                   <span className="text-textMain font-medium flex items-center gap-2"><Wallet size={16} className="text-primary" /> Demo Account Balance</span>
                   {!isEditingBalance && <button onClick={() => setIsEditingBalance(true)} className="text-[10px] font-bold text-primary hover:underline uppercase tracking-wider">Edit Manually</button>}
                 </div>
                 {isEditingBalance ? (
                   <div className="flex gap-2 animate-fade-in">
                     <div className="relative flex-1">
                        <span className="absolute left-3 top-1/2 -translate-y-1/2 text-textMuted font-bold">{CURRENCY_SYMBOLS[currency]}</span>
                        <input type="number" value={balanceInput} onChange={(e) => setBalanceInput(e.target.value)} className="w-full bg-inputBg border border-primary rounded-lg pl-8 pr-3 py-2 text-textMain font-bold focus:outline-none" autoFocus />
                     </div>
                     <button onClick={handleSetBalance} className="bg-primary text-white p-2 rounded-lg hover:bg-blue-600 transition-colors"><Check size={20} /></button>
                     <button onClick={() => setIsEditingBalance(false)} className="bg-inputBg border border-borderBase text-textMuted p-2 rounded-lg hover:text-textMain transition-colors"><X size={20} /></button>
                   </div>
                 ) : (
                   <div className="flex items-center justify-between bg-inputBg p-3 rounded-lg border border-borderBase"><span className="text-lg font-bold text-textMain">{CURRENCY_SYMBOLS[currency]}{bankroll.toFixed(2)}</span></div>
                 )}
               </div>
               <div className="flex items-center justify-between">
                 <span className="text-textMain font-medium">Appearance</span>
                 <div className="flex bg-inputBg rounded-lg p-1 border border-borderBase">
                    <button onClick={() => setTheme('light')} className={`p-2 rounded flex items-center gap-2 text-xs font-bold transition-all ${theme === 'light' ? 'bg-surface shadow text-primary' : 'text-textMuted'}`}><Sun size={14} /> Light</button>
                    <button onClick={() => setTheme('dark')} className={`p-2 rounded flex items-center gap-2 text-xs font-bold transition-all ${theme === 'dark' ? 'bg-surface shadow text-primary' : 'text-textMuted'}`}><Moon size={14} /> Dark</button>
                 </div>
               </div>
               <div className="flex items-center justify-between">
                 <span className="text-textMain font-medium">Currency</span>
                 <select value={currency} onChange={(e) => setCurrency(e.target.value as Currency)} className="bg-inputBg border border-borderBase rounded-lg px-3 py-1.5 text-textMain text-sm focus:outline-none focus:border-primary">
                   <option value="ZAR">ZAR (R)</option><option value="USD">USD ($)</option><option value="GBP">GBP (£)</option>
                 </select>
               </div>
               <div className="space-y-3 pt-4 border-t border-borderBase">
                  <span className="text-textMain font-medium flex items-center gap-2"><Trophy size={16} className="text-primary" /> Manage Leagues</span>
                  <div className="flex gap-2">
                    <input type="text" placeholder="e.g. Champions League" value={newLeagueInput} onChange={(e) => setNewLeagueInput(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleAddLeague()} className="flex-1 bg-inputBg border border-borderBase rounded-lg px-3 py-2 text-sm text-textMain focus:outline-none focus:border-primary" />
                    <button onClick={handleAddLeague} className="bg-primary text-white p-2 rounded-lg hover:bg-blue-600 transition-colors"><Plus size={20} /></button>
                  </div>
                  <div className="flex flex-wrap gap-2">
                    {customLeagues.map(league => (
                      <div key={league} className="flex items-center gap-1 bg-inputBg border border-borderBase px-3 py-1 rounded-full text-xs text-textMain group">{league}<button onClick={() => handleRemoveLeague(league)} className="text-textMuted hover:text-danger ml-1"><X size={12} /></button></div>
                    ))}
                  </div>
               </div>
               <div className="space-y-3 pt-4 border-t border-borderBase">
                  <span className="text-textMain font-medium flex items-center gap-2"><FolderOpen size={16} /> Manage Folders</span>
                  <div className="bg-background/50 rounded-lg border border-borderBase p-2 max-h-48 overflow-y-auto space-y-2">
                    {uniqueFolders.length === 0 ? <p className="text-xs text-textMuted italic text-center py-2">No folders yet.</p> : uniqueFolders.map(folder => <FolderRow key={folder} name={folder} onRename={handleRenameFolder} onDelete={handleDeleteFolder} />)}
                  </div>
               </div>
               <div className="border-t border-borderBase pt-6">
                 <button onClick={handleResetStats} className="w-full py-3 rounded-lg border border-danger/30 text-danger hover:bg-danger hover:text-white transition-all font-bold flex items-center justify-center gap-2"><Trash2 size={18} /> Reset All Data</button>
               </div>
            </div>
          </div>
        </div>
      )}

      <div className="md:hidden fixed bottom-0 left-0 right-0 bg-surface border-t border-borderBase z-40 px-6 py-3 flex justify-between items-center">
        <MobileNavButton active={activeTab === 'dashboard'} onClick={() => setActiveTab('dashboard')} icon={LayoutDashboard} label="Overview" />
        <MobileNavButton active={activeTab === 'active'} onClick={() => setActiveTab('active')} icon={Wallet} label="Active" badge={slips.filter(s => s.status === SlipStatus.PENDING).length} />
        <MobileNavButton active={activeTab === 'stats'} onClick={() => setActiveTab('stats')} icon={BarChart3} label="Analytics" />
        <MobileNavButton active={activeTab === 'create'} onClick={() => { setEditingSlip(null); setActiveTab('create'); }} icon={PlusCircle} label="New" />
      </div>

      <main className="max-w-5xl mx-auto px-4 py-8">
        {uniqueFolders.length > 0 && activeTab !== 'create' && (
          <div className="mb-6 overflow-x-auto pb-2 scrollbar-hide">
             <div className="flex gap-2">
               <button onClick={() => setSelectedFolder('All')} className={`px-4 py-2 rounded-full text-xs font-bold whitespace-nowrap border transition-all ${selectedFolder === 'All' ? 'bg-primary text-white border-primary' : 'bg-surface text-textMuted border-borderBase hover:bg-inputBg'}`}>All Bets</button>
               {uniqueFolders.map(folder => (
                 <button key={folder} onClick={() => setSelectedFolder(folder)} className={`px-4 py-2 rounded-full text-xs font-bold whitespace-nowrap border flex items-center gap-2 transition-all ${selectedFolder === folder ? 'bg-primary text-white border-primary' : 'bg-surface text-textMuted border-borderBase hover:bg-inputBg'}`}><FolderOpen size={14} /> {folder}</button>
               ))}
             </div>
          </div>
        )}

        {activeTab === 'dashboard' && (
          <div className="space-y-8 animate-fade-in">
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
               <StatsCard title="Virtual Balance" value={bankroll.toFixed(2)} isMoney currency={currency} icon={Coins} color="text-success" />
               <StatsCard title="Net Profit" value={stats.profit.toFixed(2)} isMoney currency={currency} icon={Wallet} color={stats.profit >= 0 ? 'text-success' : 'text-danger'} />
               <StatsCard title="Win Rate" value={`${stats.winRate.toFixed(1)}%`} icon={Trophy} color="text-warning" />
               <StatsCard title="ROI" value={`${stats.roi.toFixed(1)}%`} icon={TrendingUp} color={stats.roi >= 0 ? 'text-success' : 'text-danger'} />
            </div>
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
              <div className="lg:col-span-2 space-y-4">
                <div className="flex items-center justify-between"><h2 className="text-xl font-bold text-textMain flex items-center gap-2"><History className="text-textMuted" size={20} /> Recent Activity</h2></div>
                <SlipList slips={slips.filter(s => selectedFolder === 'All' || s.folder === selectedFolder).slice(0, 5)} onUpdateSlip={handleUpdateSlip} onEditSlip={handleEditSlip} onDeleteSlip={handleDeleteSlip} currency={currency} />
              </div>
              <div className="space-y-6">
                 <div className="bg-surface p-6 rounded-xl border border-borderBase">
                    <h3 className="text-textMain font-bold mb-4">Accuracy</h3>
                    <div className="space-y-4">
                       <div className="flex justify-between text-sm"><span className="text-textMuted">Wins</span><span className="text-success font-bold">{stats.wins}</span></div>
                       <div className="w-full bg-inputBg rounded-full h-2"><div className="bg-success h-2 rounded-full" style={{ width: `${stats.totalSlips ? (stats.wins/stats.totalSlips)*100 : 0}%` }}></div></div>
                       <div className="flex justify-between text-sm"><span className="text-textMuted">Losses</span><span className="text-danger font-bold">{stats.losses}</span></div>
                        <div className="w-full bg-inputBg rounded-full h-2"><div className="bg-danger h-2 rounded-full" style={{ width: `${stats.totalSlips ? (stats.losses/stats.totalSlips)*100 : 0}%` }}></div></div>
                    </div>
                 </div>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'create' && (
          <div className="max-w-3xl mx-auto animate-fade-in">
             <NewSlipForm initialData={editingSlip || undefined} onSave={handleSaveSlip} onCancel={() => { setEditingSlip(null); setActiveTab('dashboard'); }} currency={currency} availableFolders={uniqueFolders} availableLeagues={customLeagues} />
          </div>
        )}

        {activeTab === 'stats' && <StatisticsPanel slips={slips.filter(s => selectedFolder === 'All' || s.folder === selectedFolder)} currency={currency} />}
        {activeTab === 'active' && <div className="space-y-4 animate-fade-in"><h2 className="text-xl font-bold text-textMain mb-6">Active Slips</h2><SlipList slips={slips.filter(s => s.status === SlipStatus.PENDING && (selectedFolder === 'All' || s.folder === selectedFolder))} onUpdateSlip={handleUpdateSlip} onEditSlip={handleEditSlip} onDeleteSlip={handleDeleteSlip} currency={currency} /></div>}
        {activeTab === 'settled' && <div className="space-y-4 animate-fade-in"><h2 className="text-xl font-bold text-textMain mb-6">History</h2><SlipList slips={slips.filter(s => s.status !== SlipStatus.PENDING && (selectedFolder === 'All' || s.folder === selectedFolder))} onUpdateSlip={handleUpdateSlip} onEditSlip={handleEditSlip} onDeleteSlip={handleDeleteSlip} currency={currency} /></div>}
      </main>
    </div>
  );
};

const FolderRow = ({ name, onRename, onDelete }: any) => {
  const [isEditing, setIsEditing] = useState(false);
  const [val, setVal] = useState(name);
  const handleSave = () => { if (val.trim() && val.trim() !== name) onRename(name, val); setIsEditing(false); };
  if (isEditing) return <div className="flex gap-2 items-center bg-inputBg p-2 rounded border border-primary"><input className="flex-1 bg-transparent border-none outline-none text-sm text-textMain" value={val} onChange={e => setVal(e.target.value)} autoFocus onKeyDown={(e) => { if (e.key === 'Enter') handleSave(); if (e.key === 'Escape') { setIsEditing(false); setVal(name); }}} /><button onClick={handleSave} className="text-success hover:bg-success/10 p-1 rounded"><Check size={14}/></button><button onClick={() => { setIsEditing(false); setVal(name); }} className="text-danger hover:bg-danger/10 p-1 rounded"><X size={14}/></button></div>;
  return <div className="flex justify-between items-center bg-inputBg p-2 rounded border border-borderBase hover:border-textMuted transition-colors group"><span className="text-sm text-textMain">{name}</span><div className="flex gap-2 opacity-60 group-hover:opacity-100 transition-opacity"><button onClick={() => setIsEditing(true)} className="text-textMuted hover:text-primary p-1"><Edit2 size={14}/></button><button onClick={() => onDelete(name)} className="text-textMuted hover:text-danger p-1"><Trash2 size={14}/></button></div></div>;
};

const NavButton = ({ active, onClick, icon: Icon, label, badge }: any) => <button onClick={onClick} className={`px-4 py-2 rounded-md text-sm font-medium flex items-center gap-2 transition-all ${active ? 'bg-inputBg text-textMain shadow-sm border border-borderBase' : 'text-textMuted hover:text-textMain hover:bg-inputBg'}`}><Icon size={16} /> {label}{badge > 0 && <span className="bg-primary text-white text-[10px] px-1.5 py-0.5 rounded-full">{badge}</span>}</button>;
const MobileNavButton = ({ active, onClick, icon: Icon, label, badge }: any) => <button onClick={onClick} className={`flex flex-col items-center gap-1 ${active ? 'text-primary' : 'text-textMuted'}`}><div className="relative"><Icon size={24} />{badge > 0 && <span className="absolute -top-1 -right-1 bg-red-500 text-white text-[10px] w-4 h-4 flex items-center justify-center rounded-full border border-surface">{badge}</span>}</div><span className="text-[10px] font-medium">{label}</span></button>;

export default App;
